insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قال: جَاءَ رَجُلٌ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَنْ أَحَقُّ النَّاسِ بحُسْنِ صَحَابَتِي؟ قال: "أُمُّكَ" قال: ثُمَّ مَنْ؟ قال: "ثُمَّ أُمُّكَ" قال: ثُمَّ مَنْ؟ قال: "ثُمَّ أُمُّكَ" قال: ثُمَّ مَنْ؟ قال: "ثُمَّ أَبُوكَ". (ق)', 'അബൂഹുറൈറ(റ): ഒരാൾ റസൂൽ(സ)യുടെ സന്നിധിയിൽ വന്ന് ചോദിച്ചു: ഞാൻ ജനങ്ങളിൽ ഏറ്റവും നന്നായി വർത്തിക്കേണ്ടത് ആരോടാണ്? നബി(സ) പറഞ്ഞു: "നിന്റെ മാതാവ്." അദ്ദേഹം ചോദിച്ചു: പിന്നെയാരോടാണ്? നബി(സ) പറഞ്ഞു: "നിന്റെ മാതാവിനോട്." വീണ്ടും ചോദിച്ചു: പിന്നെയാരോടാണ്? നബി(സ) പറഞ്ഞു: "നിന്റെ മാതാവിനോട്." അദ്ദേഹം ചോദിച്ചു: പിന്നെയാരോടാണ്? നബി(സ) പറഞ്ഞു: "ശേഷം നിന്റെ പിതാവിനോട്." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 745, 745, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قال: قَالُوا: يَا رَسُولَ اللهِ، مَنْ أَبَرُّ؟ قال: "أُمَّكَ" قال: ثُمَّ مَنْ؟ قال: "أُمَّكَ" قال: ثُمَّ مَنْ؟ قال: "أَبَاكَ" قال: ثُمَّ مَنْ؟ قال: "الْأَدْنَى فَالْأَدْنَى". (ق,جه)', 'അബൂഹുറൈറ(റ): സ്വഹാബികൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഏറ്റവും കൂടുതൽ നന്മ ചെയ്യേണ്ടത് ആരോടാണ്? നബി(സ) പറഞ്ഞു: "നിന്റെ മാതാവിനോട്." അവർ ചോദിച്ചു: പിന്നെയാരോടാണ്?, തിരുമേനി(സ) പറഞ്ഞു: "നിന്റെ മാതാവിനോട് തന്നെ." അവർ ചോദിച്ചു: പിന്നെയാരോടാണ്? നബി(സ) പറഞ്ഞു: "നിന്റെ പിതാവിനോട്." അവർ ചോദിച്ചു: പിന്നെയാരോടാണ്? റസൂൽ പറഞ്ഞു: "അടുത്തവർ, പിന്നെ അതിനോടടുത്തവർ." (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 745, 745, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رضي الله عنهُ قال: قُلْتُ: يَا رَسُولَ اللهِ، مَنْ أَبَرُّ؟ قال: "أُمَّكَ، ثُمَّ أُمَّكَ، ثُمَّ أُمَّكَ، ثُمَّ أَبَاكَ، ثُمَّ الْأَقْرَبَ فَالْأَقْرَبَ". وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَسْأَلُ رَجُلٌ مَوْلَاهُ مِنْ فَضْلٍ هُوَ عِنْدَهُ، فَيَمْنَعُهُ إِيَّاهُ، إِلَّا دُعِيَ لَهُ يَوْمَ الْقِيَامَةِ فَضْلُهُ الَّذِي مَنَعَهُ شُجَاعًا أَقْرَعَ". (د,ت)', 'മുആവിയതുബ്നു ഹൈദ(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ആർക്കാണ് ഏറ്റവും കൂടുതൽ ഗുണം ചെയ്തു കൊടുക്കേണ്ടത്? നബി(സ) പറഞ്ഞു: "നിന്റെ മാതാവിന്. പിന്നെയും നിന്റെ മാതാവിന്. പിന്നെയും നിന്റെ മാതാവിന്. പിന്നീട് നിന്റെ പിതാവിന്. പിന്നെ അടുത്തവർ, പിന്നെ അതിനോടടുത്തവർ." റസൂൽ(സ) പറഞ്ഞു: "തന്റെ ഉടമയോട് അവന്റെ ഔദാര്യം ചോദിച്ച് തടയപ്പെട്ടവൻ, അന്ത്യദിനത്തിൽ, ധീരനായി ആ ഔദാര്യത്തിന് വേണ്ടി വിളിക്കപ്പെടും." (ദ,തു)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 745, 745, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ خِدَاشِ بْنِ سَلَامَةَ السُّلَمِيِّ رضي الله عنه قال النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُوصِي امْرَأً بِأُمِّهِ، أُوصِي امْرَأً بِأُمِّهِ، أُوصِي امْرَأً بِأُمِّهِ، أُوصِي امْرَأً بِأَبِيهِ، أُوصِي امْرَأً بِمَوْلَاهُ الَّذِي يَلِيهِ، وَإِنْ كَانَ عَلَيْهِ مِنْهُ أَذًى يُؤْذِيهِ". (جه)', 'ഖിദാശുബ്നു സലാമതുസ്സലമി(റ): നബി(സ) പറഞ്ഞു: "ഒരാളോട് തന്റെ മാതാവിന്റെ വിഷയത്തിൽ ഞാൻ ഉപദേശിക്കുന്നു. ഒരാളോട് തന്റെ മാതാവിന്റെ വിഷയത്തിൽ ഞാൻ ഉപദേശിക്കുന്നു. ഒരാളോട് തന്റെ മാതാവിന്റെ വിഷയത്തിൽ ഞാൻ ഉപദേശിക്കുന്നു. ഒരാളോട് തന്റെ പിതാവിന്റെ വിഷയത്തിൽ ഞാൻ ഉപദേശിക്കുന്നു. ഒരാളോട് തന്നെ നിയന്ത്രിക്കുന്ന തന്റെ യജമാനന്റെ കാര്യത്തിൽ ഞാൻ ഉപദേശിക്കുന്നു. യജമാനനിൽ നിന്ന് അവനെ ബാധിക്കുന്ന വല്ല ബുദ്ധിട്ടും സഹിക്കേണ്ടിവരുന്നുണ്ടെങ്കിലും ശരി." (ജ)', 'خِدَاشِ بْنِ سَلَامَةَ السُّلَمِيِّ', 'ഖിദാശുബ്നു സലാമതുസ്സലമി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 745, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ بَكْرِ بْنِ الْحَارِثِ رضي الله عنه: أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، مَنْ أَبَرُّ؟ قال: "أُمَّكَ، وَأَبَاكَ، وَأُخْتَكَ، وَأَخَاكَ، وَمَوْلَاكَ الَّذِي يَلِي ذَاكَ، حَقٌّ وَاجِبٌ وَرَحِمٌ مَوْصُولَةٌ". (د)', 'ബക്റുബ്നുൽ ഹാരിസ്(റ): അദ്ദേഹം നബി(സ)യുടെ അടുക്കൽ വന്നു കൊണ്ട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ആർക്കാണ് കൂടുതൽ ഗുണം ചെയ്യേണ്ടത്? തിരുമേനി(സ) പറഞ്ഞു: "നിന്റെ മാതാവിന്, പിന്നെ നിന്റെ പിതാവിന്, പിന്നീട് നിന്റെ സഹോദരിക്ക്, പിന്നെ നിന്റെ സഹോദരന് ശേഷം അതിനോടടുത്ത നിന്റെ യജമാനന്. ഇത് നിർബന്ധ ബാധ്യതയും, പുലർത്തപ്പെടേണ്ട കുടുംബബന്ധവുമാണ്." (ദ)', 'بَكْرِ بْنِ الْحَارِثِ', 'ബക്റുബ്നുൽ ഹാരിസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 746, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنِ ابْنِ مَسْعُودٍ رضي الله عنه قال: سَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللهِ، أَيُّ الْأَعْمَالِ أَفْضَلُ؟ قال: "الصَّلَاةُ لِمِيقَاتِهَا". قُلْتُ: ثُمَّ مَاذَا يَا رَسُولَ اللهِ؟ قال: "بِرُّ الْوَالِدَيْنِ". قُلْتُ: ثُمَّ مَاذَا يَا رَسُولَ اللهِ؟ قال: "الْجِهَادُ فِي سَبِيلِ اللهِ". ثُمَّ سَكَتَ عَنِّي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَوِ اسْتَزَدْتُهُ لَزَادَنِي. حَسَنٌ صَحِيحٌ (ق,ت,ن)', 'ഇബ്നു മസ്ഊദ്(റ): ഞാൻ റസൂൽ(സ)യോട് ചോദിച്ചു: റസൂലേ, കർമ്മങ്ങളിൽ ഏറ്റവും ശ്രേഷ്ഠമായത് ഏതാണ്? റസൂൽ(സ) പറഞ്ഞു: "നിസ്കാരം അതിന്റെ സമയത്ത് അനുഷ്ഠിക്കുക." ഞാൻ ചോദിച്ചു: പിന്നെയേതാണ് അല്ലാഹുവിന്റെ റസൂലേ? റസൂൽ(സ) പറഞ്ഞു: "മാതാപിതാക്കൾക്ക് ഗുണം ചെയ്യുക." ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ പിന്നെയേതാണ്? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുക." പിന്നെ റസൂൽ(സ) എന്നോട് മൗനവലംബിച്ചു. ഞാൻ അധികം ചോദിച്ചിരുന്നെങ്കിൽ, അവിടന്ന് കൂടുതൽ പറയുമായിരുന്നു. (ബു,മു,തു,ന)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നു മസ്ഊദ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 746, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رضي الله عنهما، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "رِضَى الرَّبِّ فِي رِضَى الْوَالِدِ، وَسَخَطُ الرَّبِّ فِي سَخَطِ الْوَالِدِ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "രക്ഷിതാവിന്റെ (അല്ലാഹുവിന്റെ) തൃപ്തി മാതാപിതാക്കളുടെ തൃപ്തിയിലാണ്. രക്ഷിതാവിന്റെ കോപം മാതാപിതാക്കളുടെ കോപത്തിലാണ്." (തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 746, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي الدَّرْدَاءِ رضي الله عنهُ: أَنَّ رَجُلًا أَتَاهُ فَقَالَ: إِنَّ لِي امْرَأَةٌ، وَإِنَّ أُمِّي تَأْمُرُنِي بِطَلَاقِهَا؟ قال أَبُو الدَّرْدَاءِ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْوَالِدُ أَوْسَطُ أَبْوَابِ الْجَنَّةِ، فَإِنْ شِئْتَ فَأَضِعْ ذَلِكَ الْبَابَ أَوِ احْفَظْهُ". صحيحٌ (ت,جه)', 'അബുദ്ദർദാഅ്(റ): ഒരാൾ അദ്ദേഹത്തിന്റെയടുത്ത് വന്നിട്ട് പറഞ്ഞു: എനിക്കൊരു ഭാര്യയുണ്ട്. എന്റെ ഉമ്മ അവളെ മൊഴിചൊല്ലാൻ പറയുന്നു? അബുദ്ദർദാഅ്(റ) പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "മാതാപിതാക്കൾ സ്വർഗ്ഗത്തിലെ കവാടങ്ങളിൽ ഏറ്റവും മധ്യത്തിലുള്ളതാണ്. നിനക്കുവേണമെങ്കിൽ ആ കവാടം നഷ്ടപ്പെടുത്തുക. അല്ലെങ്കിൽ അത് സൂക്ഷിക്കുക." (തു,ജ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 746, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِ يكرِبَ رضي الله عنهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "إِنَّ اللهَ يُوصِيكُمْ بِأُمَّهَاتِكُمْ، ثَلَاثًا. إِنَّ اللهَ يُوصِيكُمْ بِآبَائِكُمْ، إِنَّ اللهَ يُوصِيكُمْ بِالْأَقْرَبِ فَالْأَقْرَبِ". في سنده ضعف. (جه)', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിങ്ങളുടെ മാതാക്കളുടെ വിഷയത്തിൽ നിങ്ങളെ ഉപദേശിക്കുന്നു. അവിടന്ന് അത് മൂന്ന് പ്രാവശ്യം ആവർത്തിച്ചു അല്ലാഹു നിങ്ങളുടെ പിതാക്കളുടെ വിഷയത്തിൽ നിങ്ങളെ ഉപദേശിക്കുന്നു. അല്ലാഹു അടുത്തവരുടെയും പിന്നെ അടുത്തവരുടെയും വിഷയത്തിൽ നിങ്ങളെ ഉപദേശിക്കുന്നു." പരമ്പരയിൽ ഭംഗമുണ്ട്. (ജ)', 'الْمِقْدَامِ بْنِ مَعْدِ يكرِبَ', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي أُمَامَةَ رضي الله عنهُ: أَنَّ رَجُلًا قال: يَا رَسُولَ اللهِ، مَا حَقُّ الْوَالِدَيْنِ عَلَى وَلَدِهِمَا؟ قال: "هُمَا جَنَّتُكَ وَنَارُكَ". فِي سَنَدِهِ ضُعْفٌ (جه)', 'അബൂഉമാമ(റ): ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, മകന് മാതാപിതാക്കളോടുള്ള കടപ്പാട് എന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "അവർ രണ്ട് പേരും നിന്റെ സ്വർഗ്ഗവും നരകവുമാണ്." പരമ്പരയിൽ ഭംഗമുണ്ട്. (ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ قال: قال رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَجْزِي وَلَدٌ وَالِدًا إِلَّا أَنْ يَجِدَهُ مَمْلُوكًا فَيَشْتَرِيَهُ، فَيُعْتِقَهُ". حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അടിമയായി കണ്ടെത്തിയിട്ട് വാങ്ങി മോചിപ്പിച്ചാലല്ലാതെ, ഒരു മകൻ തന്റെ മാതാപിതാക്കൾക്ക് പ്രതിഫലം ചെയ്യുന്നവനാകില്ല." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رضي الله عنهما قال: كَانَتْ تَحْتِي امْرَأَةٌ، وَكُنْتُ أُحِبُّهَا، وَكَانَ عُمَرُ يَكْرَهُهَا، فَقَالَ: لِي: طَلِّقْهَا، فَأَبَيْتُ، فَأَتَى عُمَرُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "طَلِّقْهَا". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): എനിക്ക് ഒരു ഭാര്യയുണ്ടായിരുന്നു. ഞാനവളെ വളരെ ഇഷ്ടപ്പെട്ടിരുന്നു. എന്നാൽ ഉമർ(റ)വിന് അവളെ വെറുപ്പായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: അവളെ നീ ത്വലാഖ് ചൊല്ലുക. ഞാനത് വിസമ്മതിച്ചു. അപ്പോൾ ഉമർ(റ) നബി(സ)യുടെ അടുക്കൽ ചെന്നിട്ട് വിവരം പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അവളെ നിങ്ങൾ ത്വലാഖ് ചൊല്ലുക." (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ قال: قال رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثُ دَعَوَاتٍ مُسْتَجَابَاتٌ لَا شَكَّ فِيهِنَّ: دَعْوَةُ الْمَظْلُومِ، وَدَعْوَةُ الْمُسَافِرِ، وَدَعْوَةُ الْوَالِدِ عَلَى وَلَدِهِ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിസ്സംശയം മൂന്ന് പ്രാർത്ഥനകൾ ഉത്തരം ലഭിക്കുന്നവയാണ്: മർദ്ദിതന്റെ പ്രാർത്ഥന, യാത്രക്കാരന്റെ പ്രാർത്ഥന, മകനെതിരെയുള്ള പിതാവിന്റെ പ്രാർത്ഥന." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "لَمْ يَتَكَلَّمْ فِي الْمَهْدِ إِلَّا ثَلَاثَةٌ: عِيسَى ابْنُ مَرْيَم وَصَاحِبُ جُرَيْجٍ، وَكَانَ جُرَيْجٌ رَجُلًا عَابِدًا، فَاتَّخَذَ صَوْمَعَةً فَكَانَ فِيهَا، فَأَتَتْهُ أُمُّهُ وَهُوَ يُصَلِّي فَقَالَتْ: يَا جُرَيْجُ، فَقَالَ: يَا رَبِّ، أُمِّي وَصَلَاتِي؟ فَأَقْبَلَ عَلَى صَلَاتِهِ، فَانْصَرَفَتْ، فَلَمَّا كَانَ مِنَ الْغَدِ أَتَتْهُ وَهُوَ يُصَلِّي، فَقَالَتْ: يَا جُرَيْجُ، فَقَالَ: يَا رَبِّ، أُمِّي وَصَلَاتِي؟ فَأَقْبَلَ عَلَى صَلَاتِهِ، فَانْصَرَفَتْ، فَلَمَّا كَانَ مِنَ الْغَدِ أَتَتْهُ، فَقَالَتْ: يَا جُرَيْجُ، فَقَالَ: أَيْ رَبِّ أُمِّي وَصَلَاتِي؟ فَأَقْبَلَ عَلَى صَلَاتِهِ، فَقَالَتْ: اللَّهُمَّ لَا تُمِتْهُ حَتَّى يَنْظُرَ إِلَى وُجُوهِ الْمُومِسَاتِ. فَتَذَاكَرَ بَنُو إِسْرَائِيلَ جُرَيْجًا وَعِبَادَتَهُ، وَكَانَتِ امْرَأَةٌ بَغِيٌّ يُتَمَثَّلُ بِحُسْنِهَا، فَقَالَتْ: إِنْ شِئْتُمْ لَأَفْتِنَنَّهُ لَكُمْ. قَالَ: فَتَعَرَّضَتْ لَهُ فَلَمْ يَلْتَفِتْ إِلَيْهَا، فَأَتَتْ رَاعِيًا كَانَ يَأْوِي إِلَى صَوْمَعَتِهِ فَأَمْكَنَتْهُ مِنْ نَفْسِهَا، فَوَقَعَ عَلَيْهَا، فَحَمَلَتْ، فَلَمَّا وَلَدَتْ قَالَتْ: هُوَ مِنْ جُرَيْجٍ. فَأَتَوْهُ فَاسْتَنْزَلُوهُ، وَهَدَمُوا صَوْمَعَتَهُ، وَجَعَلُوا يَضْرِبُونَهُ. فَقَالَ: مَا شَأْنُكُمْ؟ قَالُوا: زَنَيْتَ بِهَذِهِ الْبَغِيِّ فَوَلَدَتْ مِنْكَ. فَقَالَ: أَيْنَ الصَّبِيُّ؟ فَجَاءُوا بِهِ. فَقَالَ: دَعُونِي حَتَّى أُصَلِّيَ، فَصَلَّى، فَلَمَّا انْصَرَفَ أَتَى الصَّبِيَّ فَطَعَنَ فِي بَطْنِهِ وَقَالَ: يَا غُلَامُ مَنْ أَبُوكَ؟ قَالَ: فُلَانٌ الرَّاعِي. قَالَ: فَأَقْبَلُوا عَلَى جُرَيْجٍ يُقَبِّلُونَهُ وَيَتَمَسَّحُونَ بِهِ، وَقَالُوا: نَبْنِي لَكَ صَوْمَعَتَكَ مِنْ ذَهَبٍ وَفِضَّةٍ. قَالَ: لَا، أَعِيدُوهَا مِنْ طِينٍ كَمَا كَانَتْ. فَفَعَلُوا. وَبَيْنَا صَبِيٌّ يَرْضَعُ مِنْ أُمِّهِ، فَمَرَّ رَجُلٌ رَاكِبٌ عَلَى دَابَّةٍ فَارِهَةٍ، وَشَارَةٍ حَسَنَةٍ، فَقَالَتْ أُمُّهُ: اللَّهُمَّ اجْعَلِ ابْنِي مِثْلَ هَذَا، فَتَرَكَ الثَّدْيَ وَأَقْبَلَ إِلَيْهِ، فَنَظَرَ إِلَيْهِ، فَقَالَ: اللَّهُمَّ لَا تَجْعَلْنِي مِثْلَهُ. ثُمَّ أَقْبَلَ عَلَى ثَدْيِهِ، فَجَعَلَ يَرْتَضِعُ قَالَ: فَكَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَحْكِي ارْتِضَاعَهُ بِإِصْبَعِهِ السَّبَّابَةِ فِي فَمِهِ فَجَعَلَ يَمُصُّهَا. قَالَ: وَمَرُّوا بِجَارِيَةٍ وَهُمْ يَضْرِبُونَهَا، وَيَقُولُونَ: زَنَيْتِ سَرَقْتِ، وَهِيَ تَقُولُ: حَسْبِيَ اللهُ وَنِعْمَ الْوَكِيلُ، فَقَالَتْ أُمُّهُ: اللَّهُمَّ لَا تَجْعَلِ ابْنِي مِثْلَهَا، فَتَرَكَ الرَّضَاعَ وَنَظَرَ إِلَيْهَا فَقَالَ: اللَّهُمَّ اجْعَلْنِي مِثْلَهَا، فَهُنَاكَ تَرَاجَعَا الْحَدِيثَ. فَقَالَتْ: حَلْقَى، مَرَّ رَجُلٌ حَسَنُ الْهَيْئَةِ فَقُلْتُ: اللَّهُمَّ اجْعَلِ ابْنِي مِثْلَهُ، فَقُلْتَ: اللَّهُمَّ لَا تَجْعَلْنِي مِثْلَهُ! وَمَرُّوا بِهَذِهِ الْأَمَةِ وَهُمْ يَضْرِبُونَهَا وَيَقُولُونَ: زَنَيْتِ سَرَقْتِ، فَقُلْتُ: اللَّهُمَّ لَا تَجْعَلِ ابْنِي مِثْلَهَا، فَقُلْتَ: اللَّهُمَّ اجْعَلْنِي مِثْلَهَا! قَالَ: إِنَّ ذَاكَ الرَّجُلَ كَانَ جَبَّارًا، فَقُلْتُ: اللَّهُمَّ لَا تَجْعَلْنِي مِثْلَهُ، وَإِنَّ هَذِهِ: يَقُولُونَ لَهَا: زَنَيْتِ وَلَمْ تَزْنِ، وَسَرَقْتِ وَلَمْ تَسْرِقْ، فَقُلْتُ: اللَّهُمَّ اجْعَلْنِي مِثْلَهَا". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "തൊട്ടിലിൽ വെച്ച് മൂന്ന് പേർ മാത്രമേ സംസാരിച്ചിട്ടുള്ളൂ: ഈസബ്നു മർയം(അ), ജുറൈജിന്റെ ആൾ. ജുറൈജ്(റ) ഒരു ആബിദായ മനുഷ്യനായിരുന്നു. അദ്ദേഹമൊരു കൂടാരമുണ്ടാക്കി. അതിൽ താമസിച്ചു നിസ്കരിക്കുമ്പോൾ അദ്ദേഹത്തിന്റെയടുത്ത് തന്റെ മാതാവ് വന്നു. മാതാവ് ജുറൈജ്(റ)വിനെ വിളിച്ചു. ജുറൈജ്(റ) പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, ഉമ്മയും നിസ്കാരവും (ഏതാണ് മുന്തിക്കേണ്ടത്?) അദ്ദേഹം നിസ്കാരം തുടർന്നു. മാതാവ് തിരിച്ചു പോയി. അടുത്ത ദിവസമായപ്പോൾ മാതാവ് വീണ്ടും വന്നു. ജുറൈജ്(റ) നിസ്കരിക്കുകയായിരുന്നു. അവർ ജുറൈജ്(റ)വിനെ വിളിച്ചു. അദ്ദേഹം പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, എന്റെ ഉമ്മയും നിസ്കാരവും? അദ്ദേഹം നിസ്കരിക്കാൻ നിന്നു. മാതാവ് തിരിച്ചു പോയി. പിറ്റേ ദിവസം ജുറൈജ് നിസ്കരിക്കുമ്പോൾ മാതാവ് അദ്ദേഹത്തിന്റെയടുത്ത് വന്നു. അവർ ജുറൈജ്(റ)വിനെ വിളിച്ചു. ജുറൈജ്(റ) പറഞ്ഞു: രക്ഷിതാവേ, എന്റെ ഉമ്മയും എന്റെ നിസ്കാരവും? അദ്ദേഹം നിസ്കരിക്കാൻ നിന്നു. അപ്പോൾ മാതാവ് ഇപ്രകാരം പ്രാർത്ഥിച്ചു: അല്ലാഹുവേ, വേശ്യ സ്ത്രീകളുടെ മുഖങ്ങളിലേക്ക് നോക്കുന്നതുവരെ അവനെ നീ മരിപ്പിക്കല്ലേ. അങ്ങനെ ജുറൈജ്(റ)വിനെതിരെയും അദ്ദേഹത്തിന്റെ ആരാധനക്കെതിരെയും ഇസ്രാഈല്യർ ഗൂഢാലോചന നടത്തി. സൗന്ദര്യത്തിന്റെ പ്രതീകമായി അറിയപ്പെടുന്ന ഒരു വേശ്യസ്ത്രീ അന്നാട്ടിലുണ്ടായിരുന്നു. അവൾ പറഞ്ഞു: നിങ്ങളാഗ്രഹിക്കുന്നുവെങ്കിൽ അവനെ ഞാൻ അസാന്മാർഗികതയിലേക്ക് തിരിച്ചുവിടാം. വേശ്യ ജുറൈജ്(റ)വിന്റെ മുന്നിൽ വിവസ്ത്രയായി പ്രത്യക്ഷപ്പെട്ടു. ജുറൈജ്(റ) അവളെ തിരിഞ്ഞു നോക്കിയില്ല. അപ്പോഴവൾ ജുറൈജ്(റ)വിന്റെ കൂടാരത്തിൽ വരാറുള്ള ഒരു ഇടയന്റെ അടുത്ത് ചെന്നു. ഇടയന് അവളുമായി വ്യഭിചാര വേഴ്ചക്ക് സൗകര്യം നൽകി. ഇടയൻ വേശ്യയുമായി ബന്ധപ്പെട്ടു. അങ്ങനെ അവൾ ഗർഭിണിയായി. പ്രസവിച്ചപ്പോൾ അവൾ പറഞ്ഞു: ഇത് ജുറൈജിന്റെ മകനാണ്. ജനങ്ങൾ ജുറൈജ്(റ)വിന്റെയടുത്ത് ചെന്നു. അവർ ജുറൈജ്(റ)വിനെ പുറത്തേക്ക് വലിച്ചിറക്കി. അദ്ദേഹത്തിന്റെ കൂടാരം തകർത്തു. അദ്ദേഹത്തെ അവർ അടിക്കാൻ തുടങ്ങി. ജുറൈജ്(റ) ചോദിച്ചു: നിങ്ങൾക്കെന്താണ് പ്രശ്നം? അവർ പറഞ്ഞു: നീ ഈ വേശ്യയെ വ്യഭിചരിച്ച് നിന്നിൽ നിന്ന് അവൾക്കൊരു കുട്ടി പിറന്നില്ലേ? അദ്ദേഹം ചോദിച്ചു: കുട്ടിയെവിടെ? അവർ കുട്ടിയെക്കൊണ്ടു വന്നു. അദ്ദേഹം പറഞ്ഞു: എനിക്ക് നിസ്കരിക്കാൻ സമയം അനുവദിക്കുക. അദ്ദേഹം നിസ്കരിച്ചു. നിസ്കാരം കഴിഞ്ഞ് അദ്ദേഹം കുട്ടിയുടെ അടുത്തേക്ക് ചെന്നു. അവന്റെ ഉദരത്തിൽ കുത്തിയിട്ട് ചോദിച്ചു: കുഞ്ഞേ, നിന്റെ പിതാവാരാണ്? കുട്ടി പറഞ്ഞു: ഇടയനായ ആ വ്യക്തിയാണ്. തത്സമയം ജനങ്ങൾ ജുറൈജ്(റ)വിന്റെയടുത്ത് വന്ന് അദ്ദേഹത്തെ ചുംബിക്കാനും തടവാനും തുടങ്ങി. അവർ പറഞ്ഞു: അങ്ങേക്ക് ഞങ്ങൾ സ്വർണ്ണത്തിന്റെയും വെള്ളിയുടെയും കൂടാരമുണ്ടാക്കിത്തരാം. അദ്ദേഹം പറഞ്ഞു: വേണ്ട, ആദ്യമുണ്ടായിരുന്നത് പോലോത്ത മണ്ണിന്റെ കൂടാരം പുനർനിർമ്മിച്ചാൽ മതി. അവർ അങ്ങനെ ചെയ്തു. മറ്റൊരു കുട്ടി, മുല കുടിച്ചുകൊണ്ടിരിക്കുമ്പോൾ, കാണാൻ ചന്തവും ചുറുചുറുക്കുമുള്ള ഒരു മൃഗത്തിന്റെ പുറത്ത് ഒരു യാത്രികൻ കടന്ന് പോയി. അപ്പോൾ കുട്ടിയുടെ മാതാവ് പ്രാർത്ഥിച്ചു: അല്ലാഹുവേ, എന്റെ മകനെ നീ ഇദ്ദേഹത്തെപ്പോലെയാക്കണേ. അപ്പോൾ കുട്ടി മുലകുടി നിർത്തി അയാളിലേക്ക് തിരിഞ്ഞ് നോക്കി. എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവേ, എന്നെ നീ അയാളെപ്പോലെയാക്കരുത്. കുട്ടി മാതാവിന്റെ മാറിടത്തിലേക്ക് തിരിഞ്ഞ് മുല വീണ്ടും കുടിക്കാൻ തുടങ്ങി." അബൂഹുറൈറ(റ) പറയുന്നു: അവിടത്തെ ചൂണ്ടുവിരൽ വായിൽ വെച്ച് ഊമ്പിയിട്ട് കുട്ടിയുടെ മുലകുടി വിവരിക്കുന്ന റസൂൽ(സ)യെ ഞാനിപ്പോൾ നോക്കുന്നത് പോലെയുണ്ട്. നബി(സ) പറയുന്നു: "അവർ ഒരു അടിമസ്ത്രീയുടെ അടുത്ത് കൂടെ നടന്നുപോയി. ജനങ്ങൾ അവളെ അടിക്കുന്നുണ്ട്. അവർ പറയുന്നു: നീ വ്യഭിചരിക്കുകയും, മോഷ്ടിക്കുകയും ചെയ്തിരിക്കുന്നു. അവൾ പറയുന്നു: എനിക്കല്ലാഹു മതി. ഭരമേൽപ്പിക്കപ്പെടുന്നവനെത്ര ഉത്തമൻ! അപ്പോൾ കുട്ടിയുടെ മാതാവ് പറഞ്ഞു: അല്ലാഹുവേ, എന്റെ മകനെ, അവളെപ്പോലെയാക്കരുത്. കുട്ടി മുലകുടി നിർത്തി അവളെ നോക്കി. എന്നിട്ട് പറഞ്ഞു: എന്നെ നീ അവളെപ്പോലെയാക്കണേ. ശേഷം അവർ പരസ്പരം സംസാരം തുടർന്നു. മാതാവ് പറഞ്ഞു: ഹോ, സുന്ദരനായ ഒരാൾ നടന്നുപോയി. അപ്പോൾ ഞാൻ പ്രാർത്ഥിച്ചു: അല്ലാഹുവേ, എന്റെ മകനെ നീ അയാളെപ്പോലെയാക്കണേ. അപ്പോൾ നീ പറഞ്ഞു: അല്ലാഹുവേ, എന്നെ അയാളെപ്പോലെയാക്കരുത്. അങ്ങനെ ജനങ്ങൾ അടിച്ചു കൊണ്ടിരിക്കുന്ന ഈ അടിമസ്ത്രീയുടെയരികിലൂടെ നടന്നു പോയി. ജനങ്ങൾ പറയുന്നുണ്ടായിരുന്നു: നീ വ്യഭിചരിക്കുകയും മോഷണം നടത്തുകയും ചെയ്തിരിക്കുന്നു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവേ, എന്റെ മകനെ നീ അവളെപ്പോലെയാക്കരുത്. അപ്പോൾ നീ പറഞ്ഞു: അല്ലാഹുവേ, എന്നെ നീ അവളെപ്പോലെയാക്കണേ. കുട്ടി പറഞ്ഞു: അയാളൊരു പോക്കിരിയായിരുന്നു. അപ്പോൾ ഞാൻ പ്രാർത്ഥിച്ചു: അല്ലാഹുവേ, എന്നെ നീ അവനെപ്പോലെയാക്കരുത്. പിന്നീട് കണ്ട സ്ത്രീയോട് ജനങ്ങൾ പറയുന്നത് ''നീ വ്യഭിചരിച്ചിട്ടുണ്ട്'' എന്നാണ്. (പക്ഷേ, യഥാർത്ഥത്തിൽ) അവൾ വ്യഭിചരിച്ചിട്ടില്ല, ''നീ മോഷ്ടിച്ചിരിക്കുന്നു'' എന്നുമവർ പറയുന്നു. (യഥാർത്ഥത്തിൽ) അവൾ മോഷ്ടിച്ചിട്ടില്ല. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവേ, എന്നെ നീ അവളെപ്പോലെയാക്കണേ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 747, 749, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ رضي الله عنهما قال: أَقْبَلَ رَجُلٌ إِلَى نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: أُبَايِعُكَ عَلَى الْهِجْرَةِ وَالْجِهَادِ، أَبْتَغِي الْأَجْرَ مِنَ اللهِ عَزَّ وَجَلَّ. قَالَ: "فَهَلْ مِنْ وَالِدَيْكَ أَحَدٌ حَيٌّ". قَالَ: نَعَمْ، بَلْ كِلَاهُمَا. قَالَ: "فَتَبْتَغِي الْأَجْرَ مِنَ اللهِ عَزَّ وَجَلَّ". قَالَ: نَعَمْ. قَالَ: "فَارْجِعْ إِلَى وَالِدَيْكَ فَأَحْسِنْ صُحْبَتَهُمَا". (م)', 'അബ്ദുല്ലാഹിബ്നു അംറിബ്നിൽ ആസ്(റ): ഒരാൾ റസൂൽ(സ)യുടെ അടുത്ത് വന്നു കൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിൽ നിന്നുള്ള പ്രതിഫലം കാംക്ഷിച്ച് ഹിജ്റ ചെയ്യുമെന്നും ജിഹാദ് ചെയ്യുമെന്നും ഞാൻ അങ്ങയോട് പ്രതിജ്ഞ ചെയ്യുന്നു. നബി(സ) ചോദിച്ചു: "നിന്റെ മാതാപിതാക്കളിൽ ആരെങ്കിലും ജീവിച്ചിരിക്കുന്നുണ്ടോ?" അദ്ദേഹം പ്രതിവചിച്ചു: ഉണ്ട്, രണ്ടുപേരും ജീവിച്ചിരിപ്പുണ്ട്. നബി(സ) ചോദിച്ചു: "അപ്പോൾ അല്ലാഹുവിൽ നിന്നും നീ പ്രതിഫലമാഗ്രഹിക്കുന്നു?" അദ്ദേഹം പറഞ്ഞു: അതെ, അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "എങ്കിൽ നിന്റെ മാതാപിതാക്കളിലേക്ക് മടങ്ങുക. അവരോടുള്ള സഹവാസം നന്നാക്കുക." (മു)', 'عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറിബ്നിൽ ആസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 749, 750, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي بَكْرَةَ رضي الله عنهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أُحَدِّثُكُمْ بِأَكْبَرِ الْكَبَائِرِ". قَالُوا: بَلَى يَا رَسُولَ اللهِ. قَالَ: "الْإِشْرَاكُ بِاللهِ، وَعُقُوقُ الْوَالِدَيْنِ". قَالَ: وَجَلَسَ وَكَانَ مُتَّكِئًا فَقَالَ: "وَشَهَادَةُ الزُّورِ. أَوْ: قَوْلُ الزُّورِ". فَمَا زَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُهَا حَتَّى قُلْنَا: لَيْتَهُ سَكَتَ. حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബൂബക്റ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് ഞാൻ വൻകുറ്റങ്ങളിൽ ഏറ്റവും വലുത് ഏതെന്ന് പറഞ്ഞ് തരട്ടെയോ?" അനുചരർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, പറഞ്ഞു തന്നാലും നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിൽ പങ്ക് ചേർക്കുക. മാതാപിതാക്കളെ വെറുപ്പിക്കുക." നിവേദകൻ പറഞ്ഞു: നബി(സ) ഇരുന്നു. അവിടന്ന് ചാരിയിരിക്കുകയായിരുന്നു. എന്നിട്ട് പറഞ്ഞു: "കള്ള സാക്ഷി പറയുക, അല്ലെങ്കിൽ കള്ളം പറയുക." അവിടുന്നത് നിർത്തിയിരുന്നെങ്കിൽ എന്ന് ഞങ്ങൾ പറയുന്നത് വരെ റസൂൽ(സ) അത് ആവർത്തിച്ച് കൊണ്ടിരുന്നു. (ബു,മു,തു)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 750, 750, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رضي الله عنهما قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مِنَ الْكَبَائِرِ أَنْ يَشْتُمَ الرَّجُلُ وَالِدَيْهِ". قَالُوا: يَا رَسُولَ اللهِ، وَهَلْ يَشْتُمُ الرَّجُلُ وَالِدَيْهِ؟ قَالَ: نَعَمْ، يَسُبُّ أَبَا الرَّجُلِ فَيَشْتُمُ أَبَاهُ، وَيَشْتُمُ أُمَّهُ فَيَسُبُّ أُمَّهُ". حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ പിതാവിനെ അസഭ്യം പറയുന്നത് വൻകുറ്റങ്ങളിൽ പെട്ടതാണ്." അവർ ചോദിച്ചു: ഒരാൾ തന്റെ മാതാപിതാക്കളെ ആക്ഷേപിക്കുമോ? അവിടന്ന് പറഞ്ഞു: "അതെ, ഒരാൾ വേറൊരുത്തന്റെ പിതാവിനെ കുറ്റം പറയും. അപ്പോൾ അദ്ദേഹം ഇയാളുടെ പിതാവിനെ കുറ്റം പറയും. അവൻ അയാളുടെ ഉമ്മയെ കുറ്റം പറയും. അപ്പോൾ അവൻ ഇവന്റെ ഉമ്മയെയും കുറ്റം പറയും." (ബു,മു,ദ,തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 750, 750, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رضي الله عنهُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "إِنَّ اللهَ عَزَّ وَجَلَّ حَرَّمَ عَلَيْكُمْ عُقُوقَ الْأُمَّهَاتِ، وَوَأْدَ الْبَنَاتِ، وَمَنْعًا وَهَاتِ، وَكَرِهَ لَكُمْ ثَلَاثًا: قِيلَ وَقَالَ، وَكَثْرَةَ السُّؤَالِ، وَإِضَاعَةَ الْمَالِ". (م)', 'മുഗീരതുബ്നു ശുഅ്ബ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഉമ്മമാരെ ബുദ്ധിമുട്ടിക്കലും പെൺമക്കളെ കുഴിച്ചുമൂടലും നിർബന്ധമുള്ളത് തടയലും അനർഹമായത് സ്വീകരിക്കലും അല്ലാഹു നിങ്ങൾക്ക് നിഷിദ്ധമാക്കിയിരിക്കുന്നു. മൂന്ന് കാര്യങ്ങൾ നിങ്ങൾക്ക് അനിഷ്ടകരമാക്കിയിരിക്കുന്നു (കറാഹത്താക്കി). കേട്ടു കൾവികൾ, ചോദ്യം അധികരിപ്പിക്കൽ, സമ്പത്ത് നഷ്ടപ്പെടുത്തൽ." (മു)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീരതുബ്നു ശുഅ്ബ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 750, 751, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "رَغِمَ أَنْفُهُ، ثُمَّ رَغِمَ أَنْفُهُ، ثُمَّ رَغِمَ أَنْفُهُ". قِيلَ: مَنْ يَا رَسُولَ اللهِ؟ قَالَ: "مَنْ أَدْرَكَ وَالِدَيْهِ عِنْدَ الْكِبَرِ: أَحَدَهُمَا أَوْ كِلَيْهِمَا، ثُمَّ لَمْ يَدْخُلِ الْجَنَّةَ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ നിന്ദ്യനായിരിക്കുന്നു, ഒരാൾ നിന്ദ്യനായിരിക്കുന്നു. വീണ്ടും ഒരുത്തൻ നിന്ദ്യനായിരിക്കുന്നു. തിരുദൂതർ(സ)യോട് ചോദിക്കപ്പെട്ടു: ആരാണ് അല്ലാഹുവിന്റെ ദൂതരേ? നബി(സ) പറഞ്ഞു: "തന്റെ മാതാപിതാക്കളിൽ ഒരാളെയോ അല്ലെങ്കിൽ രണ്ടുപേരെയോ വാർദ്ധക്യ സമയത്ത് എത്തിച്ചിട്ട് സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കാത്തവൻ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 751, 751, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رضي الله عنهما: أَنَّهُ كَانَ إِذَا خَرَجَ إِلَى مَكَّةَ كَانَ لَهُ حِمَارٌ يَتَرَوَّحُ عَلَيْهِ إِذَا مَلَّ رُكُوبَ الرَّاحِلَةِ، وَعِمَامَةٌ يَشُدُّ بِهَا رَأْسَهُ، فَبَيْنَا هُوَ يَوْمًا عَلَى ذَلِكَ الْحِمَارِ إِذْ مَرَّ بِهِ أَعْرَابِيٌّ فَقَالَ: أَلَسْتَ ابْنَ فُلَانِ بْنِ فُلَانٍ؟ قَالَ: بَلَى. فَأَعْطَاهُ الْحِمَارَ وَقَالَ: ارْكَبْ هَذَا، وَالْعِمَامَةَ قَالَ: اشْدُدْ بِهَا رَأْسَكَ. فَقَالَ لَهُ بَعْضُ أَصْحَابِهِ: غَفَرَ اللهُ لَكَ، أَعْطَيْتَ هَذَا الْأَعْرَابِيَّ حِمَارًا كُنْتَ تَرَوَّحُ عَلَيْهِ، وَعِمَامَةً كُنْتَ تَشُدُّ بِهَا رَأْسَكَ؟ فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ مِنْ أَبَرِّ الْبِرِّ صِلَةَ الرَّجُلِ أَهْلَ وُدِّ أَبِيهِ بَعْدَ أَنْ يُوَلِّيَ". وَإِنَّ أَبَاهُ كَانَ صديقا لِعُمَرَ رضي الله عنهم. (م,د,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): മക്കയിലേക്ക് പുറപ്പെട്ടാൽ യാത്ര മടുക്കുമ്പോൾ വിശ്രമിക്കാനൊരു കഴുതയും തലയിൽ കെട്ടാനുള്ള ഒരു തലപ്പാവും അദ്ദേഹത്തിന്റെ പക്കലുണ്ടായിരുന്നു. അങ്ങനെ ഒരു ദിവസം അദ്ദേഹം കഴുതപ്പുറത്തിരിക്കുമ്പോൾ ഒരു അഅ്റാബി അതിലൂടെ വന്നു. ഇബ്നുഉമർ(റ) ചോദിച്ചു: നിങ്ങൾ ഇന്നാലിന്നയാളുടെ മകനല്ലെയോ? അയാൾ പറഞ്ഞു: അതെ. ഇബ്നുഉമർ(റ) തന്റെ കഴുതയെ അയാൾക്ക് നൽകിയിട്ട് പറഞ്ഞു: നിങ്ങൾ ഇതിന്മേൽ യാത്ര ചെയ്യുക. തലപ്പാവ് നൽകിയിട്ട് പറഞ്ഞു: ഇത് തലയിൽ കെട്ടുക. അപ്പോൾ അദ്ദേഹത്തിന്റെ ചില കൂട്ടുകാർ ചോദിച്ചു: അല്ലാഹു നിങ്ങൾക്ക് പൊറുത്തു തരട്ടെ. നിങ്ങൾ വിശ്രമിച്ചിരുന്ന കഴുതയെയും തലയിൽ കെട്ടിയിരുന്ന തലപ്പാവും അഅ്റാബിക്ക് നൽകിയതെന്തിനാണ്? അപ്പോൾ ഇബ്നുഉമർ(റ) പറഞ്ഞു: നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ഗുണങ്ങളിൽ വെച്ചേറ്റവും ഗുണമുള്ളത് ഒരാൾ തന്റെ പിതാവിന്റെ സ്നേഹിതരോട് അദ്ദേഹത്തിന്റെ മരണശേഷം ബന്ധം പുലർത്തലാണ്." അയാളുടെ പിതാവ് ഉമർ(റ)വിന്റെ കൂട്ടുകാരനായിരുന്നു. (മു,ദ,തു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 751, 751, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي الطُّفَيْلِ رضي الله عنهُ قال: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْسِمُ لَحْمًا بِالْجِعِرَّانَةِ، وَأَنَا يَوْمَئِذٍ غُلَامٌ أَحْمِلُ عَظْمَ الْجُزُورِ، إِذْ أَقْبَلَتِ امْرَأَةٌ حَتَّى دَنَتْ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَبَسَطَ لَهَا رِدَاءَهُ، فَجَلَسَتْ عَلَيْهِ، فَقُلْتُ: مَنْ هِيَ؟ فَقَالُوا: هَذِهِ أُمُّهُ الَّتِي أَرْضَعَتْهُ. (د)', 'അബു ഥുഫൈൽ(റ): നബി(സ) ജിഅ്റാനയിൽ വെച്ച് മാംസം വീതിക്കുന്നത് ഞാൻ കണ്ടു. ഞാൻ അന്ന് ഒട്ടകങ്ങളുടെ എല്ല് ചുമക്കുന്ന ഒരു കുട്ടിയായിരുന്നു. അപ്പോൾ ഒരു സ്ത്രീ വന്നു. തിരുനബി(സ)യുടെ അടുത്തെത്തി. അവിടന്ന് സ്ത്രീക്ക് വിരിപ്പ് വിരിച്ചു കൊടുത്തു. സ്ത്രീ അതിൽ ഇരുന്നു. ഞാൻ ചോദിച്ചു. ആരാണത്? അപ്പോൾ അവർ പറഞ്ഞു: ഇവർ നബി(സ)ക്ക് മുല കൊടുത്ത അവിടത്തെ ഉമ്മയാണ്. (ദ)', 'أَبِي الطُّفَيْلِ', 'അബു ഥുഫൈൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 751, 752, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عُمَرَ بْنِ السَّائِبِ أَنَّهُ بَلَغَهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ جَالِسًا فَأَقْبَلَ أَبُوهُ مِنَ الرَّضَاعَةِ، فَوَضَعَ لَهُ بَعْضَ ثَوْبِهِ فَقَعَدَ عَلَيْهِ، ثُمَّ أَقْبَلَتْ أُمُّهُ فَوَضَعَ لَهَا شِقَّ ثَوْبِهِ مِنْ جَانِبِهِ الْآخَرِ فَجَلَسَتْ عَلَيْهِ، ثُمَّ أَقْبَلَ أَخُوهُ مِنَ الرَّضَاعَةِ، فَقَامَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَجْلَسَهُ بَيْنَ يَدَيْهِ. (د)', 'ഉമറുബ്നു സാഇബ്(റ): റസൂൽ(സ) ഇരിക്കുകയായിരുന്നു. അപ്പോൾ തന്റെ മുലകുടി ബന്ധത്തിലുള്ള പിതാവ് വന്നു. നബി(സ) അവിടത്തെ ഒരു വസ്ത്രം അദ്ദേഹത്തിന് വിരിച്ച് കൊടുത്തു. അദ്ദേഹം അതിൻമേലിരുന്നു. പിന്നീട് തിരുനബി(സ)യുടെ (മുലകുടി ബന്ധത്തിലെ) ഉമ്മ വന്നു. അവർക്ക് നബി(സ) അവിടുത്തെ വസ്ത്രത്തിന്റെ ഭാഗം മറുഭാഗത്ത് വിരിച്ച് നൽകി മഹതി അതിലിരുന്നു. പിന്നെ മുലകുടി ബന്ധത്തിലെ സഹോദരൻ വന്നു. അദ്ദേഹത്തിന് വേണ്ടി റസൂൽ(സ) എണീറ്റ് കൊടുക്കുകയും മുമ്പിൽ അദ്ദേഹത്തെ ഇരുത്തുകയും ചെയ്തു. (ദ)', 'عُمَرَ بْنِ السَّائِبِ أَنَّهُ بَلَغَهُ', 'ഉമറുബ്നു സാഇബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 752, 752, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَبِي أُسَيْدٍ مَالِكِ بْنِ رَبِيعَةَ رضي الله عنهُ قال: بَيْنَمَا نَحْنُ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ رَجُلٌ مِنْ بَنِي سَلِمَةَ فَقَالَ: يَا رَسُولَ اللهِ، أَبَقِيَ مِنْ بِرِّ أَبَوَيَّ شَيْءٌ أَبَرُّهُمَا بِهِ مِنْ بَعْدِ مَوْتِهِمَا؟ قال: "نَعَمْ، الصَّلَاةُ عَلَيْهِمَا، وَالِاسْتِغْفَارُ لَهُمَا، وَإِيفَاءٌ بِعُهُودِهِمَا مِنْ بَعْدِ مَوْتِهِمَا، وَإِكْرَامُ صَدِيقِهِمَا، وَصِلَةُ الرَّحِمِ الَّتِي لَا تُوصَلُ إِلَّا بِهِمَا". (د,جه)', 'അബു ഉസൈദ് മാലികുബ്നു റബീഅ(റ): ഞങ്ങൾ നബി(സ)യുടെ അടുത്തുള്ളപ്പോൾ അവിടത്തെ സന്നിധിയിൽ ബനൂ സലമ ഗോത്രത്തിൽപ്പെട്ട ഒരാൾ വന്നിട്ട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ മാതാപിതാക്കളുടെ മരണ ശേഷം അവർക്ക് വേണ്ടി ഞാൻ ചെയ്യേണ്ട വല്ല നന്മയുമുണ്ടോ? നബി(സ) പറഞ്ഞു: "അതെ, അവരുടെ മേൽ നിസ്കരിക്കുക, അവർക്ക് വേണ്ടി പൊറുക്കലിനെ തേടുക, മരണശേഷം നിർവ്വഹിക്കാൻ പറഞ്ഞ അവരുടെ കരാറുകൾ നിറവേറ്റുക, അവരുടെ സുഹൃത്തിനെ ബഹുമാനിക്കുകയും അവരെക്കൊണ്ട് മാത്രം പുലർത്തപ്പെടുന്ന കുടുംബ ബന്ധം പുലർത്തുകയും ചെയ്യുക." (ദ,ജ)', 'أَبِي أُسَيْدٍ مَالِكِ بْنِ رَبِيعَةَ', 'അബു ഉസൈദ് മാലികുബ്നു റബീഅ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 752, 752, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ عَائِشَةَ رضي الله عنها زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: جَاءَتْنِي امْرَأَةٌ وَمَعَهَا ابْنَتَانِ لَهَا، فَسَأَلَتْنِي فَلَمْ تَجِدْ عِنْدِي شَيْئًا غَيْرَ تَمْرَةٍ وَاحِدَةٍ، فَأَعْطَيْتُهَا إِيَّاهَا، فَأَخَذَتْهَا فَقَسَمَتْهَا بَيْنَ ابْنَتَيْهَا وَلَمْ تَأْكُلْ مِنْهَا شَيْئًا، ثُمَّ قَامَتْ فَخَرَجَتْ وَابْنَتَاهَا، فَدَخَلَ عَلَيَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَحَدَّثْتُهُ حَدِيثَهَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنِ ابْتُلِيَ مِنَ الْبَنَاتِ بِشَيْءٍ، فَأَحْسَنَ إِلَيْهِنَّ، كُنَّ لَهُ سِتْرًا مِنَ النَّارِ". (م,ت)', 'പ്രവാചക പത്നിയായ ആഇശ(റ): എന്റെയടുത്ത് ഒരു സ്ത്രീ വന്നു. അവളുടെ കൂടെ രണ്ട് പെൺമക്കളുമുണ്ട്. അവൾ എന്നോട് യാചിച്ചു: എന്റെയടുത്ത് ഒരു കാരക്ക മാത്രമാണ് അവൾക്ക് കൊടുക്കാനുണ്ടായിരുന്നത്. ഞാനതവൾക്ക് നൽകി. അവളതെടുത്ത് അത് തന്റെ രണ്ട് കുട്ടികൾക്കിയടിൽ വീതിച്ചു. അവൾ അതിൽ നിന്നൊന്നും കഴിച്ചില്ല. പിന്നെ അവൾ എണീറ്റു. കുട്ടികളെയും കൂട്ടി പുറപ്പെട്ടു. അപ്പോൾ നബി(സ) എന്റെയടുത്ത് വന്നു. ഞാൻ തിരുമേനി(സ)ക്ക് അവളുടെ വാർത്ത പറഞ്ഞു കൊടുത്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഒരാൾ പെൺമക്കളെ കൊണ്ട് വല്ലതിലും പരീക്ഷിക്കപ്പെടുകയും അവർക്ക് നന്മ ചെയ്യുകയും ചെയ്താൽ അവർ അവന് നരകത്തിൽ നിന്ന് മറയായി മാറുന്നതാണ്." (മു,തു)', 'عَائِشَةَ', 'പ്രവാചക പത്നിയായ ആഇശ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 752, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ عَالَ جَارِيَتَيْنِ حَتَّى تَبْلُغَا جَاءَ يَوْمَ الْقِيَامَةِ أَنَا وَهُوَ" وَضَمَّ أَصَابِعَهُ. (م,ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ രണ്ട് പെൺമക്കളെ, പ്രായപൂർത്തിയാകുന്നത് വരെ പോറ്റി വളർത്തിയാൽ ഞാനും അവനും ഒപ്പം അന്ത്യദിനത്തിൽ വരും." നബി(സ) അവിടത്തെ വിരലുകൾ ചേർത്ത് വെച്ചു. (മു,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 753, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رضي الله عنهما قال: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْخُذُنِي فَيُقْعِدُنِي عَلَى فَخِذِهِ، وَيُقْعِدُ الْحَسَنَ عَلَى فَخِذِهِ الْأُخْرَى، ثُمَّ يَضُمُّهُمَا، ثُمَّ يَقُولُ: "اللَّهُمَّ ارْحَمْهُمَا فَإِنِّي أَرْحَمُهُمَا". (خ)', 'ഉസാമതുബ്നു സൈദ്(റ): റസൂൽ(സ) എന്നെ എടുത്ത് അവിടുത്തെ തുടയിൽ ഇരുത്തുമായിരുന്നു. ഹസൻ(റ)വിനെ മറ്റേ തുടയിലും ഇരുത്തും. പിന്നെ രണ്ട് പേരെയും ചേർത്ത് പിടിച്ച് പറയും: "അല്ലാഹുവേ, നീ ഇവർക്ക് കരുണ ചെയ്യണേ, ഞാനവരോട് കരുണ ചെയ്യുന്നുണ്ട്." (ബു)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 753, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ عَائِشَةَ رضي الله عنها قَالَتْ: قَدِمَ نَاسٌ مِنَ الْأَعْرَابِ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: أَتُقَبِّلُونَ صِبْيَانَكُمْ؟ قَالُوا: نَعَمْ. فَقَالُوا: لَكِنَّا وَاللهِ مَا نُقَبِّلُ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَأَمْلِكُ أَنْ كَانَ اللهُ قَدْ نَزَعَ مِنْكُمُ الرَّحْمَةَ". (م,جه)', 'ആഇശ(റ): അഅ്റാബികളായ ചിലർ നബി(സ)യുടെ അടുത്ത് വന്നു. അവർ ചോദിച്ചു: നിങ്ങളുടെ കുട്ടികളെ നിങ്ങൾ ചുംബിക്കാറുണ്ടോ? റസൂൽ(സ)യുടെ അനുചരർ പറഞ്ഞു: അതെ, അപ്പോൾ അവർ പറഞ്ഞു: പക്ഷേ, അല്ലാഹു തന്നെ സത്യം. ഞങ്ങൾ ചുംബിക്കില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ നിന്നല്ലാഹു അനുഗ്രഹം എടുത്ത് കളഞ്ഞെങ്കിൽ എനിക്ക് എന്ത് ചെയ്യാൻ കഴിയും". (മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 753, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ يَعْلَى بْنِ مُرَّةَ الْعَامِرِيِّ رضي الله عنهُ قال: جَاءَ الْحَسَنُ وَالْحُسَيْنُ _ رضي الله عنهما _ يَسْعَيَانِ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَضَمَّهُمَا إِلَيْهِ، وَقَالَ: "إِنَّ الْوَلَدَ مَبْخَلَةٌ مَجْبَنَةٌ". (جه)', 'യഅ്ലബ്നു മുർറതുൽ ആമിരീ(റ): ഹസൻ(റ)വും ഹുസൈൻ(റ)വും നബി(സ)യുടെ അടുത്തേക്ക് ഓടി വന്നു. അവർ രണ്ടു പേരെയും നബി(സ) അവിടത്തോട് ചേർത്തു പിടിച്ചു. എന്നിട്ട് പറഞ്ഞു: "മകൻ പിശുക്കിനും ഭീരുത്വത്തിനും കാരണമാണ്." (ജ)', 'يَعْلَى بْنِ مُرَّةَ الْعَامِرِيِّ', 'യഅ്ലബ്നു മുർറതുൽ ആമിരീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 753, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ سُرَاقَةَ بْنِ مَالِكٍ رضي الله عنهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "أَلَا أَدُلُّكُمْ عَلَى أَفْضَلِ الصَّدَقَةِ؟ ابْنَتُكَ مَرْدُودَةً إِلَيْكَ، لَيْسَ لَهَا كَاسِبٌ غَيْرُكَ". (جه)', 'സുറാഖതുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് ഞാൻ ഏറ്റവും ഉത്തമമായ ധർമ്മം പറഞ്ഞ് തരട്ടെയോ? നിന്റെ മകൾ നിന്നിലേക്ക് മടക്കപ്പെട്ട് അവൾക്ക് സമ്പാദിക്കാൻ നീയല്ലാതെ ആരുമില്ലാത്ത അവസ്ഥ(യിൽ അവൾക്ക് നന്മയചെയ്യൽ)." (ജ)', 'سُرَاقَةَ بْنِ مَالِكٍ', 'സുറാഖതുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 753, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ صَعْصَعَةَ – عَمِّ الْأَحْنَفِ – قَالَ: دَخَلَتْ عَلَى عَائِشَةَ رضي الله عنها امْرَأَةٌ مَعَهَا ابْنَتَانِ لَهَا، فَأَعْطَتْهَا ثَلَاثَ تَمَرَاتٍ، فَأَعْطَتْ كُلَّ وَاحِدَةٍ مِنْهُمَا تَمْرَةً، ثُمَّ صَدَعَتِ الْبَاقِيَةَ بَيْنَهُمَا، قَالَتْ: فَأَتَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَحَدَّثْتُهُ، فَقَالَ: "مَا عَجَبُكِ؟ لَقَدْ دَخَلَتْ بِهِ الْجَنَّةَ". (جه)', 'സ്വഅ്സ്വഅ്(റ) (അഹ്നഫ്(റ)വിന്റെ പിതൃസഹോദരൻ): ആഇശ(റ)യുടെ അടുക്കൽ രണ്ട് പെൺമക്കളുമായി ഒരു സ്ത്രീ വന്നു. ആഇശ(റ) അവൾക്ക് മൂന്ന് കാരക്ക നൽകി. സ്ത്രീ രണ്ട് പേർക്കും ഓരോ കാരക്ക വീതം നൽകി. ബാക്കിയുള്ളത് അവർക്കിടയിൽ വീതിച്ചു. ആഇശ(റ) പറയുന്നു: അപ്പോൾ നബി(സ) വന്നു: നബി(സ)യോട് ഞാൻ വിഷയം പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ എന്തിന് അത്ഭുതപ്പെടുന്നു അത് കാരണം അവൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിച്ചിരിക്കുന്നു." (ജ)', 'صَعْصَعَةَ – عَمِّ الْأَحْنَفِ – قَالَ', 'സ്വഅ്സ്വഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 753, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رضي الله عنهُ قال: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ كَانَ لَهُ ثَلَاثُ بَنَاتٍ، فَصَبَرَ عَلَيْهِنَّ وَأَطْعَمَهُنَّ وَسَقَاهُنَّ وَكَسَاهُنَّ مِنْ جِدَتِهِ، كُنَّ لَهُ حِجَابًا مِنَ النَّارِ يَوْمَ الْقِيَامَةِ". (جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരാൾക്ക് മൂന്ന് പെൺമക്കളുണ്ടായിട്ട് അവരുടെ കാര്യത്തിൽ ക്ഷമിക്കുകയും തന്റെ ഐശ്വര്യത്തിൽ നിന്ന് അവരെ ഭക്ഷിപ്പിക്കുകയും കുടിപ്പിക്കുകയും ധരിപ്പിക്കുകയും ചെയ്താൽ അവർ അവന് അന്ത്യദിനത്തിൽ നരകത്തിൽ നിന്ന് മറയാകുന്നതാണ്." (ജ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 754, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ رَجُلٍ تُدْرِكُ لَهُ ابْنَتَانِ، فَيُحْسِنُ إِلَيْهِمَا مَا صَحِبَتَاهُ، أَوْ صَحِبَهُمَا، إِلَّا أَدْخَلَتَاهُ الْجَنَّةَ". فِي سَنَدِهِ رَاوٍ مُخْتَلَفٌ فِيهِ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾക്ക് രണ്ട് പെൺമക്കളുണ്ടാകുകയും അവർ ഇവനോട് സഹവസിക്കുന്ന കാലമത്രയും അല്ലെങ്കിൽ ഇവൻ അവരോട് സഹവസിക്കുന്ന കാലമത്രയും അവർക്ക് നന്മ ചെയ്യുകയും ചെയ്താൽ അവർ ഇവനെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കാതിരിക്കില്ല." പരമ്പരയിലെ ഒരു നിവേദകനെക്കുറിച്ച് വ്യത്യസ്താഭിപ്രായമുണ്ട്. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 754, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رضي الله عنهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَأَنْ يُؤَدِّبَ الرَّجُلُ وَلَدَهُ خَيْرٌ مِنْ أَنْ يَتَصَدَّقَ بِصَاعٍ". (ت)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ മകന് മര്യാദ പഠിപ്പിച്ചു കൊടുക്കുന്നത് ഒരു സ്വാഅ് ധർമ്മം ചെയ്യുന്നതിനേക്കാൾ ഉത്തമമാണ്." (തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 754, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ سَعِيدِ بْنِ الْعَاصِ رضي الله عنهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "مَا نَحَلَ وَالِدٌ وَلَدًا مِنْ نَحْلٍ أَفْضَلَ مِنْ أَدَبٍ حَسَنٍ". (ت)', 'സഈദുബ്നുൽ ആസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു പിതാവും തന്റെ മകന് നല്ല മര്യാദയേക്കാൾ ഉത്തമമായ ഒരു സമ്മാനവും നൽകിയിട്ടില്ല." (തു)', 'سَعِيدِ بْنِ الْعَاصِ', 'സഈദുബ്നുൽ ആസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 754, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: ": مَنْ كَانَتْ لَهُ أُنْثَى فَلَمْ يَئِدْهَا وَلَمْ يُهِنْهَا وَلَمْ يُؤْثِرْ وَلَدَهُ عَلَيْهَا_ يَعْنِي: الذُّكُورَ_ أَدْخَلَهُ اللهُ الْجَنَّةَ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾക്ക് ഒരു പെൺകുട്ടിയുണ്ടായിട്ട്, അവളെ കുഴിച്ച് മൂടുകയോ, നിന്ദിക്കുകയോ, തന്റെ ആൺമക്കൾക്ക് അവളേക്കാൾ പരിഗണന നൽകുകയോ ചെയ്തിട്ടില്ലെങ്കിൽ അല്ലാഹു അവനെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കും." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 754, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رضي الله عنهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ عَالَ ثَلَاثَ بَنَاتٍ، فَأَدَّبَهُنَّ وَزَوَّجَهُنَّ وَأَحْسَنَ إِلَيْهِنَّ، فَلَهُ الْجَنَّةُ". وَفِي رِوَايَةٍ: "ثَلَاثُ أَخَوَاتٍ، أَوْ ثَلَاثُ بَنَاتٍ، أَوْ بِنْتَانِ، أَوْ أُخْتَانِ". (د,ت)', 'അബൂ സഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും മൂന്ന് പെൺമക്കളെ വളർത്തുകയും, അവർക്ക് മര്യാദ പഠിപ്പിക്കുകയും, വിവാഹം കഴിച്ചുകൊടുക്കുകയും അവർക്ക് നന്മ ചെയ്യുകയും ചെയ്താൽ, അവന് സ്വർഗ്ഗമുണ്ട്." മറ്റൊരു നിവേദനത്തിൽ: "മൂന്ന് സഹോദരികൾ, അല്ലെങ്കിൽ മൂന്ന് പെൺമക്കൾ, അല്ലെങ്കിൽ രണ്ട് പെൺമക്കൾ, അല്ലെങ്കിൽ രണ്ട് സഹോദരിമാർ." (ദ,തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂ സഈദിൽ ഖുദ്രി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 754, 755, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=36), 1, 'وَفِي رِوَايَةٍ: "ثَلَاثُ أَخَوَاتٍ، أَوْ ثَلَاثُ بَنَاتٍ، أَوْ بِنْتَانِ، أَوْ أُخْتَانِ". (د,ت)', 'മറ്റൊരു നിവേദനത്തിൽ: "മൂന്ന് സഹോദരികൾ, അല്ലെങ്കിൽ മൂന്ന് പെൺമക്കൾ, അല്ലെങ്കിൽ രണ്ട് പെൺമക്കൾ, അല്ലെങ്കിൽ രണ്ട് സഹോദരിമാർ." (ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنهُ، يُحَدِّثُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "أَكْرِمُوا أَوْلَادَكُمْ، وَأَحْسِنُوا أَدَبَهُمْ". فِي سَنَدِهِ مُخْتَلَفٌ فِيهِ (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ സന്താനങ്ങളെ നിങ്ങൾ ബഹുമാനിക്കുക, അവരുടെ സ്വഭാവം നന്നാക്കുക." പരമ്പരയിലെ ഒരു നിവേദകനെക്കുറിച്ച് വ്യത്യസ്താഭിപ്രായമുണ്ട്. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 755, 755, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ خَوْلَةَ بِنْتِ حَكِيمٍ رضي الله عنها قَالَتْ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ وَهُوَ مُحْتَضِنٌ أَحَدَ ابْنَيِ ابْنَتِهِ، وَهُوَ يَقُولُ: "إِنَّكُمْ لَتُبَخِّلُونَ وَتُجَبِّنُونَ وَتُجَهِّلُونَ، وَإِنَّكُمْ لَمِنْ رَيْحَانِ اللهِ". (ت)', 'ഖൗലതു ബിൻത് ഹകീം(റ): ഒരു ദിവസം റസൂൽ(സ) അവിടുത്തെ മകളുടെ രണ്ടാലൊരു കുട്ടിയെ കൂട്ടിയണച്ച് പിടിച്ച്കൊണ്ട് പുറപ്പെട്ടു. തിരുദൂതർ(സ) പറയുന്നുണ്ട്: "നിങ്ങൾ പിശുക്കരാക്കുകയും ഭീരുക്കളാക്കുകയും വിഡ്ഢികളാക്കുകയും ചെയ്യും. നിങ്ങൾ അല്ലാഹുവിന്റെ അനുഗ്രഹത്തിൽ പെട്ടവരാണ്." (തു)', 'خَوْلَةَ بِنْتِ حَكِيمٍ', 'ഖൗലതു ബിൻത് ഹകീം(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 755, 755, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ قال: أَبْصَرَ الْأَقْرَعُ بْنُ حَابِسٍ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُقَبِّلُ الْحُسَيْنَ أَوِ الْحَسَنَ، فَقَالَ: إِنَّ لِي مِنَ الْوَلَدِ عَشَرَةً، مَا قَبَّلْتُ أَحَدًا مِنْهُمْ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهُ مَنْ لَا يَرْحَمْ لَا يُرْحَمْ". حَسَنٌ صَحِيحٌ (ق,ت)', 'അബൂഹുറൈറ(റ): അഖ്റഉബ്നു ഹാബിസ്(റ) നബി(സ) ഹസൻ(റ)വിനെയോ ഹുസൈൻ(റ)വിനെയോ ചുംബിക്കുന്നത് കണ്ടു. അദ്ദേഹം പറഞ്ഞു: എനിക്ക് പത്ത് മക്കളുണ്ട്. ഞാൻ അവരിൽ ആരെയും ചുംബിച്ചിട്ടില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം കരുണ ചെയ്യാത്തവൻ കരുണ ചെയ്യപ്പെടില്ല." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 755, 755, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رضي الله عنهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ لَهُ ثَلَاثُ بَنَاتٍ، أَوْ ثَلَاثُ أَخَوَاتٍ، أَوِ ابْنَتَانِ، أَوْ أُخْتَانِ: فَأَحْسَنَ صُحْبَتَهُنَّ، وَاتَّقَى اللهَ فِيهِنَّ، فَلَهُ الْجَنَّةُ". (د,ت)', 'അബൂ സഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾക്ക് മൂന്ന് പെൺമക്കളോ, മൂന്ന് സഹോദരികളോ, അല്ലെങ്കിൽ രണ്ട് പെൺകുട്ടികളോ, രണ്ട് സഹോദരികളോ ഉണ്ടായിട്ട് അവരുമായുള്ള സഹവാസം നന്നാക്കുകയും, അവരുടെ വിഷയത്തിൽ അല്ലാഹുവിനെ സൂക്ഷിക്കുകയും ചെയ്താൽ അവന് സ്വർഗ്ഗമുണ്ട്." (ദ,തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂ സഈദിൽ ഖുദ്രി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 755, 755, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رضي الله عنهُ قال: قُدِمَ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِسَبْيٍ، فَإِذَا امْرَأَةٌ مِنَ السَّبْيِ تَحْلُبُ ثَدْيَهَا، تَسْقِي، إِذَا وَجَدَتْ صَبِيًّا فِي السَّبْيِ أَخَذَتْهُ فَأَلْصَقَتْهُ بِبَطْنِهَا وَأَرْضَعَتْهُ، فَقَالَ لَنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: ": أَتَرَوْنَ هَذِهِ طَارِحَةً وَلَدَهَا فِي النَّارِ" قُلْنَا: لَا، وَهِيَ تَقْدِرُ عَلَى أَنْ لَا تَطْرَحَهُ؟ فَقَالَ: لَلَّهُ أَرْحَمُ بِعِبَادِهِ مِنْ هَذِهِ بِوَلَدِهَا". (خ)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): തിരുനബി(സ)യുടെ അടുക്കൽ ഒരു സംഘം ബന്ധികളെ കൊണ്ടു വന്നു. കൂട്ടത്തിലുണ്ടായിരുന്ന ഒരു സ്ത്രീ (മുലപ്പാൽ കൂടുതലായുണ്ടായിരുന്നത് കാരണം) തന്റെ മുലപ്പാൽ കറന്നെടുത്ത് കൊണ്ടിരുന്നു. സംഘത്തിലെ വല്ല കുട്ടിയെയും കണ്ടാൽ അവൾ അതിനെ മാറോട് ചേർത്ത് മുലകൊടുക്കും. തിരുമേനി(സ) ചോദിച്ചു: "ഇവർ സ്വന്തം കുഞ്ഞിനെ തീയിലെറിയുമെന്ന് നിങ്ങൾക്ക് തോന്നുന്നുണ്ടോ?" ഞങ്ങൾ പറഞ്ഞു: ഇല്ല, വല്ല മാർഗ്ഗവുമുണ്ടെങ്കിൽ അവൾ എറിയുകയില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇവൾക്ക് തന്റെ കുഞ്ഞിനോടുള്ളതിനേക്കാൾ കൂടുതൽ, അല്ലാഹു തന്റെ അടിമകളോട് കരുണയുള്ളവനാണ്." (ബു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 755, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنهُ يَقُولُ: جَاءَ شَيْخٌ يُرِيدُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَبْطَأَ الْقَوْمُ عَنْهُ أَنْ يُوَسِّعُوا لَهُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ مِنَّا مَنْ لَمْ يَرْحَمْ صَغِيرَنَا وَيُوَقِّرْ كَبِيرَنَا". (ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യെ ലക്ഷ്യം വെച്ച് ഒരു വൃദ്ധൻ വന്നു. അദ്ദേഹത്തിന് സ്ഥലം നൽകാൻ അൽപം താമസിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നമ്മിലെ ചെറിയവരോട് കരുണ കാണിക്കാത്തവനും, വലിയവരെ ബഹുമാനിക്കാത്തവനും നമ്മിൽപ്പെട്ടവനല്ല." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 756, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ مِنَّا مَنْ لَمْ يَرْحَمْ صَغِيرَنَا، وَيُوَقِّرْ كَبِيرَنَا، وَيَأْمُرْ بِالْمَعْرُوفِ وَيَنْهَ عَنِ الْمُنْكَرِ" حسن. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നമ്മിലുള്ള ചെറിയവരോട് കരുണ കാണിക്കാത്തവനും, നമ്മളിലെ വലിയവരെ ബഹുമാനിക്കാത്തവനും നന്മ കൽപിക്കാത്തവനും തിന്മ തടയാത്തവനും നമ്മിൽപ്പെട്ടവനല്ല." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 756, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رضي الله عنهما، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "الْخَالَةُ بِمَنْزِلَةِ الْأُمِّ" وَفِي الْحَدِيثِ قِصَّةٌ طَوِيلَةٌ. صَحِيحٌ. (ت)', 'ബറാഉബ്നു ആസിബ്(റ): നബി(സ) പറഞ്ഞു: "മാതൃസഹോദരി, ഉമ്മയുടെ സ്ഥാനത്താണ്" ഈ ഹദീസിന്റെ പശ്ചാത്തലത്തിൽ ഒരു നീണ്ടചരിത്രമുണ്ട്. (തു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 756, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ ابْنِ عُمَرَ رضي الله عنهما: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي أَصَبْتُ ذَنْبًا عَظِيمًا، فَهَلْ لِي مِنْ تَوْبَةٍ؟ قَالَ: "هَلْ لَكَ مِنْ أُمٍّ". قَالَ: لَا. قَالَ: "هَلْ لَكَ مِنْ خَالَةٍ". قَالَ: نَعَمْ. قَالَ: فَبِرَّهَا". (ت)', 'ഇബ്നുഉമർ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ വലിയൊരു പാപം ചെയ്തു. എനിക്ക് പശ്ചാത്താപത്തിന് വല്ല വഴിയുമുണ്ടോ? നബി(സ) ചോദിച്ചു: "നിങ്ങൾക്ക് ഉമ്മയുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. നബി(സ) ചോദിച്ചു: "നിങ്ങൾക്ക് മാതൃസഹോദരിയുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഉണ്ട്. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങളവർക്ക് ഗുണം ചെയ്യുക." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 756, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنهُ قال: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ سَرَّهُ أَنْ يُبْسَطَ عَلَيْهِ رِزْقُهُ أَوْ يُنْسَأَ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ". (م)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും തന്റെ ഭക്ഷണം വിശാലമാകാനും ആയുസ്സ് ദീർഘിക്കാനും ആഗ്രഹിക്കുന്നെങ്കിൽ തന്റെ കുടുംബബന്ധം പുലർത്തട്ടെ." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 756, 757, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ أَنَّ رَجُلًا قال: يَا رَسُولَ اللهِ، إِنَّ لِي قَرَابَةً أَصِلُهُمْ وَيَقْطَعُونِي، وَأُحْسِنُ إِلَيْهِمْ وَيُسِيئُونَ إِلَيَّ، وَأَحْلُمُ عَنْهُمْ وَيَجْهَلُونَ عَلَيَّ. فَقَالَ: "لَئِنْ كُنْتَ كَمَا قُلْتَ فَكَأَنَّمَا تُسِفُّهُمُ الْمَلَّ، وَلَا يَزَالُ مَعَكَ مِنَ اللهِ ظَهِيرٌ عَلَيْهِمْ مَا دُمْتَ عَلَى ذَلِكَ". (م)', 'അബൂഹുറൈറ(റ): ഒരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്കൊരു കുടുംബമുണ്ട്. അവരോടുള്ള ബന്ധം ഞാൻ പുലർത്തുന്നു. അവർ എന്നോടുള്ള ബന്ധം മുറിക്കുന്നു. അവർക്ക് ഞാൻ നന്മ ചെയ്യുന്നു. അവരെന്നോട് തിന്മ കാണിക്കുന്നു. ഞാനവരോട് സഹിഷ്ണുത കാണിക്കുന്നു. അവർ എന്നോട് അസഹിഷ്ണുത കാണിക്കുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ പറഞ്ഞത് പ്രകാരമാണെങ്കിൽ നീ അവരെ ചുടുവെണ്ണീർ തീറ്റിക്കുന്നത് പോലെയാണ്. നീ ഇപ്രകാരമായിക്കൊണ്ടിരിക്കുമ്പോഴൊക്കെ, നിനക്ക് അല്ലാഹുവിൽ നിന്ന് അവരുടെ മേൽ ഒരു സഹായി ഉണ്ടായിക്കൊണ്ടിരിക്കും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 757, 757, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رضي الله عنهما عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "لَيْسَ الْوَاصِلُ بِالْمُكَافِئِ وَلَكِنَّ الْوَاصِلَ الَّذِي إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا". (خ,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "പ്രത്യുപകാരം ചെയ്യുന്നവനല്ല കുടുംബ ബന്ധം ചേർക്കുന്നവൻ, മറിച്ച് തന്റെ കുടുംബബന്ധം മുറിയുമ്പോൾ അത് പുലർത്തുന്നവനാണ് കുടുംബബന്ധം ചേർക്കുന്നവൻ." (ബു,തു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 757, 757, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ خَلَقَ الْخَلْقَ، حَتَّى إِذَا فَرَغَ مِنْهُمْ قَامَتِ الرَّحِمُ فَقَالَتْ: هَذَا مَقَامُ الْعَائِذِ مِنَ الْقَطِيعَةِ، قَالَ: نَعَمْ، أَمَا تَرْضَيْنَ أَنْ أَصِلَ مَنْ وَصَلَكِ، وَأَقْطَعَ مَنْ قَطَعَكِ؟ قَالَتْ: بَلَى، قَالَ: فَذَاكِ لَكِ" ثُمَّ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اقْرَءُوا إِنْ شِئْتُمْ: {فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ. أُولَئِكَ الَّذِينَ لَعَنَهُمُ اللهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ. أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا} [محمّد: ٢٢-٢٤]" (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു സൃഷ്ടികളെ പടച്ചു. അല്ലാഹു സൃഷ്ടിപ്പിൽ നിന്ന് വിരമിച്ചപ്പോൾ കുടുംബബന്ധം എണീറ്റ് കൊണ്ട് പറഞ്ഞു: ഇത് കുടുംബബന്ധം മുറിക്കുന്നതിൽ നിന്ന് കാവൽ ചോദിക്കുന്നവരുടെ സ്ഥാനമാണ്. അല്ലാഹു പറഞ്ഞു: അതെ, നിന്നോട് ബന്ധം പുലർത്തിയവരോട് ഞാൻ ബന്ധം പുലർത്തുന്നതും നിന്നോട് ബന്ധം വിഛേദിച്ചവരോട് ഞാൻ ബന്ധം വിഛേദിക്കുന്നതും നീ ഇഷ്ടപ്പെടുന്നില്ലേ?" കുടുംബബന്ധം പറഞ്ഞു: അതെ. അല്ലാഹു പറഞ്ഞു: അത് നിനക്കുള്ളതാണ്." പിന്നെ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ ഓതുക: (എന്നാൽ നിങ്ങൾ അധികാരം നേടിയാൽ ഭൂമിയിൽ പ്രശ്നമുണ്ടാക്കുകയും നിങ്ങളുടെ കുടുംബബന്ധങ്ങൾ മുറിക്കുകയും ചെയ്തേക്കുമോ? അക്കൂട്ടർ അല്ലാഹു ശപിച്ചവരാണ്. അങ്ങനെ അവരെ അവൻ ബധിരരാക്കുകയും അന്ധരാക്കുകയും ചെയ്തിരിക്കുന്നു. അവർ ഖുർആനിൽ ചിന്തിക്കുന്നില്ലേ, അതോ അവരുടെ ഹൃദയങ്ങളുടെ മേൽ പൂട്ടുകളുണ്ടോ)"-മുഹമ്മദ്: 22-24 (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'محمّد: ٢٢-٢٤', null, 757, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رضي الله عنهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "لَا يَدْخُلُ الْجَنَّةَ قَاطِعٌ". قَالَ ابْنُ أَبِي عُمَرَ: قال: سُفْيَانُ: يَعْنِي قَاطِعَ رَحِمٍ. (ق,ت)', 'ജുബൈറുബ്നു മുത്ഇം(റ): നബി(സ) പറഞ്ഞു: "ബന്ധം മുറിക്കുന്നവർ സ്വർഗത്തിൽ പ്രവേശിക്കുകയില്ല." ഇബ്നു അബീ ഉമർ(റ) പറയുന്നു: സുഫ്യാൻ(റ) പറഞ്ഞു: കുടുംബബന്ധം മുറിക്കുന്നവനെയാണ് ഉദ്ദേശിക്കുന്നത്. (ബു,മു,തു)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 758, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنه عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "إِنَّ الرَّحِمَ شَجْنَةٌ مِنَ الرَّحْمَنِ، فَقَالَ اللهُ: مَنْ وَصَلَكِ وَصَلْتُهُ، وَمَنْ قَطَعَكِ قَطَعْتُهُ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "കുടുംബബന്ധം റഹ്മാനി(പരമകാരുണ്യവാനി)ൽ നിന്നുള്ള ഒരു കൊമ്പാണ്. അല്ലാഹു പറഞ്ഞു: നിന്നോട് ബന്ധം പുലർത്തുന്നവനോട് ഞാൻ ബന്ധം പുലർത്തും. നിന്നോട് ബന്ധം വിഛേദിച്ചവനോട് ഞാനും ബന്ധം വിഛേദിക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 758, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَمْرِو بْنِ الْعَاصِ رضي الله عنهُ قال: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جِهَارًا غَيْرَ سِرٍّ يَقُولُ: "إِنَّ آلَ أَبِي فُلَانٍ لَيْسُوا بِأَوْلِيَائِي، إِنَّمَا وَلِيِّيَ اللهُ وَصَالِحُ الْمُؤْمِنِينَ، وَلَكِنْ لَهُمْ رَحِمٌ أَبُلُّهَا بِبِلَالِهَا". (خ)', 'അംറുബ്നുൽ ആസ്(റ): ഞാൻ നബി(സ) ഉറക്കെ പറയുന്നത് കേട്ടു: "ഇന്നാലിന്നയാളുടെ കുടുംബം എന്റെ സഹായികളല്ല. എന്റെ സഹായി അല്ലാഹുവും സൽവൃത്തരായ മുഅ്മിനുകളുമാണ്. പക്ഷേ, അവർക്ക് കുടുംബബന്ധമുണ്ട്. അതിന്റെ നനവ് കൊണ്ട് ഞാനതിനെ നനക്കും." (ബു)', 'عَمْرِو بْنِ الْعَاصِ', 'അംറുബ്നുൽ ആസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 758, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ رضي الله عنهُ قال: اشْتَكَى أَبُو الرَّدَّادِ اللَّيْثِيُّ، فَعَادَهُ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ رضي الله عنهُ، فَقَالَ: خَيْرُهُمْ وَأَوْصَلُهُمْ – مَا عَلِمْتُ – أَبُو مُحَمَّدٍ. فَقَالَ عَبْدُ الرَّحْمَنِ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "قَالَ اللهُ: أَنَا اللهُ، وَأَنَا الرَّحْمَنُ، خَلَقْتُ الرَّحِمَ وَشَقَقْتُ لَهَا مِنْ اسْمِي، فَمَنْ وَصَلَهَا وَصَلْتُهُ، وَمَنْ قَطَعَهَا بَتَتُّهُ" صحيحٌ. (د,ت)', 'അബൂസലമതുബ്നു അബ്ദിറഹ്മനിബ്നി ഔഫ്(റ): അബുർദ്ദാദുല്ലൈസി(റ)വിന് രോഗം ബാധിച്ചു. അദ്ദേഹത്തെ അബ്ദുർറഹ്മാനു ബ്നു ഔഫ്(റ) സന്ദർശിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അവരിൽ ഏറ്റവും ഉത്തമനും ഏറ്റവും കൂടുതൽ ബന്ധം പുലർത്തുന്നവനും - ഞാനറിയുന്നതിൽ വെച്ച് - അബു മുഹമ്മദാണ്. അപ്പോൾ അബ്ദുർറഹ്മാൻ(റ) പറഞ്ഞു: ഞാൻ റസൂൽ(സ) പറയുന്നത് കേട്ടു: "അല്ലാഹു പറഞ്ഞിരിക്കുന്നു: ഞാൻ അല്ലാഹുവാണ്, ഞാൻ റഹ്മാനാണ്. ഞാൻ കുടുംബബന്ധം സൃഷ്ടിച്ചു. അതിന് ഞാനെന്റെ നാമത്തിൽ നിന്നെടുത്ത നാമം നൽകി. അത് ആരെങ്കിലും ചേർത്താൽ അവനെ ഞാനും ചേർക്കും. അത് ആരെങ്കിലും വിഛേദിച്ചാൽ അവനെ ഞാനും വിഛേദിക്കും." (ദ,തു)', 'أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ', 'അബൂസലമതുബ്നു അബ്ദിറഹ്മനിബ്നി ഔഫ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 758, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ رضي الله عنهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "نَفَقَةُ الرَّجُلِ عَلَى أَهْلِهِ صَدَقَةٌ". حَسَنٌ صَحِيحٌ. (ق,ت,ن)', 'അബൂമസ്ഊദിൽ അൻസാരി(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ കുടുംബത്തിന് വേണ്ടി ചെലവഴിക്കുന്നത് ധർമ്മമാണ്." (ബു,മു,തു,ന)', 'أَبِي مَسْعُودٍ الْأَنْصَارِيِّ', 'അബൂമസ്ഊദിൽ അൻസാരി(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 758, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ ثَوْبَانَ رضي الله عنهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: أَفْضَلُ الدِّينَارِ دِينَارٌ يُنْفِقُهُ الرَّجُلُ عَلَى عِيَالِهِ، وَدِينَارٌ يُنْفِقُهُ الرَّجُلُ عَلَى دَابَّتِهِ فِي سَبِيلِ اللهِ، وَدِينَارٌ يُنْفِقُهُ الرَّجُلُ عَلَى أَصْحَابِهِ فِي سَبِيلِ اللهِ". ثُمَّ قَالَ: فَأَيُّ رَجُلٍ أَعْظَمُ أَجْرًا مِنْ رَجُلٍ يُنْفِقُ عَلَى عِيَالٍ لَهُ صِغَارٍ، يُعِفُّهُمُ اللهُ بِهِ وَيُغْنِيهِمُ اللهُ بِهِ" حَسَنٌ صَحِيحٌ. (م,ت,جه)', 'സൗബാൻ(റ): നബി(സ) പറഞ്ഞു: "ഏറ്റവും ഉത്തമമായ ദീനാർ ഒരാൾ തന്റെ കുടുംബത്തിന് വേണ്ടി ചെലവഴിക്കുന്നതും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടാനുള്ള തന്റെ മൃഗത്തിന് വേണ്ടി ചെലഴിക്കുന്നതും, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുന്ന തന്റെ കൂട്ടുകാർക്ക് വേണ്ടി ചെലവഴിക്കുന്നതുമാണ്."പിന്നെ നബി(സ) പറഞ്ഞു: "തന്റെ ചെറിയ മക്കൾക്ക് വേണ്ടി ചെലവഴിക്കുന്നവനേക്കാൾ പ്രതിഫലം കിട്ടുന്നവൻ ആരാണുള്ളത്? അവൻ കാരണം അല്ലാഹു അവരെ സച്ചരിതരാക്കും. അവൻ കാരണം അല്ലാഹു അവരെ ഐശ്വര്യരാക്കും." (മു,തു,ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 759, 759, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "الْقِنْطَارُ اثْنَا عَشَرَ أَلْفَ أُوقِيَّةٍ، كُلُّ أُوقِيَّةٍ خَيْرٌ مِمَّا بَيْنَ السَّمَاءِ وَالْأَرْضِ". وَ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الرَّجُلَ لَتُرْفَعُ دَرَجَتُهُ فِي الْجَنَّةِ، فَيَقُولُ: أَنَّى هَذَا؟ فَيُقَالُ: بِاسْتِغْفَارِ وَلَدِكَ لَكَ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരു ഖിൻത്വാർ(ഒരു വലിയ അളവ് പാത്രം) പന്ത്രണ്ടായിരം ഊഖിയ(ഒരു ചെറിയ അളവ് പാത്രം)യാണ്. എല്ലാ ഊഖിയ്യയും ആകാശഭൂമികൾക്കിടയിലുള്ളതിൽ വെച്ചേറ്റവും നല്ലതാണ്. റസൂൽ(സ) പറഞ്ഞു: "സ്വർഗ്ഗത്തിൽ ഒരാളുടെ സ്ഥാനം ഉയരും. അദ്ദേഹം ചോദിക്കും: എന്ത് കൊണ്ടാണിത്.? അപ്പോൾ അയാളോട് പറയപ്പെടും: നിനക്ക് വേണ്ടി നിന്റെ മകൻ പാപമോചനം തേടിയതു കൊണ്ടാണിത്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 759, 759, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "تَعَلَّمُوا مِنْ أَنْسَابِكُمْ مَا تَصِلُونَ بِهِ أَرْحَامَكُمْ، فَإِنَّ صِلَةَ الرَّحِمِ مَحَبَّةٌ فِي الْأَهْلِ، مَثْرَاةٌ فِي الْمَالِ، مَنْسَأَةٌ فِي الْأَثَرِ". (م,د,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "കുടുംബബന്ധങ്ങളെ ചേർക്കാൻകഴിയും വിധമുള്ള നിങ്ങളുടെ കുടുംബപരമ്പര പഠിക്കുക. നിശ്ചയം കുടുംബബന്ധം ചേർക്കൽ കുടുംബത്തിൽ സ്നേഹമുണ്ടാക്കും, സമ്പത്തിൽ അഭിവൃദ്ധിയുണ്ടാക്കും, ആയുസ്സിൽ ദൈർഘ്യമുണ്ടാക്കും." (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 759, 759, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَبِي هُرَيْرَةَ قال: قَالَ رَسُولُ اللهِ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ: "كَافِلُ الْيَتِيمِ لَهُ أَوْ لِغَيْرِهِ أَنَا وَهُوَ كَهَاتَيْنِ فِي الْجَنَّةِ". وَأَشَارَ مَالِكٌ بِالسَّبَّابَةِ وَالْوُسْطَى. (م,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെയോ അല്ലെങ്കിൽ വേറൊരാളുടെയോ, അനാഥയെ രക്ഷിക്കുന്നവനും ഞാനും സ്വർഗ്ഗത്തിൻ ഇവ രണ്ടും പോലെയാണ്." മാലിക്(റ) നടുവിരൽ കൊണ്ടും ചൂണ്ടുവിരൽ കൊണ്ടും ആംഗ്യം കാണിച്ചു. (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ قال', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 759, 759, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ سَهْلٍ رضي الله عنهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "أَنَا وَكَافِلُ الْيَتِيمِ كَهَاتَيْنِ فِي الْجَنَّةِ" وَقَرَنَ بَيْنَ أُصْبُعَيْهِ الْوُسْطَى وَالَّتِي تَلِي الْإِبْهَامَ. (ق,د,ت)', 'സഹ്ൽ(റ): നബി(സ) പറഞ്ഞു: ഞാനും അനാഥയെ സംരക്ഷിക്കുന്നവനും സ്വർഗ്ഗത്തിൽ ഈ രണ്ട് വിരലുകളെപ്പോലെയാണ്." നബി(സ) അവിടുത്തെ നടുവിരലും തള്ളവിരലിനടുത്ത വിരലും അടുപ്പിച്ചു. (ബു,മു,ദ,തു)', 'سَهْلٍ', 'സഹ്ൽ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 760, 760, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ إِنِّي أُحَرِّجُ حَقَّ الضَّعِيفَيْنِ: الْيَتِيمِ وَالْمَرْأَةِ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, അനാഥ, സ്ത്രീ എന്നീ രണ്ട് പാവങ്ങളുടെ അവകാശം ധ്വംസിക്കുന്നത് ഞാൻ നിഷിദ്ധമാക്കുന്നു." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 760, 760, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "خَيْرُ بَيْتٍ فِي الْمُسْلِمِينَ بَيْتٌ فِيهِ يَتِيمٌ يُحْسَنُ إِلَيْهِ، وَشَرُّ بَيْتٍ فِي الْمُسْلِمِينَ بَيْتٌ فِيهِ يَتِيمٌ يُسَاءُ إِلَيْهِ". [ز: فيه راو مختلف فيه] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മുസ്ലിംകളിലെ ഏറ്റവും ഉത്തമമായ വീട് ഒരു അനാഥയുണ്ടായിട്ട് ആ അനാഥയോട് നന്മ ചെയ്യുന്ന വീടാണ്. മുസ്ലിംകളിൽ ഏറ്റവും മോശമായ വീട് ഒരു അനാഥയുണ്ടായിട്ട് ആ അനാഥയോട് മോശമായി പെരുമാറപ്പെട്ട വീടാണ്." (നിവേദകരിൽ ഒരാൾ അഭിപ്രായ വ്യത്യാസമുള്ളവരാണ്.) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فيه راو مختلف فيه', null, 760, 760, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رضي الله عنهما قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ عَالَ ثَلَاثَةً مِنَ الْأَيْتَامِ كَانَ كَمَنْ قَامَ لَيْلَهُ وَصَامَ نَهَارَهُ، وَغَدَا وَرَاحَ شَاهِرًا سَيْفَهُ فِي سَبِيلِ اللهِ، وَكُنْتُ أَنَا وَهُوَ فِي الْجَنَّةِ أَخَوَيْنِ، كَهَاتَيْنِ أُخْتَانِ". وَأَلْصَقَ إِصْبَعَيْهِ السَّبَّابَةَ وَالْوُسْطَى. [ز: فِيهِ رَاوٍ مَجْهُولٌ] (جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ മൂന്ന് അനാഥകളെ പോറ്റിയാൽ അവൻ രാത്രി മുഴുവൻ നമസ്കരിക്കുകയും പകൽ നോമ്പനുഷ്ഠിക്കുകയും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വാളൂരിപ്പിടിച്ച് രാവിലെ പോവുകയും രാത്രി മടങ്ങുകയും ചെയ്തവനെപ്പോലെയാണ്. ഞാനും അവനും സ്വർഗ്ഗത്തിൽ സഹോദരങ്ങളാണ്. ഈ രണ്ട് വിരലുകൾ സഹോദരികളായത് പോലെ." നബി(സ) അവിടുത്തെ ചൂണ്ട് വിരലും നടുവിരലും ചേർത്ത് പിടിച്ചു. (പരമ്പരയിൽ അറിയപ്പെടാത്ത ഒരു നിവേദകനുണ്ട്.) (ജ)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِيهِ رَاوٍ مَجْهُولٌ', null, 760, 760, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "مَنْ قَبَضَ يَتِيمًا مِنْ بَيْنِ الْمُسْلِمِينَ إِلَى طَعَامِهِ وَشَرَابِهِ أَدْخَلَهُ اللهُ الْجَنَّةَ الْبَتَّةَ، إِلَّا أَنْ يَعْمَلَ ذَنْبًا لَا يُغْفَرُ لَهُ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും മുസ്ലിംകൾക്കിടയിൽ ഒരു അനാഥയെ തന്റെ ഭക്ഷണത്തിലേക്കും പാനീയത്തിലേക്കും ക്ഷണിച്ചാൽ, പൊറുക്കപ്പെടാത്ത ദോഷം ചെയ്തിട്ടില്ലെങ്കിൽ അല്ലാഹു അവനെ എന്നെന്നേക്കും സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുക തന്നെ ചെയ്യും." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 760, 760, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ رضي الله عنهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنَا وَامْرَأَةٌ سَفْعَاءُ الْخَدَّيْنِ كَهَاتَيْنِ يَوْمَ الْقِيَامَةِ – وَأَوْمَأَ يَزِيدُ بِالْوُسْطَى وَالسَّبَّابَةِ–: امْرَأَةٌ آمَتْ مِنْ زَوْجِهَا، ذَاتُ مَنْصِبٍ وَجَمَالٍ، حَبَسَتْ نَفْسَهَا عَلَى يَتَامَاهَا حَتَّى بَانُوا أَوْ مَاتُوا". (د)', 'ഔഫുബ്നു മാലികിൽ അഷ്ജഇയ്യ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാനും പ്രാരാബ്ധം കൊണ്ട് കവിളൊട്ടിയ സ്ത്രീയും അന്ത്യനാളിൽ ഈ രണ്ട് വിരലുകൾ പോലെയാണ്" - യസീദ്(റ) നടുവിരൽ കൊണ്ടും ചൂണ്ടു വിരൽ കൊണ്ടും ആംഗ്യം കാണിച്ചു. - "തന്റെ അനാഥരായമക്കൾക്ക് വേണ്ടി അവർ വളർന്ന് വലുതാകുന്നത് വരെയോ, അല്ലെങ്കിൽ അവർ മരിക്കുന്നത് വരെയോ തന്റെ ശറീരത്തെ തടഞ്ഞുനിർത്തിയ വിധവയായ സൗന്ദര്യവും തറവാടിത്തവുമുള്ള സ്ത്രീയാണത്." (ദ)', 'عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ', 'ഔഫുബ്നു മാലികിൽ അഷ്ജഇയ്യ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 760, 761, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "السَّاعِي عَلَى الْأَرْمَلَةِ وَالْمِسْكِينِ كَالْمُجَاهِدِ فِي سَبِيلِ اللهِ" وَأَحْسُبُهُ قَالَ: "وَكَالْقَائِمِ لَا يَفْتُرُ، وَكَالصَّائِمِ لَا يُفْطِرُ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "വിധവയ്ക്കും ദരിദ്രനും വേണ്ടി പരിശ്രമിക്കുന്നവൻ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുന്നവനെപ്പോലെയാണ്." തിരുദൂതർ(സ) ഇതുകൂടി പറഞ്ഞിട്ടുണ്ടെന്ന് ഞാൻ വിചാരിക്കുന്നു. "ക്ഷീണിക്കാതെ നിസ്ക്കരിക്കുന്നവനെയും മുറിയാതെ നോമ്പനുഷ്ഠിക്കുന്നവനെയും പോലെയാണവൻ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 761, 761, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ عَائِشَةَ رضي الله عنها قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا زَالَ جِبْرِيلُ يُوصِينِي بِالْجَارِ، حَتَّى ظَنَنْتُ إِنَّهُ لَيُوَرِّثُهُ". (ق,د,ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "തീർച്ചയായും അയൽവാസിയെ എന്റെ അനന്തരാവകാശിയാക്കുമെന്ന് ഞാൻ വിചാരിക്കുന്നത് വരെ, അയൽവാസിയുടെ വിഷയത്തിൽ ജിബ്രീൽ(അ) എന്നെ ഉപദേശിച്ചു കൊണ്ടിരുന്നു." (ബു,മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 761, 761, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَبِي ذَرٍّ رضي الله عنهُ قال: إِنَّ خَلِيلِي صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَوْصَانِي: "إِذَا طَبَخْتَ مَرَقًا فَأَكْثِرْ مَاءَهُ، ثُمَّ انْظُرْ أَهْلَ بَيْتٍ مِنْ جِيرَانِكَ، فَأَصِبْهُمْ مِنْهَا بِمَعْرُوفٍ". (م)', 'അബൂദർറ്(റ): എന്റെ സുഹൃത്തായ നബി(സ) എന്നോട് ഉപദേശിച്ചു: "നീ കറി പാചകം ചെയ്യുമ്പോൾ അതിൽ വെള്ളം കൂട്ടുക. പിന്നെ നിന്റെ അയൽവാസികളിൽപ്പെട്ട വീട്ടുകാരെ വീക്ഷിക്കുക. കറിയിൽ നിന്ന് ആവശ്യാനുസരണം അവർക്കും നൽകുക." (മു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 761, 761, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ أَبِي ذَرٍّ رضي الله عنهُ قال: قَالَ لِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا، وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ". (م)', 'അബൂദർറ്(റ): എന്നോട് നബി(സ) പറഞ്ഞു: "ഒരു നന്മയെയും നീ നിസ്സാരമാക്കരുത്. അത് നിന്റെ സഹോദരനെ പ്രസന്നമായ മുഖത്തോടെ കണ്ടുമുട്ടലാണെങ്കിലും." (മു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 761, 761, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي شُرَيْحٍ الْخُزَاعِيِّ رضي الله عنهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلْيُحْسِنْ إِلَى جَارِهِ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ". (ق,د,ت,جه)', 'അബൂശുറൈഹിൽ ഖുസാഇയ്യ്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നവൻ തന്റെ അയൽവാസിക്ക് നന്മ ചെയ്യട്ടെ. അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നവൻ തന്റെ അതിഥിയെ ബഹുമാനിക്കട്ടെ. അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നവൻ നല്ലത് പറയട്ടെ, അല്ലെങ്കിൽ മൗനവലംബിക്കട്ടെ." (ബു,മു,ദ,തു,ജ)', 'أَبِي شُرَيْحٍ الْخُزَاعِيِّ', 'അബൂശുറൈഹിൽ ഖുസാഇയ്യ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 762, 762, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي شُرَيْحٍ الْخُزَاعِيِّ رضي الله عنهُ قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَاللهِ لَا يُؤْمِنُ، وَاللهِ لَا يُؤْمِنُ، وَاللهِ لَا يُؤْمِنُ" قِيلَ: وَمَنْ يَا رَسُولَ اللهِ؟ قَالَ: "الَّذِي لَا يَأْمَنُ جَارُهُ بَوَايِقَهُ". (خ)', 'അബൂശുറൈഹിൽ ഖുസാഇ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവാണ് സത്യം, അവൻ മുഅ്മിനാകുകയില്ല. അല്ലാഹുവാണ് സത്യം, അവൻ മുഅ്മിനാകുകയില്ല. അല്ലാഹുവാണ് സത്യം, അവൻ മുഅ്മിനാകുകയില്ല." റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, ആരാണത്? നബി(സ) പറഞ്ഞു: "തന്റെ വിപത്തുകളിൽ നിന്ന് തന്റെ അയൽവാസി നിർഭയനല്ലാത്തവൻ." (ബു)', 'أَبِي شُرَيْحٍ الْخُزَاعِيِّ', 'അബൂശുറൈഹിൽ ഖുസാഇ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 762, 762, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رضي الله عنهما: أَنَّهُ ذَبَحَ شَاةً فَقَالَ: أَهْدَيْتُمْ لِجَارِي الْيَهُودِيِّ؟ فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا زَالَ جِبْرِيلُ يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ". (ق,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): അദ്ദേഹം ഒരാടിനെ അറുത്തു. അദ്ദേഹം ചോദിച്ചു: ജൂതനായ എന്റെ അയൽവാസിക്ക് നിങ്ങളത് നൽകിയോ? ഞാൻ റസൂൽ(സ) പറയുന്നത് കേട്ടിട്ടുണ്ട്: "അയൽവാസിയുടെ വിഷയത്തിൽ, അവനെ എന്റെ അനന്തരാവകാശിയാക്കുമോ എന്ന് വിചാരിക്കുന്നത് വരെ ജിബ്രീൽ(അ) എന്നെ ഉപദേശിച്ച് കൊണ്ടിരുന്നു." (ബു,മു,ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 762, 762, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنهُ قال: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَشْكُو جَارَهُ، فَقَالَ: "اذْهَبْ فَاصْبِرْ". فَأَتَاهُ مَرَّتَيْنِ أَوْ ثَلَاثًا، فَقَالَ: "اذْهَبْ فَاطْرَحْ مَتَاعَكَ فِي الطَّرِيقِ". فَطَرَحَ مَتَاعَهُ فِي الطَّرِيقِ، فَجَعَلَ النَّاسُ يَسْأَلُونَهُ فَيُخْبِرُهُمْ خَبَرَهُ، فَجَعَلَ النَّاسُ يَلْعَنُونَهُ: فَعَلَ اللهُ بِهِ، وَفَعَلَ، وَفَعَلَ، فَجَاءَ إِلَيْهِ جَارُهُ فَقَالَ لَهُ: ارْجِعْ، لَا تَرَى مِنِّي شَيْئًا تَكْرَهُهُ. (د)', 'അബൂഹുറൈറ(റ): ഒരാൾ തന്റെ അയൽവാസിയെക്കുറിച്ച് പരാതി ബോധിപ്പിച്ചു കൊണ്ട് നബി(സ)യുടെ അടുത്ത് വന്നു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പോയി ക്ഷമ കൈകൊള്ളുക." പിന്നെ രണ്ടോ മൂന്നോ പ്രാവശ്യം അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് വന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പോയിട്ട് നിങ്ങളുടെ സാധനങ്ങൾ വഴിയിലിടുക." അദ്ദേഹം തന്റെ സാധനങ്ങൾ വഴിയിലിട്ടു. ജനങ്ങൾ അദ്ദേഹത്തോട് കാരണം ചോദിക്കാൻ തുടങ്ങി. അദ്ദേഹം വിവരം പറഞ്ഞുകൊടുത്തു. അപ്പോൾ ''അവനെ അല്ലാഹു ഇങ്ങനെ ചെയ്യട്ടെ. അങ്ങനെ ചെയ്യട്ടെ.'' എന്ന് പറഞ്ഞ് ജനങ്ങൾ അദ്ദേഹത്തെ ശപിക്കാൻ തുടങ്ങി. അപ്പോൾ അയാളുടെ അയൽവാസി വന്നുകൊണ്ടുപറഞ്ഞു: നിങ്ങൾ മടങ്ങിപ്പോകുക. നിങ്ങൾ വെറുക്കുന്ന ഒന്നും എന്നിൽ നിന്ന് നിങ്ങൾ കാണില്ല. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 762, 762, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ عَائِشَةَ رضي الله عنها قَالَتْ: قُلْتُ: يَا رَسُولَ اللهِ، إِنَّ لِي جَارَيْنِ، بِأَيِّهِمَا أَبْدَأُ؟ قَالَ: "بِأَدْنَاهُمَا بَابًا". (خ,د)', 'ആഇശ(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്ക് രണ്ട് അയൽവാസികളുണ്ട്. അവരിൽ ആരിൽ നിന്നാണ് ഞാൻ തുടങ്ങേണ്ടത്? നബി(സ) പറഞ്ഞു: "നിന്റെ വീടിനോടേറ്റവും അടുത്ത് വാലതിലുള്ളവനിൽ നിന്ന്." (ബു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 762, 763, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَيْرُ الْأَصْحَابِ عِنْدَ اللهِ خَيْرُهُمْ لِصَاحِبِهِ، وَخَيْرُ الْجِيرَانِ عِنْدَ اللهِ خَيْرُهُمْ لِجَارِهِ". حَسَنٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിങ്കൽ കൂട്ടുകാരിൽ ഏറ്റവും ഉത്തമൻ തന്റെ കൂട്ടുകാരനോട് നല്ല രീതിയിൽ പെരുമാറുന്നവനാണ്. അല്ലാഹുവിങ്കൽ അയൽവാസികളിൽ ഉത്തമൻ തന്റെ അയൽവാസിയോട് നല്ല രീതിയിൽ പെരുമാറുന്നവനാണ്." (തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 763, 763, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ آخِرُ كَلَامِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الصَّلَاةَ الصَّلَاةَ، اتَّقُوا اللهَ فِيمَا مَلَكَتْ أَيْمَانُكُمْ". (د,جه)', 'അലി(റ): റസൂൽ(സ)യുടെ അവസാനത്തെ സംസാരം ഇപ്രകാരമായിരുന്നു: "നിസ്കാരം നിങ്ങൾ സൂക്ഷിക്കുക. നിസ്കാരം നിങ്ങൾ സൂക്ഷിക്കുക. നിങ്ങൾ ഉടമപ്പെടുത്തിയ(അടിമകൾ)വയിൽ നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുക." (ദ,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 763, 763, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنِ الْمَعْرُورِ بْنِ سُوَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ أَبَا ذَرٍّ بِالرَّبَذَةِ وَعَلَيْهِ بُرْدٌ غَلِيظٌ وَعَلَى غُلَامِهِ مِثْلُهُ، قَالَ: فَقَالَ الْقَوْمُ: يَا أَبَا ذَرٍّ، لَوْ كُنْتَ أَخَذْتَ الَّذِي عَلَى غُلَامِكَ فَجَعَلْتَهُ مَعَ هَذَا، فَكَانَتْ حُلَّةً، وَكَسَوْتَ غُلَامَكَ ثَوْبًا غَيْرَهُ؟ قَالَ: فَقَالَ أَبُو ذَرٍّ: إِنِّي كُنْتُ سَابَبْتُ رَجُلًا وَكَانَتْ أُمُّهُ أَعْجَمِيَّةً، فَعَيَّرْتُهُ بِأُمِّهِ، فَشَكَانِي إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا أَبَا ذَرٍّ، إِنَّكَ امْرُؤٌ فِيكَ جَاهِلِيَّةٌ، إِنَّهُمْ إِخْوَانُكُمْ، فَضَّلَكُمُ اللهُ عَلَيْهِمْ، فَمَنْ لَمْ يُلَائِمْكُمْ فَبِيعُوهُ، وَلَا تُعَذِّبُوا خَلْقَ اللهِ". (ق,د,ت)', 'മഅ്റൂറുബ്നു സുവൈദ്(റ): ഞാൻ അബൂദർറ്(റ)വിനെ റബദയിൽ വെച്ച് കണ്ടു. അദ്ദേഹത്തിന്റെ ശരീരത്തിൽ പരുപരുത്ത ഒരു പുതപ്പുണ്ട്. അതുപോലെ ഒന്ന് അദ്ദേഹത്തിന്റെ അടിമയുടെ ശരീരത്തിലമുണ്ട്. അപ്പോൾ ജനങ്ങൾ ചോദിച്ചു: അബൂദർറേ, താങ്കളുടെ അടിമയുടെ ശരീരത്തിലുള്ളത് എടുത്ത് താങ്കളുടെ പുതിപ്പിനോട് ചേർത്താൽ അത് കോട്ടാകും. താങ്കളുടെ അടിമക്ക് വേറെ വസ്ത്രം ധരിപ്പിച്ചാൽ പോരേ? അപ്പോൾ അബൂദർറ്(റ) പറഞ്ഞു: ഞാനൊരാളെ ചീത്ത പറഞ്ഞു. അയാളുടെ ഉമ്മ അനറബിയായിരുന്നു. ഞാനവന്റെ ഉമ്മയുടെ വിഷയത്തിൽ അവനെ കുറ്റം പറഞ്ഞു. അയാൾ എന്നെക്കുറിച്ച് റസൂൽ(സ)യോട് പരാതി പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഓ അബൂദർറ്, നീ ജാഹിലിയ്യത് (അജ്ഞാനകാലത്തെ സ്വഭാവം) ഉള്ള ആളാണ്. അവർ നിങ്ങളുടെ സഹോദരങ്ങളാണ്. അവരേക്കാൾ അല്ലാഹു നിങ്ങളെ ശ്രേഷ്ഠരാക്കി. നിങ്ങളോട് യോജിക്കാത്തവരെ നിങ്ങൾ വിൽക്കുക. അല്ലാഹുവിന്റെ സൃഷ്ടികളെ നിങ്ങൾ ശിക്ഷിക്കരുത്." (ബു,മു,ദ,തു)', 'الْمَعْرُورِ بْنِ سُوَيْدٍ', 'മഅ്റൂറുബ്നു സുവൈദ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 763, 763, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِخْوَانُكُمْ جَعَلَهُمُ اللهُ تَحْتَ أَيْدِيكُمْ، فَأَطْعِمُوهُمْ مِمَّا تَأْكُلُونَ، وَأَلْبِسُوهُمْ مِمَّا تَلْبَسُونَ، وَلَا تُكَلِّفُوهُمْ مَا يَغْلِبُهُمْ، فَإِنْ كَلَّفْتُمُوهُمْ فَأَعِينُوهُمْ". (ق,د,ت,جه)', 'അബുദർറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിങ്ങളുടെ കീഴിലാക്കിയ സഹോദരങ്ങളാണവർ, നിങ്ങൾ ഭക്ഷിക്കുന്നത് അവരെ ഭക്ഷിപ്പിക്കുക. നിങ്ങൾ ധരിക്കുന്നത് അവരെ ധരിപ്പിക്കുക. അവർക്ക് കഴിയാത്തത് അവരോട് കൽപിക്കരുത്. അപ്രകാരം കൽപിക്കുന്നുവെങ്കിൽ അവരെ നിങ്ങൾ സഹായിക്കുക." (ബു,മു,ദ,തു,ജ)', 'أَبِي ذَرٍّ', 'അബുദർറ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 763, 764, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَدْخُلُ الْجَنَّةَ سَيِّئُ الْمَلَكَةِ". قَالُوا: يَا رَسُولَ اللهِ، أَلَيْسَ أَخْبَرْتَنَا أَنَّ هَذِهِ الْأُمَّةَ أَكْثَرُ الْأُمَمِ مَمْلُوكِينَ وَيَتَامَى؟ قَالَ: "نَعَمْ ، فَأَكْرِمُوهُمْ كَكَرَامَةِ أَوْلَادِكُمْ، وَأَطْعِمُوهُمْ مِمَّا تَأْكُلُونَ". قَالُوا: فَمَا يَنْفَعُنَا فِي الدُّنْيَا؟ قَالَ: "فَرَسٌ تَرْتَبِطُهُ تُقَاتِلُ عَلَيْهِ فِي سَبِيلِ اللهِ، مَمْلُوكُكَ يَكْفِيكَ، فَإِذَا صَلَّى فَهُوَ أَخُوكَ".[ز: في سنده مُخْتَلَفٌ فِيهِ] (ت,جه)', 'അബൂബക്കർ സിദ്ദീഖ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അടിമകളോട് മോശമായി പെരുമാറുന്നവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയില്ല." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, സമുദായങ്ങളിൽ വെച്ച് ഏറ്റവും കൂടുതൽ അടിമകളും അനാഥകളുമുള്ള സമുദായം ഈ സമുദായമാണെന്ന് അങ്ങ് ഞങ്ങൾക്ക് പറഞ്ഞു തന്നിട്ടില്ലേ? നബി(സ) പറഞ്ഞു: "അതെ, നിങ്ങളുടെ സന്താനങ്ങളെ ബഹുമാനിക്കുന്നത് പോലെ അവരെ നിങ്ങൾ ബഹുമാനിക്കുക. നിങ്ങൾ ഭക്ഷിക്കുന്നത് അവരെയും ഭക്ഷിപ്പിക്കുക." അവർ ചോദിച്ചു: ദുൻയാവിൽ ഞങ്ങൾക്ക് ഉപകരിക്കുന്നത് എന്താണ്? നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യാൻ വേണ്ടി നീ ബന്ധിക്കുന്ന കുതിര, നിന്നെ സഹായിക്കുന്ന നിന്റെ അടിമ. നിസ്കരിക്കുന്നവനാണെങ്കിൽ അവനും നിന്റെ സഹോദരനാണ്." (പരമ്പരയിലെ ഒരു നിവേദകനിൽ അഭിപ്രായാന്തരമുണ്ട്.) (തു,ജ)', 'أَبِي بَكْرٍ الصِّدِّيقِ', 'അബൂബക്കർ സിദ്ദീഖ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], 'ز: في سنده مُخْتَلَفٌ فِيهِ', null, 764, 764, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَضْرِبُ غُلَامًا لِي – وفي رواية: أسود، بِالسَّوْطِ – فَسَمِعْتُ مِنْ خَلْفِي صَوْتًا: "اعْلَمْ أَبَا مَسْعُودٍ – مَرَّتَيْنِ – لَلَّهُ أَقْدَرُ عَلَيْكَ مِنْكَ عَلَيْهِ". فَالْتَفَتُّ فَإِذَا هُوَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: يَا رَسُولَ اللهِ، هُوَ حُرٌّ لِوَجْهِ اللهِ تَعَالَى. قَالَ: "أَمَا إِنَّكَ لَوْ لَمْ تَفْعَلْ لَلَفَحَتْكَ النَّارُ". أَوْ: "لَمَسَّتْكَ النَّارُ". (م,د)', 'അബൂ മസ്ഊദിൽ അൻസാരി(റ): ഞാനെന്റെ ഒരു കറുത്ത അടിമയെ ചാട്ടവാർ കൊണ്ട് അടിക്കുകയായിരുന്നു. അപ്പോൾ പിന്നിൽ നിന്ന് ഒരു ശബ്ദം കേട്ടു: "അബൂ മസ്ഊദ്, നീ അറിയണം." രണ്ട് പ്രാവശ്യം ഇങ്ങനെ പറഞ്ഞു: "അവന്റെ മേൽ നിനക്ക് കഴിവുള്ളതിനേക്കാൾ കൂടുതൽ നിന്റെ മേൽ അല്ലാഹു കഴിവുള്ളവനാകുന്നു." ഞാൻ തിരിഞ്ഞു നോക്കി. അപ്പോൾ അത് റസൂൽ(സ)യായിരുന്നു. ഞാൻ പറഞ്ഞു: അവൻ അല്ലാഹുവിന്റെ പ്രീതിക്ക് വേണ്ടി, സ്വതന്ത്രനാണ്. നബി(സ) പറഞ്ഞു: "നീ അത് ചെയ്തില്ലെങ്കിൽ നിന്നെ നരകം സ്പർശിക്കുമായിരുന്നു." (മു,ദ)', 'أَبِي مَسْعُودٍ الْأَنْصَارِيِّ', 'അബൂ മസ്ഊദിൽ അൻസാരി(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 764, 764, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=79), 1, 'وَفِي رِوَايَةٍ: أسود، بِالسَّوْطِ – فَسَمِعْتُ مِنْ خَلْفِي صَوْتًا: "اعْلَمْ أَبَا مَسْعُودٍ – مَرَّتَيْنِ – لَلَّهُ أَقْدَرُ عَلَيْكَ مِنْكَ عَلَيْهِ". فَالْتَفَتُّ فَإِذَا هُوَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: يَا رَسُولَ اللهِ، هُوَ حُرٌّ لِوَجْهِ اللهِ تَعَالَى. قَالَ: "أَمَا إِنَّكَ لَوْ لَمْ تَفْعَلْ لَلَفَحَتْكَ النَّارُ". أَوْ: "لَمَسَّتْكَ النَّارُ". (م,د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَاءَمَكُمْ مِنْ مَمْلُوكِيكُمْ فَأَطْعِمُوهُ مِمَّا تَأْكُلُونَ، وَاكْسُوهُ مِمَّا تَلْبَسُونَ، وَمَنْ لَمْ يُلَائِمْكُمْ مِنْهُمْ فَبِيعُوهُ، وَلَا تُعَذِّبُوا خَلْقَ اللهِ". (د)', 'അബൂദർറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ അടിമകളിൽ നിങ്ങളോട് യോജിക്കുന്നവർക്ക് നിങ്ങൾ ഭക്ഷിക്കുന്നതിൽ നിന്ന് ഭക്ഷിപ്പിക്കുക. നിങ്ങൾ ധരിക്കുന്നതിൽ നിന്ന് ധരിപ്പിക്കുക. അടിമകളിൽ നിങ്ങളോട് യോജിക്കാത്തവരെ നിങ്ങൾ വിൽക്കുക. അല്ലാഹുവിന്റെ സൃഷ്ടികളെ നിങ്ങൾ ശിക്ഷിക്കരുത്." (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 764, 764, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ رَافِعِ بْنِ مَكِيثٍ رَضِيَ اللهُ عَنْهُ، وَكَانَ مِمَّنْ شَهِدَ الْحُدَيْبِيَةَ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "حُسْنُ الْمَلَكَةِ يُمْنٌ، وَسُوءُ الْخُلُقِ شُؤْمٌ" (د)', 'റാഫിഉബ്നു മകീസ്(റ): നബി(സ)യോടു കൂടെ ഹുദൈബിയ്യ സംഭവത്തിൽ സാക്ഷിയായവരിൽപ്പെട്ടവരാണദ്ദേഹം. നബി(സ) പറഞ്ഞു: "അടിമകളോട് നല്ല രീതിയിൽ പെരുമാറുന്നത് ശുഭലക്ഷണമാണ്. മോശമായി പെരുമാറുന്നത് ദുശ്ശകുനമാണ്." (ദ)', 'رَافِعِ بْنِ مَكِيثٍ', 'റാഫിഉബ്നു മകീസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 764, 765, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنِي أَبُو الْقَاسِمِ نَبِيُّ التَّوْبَةِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَذَفَ مَمْلُوكَهُ وَهُوَ بَرِيءٌ مِمَّا قَالَ: جُلِدَ لَهُ يَوْمَ الْقِيَامَةِ حَدًّا". (ق,د,ت)', 'അബൂഹുറൈറ(റ): തൗബയുടെ പ്രവാചകനായ അബുൽഖാസിം(സ) എന്നോട് പറഞ്ഞു: "താൻ ആരോപിക്കുന്നതിൽ നിന്ന് മുക്തനായിരിക്കെ ഒരാൾ തന്റെ അടിമക്കെതിരെ വ്യഭിചാരാരോപണം നടത്തിയാൽ അന്ത്യദിനത്തിൽ അവൻ ചാട്ടവാർ കൊണ്ട് അടിക്കപ്പെടും." (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 765, 765, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ هِلَالِ بْنِ يَسَافٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نُزُولًا فِي دَارِ سُوَيْدِ بْنِ مُقَرِّنٍ وَفِينَا شَيْخٌ فِيهِ حِدَّةٌ، وَمَعَهُ جَارِيَةٌ لَهُ، فَلَطَمَ وَجْهَهَا، فَمَا رَأَيْتُ سُوَيْدًا أَشَدَّ غَضَبًا مِنْهُ ذَاكَ الْيَوْمَ، قَالَ: عَجَزَ عَلَيْكَ إِلَّا حُرُّ وَجْهِهَا؟ لَقَدْ رَأَيْتُنَا سَابِعَ سَبْعَةٍ مِنْ وَلَدِ مُقَرِّنٍ، وَمَا لَنَا إِلَّا خَادِمٌ، فَلَطَمَ أَصْغَرُنَا وَجْهَهَا، فَأَمَرَنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِعِتْقِهَا. (م,د,ت)', 'ഹിലാലുബ്നു യസാഫ്(റ): ഞങ്ങൾ സുവൈദുബ്നു മുഖർരിൻ(റ)വിന്റെ വീട്ടിലേക്ക് ചെന്നതായിരുന്നു. ഞങ്ങളുടെ കൂട്ടത്തിൽ പെട്ടെന്ന് ദേഷ്യം പിടിക്കുന്ന ഒരു വൃദ്ധനുണ്ടായിരുന്നു. അദ്ദേഹത്തിന്റെ കൂടെ ഒരടിമസ്ത്രീയുമുണ്ട്. അദ്ദേഹം അവളുടെ മുഖത്തടിച്ചു. സുവൈദ്(റ) ആ ദിവസം ദേഷ്യപ്പെട്ടതിനേക്കാൾ കൂടുതൽ ദേഷ്യപ്പെട്ടതായി ഞാൻ കണ്ടിട്ടില്ല. അദ്ദേഹം ചോദിച്ചു: അവളുടെ മുഖത്തെ മൃദു സ്ഥലമല്ലാതെ വേറെയൊന്നും നിങ്ങൾക്ക് കിട്ടിയില്ലേ? മുഖർരിന്റെ മക്കളിൽ ഏഴാമത്തവനാണ് നാമെന്ന് താങ്കൾക്കറിയില്ലേ. ഞങ്ങൾക്ക് ഒരു വേലക്കാരി മാത്രമേ ഉണ്ടായിരുന്നുള്ളു. ഞങ്ങളിലെ ചെറിയവൻ അവളുടെ മുഖത്തടിച്ചു. അപ്പോൾ നബി(സ) അവളെ മോചിപ്പിക്കാൻ കൽപിച്ചു. (മു,ദ,തു)', 'هِلَالِ بْنِ يَسَافٍ', 'ഹിലാലുബ്നു യസാഫ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 765, 765, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ مُعَاوِيَةَ بْنِ سُوَيْدِ بْنِ مُقَرِّنٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَطَمْتُ مَوْلًى لَنَا، فَدَعَاهُ أَبِي وَدَعَانِي، فَقَالَ: اقْتَصَّ مِنْهُ، فَإِنَّا مَعْشَرَ بَنِي مُقَرِّنٍ كُنَّا سَبْعَةً عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَيْسَ لَنَا إِلَّا خَادِمٌ، فَلَطَمَهَا رَجُلٌ مِنَّا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَعْتِقُوهَا". قَالُوا: إِنَّهُ لَيْسَ لَنَا خَادِمٌ غَيْرُهَا، قَالَ: "فَلْتَخْدُمْهُمْ حَتَّى يَسْتَغْنُوا، فَإِذَا اسْتَغْنَوْا فَلْيُعْتِقُوهَا". (د)', 'മുആവിയതുബ്നു സുവൈദുബ്നു മുഖർരിൻ(റ): ഞാൻ ഞങ്ങളുടെ ഒരടിമയെ അടിച്ചു. അടിമയെയും എന്നെയും എന്റെ ഉപ്പ അടുത്ത് വിളിച്ചു. അദ്ദേഹം പറഞ്ഞു: അവനോട് നീ പ്രതികാരം ചെയ്യുക. ഞങ്ങൾ മുഖർരിനിന്റെ മക്കൾ നബി(സ)യുടെ കാലത്ത് ഏഴ് പേരായിരുന്നു. ഞങ്ങൾക്കൊരു വേലക്കാരി മാത്രമേയുണ്ടായിരുന്നുള്ളു. ഞങ്ങളിൽപ്പെട്ട ഒരാൾ അവളുടെ മുഖത്തടിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവളെ നിങ്ങൾ മോചിപ്പിക്കുക." അവർ പറഞ്ഞു: ഞങ്ങൾക്ക് അവളല്ലാത്ത വേറൊരു വേലക്കാരിയില്ല. നബി(സ) പറഞ്ഞു: "എങ്കിൽ ആവശ്യം തീരുംവരെ അവളവർക്ക് സേവനം ചെയ്യട്ടെ. ആവശ്യം തീർന്നാൽ അവളെ അവർ മോചിപ്പിക്കട്ടെ." (ദ)', 'مُعَاوِيَةَ بْنِ سُوَيْدِ بْنِ مُقَرِّنٍ', 'മുആവിയതുബ്നു സുവൈദുബ്നു മുഖർരിൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 765, 765, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَضْرِبُ مَمْلُوكًا لِي، فَسَمِعْتُ قَائِلًا مِنْ خَلْفِي يَقُولُ: "اعْلَمْ أَبَا مَسْعُودٍ، اعْلَمْ أَبَا مَسْعُودٍ". فَالْتَفَتُّ فَإِذَا أَنَا بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "لَلَّهُ أَقْدَرُ عَلَيْكَ مِنْكَ عَلَيْهِ". قَالَ أَبُو مَسْعُودٍ: فَمَا ضَرَبْتُ مَمْلُوكًا لِي بَعْدَ ذَلِكَ. حَسَنٌ صَحِيحٌ. (م,د,ت)', 'അബൂ മസ്ഊദിൽ അൻസാരി(റ): ഞാനെന്റെ അടിമയെ അടിക്കുകയായിരുന്നു. അപ്പോൾ എന്റെ പിറകിൽ നിന്ന് ഒരാൾ പറയുന്നത് കേട്ടു. അബൂ മസ്ഊദേ, അറിയുക, അബൂ മസ്ഊദേ അറിയുക. ഞാൻ തിരിഞ്ഞ് നോക്കി. അപ്പോൾ ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് നിൽക്കുന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിനക്ക് അവന്റെ മേൽ കഴിവുള്ളതിനെക്കാൾ കൂടുതൽ അല്ലാഹു നിന്റെ മേൽ കഴിവുള്ളവനാണ്." അബൂ മസ്ഊദ്(റ) പറയുന്നു: അതിനു ശേഷം എന്റെ ഒടരടിമയെയും ഞാൻ അടിച്ചിട്ടില്ല. (മു,ദ,തു)', 'أَبِي مَسْعُودٍ الْأَنْصَارِيِّ', 'അബൂ മസ്ഊദിൽ അൻസാരി(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 765, 766, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ زَاذَانَ قَالَ: أَتَيْتُ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا وَقَدْ أَعْتَقَ مَمْلُوكًا لَهُ، فَأَخَذَ مِنَ الْأَرْضِ عُودًا – أَوْ: شَيْئًا – فَقَالَ: مَا لِي فِيهِ مِنَ الْأَجْرِ مَا يَسْوَى هَذَا، سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ لَطَمَ مَمْلُوكَهُ أَوْ ضَرَبَهُ فَكَفَّارَتُهُ أَنْ يُعْتِقَهُ". (م,د)', 'സാദാൻ(റ): ഞാൻ ഇബ്നുഉമർ(റ)വിന്റെ അടുത്ത് ചെന്നു. അദ്ദേഹം തന്റെ ഒരടിമയെ മോചിപ്പിച്ചിരിക്കുന്നു. ഇബ്നുഉമർ(റ) നിലത്ത് നിന്നൊരു വടി - അല്ലെങ്കിൽ എന്തോ ഒരു വസ്തു - എടുത്തു. എന്നിട്ട് പറഞ്ഞു: അടിമയെ മോചിപ്പിച്ചതിൽ എനിക്ക് ഇതിനോട് സമമായ കൂലി ലഭിക്കില്ല. ഞാൻ റസൂൽ(സ) പറയുന്നത് കേട്ടു: "ഒരാൾ തന്റെ അടിമയുടെ മുഖത്തടിക്കുകയോ തല്ലുകയോ ചെയ്താൽ അതിന്റെ പ്രായശ്ചിത്തം അവനെ മോചിപ്പിക്കലാണ്." (മു,ദ)', 'زَاذَانَ قَالَ', 'സാദാൻ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 766, 766, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا ضرب أحدكم خَادِمَهُ، فَذَكَرَ اللهَ، فَارْفَعُوا أَيْدِيَكُمْ". (ت)', 'അബൂ സഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ തന്റെ അടിമയെ അടിച്ചു. അപ്പോൾ അവൻ അല്ലാഹുവിനെ ഓർത്താൽ, നിങ്ങൾ നിങ്ങളുടെ കരങ്ങളുയർത്തുക." (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂ സഈദിൽ ഖുദ്രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 766, 766, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْعَبْدَ إِذَا نَصَحَ لِسَيِّدِهِ وَأَحْسَنَ عِبَادَةَ اللهِ، فَلَهُ أَجْرُهُ مَرَّتَيْنِ". (ق,د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അടിമ തന്റെ യജമാനന് സദുപദേശം നൽകുകയും അല്ലാഹുവോടുള്ള തന്റെ ആരാധന നന്നാക്കുകയും ചെയ്താൽ, അവന് രണ്ട് പ്രാവശ്യം തന്റെ പ്രതിഫലമുണ്ട്." (ബു,മു,ദ,)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 766, 766, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ خَبَّبَ زَوْجَةَ امْرِئٍ أَوْ مَمْلُوكَهُ فَلَيْسَ مِنَّا". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാളുടെ അടിമയെയോ ഭാര്യയെയോ അയാൾ[?]തിരിൽ പ്രലോഭിപ്പിക്കുന്നവൻ നമ്മിൽ പെട്ടവനല്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 766, 766, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، كَمْ أَعْفُو عَنِ الْخَادِمِ؟ فَصَمَتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: يَا رَسُولَ اللهِ، كَمْ أَعْفُو عَنِ الْخَادِمِ؟ فَقَالَ: "كُلَّ يَوْمٍ سَبْعِينَ مَرَّةً". حَسَنٌ. (د,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്നു ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, വേലക്കാരന് എത്ര പ്രാവശ്യമാണ് ഞാൻ മാപ്പ് നൽകേണ്ടത്? അപ്പോൾ റസൂൽ(സ) മൗനവലംബിച്ചു. അദ്ദേഹം പിന്നെയും ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഒരു വേലക്കാരന് എത്ര പ്രാവശ്യം ഞാൻ മാപ്പ് കൊടുക്കണം. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ ദിവസവും എഴുപത് പ്രാവശ്യം". (ദ,തു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 767, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ يَقُولُ يَوْمَ الْقِيَامَةِ: أَيْنَ الْمُتَحَابُّونَ بِجَلَالِي؟ الْيَوْمَ أُظِلُّهُمْ فِي ظِلِّي يَوْمَ لَا ظِلَّ إِلَّا ظِلِّي". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മഹോന്നതനായ അല്ലാഹു തീർച്ചയായും അന്ത്യനാളിൽ ചോദിക്കും: എന്റെ ഔന്നിത്യം കൊണ്ട് പരസ്പരം സ്നേഹിച്ചവരെവിടെ? എന്റെ തണലല്ലാതെ (മറ്റൊരു) തണലില്ലാത്ത ഇന്ന് അവർക്ക് ഞാൻ എന്റെ തണലേകുന്നതാണ്". (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 767, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنَّ رَجُلًا زَارَ أَخًا لَهُ فِي قَرْيَةٍ أُخْرَى، فَأَرْصَدَ اللهُ (لَهُ) عَلَى مَدْرَجَتِهِ مَلَكًا، فَلَمَّا أَتَى عَلَيْهِ قَالَ: أَيْنَ تُرِيدُ؟ قَالَ: أُرِيدُ أَخًا لِي فِي هَذِهِ الْقَرْيَةِ، قَالَ: هَلْ لَكَ عَلَيْهِ مِنْ نِعْمَةٍ تَرُبُّهَا؟ قَالَ: لَا، غَيْرَ أَنِّي أَحْبَبْتُهُ فِي اللهِ عَزَّ وَجَلَّ، قَالَ: فَإِنِّي رَسُولُ اللهِ إِلَيْكَ، بِأَنَّ اللهَ قَدْ أَحَبَّكَ كَمَا أَحْبَبْتَهُ فِيهِ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ മറ്റൊരു ഗ്രാമത്തിലുള്ള തന്റെ സഹോദരനെ സന്ദർശിച്ചു. അപ്പോൾ അല്ലാഹു ഒരു മലക്കിനെ അയാളുടെ വഴിയിൽ നിരീക്ഷിക്കാനയച്ചു. അയാളുടെ അടുക്കൽ എത്തിയപ്പോൾ മലക്ക് ചോദിച്ചു: നീ എവിടേക്കാണ് പോകാൻ ഉദ്ദേശിക്കുന്നത്? അയാൾ പറഞ്ഞു: ഞാൻ ഈ ഗ്രാമത്തിലെ എന്റെ സഹോദരനെ (കാണാൻ) ആണ് ഉദ്ദേശിക്കുന്നത്. മലക്ക് ചോദിച്ചു: അവൻ നിനക്ക് വല്ല അനുഗ്രഹവും നൽകുന്നതിനാണോ നീ അവന്റെയടുക്കൽ പോകുന്നത്? അയാൾ പറഞ്ഞു: അല്ല. തീർച്ചയായും ഞാനവനെ മഹോന്നതനായ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സ്നേഹിക്കുന്നു. മലക് പറഞ്ഞു: ഞാൻ നിന്നിലേക്കുള്ള അല്ലാഹുവിന്റെ ദൂതനാണ്, നിശ്ചയം നീ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ അവനെ (സഹോദരനെ) സ്നേഹിച്ചതു പോലെ അല്ലാഹു നിന്നെ സ്നേഹിച്ചിരിക്കുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 767, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَحَدَكُمْ مِرْآةُ أَخِيهِ، فَإِنْ رَأَى بِهِ أَذًى فَلْيُمِطْهُ عَنْهُ". (ق,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം നിങ്ങളോരോരുത്തരും തന്റെ സഹോദരന്റെ കണ്ണാടിയാണ്. അതിനാൽ ആരെങ്കിലുമതിൽ വല്ല അഴുക്കും കണ്ടാൽ അത് തുടച്ചുകളയുക." (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 767, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا". ثُمَّ شَبَّكَ بَيْنَ أَصَابِعِهِ، قَالَ: وَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَالِسًا إِذْ جَاءَ رَجُلٌ يَسْأَلُ أَوْ طَالِبُ حَاجَةٍ، أَقْبَلَ عَلَيْنَا بِوَجْهِهِ، فَقَالَ: "اشْفَعُوا فَلْتُؤْجَرُوا وَلْيَقْضِ اللهُ عَلَى لِسَانِ نَبِيِّهِ مَا شَاءَ". (ق,ت,ن)', 'അബൂമൂസ(റ): നബി(സ) പറഞ്ഞു: "ഒരു വിശ്വാസി മറ്റൊരു വിശ്വാസിക്ക് കെട്ടിടം പോലെയാണ്. അതിന്റെ ഒരുഭാഗം മറ്റൊരു ഭാഗത്തെ ശക്തിപ്പെടുത്തുന്നു." എന്നിട്ട് അവിടന്ന് തന്റെ വിരലുകൾ പരസ്പരം കോർത്തുപിടിച്ചു. നിവേദകൻ പറയുന്നു: നബി(സ) ഇരിക്കുകയായിരുന്നു. പെട്ടെന്നൊരാൾ ഒരാവശ്യം ചോദിച്ച് വന്നു. അപ്പോൾ അവിടന്ന് ഞങ്ങളിലേക്ക് മുഖം തിരിച്ച് പറഞ്ഞു: "നിങ്ങൾ ശുപാർശ ചെയ്യുക, അങ്ങനെ നിങ്ങൾക്ക് കൂലി നൽകപ്പെടട്ടെ. അല്ലാഹു അവനുദ്ദേശിച്ചത് തന്റെ പ്രവാചകന്റെ നാവിലൂടെ വിധിക്കുകയും ചെയ്യട്ടെ." (ബു,മു,തു,ന)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 768, 768, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَرَى الْمُؤْمِنِينَ فِي تَرَاحُمِهِمْ وَتَوَادِّهِمْ وَتَعَاطُفِهِمْ كَمَثَلِ الْجَسَدِ، إِذَا اشْتَكَى عُضْوًا تَدَاعَى لَهُ سَائِرُ جَسَدِهِ بِالسَّهَرِ وَالْحُمَّى". (ق)', 'നുഅ്മാനുബ്നു ബശീർ(റ): റസൂൽ(സ) പറഞ്ഞു: "പരസ്പര കാരുണ്യത്തിലും സ്നേഹത്തിലും വാത്സല്യത്തിലും വിശ്വാസികളെ ഒരൊറ്റ ശരീരം പോലെ നിനക്ക് കാണാം. ഏതെങ്കിലുമൊരവയവത്തിന് രോഗം ബാധിച്ചാൽ പനി ബാധിച്ചും ഉറക്കമൊഴിച്ചും, മുഴുവൻ ശരീരവും അതിന് വേണ്ടി വേദനിക്കുന്നു." (ബു,മു)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 768, 768, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ مَتَى السَّاعَةُ؟ قَالَ: "وَمَا أَعْدَدْتَ لِلسَّاعَةِ". قَالَ: حُبَّ اللهِ وَرَسُولِهِ، قَالَ: "فَإِنَّكَ مَعَ مَنْ أَحْبَبْتَ". قَالَ أَنَسٌ: فَمَا فَرِحْنَا بَعْدَ الْإِسْلَامِ فَرَحًا أَشَدَّ مِنْ قَوْلِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "فَإِنَّكَ مَعَ مَنْ أَحْبَبْتَ". قَالَ أَنَسٌ: فَأَنَا أُحِبُّ اللهَ وَرَسُولَهُ وَأَبَا بَكْرٍ وَعُمَرَ، فَأَرْجُو أَنْ أَكُونَ مَعَهُمْ وَإِنْ لَمْ أَعْمَلْ بِأَعْمَالِهِمْ. (م)', 'അനസുബ്നു മാലിക്(റ): ഒരാൾ റസൂൽ(സ)യുടെ അടുക്കലേക്ക് വന്നു പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, അന്ത്യനാൾ എപ്പോഴാണ്? അവിടന്ന് ചോദിച്ചു: "താങ്കൾ അന്ത്യനാളിനായി എന്ത് തയ്യാറെടുപ്പാണ് നടത്തിയത്." അയാൾ പറഞ്ഞു: അല്ലാഹുവിനോടും അവന്റെ ദൂതനോടുമുള്ള സ്നേഹം. അവിടന്നരുളി: "എന്നാൽ, നിശ്ചയം താങ്കൾ താൻ സ്നേഹിക്കുന്നവരുടെ കൂടെത്തന്നെ ഉണ്ടായിരിക്കും." അനസ്(റ) പറഞ്ഞു: "നിശ്ചയം താങ്കൾ താൻ സ്നേഹിക്കുന്നവരുടെ കൂടെത്തന്നെയായിരിക്കും" എന്ന നബി(സ)യുടെ വാക്ക് കാരണത്താൽ സന്തോഷിച്ചയത്ര ഇസ്ലാമിൽ വന്ന ശേഷം ഒരു കാര്യത്തിലും ഞങ്ങൾ സന്തോഷിച്ചിട്ടില്ല. നിശ്ചയം ഞാൻ അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും അബൂബക്കർ(റ)വിനെയും ഉമർ(റ)വിനെയും സ്നേഹിക്കുന്നു. അവരുടെ കർമ്മങ്ങൾ ഞാൻ ചെയ്തിട്ടില്ലെങ്കിലും ഞാനവരുടെ കൂടെയാകുമെന്ന് പ്രതീക്ഷിക്കുന്നു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 768, 769, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ عَزَّ وَجَلَّ إِذَا أَحَبَّ عَبْدًا دَعَا جِبْرِيلَ عَلَيْهِ السَّلَامُ فَقَالَ: إِنِّي أُحِبُّ فُلَانًا فَأَحِبَّهُ، قَالَ: فَيُحِبُّهُ جِبْرِيلُ، ثُمَّ يُنَادِي فِي السَّمَاءِ فَيَقُولُ: إِنَّ اللهَ عَزَّ وَجَلَّ يُحِبُّ فُلَانًا فَأَحِبُّوهُ، فَيُحِبُّهُ أَهْلُ السَّمَاءِ، قَالَ: ثُمَّ يُوضَعُ لَهُ الْقَبُولُ فِي الْأَرْضِ. وَإِذَا أَبْغَضَ اللهُ عَبْدًا دَعَا جِبْرِيلَ عَلَيْهِ السَّلَامُ، فَيَقُولُ: إِنِّي أُبْغِضُ فُلَانًا فَأَبْغِضْهُ، قَالَ: فَيُبْغِضُهُ جِبْرِيلُ، ثُمَّ يُنَادِي فِي أَهْلِ السَّمَاءِ: إِنَّ اللهَ يُبْغِضُ فُلَانًا فَأَبْغِضُوهُ، فَيُبْغِضُونَهُ، ثُمَّ تُوضَعُ لَهُ الْبَغْضَاءُ فِي الْأَرْضِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും, മഹോന്നതനായ അല്ലാഹു ഒരടിമയെ സ്നേഹിച്ചാൽ ജിബ്രീൽ(അ)നെ വിളിച്ച് പറയും: ഞാൻ ഇന്നയാളെ ഇഷ്ടപ്പെടുന്നു. അതിനാൽ നീയും അയാളെ ഇഷ്ടപ്പെടുക. അവിടന്ന് പറഞ്ഞു: അപ്പോൾ ജിബ്രീൽ(അ) അയാളെ ഇഷ്ടപ്പെടും. പിന്നീട് (ജിബ്രീൽ) ആകാശത്ത് വിളിച്ച് പറയും: നിശ്ചയം മഹോന്നതനായ അല്ലാഹു ഇന്നയാളെ ഇഷ്ടപ്പെടുന്നു. അതിനാൽ നിങ്ങൾ അയാളെ ഇഷ്ടപ്പെടുക. അപ്പോൾ ആകാശത്തുള്ളവർ അയാളെ ഇഷ്ടപ്പെടും. അവിടന്ന് പറഞ്ഞു: പിന്നീട് അവന് ഭൂമിയിൽ സ്വീകാര്യത നൽകപ്പെടും. അല്ലാഹു ഏതെങ്കിലും അടിമയോട് ദേഷ്യപ്പെട്ടാൽ അല്ലാഹു ജിബ്രീൽ(അ)നെ വിളിച്ച് പറയും: നിശ്ചയം ഞാൻ ഇന്നയാളെ ദേഷ്യം വെക്കുന്നു. അതിനാൽ നീയും അയാളെ ദേഷ്യം വെക്കുക. അവിടന്ന് പറഞ്ഞു: അപ്പോൾ അയാളെ ജിബ്രീൽ(അ) ദേഷ്യം വെക്കും. പിന്നീട് ജിബ്രീൽ(അ) ആകാശത്തുള്ളവരോട് വിളിച്ച് പറയും: നിശ്ചയം അല്ലാഹു ഇന്നയാളെ ദേഷ്യം വെക്കുന്നു. അതിനാൽ നിങ്ങളും അയാളോട് ദേഷ്യം വെക്കുക. അപ്പോൾ അവർ അവനെ ദേഷ്യം വെക്കും. പിന്നീട് ഭൂമിയിൽ അവനോട് ദേഷ്യം നൽകപ്പെടും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 769, 769, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ – يَرْفَعُهُ – قَالَ: "النَّاسُ مَعَادِنُ كَمَعَادِنِ الْفِضَّةِ وَالذَّهَبِ، خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقُهُوا. وَالْأَرْوَاحُ جُنُودٌ مُجَنَّدَةٌ، فَمَا تَعَارَفَ مِنْهَا ائْتَلَفَ، وَمَا تَنَاكَرَ مِنْهَا اخْتَلَفَ". (م)', 'അബൂഹുറൈറ(റ): - (നബി(സ)യിലേക്ക് ഉയർത്തിക്കൊണ്ട് പറയുന്നു) - നബി(സ) പറഞ്ഞു: "സ്വർണ്ണത്തിന്റെയും വെള്ളിയുടെയും ഖനികൾ പോലെ ജനങ്ങൾ (വ്യത്യസ്ത) ഖനികളാണ്. ജാഹിലിയ്യാ കാലത്ത് നല്ലവരായിരുന്നവർ ജ്ഞാനികളാകുന്നുവെങ്കിൽ ഇസ്ലാമിലും അത്യുത്തമരാണ്. ആത്മാവുകൾ വ്യത്യസ്ത ഇനങ്ങളായി ഒരുമിച്ച് കൂടിയ കൂട്ടങ്ങളാണ്. അവയിൽ പരസ്പരം തിരിച്ചറിഞ്ഞവർ ഇണങ്ങുകയും പരസ്പരം തിരിച്ചറിയാത്തവർ ഭിന്നിക്കുകയും ചെയ്യുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 769, 769, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَحَاسَدُوا، وَلَا تَنَاجَشُوا، وَلَا تَبَاغَضُوا، وَلَا تَدَابَرُوا، وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ، وَكُونُوا عِبَادَ اللهِ إِخْوَانًا. الْمُسْلِمُ أَخُو الْمُسْلِمِ، لَا يَظْلِمُهُ، وَلَا يَخْذُلُهُ، وَلَا يَحْقِرُهُ، التَّقْوَى هَاهُنَا" وَيُشِيرُ إِلَى صَدْرِهِ ثَلَاثَ مَرَّاتٍ "بِحَسْبِ امْرِئٍ مِنَ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ، كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ: دَمُهُ وَمَالُهُ وَعِرْضُهُ". (م,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ പരസ്പരം അസൂയ വെക്കരുത്, പരസ്പരം (കച്ചവടത്തിൽ) വഞ്ചിക്കരുത്, അന്യോന്യം ദേഷ്യം വെക്കരുത്, അന്യോന്യം ശത്രുതവെക്കരുത്, നിങ്ങളിൽ ഒരാൾ കച്ചവടം ചെയ്തതിൻ മേൽ മറ്റൊരാൾ കച്ചവടം ചെയ്യരുത്. അല്ലാഹുവിന്റെ അടിമകളെ, നിങ്ങൾ സഹോദരൻമരാകുക. ഒരു മുസ്ലിം മറ്റൊരു മുസ്ലിമിന്റെ സഹോദരനാണ്. അവനെ അക്രമിക്കുകയും, നിന്ദിക്കുകയും, വഞ്ചിക്കുകയുമരുത്. തഖ്വ(ദൈവഭക്തി) ഇവിടെയാണ്." അവിടന്ന് തന്റെ നെഞ്ചിലേക്ക് (മൂന്ന് പ്രാവശ്യം) ആംഗ്യം കാണിച്ചു. "ഒരാൾ കുറ്റക്കാരനാകാൻ തന്റെ മുസ്ലിം സഹോദരനെ നിന്ദിക്കൽ(മാത്രം) മതി. എല്ലാ മുസ്ലിമിനും മറ്റു മുസ്ലിമിന്റെ രക്തവും സ്വത്തും മാനവും നിഷിദ്ധമാണ്." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 770, 770, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ، وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം, അല്ലാഹു നിങ്ങളുടെ രൂപങ്ങളിലേക്കും നിങ്ങളുടെ സമ്പത്തിലേക്കും നോക്കുകയില്ല. മറിച്ച്, നിങ്ങളുടെ ഹൃദയങ്ങളിലേക്കും പ്രവർത്തനങ്ങളിലേക്കുമാണ് നോക്കുന്നത്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 770, 770, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَحَبَّ الرَّجُلُ أَخَاهُ فَلْيُخْبِرْهُ أَنَّهُ يُحِبُّهُ". (د,ت)', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ്(റ): നബി(സ) ഇപ്രകാരം പറഞ്ഞതായി അദ്ദേഹത്തിന് വിവരം ലഭിച്ചു: "ഒരാൾ തന്റെ സഹോദരനെ സ്നേഹിക്കുന്നുവെങ്കിൽ അവനെ സ്നേഹിക്കുന്നുണ്ടെന്ന് അറിയിച്ചു കൊള്ളട്ടെ." (ദ,തു)', 'الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 770, 770, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا كَانَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَمَرَّ بِهِ رَجُلٌ، فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي لَأُحِبُّ هَذَا، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَعْلَمْتَهُ". قَالَ: لَا، قَالَ: "أَعْلِمْهُ". قَالَ: فَلَحِقَهُ، فَقَالَ: إِنِّي أُحِبُّكَ فِي اللهِ، فَقَالَ: أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ. (د)', 'അനസുബ്നു മാലിക്(റ): ഒരാൾ നബി(സ)യുടെ അടുക്കൽ നിൽക്കുകയായിരുന്നു. അപ്പോൾ തിരുനബി(സ)യുടെ അരികിലൂടെ ഒരാൾ നടന്നു പോയി. അപ്പോൾ അയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, നിശ്ചയം ഞാൻ ഇയാളെ ഇഷ്ടപ്പെടുന്നുണ്ട്. നബി(സ) പറഞ്ഞു: "താങ്കൾ അയാളെ വിവരം അറിയിച്ചിട്ടുണ്ടോ?." അയാൾ പറഞ്ഞു: ഇല്ല. അവിടന്നരുളി: "അയാളെ അറിയിക്കുക." നിവേദകൻ പറയുന്നു: അപ്പോൾ അയാൾ അദ്ദേഹത്തിന്റെ അടുക്കൽ ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ താങ്കളെ ഞാൻ സ്നേഹിക്കുന്നു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: താങ്കളെന്നെ ആർക്കുവേണ്ടിയാണോ ഇഷ്ടപ്പെട്ടത് അവൻ താങ്കളെയും ഇഷ്ടപ്പെടട്ടെ. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 770, 771, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: يَا رَسُولَ اللهِ، الرَّجُلُ يُحِبُّ الْقَوْمَ وَلَا يَسْتَطِيعُ أَنْ يَعْمَلَ كَعَمَلِهِمْ؟ قَالَ: "أَنْتَ يَا أَبَا ذَرٍّ مَعَ مَنْ أَحْبَبْتَ". قَالَ: فَإِنِّي أُحِبُّ اللهَ وَرَسُولَهُ، قَالَ: "فَإِنَّكَ مَعَ مَنْ أَحْبَبْتَ" قَالَ: فَأَعَادَهَا أَبُو ذَرٍّ، فَأَعَادَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'അബൂദർറ്(റ): അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഒരാൾ ഒരു കൂട്ടരെ സ്നേഹിക്കുന്നു. അവരുടെ കർമ്മങ്ങൾ പോലെ കർമ്മങ്ങൾ ചെയ്യാൻ അയാൾക്ക് കഴിയുന്നില്ല. അവന്റെ അവസ്ഥയെന്താണ്? അവിടന്നരുളി: "അബൂദർരേ, താങ്കൾ ഇഷ്ടപ്പെടുന്നവരുടെ കൂടെത്തന്നെയായിരിക്കും താങ്കൾ ഉണ്ടായിരിക്കുക" അദ്ദേഹം പറഞ്ഞു: അപ്പോൾ ഞാൻ അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും സ്നേഹിക്കുന്നു. അവിടന്നരുളി: "എന്നാൽ, നിശ്ചയം താങ്കൾ താൻ സ്നേഹിക്കുന്നവരുടെ കൂടെത്തന്നെയാണ്." നിവേദകൻ പറയുന്നു: അപ്പോൾ അബുദ്ദർദാഅ്(റ) അതാവർത്തിച്ചു ചോദിച്ചു. റസൂൽ(സ)യും അതേ മറുപടി തന്നെ ആവർത്തിച്ചു. (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 771, 771, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ أَصْحَابَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرِحُوا بِشَيْءٍ لَمْ أَرَهُمْ فَرِحُوا بِشَيْءٍ أَشَدَّ مِنْهُ، قَالَ رَجُلٌ: يَا رَسُولَ اللهِ، الرَّجُلُ يُحِبُّ الرَّجُلَ عَلَى الْعَمَلِ مِنَ الْخَيْرِ يَعْمَلُ بِهِ، وَلَا يَعْمَلُ بِمِثْلِهِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمَرْءُ مَعَ مَنْ أَحَبَّ". (ق,د)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ)യുടെ അനുചരൻമാർ ഒരു കാര്യത്തിൽ ഇത്രമേൽ സന്തോഷിക്കുന്നത് മറ്റൊരു കാര്യത്തിലും ഞാൻ കണ്ടിട്ടില്ല: ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഒരാളുടെ സൽകർമ്മങ്ങൾ കണ്ട് മറ്റൊരാൾ അയാളെ സ്നേഹിക്കുന്നു. എന്നാൽ ഇയാൾ അതുപോലെ സൽകർമ്മങ്ങൾ ചെയ്യുന്നുമില്ല, അയാളുടെ അവസ്ഥയെന്താണ്?. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഏതൊരാളും താൻ സ്നേഹിക്കുന്നവരുടെ കൂടെയാണ്." (ബു,മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 771, 771, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنِ ابْنِ عُمَرَ رضي الله عنهما، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُسْلِمُ أَخُو الْمُسْلِمِ: لَا يَظْلِمُهُ وَلَا يُسْلِمُهُ، مَنْ كَانَ فِي حَاجَةِ أخيه فَإِنَّ اللهَ فِي حَاجَتِهِ، وَمَنْ فَرَّجَ عَنْ مُسْلِمٍ كُرْبَةً فَرَّجَ اللهُ عَنْهُ بِهَا كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللهُ يَوْمَ الْقِيَامَةِ". (ق,د,ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ഒരു മുസ്ലിം മറ്റൊരു മുസ്ലിമിന്റെ സഹോദരനാണ്. അവനെ അക്രമിക്കുകയോ കൈവെടിയുകയോ അരുത്. ആരെങ്കിലും തന്റെ സഹോദരന്റെ ആവശ്യ നിർവ്വഹണത്തിലാണെങ്കിൽ നിശ്ചയം അല്ലാഹു അവന്റെ ആവശ്യത്തിലായിരിക്കും. ആരെങ്കിലും ഒരു മുസ്ലിമിനെത്തൊട്ട് വല്ല ബുദ്ധിമുട്ടും അകറ്റിക്കഴിഞ്ഞാൽ അത് കാരണം അല്ലാഹു അന്ത്യനാളിൽ അവന്റെ ബുദ്ധിമുട്ടുകളിൽ നിന്ന് ഒരു ബുദ്ധിമുട്ട് അകറ്റിക്കൊടുക്കും. ആരെങ്കിലും ഒരു മുസ്ലിമിനെ (അവന്റെ മോശത്തരത്തെ) മറച്ച് വെച്ചാൽ അല്ലാഹു അന്ത്യനാളിൽ അവനെ (അവന്റെ മോശത്തരങ്ങളെ) മറച്ച് വെക്കുന്നതാണ്." (ബു,മു,ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 771, 771, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "لَا يَسْتُرُ اللهُ عَلَى عَبْدٍ فِي الدُّنْيَا إِلَّا سَتَرَهُ اللهُ يَوْمَ الْقِيَامَةِ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു ഒരടിമയുടെ രഹസ്യം, ദുൻയാവിൽ മറച്ച് വെക്കുന്നുവെങ്കിൽ, അന്ത്യനാളിലും അവന്റെ രഹസ്യങ്ങളെ അല്ലാഹു മറച്ച് വെക്കുന്നതാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 772, 772, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَسْتُرُ عَبْدٌ عَبْدًا فِي الدُّنْيَا إِلَّا سَتَرَهُ اللهُ يَوْمَ الْقِيَامَةِ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ദുനിയാവിൽ ഒരടിമ മറ്റൊരു അടിമയുടെ കുറവിനെ മറച്ച് വെക്കുന്നുവെങ്കിൽ അല്ലാഹു അന്ത്യനാളിൽ അവന്റെ കുറവിനെയും മറച്ച് വെക്കുന്നതാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 772, 772, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "كُلُّ أُمَّتِي مُعَافًى إِلَّا الْمُجَاهِرُونَ وَإِنَّ مِنَ الْمَجَانَةِ أَنْ يَعْمَلَ الرَّجُلُ بِاللَّيْلِ عَمَلًا ثُمَّ يُصْبِحُ وَقَدْ سَتَرَهُ اللهُ عَلَيْهِ فَيَقُولُ: يَا فُلَانُ، عَمِلْتُ الْبَارِحَةَ كَذَا وَكَذَا وَقَدْ بَاتَ يَسْتُرُهُ رَبُّهُ وَيُصْبِحُ يَكْشِفُ سِتْرَ اللهِ عَنْهُ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "എന്റെ സമുദായം മുഴുവൻ സംരക്ഷിതരാണ്, (അല്ലാഹു മറച്ച് വെച്ചതിനെ) പരസ്യപ്പെടുത്തുന്നവരൊഴികെ. ഒരാൾ രാത്രിയിൽ ഒരു ദുഷ്പ്രവർത്തി ചെയ്യുകയും പിന്നീട് അല്ലാഹു അത് മറച്ച് വെച്ചിരിക്കെ, നേരം വെളുത്തതിന് ശേഷം ഞാനിന്നലെ രാത്രി ഇങ്ങനെയൊക്കെ ചെയ്തുവെന്നു പറയുകയും ചെയ്താൽ തീർച്ചയായും അത് ആഭാസ സംസാരങ്ങളിൽ പെട്ടതാണ്. രാത്രി അവനെ (അവന്റെ പ്രവർത്തിയെ) അവന്റെ രക്ഷിതാവ് മറച്ചു വെക്കുന്നു. നേരം പുലർന്ന് അല്ലാഹു അവന്റെ മേൽ ഇട്ട മറ അവൻ നീക്കം ചെയ്യുകയും ചെയ്യുന്നു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 772, 772, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ رَدَّ عَنْ عِرْضِ أَخِيهِ رَدَّ اللهُ عَنْ وَجْهِهِ النَّارَ يَوْمَ الْقِيَامَةِ" حَسَنٌ (ن)', 'അബുദ്ദർദാഅ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും തന്റെ സഹോദരന്റെ അഭിമാനം സംരക്ഷിച്ചാൽ അല്ലാഹു അന്ത്യനാളിൽ തീയിൽ നിന്ന് അവന്റെ മുഖത്തെ സംരക്ഷിക്കുന്നതാണ്." (ന)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 772, 772, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ رَأَى عَوْرَةً فَسَتَرَهَا كَانَ كَمَنْ أَحْيَا مَوْءُودَةً". وَفِي رِوَايَةٍ عَنْ دُخَيْنٍ – كَاتِبِ عُقْبَةَ بْنِ عَامِرٍ – قَالَ: كَانَ لَنَا جِيرَانٌ يَشْرَبُونَ الْخَمْرَ، فَنَهَيْتُهُمْ فَلَمْ يَنْتَهُوا، فَقُلْتُ لِعُقْبَةَ بْنِ عَامِرٍ: إِنَّ جِيرَانَنَا هَؤُلَاءِ يَشْرَبُونَ الْخَمْرَ، وَإِنِّي نَهَيْتُهُمْ فَلَمْ يَنْتَهُوا، فَأَنَا دَاعٍ لَهُمُ الشُّرَطَ فَقَالَ: دَعْهُمْ، ثُمَّ رَجَعْتُ إِلَى عُقْبَةَ مَرَّةً أُخْرَى فَقُلْتُ: إِنَّ جِيرَانَنَا قَدْ أَبَوْا أَنْ يَنْتَهُوا عَنْ شُرْبِ الْخَمْرِ، وَأَنَا دَاعٍ لَهُمُ الشُّرَطَ. قَالَ: وَيْحَكَ دَعْهُمْ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فَذَكَرَ مَعْنَى الْحَدِيثِ. وفي رواية: قَالَ: لَا تَفْعَلْ، وَلَكِنْ عِظْهُمْ وَتَهَدَّدْهُمْ". (د)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു ന്യൂനത കണ്ട് അത് മറച്ചുവെച്ചാൽ അവൻ ജീവനോട് കുഴിച്ച് മൂടപ്പെട്ടവളെ ജീവിപ്പിച്ചവനെപ്പോലെയാണ്." ദുഖൈൻ(റ)വിൽ – ഉഖ്ബതുബ്നു ആമിർ(റ)വിന്റെ എഴുത്തുകാരൻ – നിന്നും നിവേദനം: ഞങ്ങൾക്ക് കള്ളുകുടിക്കുന്ന അയൽക്കാരുണ്ടായിരുന്നു. ഞാനതിനെ നിർത്താൻ അവരോട് പറഞ്ഞു. പക്ഷേ, അവർ അതൊഴിവാക്കിയില്ല. അപ്പോൾ ഞാൻ ഉഖ്ബതുബ്നു ആമിർ(റ)നോട് പറഞ്ഞു: ഞങ്ങളുടെ ഈ അയൽവാസി തീർച്ചയായും കള്ളുകുടിക്കുന്നു. ഞാനവരെ തടഞ്ഞപ്പോൾ അവർ ഉപേക്ഷിച്ചില്ല. അതിനാൽ ഞാൻ അവർക്കെതിരിൽ പട്ടാളക്കാരെ വിളിക്കുകയാണ്. അദ്ദേഹം പറഞ്ഞു: നീ അവരെ ഒഴിവാക്കുക. പിന്നീട് ഞാൻ ഒരിക്കൽ കൂടി ഉഖ്ബതുബ്നു ആമിർ(റ)വിന്റെയടുത്തേക്ക് തിരിച്ചു വന്നു പറഞ്ഞു: ഞങ്ങളുടെ അയൽവാസി കള്ളുകുടി നിർത്താൻ വിസമ്മതിച്ചിരിക്കുന്നു. ഞാൻ പട്ടാളക്കാരെ വിളിക്കുകയാണ്. അദ്ദേഹം പറഞ്ഞു: കഷ്ടം! നീ അവരെ ഒഴിവാക്കൂ. കാരണം, റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. എന്നിട്ട് (മുമ്പത്തെ) ഹദീസിന്റെ ആശയം പറഞ്ഞു: മറ്റൊരു റിപ്പോർട്ടിൽ: നീ അങ്ങനെ ചെയ്യരുത്. എങ്കിലും അവരെ ഉപദേശിക്കുകയും ഭീഷണിപ്പെടുത്തുകയും ചെയ്യുക. (ദ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 772, 773, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=110), 1, 'وَفِي رِوَايَةٍ عَنْ دُخَيْنٍ – كَاتِبِ عُقْبَةَ بْنِ عَامِرٍ – قَالَ: كَانَ لَنَا جِيرَانٌ يَشْرَبُونَ الْخَمْرَ، فَنَهَيْتُهُمْ فَلَمْ يَنْتَهُوا، فَقُلْتُ لِعُقْبَةَ بْنِ عَامِرٍ: إِنَّ جِيرَانَنَا هَؤُلَاءِ يَشْرَبُونَ الْخَمْرَ، وَإِنِّي نَهَيْتُهُمْ فَلَمْ يَنْتَهُوا، فَأَنَا دَاعٍ لَهُمُ الشُّرَطَ فَقَالَ: دَعْهُمْ، ثُمَّ رَجَعْتُ إِلَى عُقْبَةَ مَرَّةً أُخْرَى فَقُلْتُ: إِنَّ جِيرَانَنَا قَدْ أَبَوْا أَنْ يَنْتَهُوا عَنْ شُرْبِ الْخَمْرِ، وَأَنَا دَاعٍ لَهُمُ الشُّرَطَ. قَالَ: وَيْحَكَ دَعْهُمْ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فَذَكَرَ مَعْنَى الْحَدِيثِ.', 'മറ്റൊരു നിവേദനിൽ: നീ അങ്ങനെ ചെയ്യരുത്. എങ്കിലും അവരെ ഉപദേശിക്കുകയും ഭീഷണിപ്പെടുത്തുകയും ചെയ്യുക. (ദ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=110), 2, 'وَفِي رِوَايَةٍ: قَالَ: لَا تَفْعَلْ، وَلَكِنْ عِظْهُمْ وَتَهَدَّدْهُمْ". (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ نَفَّسَ عَنْ مُسْلِمٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ سَتَرَ عَلَى مُسْلِمٍ فِي الدُّنْيَا سَتَرَ اللهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَاللهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ". (م,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) അരുളി: "ആരെങ്കിലും ഒരു മുസ്ലിമിന്റെ ഇഹലോകത്തിലെ ബുദ്ധിമുട്ടുകളിൽ നിന്നേതെങ്കിലുമൊന്ന് ഒഴിവാക്കിക്കൊടുത്താൽ അന്ത്യനാളിലെ ബുദ്ധിമുട്ടുകളിൽ നിന്നൊന്ന് അവന് അല്ലാഹു അകറ്റിക്കൊടുക്കുന്നതാണ്. ആരെങ്കിലും പ്രയാസമനുഭവിക്കുന്ന ഒരുവന് സമാധാനത്തിന്റെ വഴി തുറന്നുകൊടുത്താൽ അവന് അല്ലാഹു ഇഹലോകത്തും പരലോകത്തും പ്രയാസങ്ങളെ ദൂരീകരിച്ച് കൊടുക്കും. ആരെങ്കിലും ഒരു മുസ്ലിമിന്റെ മോശത്തരത്തെ മറച്ച് വെച്ചാൽ അല്ലാഹു ഇഹത്തിലും പരത്തിലും അവന്റെ മോശത്തരത്തെ മറച്ച് വെക്കുന്നതാണ്. അടിമ തന്റെ സഹോദരനെ സഹായിച്ച് കൊണ്ടിരിക്കുമ്പോഴൊക്കെയും അവനെ അല്ലാഹു സഹായിച്ച് കൊണ്ടിരിക്കും." (മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 773, 773, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَبَاغَضُوا، وَلَا تَحَاسَدُوا، وَلَا تَدَابَرُوا، وَكُونُوا عِبَادَ اللهِ إِخْوَانًا، وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثِ لَيَالٍ". (ق,د,ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പരസ്പരം വിദ്വേഷം വെക്കരുത്. പരസ്പരം അസൂയ വെക്കരുത്. പരസ്പരം ശത്രുത വെക്കരുത്. അല്ലാഹുവിന്റെ അടിമകളേ, നിങ്ങൾ സഹോദരങ്ങളാവുക. ഒരു മുസ്ലിമിനും തന്റെ സഹോദരനോട് മൂന്ന് രാവുകളിലേറെ പിണങ്ങി നിൽക്കൽ അനുവദനീയമല്ല." (ബു,മു,ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 773, 773, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثَةِ أَيَّامٍ: يَلْتَقِيَانِ، فَيُعْرِضُ هَذَا وَيُعْرِضُ هَذَا، وَخَيْرُهُمَا الَّذِي يَبْدَأُ بِالسَّلَامِ". (ق,د,ت)', 'അബൂഅയ്യൂബിൽ അൻസാരി(റ): റസൂൽ(സ) പറയുന്നു: "ഒരു മുസ്ലിമിനും തന്റെ സഹോദരനുമായി മൂന്ന് ദിവസത്തിലധികം തെറ്റിനിൽക്കൽ അനുവദനീയമല്ല. ഇരുവരും കണ്ടുമുട്ടുന്നു, ഇയാൾ മുഖം തിരിക്കുന്നു. അയാളും തിരിഞ്ഞുകളയുന്നു. അവരിൽ അത്യുത്തമൻ ആദ്യം സലാം പറയുന്നവനാണ്''." (ബു,മു,ദ,തു)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂഅയ്യൂബിൽ അൻസാരി(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 773, 774, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَحِلُّ لِمُؤْمِنٍ أَنْ يَهْجُرَ مُؤْمِنًا فَوْقَ ثَلَاثٍ، فَإِنْ مَرَّتْ بِهِ ثَلَاثٌ فَلْيَلْقَهُ فَلْيُسَلِّمْ عَلَيْهِ، فَإِنْ رَدَّ عَلَيْهِ السَّلَامَ فَقَدِ اشْتَرَكَا فِي الْأَجْرِ، وَإِنْ لَمْ يَرُدَّ عَلَيْهِ فَقَدْ بَاءَ بِالْإِثْمِ، وَخَرَجَ الْمُسَلِّمُ مِنَ الْهِجْرَةِ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നു: "ഒരു മുഅ്മിനിനും മൂന്ന് ദിവസത്തിലധികം മറ്റൊരു മുഅ്മിനിനോട് പിണങ്ങിനിൽക്കൽ അനുവദനീയമല്ല. മൂന്ന് ദിവസം കഴിഞ്ഞാൽ അവനയാളെ കണ്ട് മുട്ടി സലാം പറയട്ടെ. അപ്പോൾ അയാൾ സലാം മടക്കിയാൽ ഇരുവരും പ്രതിഫലത്തിൽ പങ്കാളികളായി. അയാൾ സലാം മടക്കിയില്ലെങ്കിൽ അയാൾ ശിക്ഷക്കർഹനായി. സലാം ചൊല്ലിയവൻ ബന്ധം വിച്ഛേദിക്കലിൽ നിന്ന് രക്ഷപ്പെട്ടു." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 774, 774, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَكُونُ لِمُسْلِمٍ أَنْ يَهْجُرَ مُسْلِمًا فَوْقَ ثَلَاثَةٍ، فَإِذَا لَقِيَهُ سَلَّمَ عَلَيْهِ ثَلَاثَ مِرَارٍ، كُلُّ ذَلِكَ لَا يَرُدُّ عَلَيْهِ فَقَدْ بَاءَ بِإِثْمِهِ". (د)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു മസ്ലിമും മറ്റൊരു മുസ്ലിമിനോട് മൂന്ന് ദിവസത്തിലധികം പിണങ്ങിനിൽക്കാൻ പാടില്ല. ഇനി അവനയാളെ കണ്ടുമുട്ടിയാൽ മൂന്ന് വട്ടം സലാം പറയട്ടെ. അവയൊന്നുമയാൾ മടക്കിയില്ലെങ്കിൽ തീർച്ചയായുമയാൾ ശിക്ഷക്കർഹനായി." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 774, 774, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثٍ، فَمَنْ هَجَرَ فَوْقَ ثَلَاثٍ فَمَاتَ دَخَلَ النَّارَ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് ദവസത്തിലധികം തന്റെ സഹോദരനോട് പിണങ്ങി നിൽക്കൽ ഒരു മുസ്ലിമിനും അനുവദനീയമല്ല. ആരെങ്കിലും മൂന്നിലധികം ദിവസം പിണങ്ങി നിൽക്കുകയും അങ്ങനെ മരിക്കുകയും ചെയ്താൽ അവൻ നരകത്തിൽ പ്രവേശിക്കുന്നതാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 774, 774, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ أَبِي خِرَاشٍ السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ هَجَرَ أَخَاهُ سَنَةً فَهُوَ كَسَفْكِ دَمِهِ". (د)', 'അബൂഖിറാശിസ്സുലമീ(റ): അദ്ദേഹം റസൂൽ(സ) പറയുന്നത് കേട്ടു: "ആരെങ്കിലും തന്റെ സഹോദരനോട് ഒരു വർഷം പിണങ്ങിനിന്നാൽ അത് അവന്റെ രക്തം ചിന്തിയ പോലെയാണ്." (ദ)', 'أَبِي خِرَاشٍ السُّلَمِيِّ', 'അബൂഖിറാശിസ്സുലമീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 774, 774, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تُفْتَحُ أَبْوَابُ الْجَنَّةِ يَوْمَ الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ، فَيُغْفَرُ لِكُلِّ عَبْدٍ لَا يُشْرِكُ بِاللهِ شَيْئًا، إِلَّا رَجُلًا كَانَتْ بَيْنَهُ وَبَيْنَ أَخِيهِ شَحْنَاءُ، فَيُقَالُ: أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا، أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا، [أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا]". (م,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തിങ്കളാഴ്ചയും വ്യാഴാഴ്ചയും സ്വർഗ്ഗവാതിലുകൾ തുറക്കപ്പെടും. അല്ലാഹുവിനോട് ഒന്നിനെയും പങ്കുചേർക്കാത്ത എല്ലാ അടിമകൾക്കും അപ്പോൾ പൊറുക്കപ്പെടും, തന്റെയും തന്റെ സഹോദരന്റെയുമിടയിൽ പകയുള്ളവന് ഒഴികെ. അപ്പോൾ പറയപ്പെടും: അവർ നല്ല നിലയിലാകുന്നത് വരെ അവരെ പ്രതീക്ഷിക്കുക, അവർ നല്ല നിലയിലാകുന്നത് വരെ അവരെ പ്രതീക്ഷിക്കുക. (അവർ നല്ല നിലയിലാകുന്നത് വരെ അവരെ പ്രതീക്ഷിക്കുക.)" (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], 'أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا', null, 774, 774, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا دَعْوَةٌ أَسْرَعُ إِجَابَةً مِنْ دَعْوَةِ غَائِبٍ لِغَائِبٍ". (د,ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ മറ്റൊരാൾക്ക് വേണ്ടി അയാളുടെ അസാന്നിധ്യത്തിൽ പ്രാർത്ഥിക്കുന്ന പ്രാർത്ഥനയേക്കാൾ പെട്ടെന്ന് ഉത്തരം കിട്ടുന്ന ഒരു പ്രാർത്ഥനയുമില്ല." (ദ,തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 775, 775, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اشْفَعُوا إِلَيَّ لِتُؤْجَرُوا، وَلْيَقْضِ اللهُ عَلَى لِسَانِ نَبِيِّهِ مَا شَاءَ". (ق,د,ت,ن)', 'അബൂമൂസ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ അടുക്കലേക്ക് നിങ്ങൾ ശിപാർശ ചെയ്യുവീൻ. നിങ്ങൾക്ക് കൂലി നൽകപ്പെടും. അല്ലാഹു തന്റെ പ്രവാചകനിലൂടെ താൻ ഇച്ഛിക്കുന്നത് വിധിക്കുകയും ചെയ്യട്ടെ." (ബു,മു,ദ,തു,ന)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 775, 775, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: اشْفَعُوا تُؤْجَرُوا، فَإِنِّي لَأُرِيدُ الْأَمْرَ فَأُؤَخِّرُهُ كَيْمَا تَشْفَعُوا فَتُؤْجَرُوا، فَإِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اشْفَعُوا تُؤْجَرُوا". وَفِي رِوَايَةٍ: عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صلى الله عليه وسلم، مِثْلَهُ. (د,ن)', 'മുആവിയ(റ): നിങ്ങൾ (പരസ്പരം) ശിപാർശ ചെയ്യുവീൻ. എങ്കിൽ നിങ്ങൾക്ക് പ്രതിഫലം നൽകപ്പെടും. നിശ്ചയം ഞാനൊരു കാര്യം തീരുമാനിച്ചാൽ നിങ്ങൾ ശിപാർശ ചെയ്യാനും അങ്ങിനെ നിങ്ങൾക്ക് പ്രതിഫലം ലഭിക്കാനും വേണ്ടി ഞാൻ അത് പിന്തിക്കും. കാരണം, റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "നിങ്ങൾ ശിപാർശ ചെയ്യുവീൻ. പ്രതിഫലം നൽകപ്പെടും."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=121), 1, 'وَفِي رِوَايَةٍ: عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صلى الله عليه وسلم، مِثْلَهُ. (د,ن)', 'മറ്റൊരു നിവേദനം: അബൂമൂസ(റ) നബി(സ)യിൽ നിന്നും ഇതുപോലെയുള്ള ഹദീസ് നിവേദനം ചെയ്യുന്നു. (ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّمَا مَثَلُ الْجَلِيسِ الصَّالِحِ وَالْجَلِيسِ السَّوْءِ كَحَامِلِ الْمِسْكِ وَنَافِخِ الْكِيرِ: فَحَامِلُ الْمِسْكِ إِمَّا أَنْ يُحْذِيَكَ وَإِمَّا أَنْ تَبْتَاعَ مِنْهُ، وَإِمَّا أَنْ تَجِدَ مِنْهُ رِيحًا طَيِّبَةً. وَنَافِخُ الْكِيرِ إِمَّا أَنْ يُحْرِقَ ثِيَابَكَ، وَإِمَّا أَنْ تَجِدَ رِيحًا خَبِيثَةً". (م)', 'അബൂമൂസ(റ): നബി(സ) പറഞ്ഞു: "നല്ല കൂട്ടുകാരന്റെയും ചീത്ത കൂട്ടുകാരന്റെയും ഉപമ, കസ്തൂരി വാഹകനെയും ഉലയിലൂതുന്നവനെയും പോലെയാണ്. കസ്തൂരിക്കാരൻ ഒരു പക്ഷേ നിനക്ക് കസ്തൂരി പുരട്ടിത്തന്നേക്കും. അല്ലെങ്കിൽ നീ അവനിൽ നിന്ന് കസ്തൂരി വാങ്ങിയേക്കും. അതുമല്ലെങ്കിൽ അവന്റെ അടുക്കൽ നിന്ന് സുഗന്ധം നിനക്ക് ലഭിക്കാം. ഉലയിലൂതുന്നവൻ ഒരുപക്ഷേ നിന്റെ വസ്ത്രം കരിച്ചു കളഞ്ഞേക്കാം. അല്ലെങ്കിൽ ദുഷിച്ച വാസന നിനക്ക് അനുഭവപ്പെടാം." (മു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 775, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ شَيْءٍ أَثْقَلُ فِي مِيزَانِ الْمُؤْمِنِ يَوْمَ الْقِيَامَةِ مِنْ خُلُقٍ حَسَنٍ، وَإِنَّ اللهَ لَيُبْغِضُ الْفَاحِشَ الْبَذِيءَ". حَسَنٌ صَحِيحٌ. (د,ت)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "സൽസ്വഭാവത്തേക്കാൾ കനമുള്ളതായി ഒന്നും തന്നെ അന്ത്യനാളിൽ മുഅ്മിനിന്റെ മീസാനിൽ(തുലാസിൽ) ഉണ്ടാവുകയില്ല. മോശക്കാരനായ അശ്ലീലക്കാരനോട് അല്ലാഹു തീർച്ചയായും ദേഷ്യപ്പെടുക തന്നെ ചെയ്യും." ദ,തു)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د','ت']::text[], '{}'::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ شَيْءٍ يُوضَعُ فِي الْمِيزَانِ أَثْقَلُ مِنْ حُسْنِ الْخُلُقِ، وَإِنَّ صَاحِبَ حُسْنِ الْخُلُقِ لَيَبْلُغُ بِهِ دَرَجَةَ صَاحِبِ الصَّوْمِ وَالصَّلَاةِ". (د,ت)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "സൽസ്വഭാവത്തോളം ഭാരമുള്ള ഒരൊറ്റ വസ്തുവും മീസാനിൽ വെക്കപ്പെടുന്നതായി ഇല്ല. സൽസ്വഭാവം ഉള്ളയാൾ അതുകൊണ്ട് നിസ്കാരത്തിന്റെയും നോമ്പിന്റെയും ആളുകളുടെ സ്ഥാനത്തെത്തുക തന്നെ ചെയ്യും." (ദ,തു)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ أَكْثَرِ مَا يُدْخِلُ النَّاسَ الْجَنَّةَ؟ فَقَالَ: "تَقْوَى اللهِ وَحُسْنُ الْخُلُقِ". وَسُئِلَ عَنْ أَكْثَرِ مَا يُدْخِلُ النَّاسَ النَّارَ؟ فَقَالَ: "الْفَمُ وَالْفَرْجُ". صَحِيحٌ. (ت)', 'അബൂഹുറൈറ(റ): ജനങ്ങൾക്ക് ഏറ്റവും കൂടുതലായി സ്വർഗ്ഗപ്രവേശനം നൽകുന്ന കാര്യമേതാണ്? എന്ന് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ അവിടന്നരുളി: "അല്ലാഹുവിൽ തഖ്വ(ഭക്തി) ചെയ്യലും സൽസ്വഭാവവും." ജനങ്ങളെ കൂടുതൽ നരകത്തിൽ കടത്തുന്നതെന്താണെന്ന് അവിടത്തോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ പറഞ്ഞു: "നാവും ഗുഹ്യസ്ഥാനവും." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنَا زَعِيمٌ بِبَيْتٍ فِي رَبَضِ الْجَنَّةِ لِمَنْ ترك الْمِرَاءَ وَإِنْ كَانَ مُحِقًّا، وَبِبَيْتٍ فِي وَسَطِ الْجَنَّةِ لِمَنْ تَرَكَ الْكَذِبَ وَإِنْ كَانَ مَازِحًا، وَبِبَيْتٍ فِي أَعْلَى الْجَنَّةِ لِمَنْ حَسَّنَ خُلُقَهُ". (د)', 'അബൂ ഉമാമ(റ): നബി(സ) പറഞ്ഞു: "അവകാശമുണ്ടായിട്ടും തർക്കമൊഴിവാക്കുന്നവന് സ്വർഗത്തിന്റെ ചെരുവിലൊരു വീടുണ്ടാകുമെന്നത് കൊണ്ടും, തമാശക്കാണെങ്കിലും കളവ് ഉപേക്ഷിക്കുന്നവന് സ്വർഗത്തിന്റെ മധ്യത്തിലൊരു വീടുണ്ടാകുമെന്നത് കൊണ്ടും, സ്വഭാവം നന്നാക്കിയവന് സ്വർഗത്തിന്റെ മുകളിലൊരു വീടുണ്ടാകുമെന്നത് കൊണ്ടും ഞാൻ ജാമ്യക്കാരനാണ്." (ദ)', 'أَبِي أُمَامَةَ', 'അബൂ ഉമാമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ حَارِثَةَ بْنِ وَهْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَدْخُلُ الْجَنَّةَ الْجَوَّاظُ، وَلَا الْجَعْظَرِيُّ" قَالَ: وَالْجَوَّاظُ الْغَلِيظُ الْفَظُّ. (ق,د,ت,جه)', 'ഹാരിസതുബ്നു വഹ്ബ്(റ): നബി(സ) പറഞ്ഞു: "കഠിനസ്വഭാവക്കാരനും അഹങ്കാരിയും സ്വർഗത്തിൽ കടക്കുകയില്ല." നിവേദകൻ പറയുന്നു: ''ജവ്വാള്'' എന്ന വാക്കിനർത്ഥം കഠിന സ്വഭാവക്കാരൻ എന്നാണ്. (ബു,മു,ദ,തു,ജ)', 'حَارِثَةَ بْنِ وَهْبٍ', 'ഹാരിസതുബ്നു വഹ്ബ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ عَبْدِ اللهِ بْنِ الْمُبَارَكِ: أَنَّهُ وَصَفَ حُسْنَ الْخُلُقِ فَقَالَ: هُوَ بَسْطُ الْوَجْهِ، وَبَذْلُ الْمَعْرُوفِ وَكَفُّ الْأَذَى. (ت)', 'അബ്ദുല്ലാഹിബ്നുൽ മുബാറക്(റ): അദ്ദേഹം സൽകർമത്തെ വിവരിച്ച് കൊണ്ട് പറഞ്ഞു: അത് മുഖപ്രസന്നതയും നന്മചെയ്യലും ബുദ്ധിമുട്ടുകളകറ്റലുമാണ്. (തു)', 'عَبْدِ اللهِ بْنِ الْمُبَارَكِ', 'അബ്ദുല്ലാഹിബ്നുൽ മുബാറക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 776, 777, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ أَبِي ذَرٍّ وَمُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُمَا قَالَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اتَّقِ اللهَ حَيْثُمَا كُنْتَ، وَأَتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا، وَخَالِقِ النَّاسَ بِخُلُقٍ حَسَنٍ". حَسَنٌ صَحِيحٌ. (ت)', 'അബൂദർറ്(റ), മുആദുബ്നു ജബൽ(റ): നബി(സ) പറഞ്ഞു: "നീ ഏതവസ്ഥയിലായാലും അല്ലാഹുവിനെ സൂക്ഷിക്കുക. തിന്മ ചെയ്താലുടൻ അതിനെ മായ്ച്ചുകളയുന്ന നന്മ ചെയ്യുക. ജനങ്ങളോട് നല്ല സ്വഭാവത്തിൽ പെരുമാറുകയും ചെയ്യുക." (തു)', 'أَبِي ذَرٍّ وَمُعَاذِ بْنِ جَبَلٍ', 'അബൂദർറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 777, 777, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ أَحْسَنِ النَّاسِ خُلُقًا، فَأَرْسَلَنِي يَوْمًا لِحَاجَةٍ، فَقُلْتُ: وَاللهِ لَا أَذْهَبُ، وَفِي نَفْسِي أَنْ أَذْهَبَ لِمَا أَمَرَنِي بِهِ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَخَرَجْتُ، حَتَّى أَمُرَّ عَلَى صِبْيَانٍ وَهُمْ يَلْعَبُونَ فِي السُّوقِ، فَإِذَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَابِضٌ بِقَفَايَ مِنْ وَرَائِي، فَنَظَرْتُ إِلَيْهِ وَهُوَ يَضْحَكُ، فَقَالَ: "يَا أُنَيْسُ، اذْهَبْ حَيْثُ أَمَرْتُكَ" قُلْتُ: نَعَمْ، أَنَا أَذْهَبُ يَا رَسُولَ اللهِ، قَالَ أَنَسٌ: وَاللهِ لَقَدْ خَدَمْتُهُ سَبْعَ سِنِينَ، أَوْ: تِسْعَ سِنِينَ، مَا عَلِمْتُ قَالَ لِشَيْءٍ صَنَعْتُ: لِمَ فَعَلْتَ كَذَا وَكَذَا، وَلَا لِشَيْءٍ تَرَكْتُ: هَلَّا فَعَلْتَ كَذَا وَكَذَا. (م,د)', 'അനസ്(റ): ജനങ്ങളിൽ ഏറ്റവും സൽസ്വഭാവി റസൂൽ(സ) ആയിരുന്നു. അവിടന്ന് ഒരിക്കൽ ഒരാവശ്യാർത്ഥം എന്നെ അയക്കുകയുണ്ടായി. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഞാൻ പോവുകയില്ല. എന്റെ മനസ്സിൽ അവിടന്ന് കൽപിച്ച കാര്യത്തിന് പോകണമെന്നുണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞാൻ പുറപ്പെട്ടു. അങ്ങാടിയിൽ കളിച്ചു കൊണ്ടിരിക്കുന്ന ചില കുട്ടികൾക്കടുത്തു കൂടെ ഞാൻ പോകാനിടയായി. അപ്പോൾ, റസൂൽ(സ) എന്റെ പിന്നിൽ നിന്നും എന്റെ പിരടിയിൽ പിടിച്ചു. ഞാൻ തിരിഞ്ഞു നോക്കിയപ്പോൾ അവിടന്ന് ചിരിച്ചു. എന്നിട്ട് പറഞ്ഞു: "ഉനൈസ്, ഞാൻ പോകാൻ കൽപിച്ച സ്ഥലത്ത് പോകൂ." ഞാൻ പറഞ്ഞു: അതെ, ഞാൻ പോകാം റസൂലേ. അനസ്(റ) പറയുന്നു: അല്ലാഹുവാണ, തിരുമേനി(സ)ക്ക് ഞാൻ ഏഴ് (അല്ലെങ്കിൽ ഒമ്പത്) വർഷം സേവനം ചെയ്തു. ഞാൻ ചെയ്ത ഒരു കാര്യത്തിനും നീ ''എന്തിനിങ്ങനെ ചെയ്തു?'' എന്നോ ഞാൻ ഒഴിവാക്കിയതിനെക്കുറിച്ച് ''നിനക്കിത് ചെയ്തു കൂടായിരുന്നോ?'' എന്നും അവിടന്ന് ചോദിച്ചതായി എനിക്കറിയില്ല. (മു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 777, 777, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَدَمْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَشْرَ سِنِينَ بِالْمَدِينَةِ، وَأَنَا غُلَامٌ لَيْسَ كُلُّ أَمْرِي كَمَا يَشْتَهِي صَاحِبِي أَنْ أَكُونَ عَلَيْهِ، مَا قَالَ: لِي فِيهَا أُفٍّ قَطُّ، وَمَا قَالَ لِي: لِمَ فَعَلْتَ هَذَا؟ أَوْ: أَلَّا فَعَلْتَ هَذَا. (د)', 'അനസ്(റ): ഞാൻ മദീനയിൽ വെച്ച് നബി(സ)ക്ക് പത്ത് വർഷം സേവനമനുഷ്ഠിച്ചു. ഞാൻ കുട്ടിയായിരുന്നത് കൊണ്ട് എന്റെ കാര്യമൊന്നും എന്റെ ആൾ (തിരുമേനി(സ)) ആഗ്രഹിച്ചതു പോലെയായിരുന്നില്ല. അവിടന്നെന്നോട് ഒരിക്കലും ''ഛെ'' എന്ന് പറഞ്ഞിട്ടില്ല. ''നീ എന്തിന് ചെയ്തു'' എന്നോ ''നീ ഇത് ചെയ്തില്ലേ'' എന്നോ അവിടന്ന് പറഞ്ഞിട്ടില്ല. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 777, 778, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَجْلِسُ مَعَنَا فِي الْمَجْلِسِ يُحَدِّثُنَا، فَإِذَا قَامَ قُمْنَا قِيَامًا حَتَّى نَرَاهُ قَدْ دَخَلَ بَعْضَ بُيُوتِ أَزْوَاجِهِ، فَحَدَّثَنَا يَوْمًا، فَقُمْنَا حِينَ قَامَ، فَنَظَرْنَا إِلَى أَعْرَابِيٍّ قَدْ أَدْرَكَهُ فَجَبَذَهُ بِرِدَائِهِ فَحَمَّرَ رَقَبَتَهُ، قَالَ أَبُو هُرَيْرَةَ: وَكَانَ رِدَاءً خَشِنًا، فَالْتَفَتَ، فَقَالَ لَهُ الْأَعْرَابِيُّ: احْمِلْ لِي عَلَى بَعِيرَيَّ هَذَيْنِ، فَإِنَّكَ لَا تَحْمِلُ لِي مِنْ مَالِكَ وَلَا مِنْ مَالِ أَبِيكَ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا، وَأَسْتَغْفِرُ اللهَ، لَا، وَأَسْتَغْفِرُ اللهَ، لَا، وَأَسْتَغْفِرُ اللهَ، لَا أَحْمِلُ لَكَ حَتَّى تُقِيدَنِي مِنْ جَبْذَتِكَ الَّتِي جَبَذْتَنِي". فَكُلُّ ذَلِكَ يَقُولُ لَهُ الْأَعْرَابِيُّ: وَاللهِ لَا أُقِيدُكَهَا، فَذَكَرَ الْحَدِيثَ، قَالَ: ثُمَّ دَعَا رَجُلًا فَقَالَ لَهُ: "احْمِلْ لَهُ عَلَى بَعِيرَيْهِ هَذَيْنِ: عَلَى بَعِيرٍ شَعِيرًا، وَعَلَى الْآخَرِ تَمْرًا". ثُمَّ الْتَفَتَ إِلَيْنَا فَقَالَ: "انْصَرِفُوا عَلَى بَرَكَةِ اللهِ تَعَالَى". (د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) ഞങ്ങളോട് സംസാരിച്ചുകൊണ്ട് ഞങ്ങളുടെ കൂടെ സദസ്സിലിരിക്കാറുണ്ടായിരുന്നു. അവിടന്നെഴുന്നേറ്റാൽ തന്റെ ഏതെങ്കിലും ഭാര്യാവീട്ടിൽ പ്രവേശിക്കും വരെ ഞങ്ങളും എഴുന്നേറ്റ് നിൽക്കുമായിരുന്നു. അവിടന്നൊരു ദിവസം ഞങ്ങളോട് സംസാരിച്ചു. അങ്ങനെ അവിടന്നെഴുന്നേറ്റപ്പോൾ ഞങ്ങൾ എഴുന്നേറ്റു. അപ്പോൾ ഒരു അഅ്റാബി അവിടത്തെ അടുക്കൽ വന്ന് മേൽവസ്ത്രം വലിക്കുകയും അവിടത്തെ പിരടി ചുവക്കുകയും ചെയ്തത് ഞങ്ങൾ കണ്ടു. അബൂഹുറൈറ(റ) പറയുന്നു: അത് പരുഷമായ മേൽവസ്ത്രമായിരുന്നു. അവിടന്ന് തിരിഞ്ഞ് നോക്കി. അപ്പോൾ തിരുമേനി(സ)യോട് ആ അഅ്റാബി പറഞ്ഞു: എന്റെ ഈ രണ്ട് ഒട്ടകങ്ങൾക്ക് വഹിക്കാനുള്ള ഭക്ഷണം തരൂ. നിശ്ചയം താങ്കൾ താങ്കളുടെ സ്വത്തിൽ നിന്നോ താങ്കളുടെ പിതാവിന്റെ സ്വത്തിൽ നിന്നോ അല്ല അത് നൽകുന്നത്. അവിടന്നരുളി: "ഇല്ല, ഞാൻ അല്ലാഹുവിനോട് മാപ്പിരക്കുന്നു. ഇല്ല, ഞാൻ അല്ലാഹുവിനോട് മാപ്പിരക്കുന്നു. ഇല്ല, ഞാൻ അല്ലാഹുവിനോട് മാപ്പിരക്കുന്നു. നീ എന്നെ വലിച്ച ഈ വലി വിടുംവരെ ഞാനൊന്നും നിനക്ക് (ആ ഒട്ടകങ്ങൾക്ക് വഹിക്കാൻ) തരികയില്ല." അങ്ങിനെയൊക്കെ നടന്നിട്ടും ആ അഅ്റാബി പറഞ്ഞു: അല്ലാഹുവാണ, ഞാനിതഴിക്കുകയില്ല. എന്നിട്ടദ്ദേഹം ആ ഹദീസ് പറഞ്ഞു. നിവേദകൻ പറഞ്ഞു: പിന്നീട് അവിടന്ന് ഒരാളെ വിളിച്ച് അയാളോട് പറഞ്ഞു: "അയാൾക്ക് അയാളുടെ രണ്ട് ഒട്ടകങ്ങൾക്ക് മേൽ ഭക്ഷണം വെച്ച് കൊടുക്കൂ. ഒന്നിന്മേൽ ബാർലിയും മറ്റേതിൽ ഈത്തപ്പഴവും." പിന്നീട് അവിടന്ന് ഞങ്ങളിലേക്ക് തിരിഞ്ഞ് പറഞ്ഞു: "അല്ലാഹുവിന്റെ ബർകത്തിന്മേൽ നിങ്ങൾ പിരിഞ്ഞ് പൊയ്ക്കൊള്ളുക." (ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 778, 778, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَدَمْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَشْرَ سِنِينَ، فَمَا قَالَ: لِي أُفٍّ قَطُّ، وَمَا قَالَ: لِشَيْءٍ صَنَعْتُهُ لِمَ صَنَعْتَهُ، وَلَا لِشَيْءٍ تَرَكْتُهُ لِمَ تَرَكْتَهُ، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ أَحْسَنِ النَّاسِ خُلُقًا. وَلَا مَسَسْتُ خَزًّا قَطُّ، وَلَا حَرِيرًا وَلَا شَيْئًا، كَانَ أَلْيَنَ مِنْ كَفِّ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. وَلَا شَمَمْتُ مِسْكًا قَطُّ وَلَا عِطْرًا كَانَ أَطْيَبَ مِنْ عَرَقِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. حَسَنٌ صَحِيحٌ (ق,د,ن,جه)', 'അനസ്(റ): ഞാൻ നബി(സ)ക്ക് പത്ത് വർഷം സേവനമനുഷ്ഠിച്ചു. അവിടന്നെന്നോടൊരിക്കലും ''ഛെ'' എന്ന് പറഞ്ഞിട്ടില്ല. ഞാൻ ചെയ്ത ഒന്നിനെയും ''നീ എന്തിന് ചെയ്തു'' എന്നോ ഒഴിവാക്കിയ ഒന്നിനെക്കുറിച്ചും ''നീ എന്തിന് ഒഴിവാക്കി'' എന്നോ പറഞ്ഞിട്ടില്ല. ജനങ്ങളിൽ ഏറ്റവും നല്ല സ്വഭാവക്കാരനായിരുന്നു റസൂൽ(സ). റസൂൽ(സ)യുടെ മുൻകയ്യിനോക്കാൾ നേർത്ത പട്ട് വസ്ത്രമോ, പട്ടും രോമവും ചേർത്ത് നെയത വസ്ത്രമോ, മറ്റു വസ്ത്രങ്ങളോ ഞാൻ സ്പർശിച്ചിട്ടില്ല. ഞാൻ റസൂൽ(സ)യുടെ വിയർപ്പിനെക്കാൾ സുഗന്ധമുള്ള ഒരു അത്തറും ഒരു മിസ്കും വാസനിച്ചിട്ടില്ല. (ബു,മു,ദ,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 778, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، وَقَدْ سُئِلَتْ عَنْ خُلُقِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: لَمْ يَكُنْ فَاحِشًا وَلَا مُتَفَحِّشًا وَلَا صَخَّابًا فِي الْأَسْوَاقِ، وَلَا يَجْزِي بِالسَّيِّئَةِ السَّيِّئَةَ، وَلَكِنْ يَعْفُو وَيَصْفَحُ. حَسَنٌ صَحِيحٌ. (ت)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ സ്വഭാവത്തെക്കുറിച്ച് മഹതിയോട് ചോദിക്കപ്പെട്ടു. അവർ പറഞ്ഞു: അവിടന്ന് മോശക്കാരനോ തെമ്മാടിയോ അങ്ങാടിയിൽ ബഹളം വെക്കുന്നവനോ ആയിരുന്നില്ല. ചീത്തയെ ചീത്തകൊണ്ട് നേരിടുന്നവരുമായിരുന്നില്ല. അവിടന്ന് പൊറുക്കുകയും മാപ്പ് കൊടുക്കുകയും ചെയ്യുമായിരുന്നു. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 779, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَا سُئِلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ شَيْءٍ قَطُّ فَقَالَ: "لَا".. (خ)', 'ജാബിർ(റ): നബി(സ)യോട് വല്ലതും ചോദിക്കപ്പെട്ടിട്ട് അവിടന്ന് ''ഇല്ല'' എന്ന് പറയുന്ന അവസ്ഥ ഒരിക്കലും ഉണ്ടായിട്ടില്ല. (ബു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 779, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمْ يَكُنِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَبَّابًا، وَلَا فَحَّاشًا، وَلَا لَعَّانًا، كَانَ يَقُولُ لِأَحَدِنَا عِنْدَ الْمَعْتِبَةِ: "مَا لَهُ تَرِبَ جَبِينُهُ؟". (خ)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) കൂടുതൽ ശകാരിക്കുന്നവരോ കുറെ മോശത്തരങ്ങൾ പറയുന്നവരോ കൂടുതലായി ശപിക്കുന്നവരോ ആയിരുന്നില്ല. അവിടത്തേക്ക് അനിഷ്ടം വരുമ്പോൾ ഞങ്ങളിലൊരാളോട് പറയുമായിരുന്നു: "എന്താണവന്റെ കാര്യം, അവന്റെ നെറ്റി മണ്ണിൽ വീഴട്ടെ!" (ഈ വാക്യം അറബികളുടെ സംസാരങ്ങളിൽ വരാറുള്ളതാണെങ്കിലും ഇതിന്റെ വാക്കർത്ഥം ഉദ്ദേശിക്കപ്പെടാറില്ല) (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 779, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خِيَارُكُمْ أَحَاسِنُكُمْ أَخْلَاقًا". وَلَمْ يَكُنِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاحِشًا وَلَا مُتَفَحِّشًا. حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലെ സൽസ്വഭാവികളാണ് നിങ്ങളിലെ ഏറ്റവും ഉത്തമർ." നബി(സ) മോശക്കാരനോ തെമ്മാടിയോ ആയിരുന്നില്ല. (ബു,മു,തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 779, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِيَّاكُمْ وَالظَّنَّ، فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ، وَلَا تَحَسَّسُوا وَلَا تَجَسَّسُوا، وَلَا تَنَافَسُوا، وَلَا تَحَاسَدُوا، وَلَا تَبَاغَضُوا، وَلَا تَدَابَرُوا، وَكُونُوا عِبَادَ اللهِ إِخْوَانًا". (ق,د,ت)', 'അബൂഹുറൈറ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളെയും ഊഹത്തെയും സൂക്ഷിക്കണം. കാരണം ഊഹമാണ് സംസാരങ്ങളിൽ ഏറ്റവും വലിയ കള്ളം. നിങ്ങൾ ചികഞ്ഞന്വേഷിക്കുകയോ ചാരപ്പണി നടത്തുകയോ അരുത്. നിങ്ങൾ പരസ്പരം ശണ്ഠ കൂടരുത്. നിങ്ങൾ പരസ്പരം അസൂയ വെക്കരുത്. നിങ്ങൾ പരസ്പരം ദേഷ്യം വെക്കരുത്. നിങ്ങൾ പരസ്പരം ശത്രുത വെക്കരുത്. അല്ലാഹുവിന്റെ അടിമകളേ, നിങ്ങൾ സഹോദരൻമാരാവുക." (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 779, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "حُسْنُ الظَّنِّ مِنْ حُسْنِ الْعِبَادَةِ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നല്ലത് വിചാരിക്കൽ നല്ല ഇബാദത്തിൽ പെട്ടതാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 780, 780, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ صَفِيَّةَ بِنْتِ حُيَيٍّ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُعْتَكِفًا، فَأَتَيْتُهُ أَزُورُهُ لَيْلًا، فَحَدَّثْتُهُ وَقُمْتُ، فَانْقَلَبْتُ، فَقَامَ مَعِي لِيَقْلِبَنِي، وَكَانَ مَسْكَنُهَا فِي دَارِ أُسَامَةَ بْنِ زَيْدٍ فَمَرَّ رَجُلَانِ مِنَ الْأَنْصَارِ، فَلَمَّا رَأَيَا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَسْرَعَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَى رِسْلِكُمَا، إِنَّهَا صَفِيَّةُ بِنْتُ حُيَيٍّ". قَالَا: سُبْحَانَ اللهِ، يَا رَسُولَ اللهِ! قَالَ: "إِنَّ الشَّيْطَانَ يَجْرِي مِنَ الْإِنْسَانِ مَجْرَى الدَّمِ، فَخَشِيتُ أَنْ يَقْذِفَ فِي قُلُوبِكُمَا شَيْئًا". أَوْ قَالَ: "شَرًّا". (ق,د,جه)', 'സ്വഫിയ്യ ബിൻതു ഹുയിയ്യ്(റ): റസൂൽ(സ) ഇഅ്തികാഫിരിക്കുകയായിരുന്നു. അപ്പോൾ രാത്രി ഞാനവിടത്തെ സന്ദർശിക്കാൻ ചെന്നു. ഞാൻ അവിടത്തോട് സംസാരിച്ചു. ശേഷം എഴുന്നേറ്റു. അപ്പോൾ ഞാൻ മറിഞ്ഞു. ഉടൻ അവിടന്ന് എന്നെ മാറ്റാനായി എന്റെ കൂടെ എഴുന്നേറ്റു. മഹതിയുടെ വാസസ്ഥലം ഉസാമതുബ്നു സൈദ്(റ)വിന്റെ വീട്ടിലായിരുന്നു. അപ്പോൾ അൻസാരികളിലെ രണ്ടാളുകൾ നടന്നു പോയി. നബി(സ)യെ കണ്ടപ്പോൾ ഇരുവരും വേഗത്തിൽ പോയി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ധൃതി കൂട്ടാതെ! നിശ്ചയം ഇത് ഹുയിയ്യിന്റെ മകൾ സ്വഫിയ്യയാണ്." ഇരുവരും പറഞ്ഞു: ഞങ്ങൾ അല്ലാഹുവിനെ വാഴ്ത്തുന്നു, (അത്ഭുതം കുറിക്കുന്ന വചനം) അല്ലാഹുവിന്റെ ദൂതരേ, അവിടന്ന് പറഞ്ഞു: "നിശ്ചയം പിശാച് മനുഷ്യനിൽ രക്തം സഞ്ചരിക്കുന്നിടത്തെല്ലാം സഞ്ചരിക്കും. അതിനാൽ നിങ്ങളുടെ ഹൃദയങ്ങളിൽ വല്ലതും വന്നുചേരുമോ എന്ന് ഞാൻ ഭയന്നു." ''വല്ലതും'' എന്നോ ''വല്ല ദുഷ്ടതയും'' എന്നോ എന്ന് റാവി സംശയിക്കുന്നു. (ബു,മു,ദ,ജ)', 'صَفِيَّةَ بِنْتِ حُيَيٍّ', 'സ്വഫിയ്യ ബിൻതു ഹുയിയ്യ്(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 780, 780, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا أَظُنُّ فُلَانًا وَفُلَانًا يَعْرِفَانِ مِنْ دِينِنَا شَيْئًا، وفي رواية: وَفُلَانًا يَعْرِفَانِ دِينَنَا الَّذِي نَحْنُ عَلَيْهِ". (خ)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ഇന്നവനെക്കുറിച്ചും ഇന്നവനെക്കുറിച്ചും, അവരിരുവർക്കും നമ്മുടെ ദീനിൽ നിന്ന് വല്ലതും അറിയുമെന്ന് ഞാൻ വിചാരിക്കുന്നില്ല." മറ്റൊരു റിപ്പോർട്ടിൽ: "നാം നിലനിൽക്കുന്ന നമ്മുടെ ദീനിനെ അവരിരുവരുമറിയുമെന്ന് ഞാൻ വിചാരിക്കുന്നില്ല." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 780, 780, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=141), 1, 'وَفِي رِوَايَةٍ: وَفُلَانًا يَعْرِفَانِ دِينَنَا الَّذِي نَحْنُ عَلَيْهِ". (خ)', 'മറ്റൊരു നിവേദനിൽ: "നാം നിലനിൽക്കുന്ന നമ്മുടെ ദീനിനെ അവരിരുവരുമറിയുമെന്ന് ഞാൻ വിചാരിക്കുന്നില്ല." (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كُنْتُمْ ثَلَاثَةً، فَلَا يَتَنَاجَى رَجُلَانِ دُونَ الْآخَرِ حَتَّى تَخْتَلِطُوا بِالنَّاسِ أَجْلَ أَنْ يُحْزِنَهُ". (ق,د,ت,ج)', 'അബ്ദുല്ലാഹ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ മൂന്നാളുകൾ ഉണ്ടെങ്കിൽ ജനങ്ങളിൽ ഇടകലരുന്നത് വരെ ഒരാളെക്കൂട്ടാതെ മറ്റു രണ്ടുപേർ മാറി നിൽക്കരുത്. കാരണം അത് അവനെ ദു:ഖിപ്പിക്കും." (ബു,മു,ദ,തു,ജ)', 'عَبْدِاللهِ', 'അബ്ദുല്ലാഹ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 780, 780, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَتَنَاجَى اثْنَانِ دُونَ الثَّالِثِ. (جه)', 'ഇബ്നൂഉമർ(റ): മൂന്നാളുകളിൽ നിന്ന് രണ്ടാളുകൾ വേറിട്ട് നിൽക്കൽ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നൂഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 780, 781, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُما قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِثْلَهُ... قِيلَ لِابْنِ عُمَرَ: فَأَرْبَعَةً؟ قَالَ: لَا يَضُرُّكَ. (خ,د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു (മുമ്പത്തെ പോലെ): ഇബ്നുഉമർ(റ)വിനോട് ചോദിക്കപ്പെട്ടു: അപ്പോൾ നാലാളുകൾ? അദ്ദേഹം പറഞ്ഞു: അത് പ്രശ്നമില്ല. (ബു,ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 781, 781, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَا يَرْحَمِ النَّاسَ لَا يَرْحَمُهُ اللهُ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'ജരീറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളോട് കരുണ കാണിക്കാത്തവനോട് അല്ലാഹു കരുണ ചെയ്യുകയില്ല." (ബു,മു,തു)', 'جَرِيرِ بْنِ عَبْدِ اللهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 781, 781, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ أَبَا الْقَاسِمِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تُنْزَعُ الرَّحْمَةُ إِلَّا مِنْ شَقِيٍّ". حَسَنٌ. (د,ت)', 'അബൂഹുറൈറ(റ): ഞാൻ അബുൽഖാസിം(സ) പറയുന്നത് കേട്ടു: "ഒരു പരാജിതനിൽ നിന്നല്ലാതെ കാരുണ്യം ഊരപ്പെടുകയില്ല." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 781, 781, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمَنُ، ارْحَمُوا مَنْ فِي الْأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ. الرَّحِمُ شُجْنَةٌ مِنَ الرَّحْمَنِ، فَمَنْ وَصَلَهَا وَصَلَهُ اللهُ، وَمَنْ قَطَعَهَا قَطَعَهُ اللهُ". حَسَنٌ صَحِيحٌ. (د,ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "കരുണ ചെയ്യുന്നവരോട് റഹ്മാൻ (മഹാ കാരുണ്യവാൻ) കരുണ ചെയ്യും. നിങ്ങൾ ഭൂനിവാസികളോട് കരുണ ചെയ്യുക. എന്നാൽ ആകാശ നിവാസികൾ നിങ്ങൾക്ക് കരുണ ചെയ്യും. കുടുംബബന്ധം റഹ്മാനിൽ നിന്നുള്ള (തിങ്ങി നിറഞ്ഞ) ശാഖകളാണ്. ആരെങ്കിലുമത് ചേർത്താൽ അവനെ അല്ലാഹു ചേർക്കും. ആരെങ്കിലുമത് മുറിച്ചാൽ അല്ലാഹു അവനെയും (അവനുമായുള്ള ബന്ധം) മുറിക്കും." (ദ,തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 781, 781, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "جَعَلَ اللهُ الرَّحْمَةَ مِائَةَ جُزْءٍ فَأَمْسَكَ عِنْدَهُ تِسْعَةً وَتِسْعِينَ جُزْءًا، وَأَنْزَلَ فِي الْأَرْضِ جُزْءًا وَاحِدًا، فَمِنْ ذَلِكَ الْجُزْءِ يَتَرَاحَمُ الْخَلْقُ حَتَّى تَرْفَعَ الْفَرَسُ حَافِرَهَا عَنْ وَلَدِهَا خَشْيَةَ أَنْ تُصِيبَهُ". (خ)', 'അബൂഹുറൈറ(റ): ഞാൻ റസൂൽ(സ) പറയുന്നത് കേട്ടു: "അല്ലാഹു കാരുണ്യത്തെ നൂറ് ഭാഗങ്ങളാക്കി. (അവയിൽ) തൊണ്ണൂറ്റി ഒമ്പത് ഭാഗവും അവൻ പിടിച്ച് വെച്ചു. ഭൂമിയിൽ അവൻ ഒരു ഭാഗം ഇറക്കി. ആ ഭാഗത്തിൽ സൃഷ്ടികൾ പരസ്പരം കാരുണ്യം ചെയ്യുന്നു. എത്രത്തോളമെന്നാൽ കുതിര തന്റെ കുളമ്പടി കുട്ടിയുടെ മേൽ തട്ടുമോ എന്ന് പേടിച്ച് കുട്ടിയിൽ നിന്നുയർത്തി വെക്കുന്നു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 781, 781, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ لَمْ يَرْحَمْ صَغِيرَنَا وَيَعْرِفْ حَقَّ كَبِيرِنَا فَلَيْسَ مِنَّا". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "നമ്മിലെ ചെറിയവരോട് കരുണ കാണിക്കാത്തവനും വലിയവരുടെ അവകാശം തിരിച്ചറിയാത്തവനും നമ്മിൽ പെട്ടവനല്ല." (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 781, 782, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ جَرِيرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ لَا يَرْحَمْ لَا يُرْحَمْ". (خ)', 'ജരീറുബ്നു അബ്ദില്ലാഹി(റ): നബി(സ)പറഞ്ഞു: "കരുണ ചെയ്യാത്തവനോട് കരുണ ചെയ്യപ്പെടുകയില്ല." (ബു)', 'جَرِيرِ بْنِ عَبْدِاللهِ', 'ജരീറുബ്നു അബ്ദില്ലാഹി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 782, 782, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةٍ وَقُمْنَا مَعَهُ، فَقَالَ أَعْرَابِيٌّ وَهُوَ فِي الصَّلَاةِ: اللَّهُمَّ ارْحَمْنِي وَمُحَمَّدًا، وَلَا تَرْحَمْ مَعَنَا أَحَدًا فَلَمَّا سَلَّمَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِلْأَعْرَابِيِّ: "لَقَدْ حَجَّرْتَ وَاسِعًا". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) നിസ്കാരത്തിനായി നിന്നു. ഞങ്ങളും കൂടെ നിന്നു. നിസ്കാരത്തിലായിരിക്കെ ഒരു അഅ്റാബി പറഞ്ഞു: അല്ലാഹുവേ, നീ എനിക്കും മുഹമ്മദ്(സ)ക്കും കരുണ നൽകണേ. ഞങ്ങളോട് കൂടെ മറ്റാർക്കും നീ കരുണ ചെയ്യരുതേ. നബി(സ) സലാം വീട്ടിയപ്പോൾ അഅ്റാബിയോട് പറഞ്ഞു: "വിശാലമായതിനെ താങ്കൾ ഇടുങ്ങിയതാക്കി." (അല്ലാഹുവിന്റെ കാരുണ്യം ലോകമാകെ വിശാലമായതാണ്. അതിനെ രണ്ടാളുകൾക്കായി ചുരുക്കി.) (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 782, 782, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ جَرِيرٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ يُحْرَمِ الرِّفْقَ يُحْرَمِ الْخَيْرَ". (م,د,جه)', 'ജരീർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു. "അനുകമ്പ ആർക്കെങ്കിലും തടഞ്ഞ് വെക്കപ്പെട്ടാൽ അവന് .നന്മ തടയപ്പെടും." (മു,ദ,ജ)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 782, 782, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أُعْطِيَ حَظَّهُ مِنَ الرِّفْقِ فَقَدْ أُعْطِيَ حَظَّهُ مِنَ الْخَيْرِ، وَمَنْ حُرِمَ حَظَّهُ مِنَ الرِّفْقِ فَقَدْ حُرِمَ حَظَّهُ مِنَ الْخَيْرِ". حَسَنٌ صَحِيحٌ. (ت)', 'അബുദ്ദർദാഅ്(റ): നബി(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും അനുകമ്പയിൽ നിന്നുള്ള തന്റെ ഓഹരി നൽകപ്പെട്ടാൽ നന്മയിൽ നിന്നുള്ള തന്റെ ഓഹരി നൽകപ്പെട്ടു. ആർക്കെങ്കിലും അനുകമ്പയിൽ നിന്ന് തന്റെ ഓഹരി തടയപ്പെട്ടാൽ നന്മയിൽ നിന്ന് തന്റെ ഓഹരി തടയപ്പെട്ടു." (തു)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 782, 782, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ شُرَيْحٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ عَائِشَةَ عَنِ الْبَدَاوَةِ فَقَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَبْدُو إِلَى هَذِهِ التِّلَاعِ، وَإِنَّهُ أَرَادَ الْبَدَاوَةَ مَرَّةً فَأَرْسَلَ إِلَيَّ نَاقَةً مُحَرَّمَةً مِنْ إِبِلِ الصَّدَقَةِ، فَقَالَ لِي: "يَا عَائِشَةُ، ارْفُقِي، فَإِنَّ الرِّفْقَ لَمْ يَكُنْ فِي شَيْءٍ قَطُّ إِلَّا زَانَهُ، وَلَا نُزِعَ مِنْ شَيْءٍ قَطُّ إِلَّا شَانَهُ". (م,د)', 'ശുറൈഹ്(റ): ആഇശ(റ)യോട് ഉൾപ്രദേശത്ത് താമസിക്കുന്നതിനെക്കുറിച്ച് ഞാൻ ചോദിച്ചപ്പോൾ മഹതി പറഞ്ഞു: "നബി(സ) ഈ ഉയർന്ന സ്ഥലത്തേക്ക് പോകുമായിരുന്നു. ഒരിക്കൽ അവിടന്ന് ഉൾപ്രദേശത്ത് താമസിക്കാൻ ആഗ്രഹിച്ചു. അപ്പോൾ എന്റെ അടുക്കലേക്ക് സ്വദഖയുടെ ഒട്ടകങ്ങളിൽ പെട്ട, ഉപയോഗിച്ച് തഴക്കം വരാത്ത ഒരൊട്ടകത്തെ അയച്ചു. എന്നിട്ടെന്നോട് പറഞ്ഞു: "ആഇശ, സൗമ്യമായി പെരുമാറുക, കാരണം സൗമ്യത ഏതെങ്കിലും വസ്തുവിൽ ഉണ്ടെങ്കിൽ അതിനെ ഭംഗിയാക്കും. സൗമ്യത ഏതെങ്കിലും വസ്തുവിൽ നിന്ന് നീക്കപ്പെട്ടാൽ അതിനെ വിരൂപമാക്കുകയും ചെയ്യും." (മു,ദ)', 'شُرَيْحٍ', 'ശുറൈഹ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 782, 782, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ سَعْدٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "التُّؤَدَةُ فِي كُلِّ شَيْءٍ، إِلَّا فِي عَمَلِ الْآخِرَةِ". (د)', 'സഅ്ദ്(റ): നബി(സ) പറഞ്ഞു: "ആഖിറത്തിന്റെ കർമ്മമല്ലാത്ത എല്ലാത്തിലും അവധാനത വേണം." (ദ)', 'سَعْدٍ', 'സഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 783, 783, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا عَائِشَةُ، إِنَّ اللهَ رَفِيقٌ يُحِبُّ الرِّفْقَ، وَيُعْطِي عَلَى الرِّفْقِ مَا لَا يُعْطِي عَلَى الْعُنْفِ، وَمَا لَا يُعْطِي عَلَى مَا سِوَاهُ". (م,د,جه)', 'പ്രവാചക പത്നി ആഇശ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഓ ആഇശ! നിശ്ചയം അല്ലാഹു അനുകമ്പയുള്ളവനാണ്. അവൻ അനുകമ്പ ഇഷ്ടപ്പെടുന്നു. പരുഷതക്ക് നൽകാത്തതും മറ്റൊന്നിനും നൽകാത്തതും സൗമ്യതക്ക് അവൻ നൽകും." (മു,ദ,ജ)', 'عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 'പ്രവാചക പത്നി ആഇശ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 783, 783, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللهَ رَفِيقٌ يُحِبُّ الرِّفْقَ فِي الْأَمْرِ كُلِّهِ". (خ,جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം, അല്ലാഹു സൗമ്യനാണ്. സർവ്വ കാര്യങ്ങളിലും സൗമ്യത ഇഷ്ടപ്പെടുന്നവനുമാണ്." (ബു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 783, 783, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ مَالِكِ بْنِ نَضْلَةَ الْجُشَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، الرَّجُلُ أَمُرُّ بِهِ فَلَا يَقْرِينِي وَلَا يُضَيِّفُنِي، فَيَمُرُّ بِي، أَفَأُقْرِيهِ؟ قَالَ: "لَا أَقْرِهِ". قَالَ: وَرَآنِي رَثَّ الثِّيَابِ، فَقَالَ: "هَلْ لَكَ مِنْ مَالٍ". قُلْتُ: مِنْ كُلِّ الْمَالِ، قَدْ أَعْطَانِيَ اللهُ مِنَ الْإِبِلِ وَالْغَنَمِ. قَالَ: "فَلْيُرَ عَلَيْكَ". حَسَنٌ صَحِيحٌ. (ت)', 'മാലികുബ്നു നള്ലത്തിൽ ജുശമി(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഒരു മനുഷ്യൻ, ഞാനയാളുടെ അടുക്കലൂടെ നടന്ന് പോകുന്നു. അയാൾ എനിക്ക് ആതിഥ്യമരുളുകയോ എന്നെ സ്വീകരിച്ചിരുത്തുകയോ ചെയ്യുന്നില്ല. ഇനി അയാൾ എന്റെയടുക്കലൂടെ നടന്ന് പോകുമ്പോൾ ഞാനയാൾക്ക് ആതിഥ്യം നൽകണോ? അവിടന്നരുളി: "അങ്ങിനെയല്ല, നീ അയാൾക്ക് ആതിഥ്യമരുളുക." നിവേദകൻ പറയുന്നു: അവിടന്നെന്നെ പഴകി ദ്രവിച്ച വസ്ത്രം ധരിച്ചവനായിക്കണ്ടു. അപ്പോൾ അവിടന്ന് ചോദിച്ചു: "നിനക്ക് വല്ല സമ്പത്തുമുണ്ടോ?" ഞാൻ പറഞ്ഞു: എല്ലാതരം സമ്പത്തുമുണ്ട്. നിശ്ചയമായും എനിക്കല്ലോഹു ഒട്ടകങ്ങളും ആടുകളും തന്നിട്ടുണ്ട്. അവിടന്നരുളി: "എന്നാലത് നിന്റെ മേൽ കാണട്ടെ." (തു)', 'مَالِكِ بْنِ نَضْلَةَ الْجُشَمِيِّ', 'മാലികുബ്നു നള്ലത്തിൽ ജുശമി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 783, 783, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ أَبِي الطُّفَيْلِ عَنْ حُذَيْفَةَ – رَضِيَ اللهُ عَنْهُمَا – قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَكُونُوا إِمَّعَةً، تَقُولُونَ: إِنْ أَحْسَنَ النَّاسُ أَحْسَنَّا، وَإِنْ ظَلَمُوا ظَلَمْنَا. وَلَكِنْ وَطِّنُوا أَنْفُسَكُمْ: إِنْ أَحْسَنَ النَّاسُ أَنْ تُحْسِنُوا، وَإِنْ أَسَاءُوا فَلَا تَظْلِمُوا". حَسَنٌ. (ت)', 'ഹുദൈഫയിൽ നിന്ന് അബുത്തുഫൈൽ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അവസര സേവകരാകരുത്. അങ്ങനെ ''ജനങ്ങൾ നന്മ ചെയ്താൽ ഞങ്ങളും നന്മ ചെയ്യും, അവർ അക്രമിക്കുകയാണെങ്കിൽ ഞങ്ങളും അക്രമിക്കും'' എന്ന് നിങ്ങൾ പറയും. മറിച്ച് നിങ്ങൾ നിങ്ങളുടെ ശരീരത്തെ, ജനങ്ങൾ നന്മ ചെയ്താൽ നന്മ ചെയ്യാനും അവർ ചീത്തയായി പെരുമാറിയാൽ നിങ്ങൾ അക്രമിക്കാതിരിക്കാനും പരിശീലിപ്പിക്കുക." (തു)', 'أَبِي الطُّفَيْلِ عَنْ حُذَيْفَةَ –', 'ഹുദൈഫയിൽ നിന്ന് അബുത്തുഫൈൽ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 783, 784, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ، وَمَا زَادَ اللهُ عَبْدًا بِعَفْوٍ إِلَّا عِزًّا، وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلَّا رَفَعَهُ اللهُ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു ദാനവും സമ്പത്തിനെ കുറച്ചിട്ടില്ല. വിട്ടുവീഴ്ച ചെയ്തതു കാരണം അടിമക്ക് അല്ലാഹു അഭിമാനം വർധിപ്പിച്ചിട്ടേയുള്ളൂ. അല്ലാഹുവിന് വേണ്ടി താഴ്മ കാണിക്കുന്നവനെ അല്ലാഹു ഉയർത്തുകതന്നെ ചെയ്യും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 784, 784, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ نَوَّاسِ بْنِ سِمْعَانَ رَضِيَ اللهُ عَنْهُ قَالَ: أَقَمْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ سَنَةً، مَا يَمْنَعُنِي مِنَ الْهِجْرَةِ إِلَّا الْمَسْأَلَةُ، كَانَ أَحَدُنَا إِذَا هَاجَرَ لَمْ يَسْأَلْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ شَيْءٍ، قَالَ: فَسَأَلْتُهُ عَنِ الْبِرِّ وَالْإِثْمِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْبِرُّ حُسْنُ الْخُلُقِ، وَالْإِثْمُ: مَا حَاكَ فِي نَفْسِكَ، وَكَرِهْتَ أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ". (م)', 'നവാസുബ്നു സിംആൻ(റ): ഞാൻ റസൂൽ(സ)യുടെ കൂടെ മദീനയിൽ ഒരു വർഷം താമസിച്ചു. ഹിജ്റയിൽ നിന്ന് എന്നെ തടഞ്ഞത് എന്റെ ചോദ്യങ്ങൾ മാത്രമായിരുന്നു. ഞങ്ങളിലാരെങ്കിലും ഹിജ്റ പുറപ്പെട്ടാൽ റസൂൽ(സ)യോട് ഒന്നിനെക്കുറിച്ചും ചോദിക്കാറുണ്ടായിരുന്നില്ല. നിവേദകൻ പറയുന്നു: അപ്പോൾ ഞാൻ അവിടത്തോട് നന്മയെക്കുറിച്ചും തിന്മയെക്കുറിച്ചും ചോദിച്ചു: അപ്പോൾ അവിടന്നരുളി: "സൽസ്വഭാവമാണ് നന്മ. നിന്റെ മനസ്സിൽ ചൊറിച്ചിലുണ്ടാക്കുന്നതും അത് ജനങ്ങളറിയുന്നത് നീ വെറുക്കുന്നതുമായ കാര്യമാണ് തിന്മ." (മു)', 'نَوَّاسِ بْنِ سِمْعَانَ', 'നവാസുബ്നു സിംആൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 784, 784, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ بِالصِّدْقِ، فَإِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ، وَمَا يَزَالُ الرَّجُلُ يَصْدُقُ وَيَتَحَرَّى الصِّدْقَ حَتَّى يُكْتَبَ عِنْدَ اللهِ صِدِّيقًا. وَإِيَّاكُمْ وَالْكَذِبَ، فَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ، وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ، وَمَا يَزَالُ الْعَبْدُ يَكْذِبُ وَيَتَحَرَّى الْكَذِبَ حَتَّى يُكْتَبَ عِنْدَ اللهِ كَذَّابًا". حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "സത്യം പറയൽ നിങ്ങൾക്ക് നിർബന്ധമാണ്. തീർച്ചയായും സത്യം നന്മയിലേക്ക് നയിക്കും. നന്മ സ്വർഗ്ഗത്തിലേക്ക് വഴികാണിക്കും. മനുഷ്യൻ സത്യം പറഞ്ഞും സത്യത്തിൽ പ്രേരണനൽകിയും കൊണ്ടേയിരിക്കും, അല്ലാഹുവിന്റെ പക്കൽ അവൻ സ്വിദ്ദീഖ് (പരിപൂർണ സത്യസന്ധൻ) എന്ന് എഴുതപ്പെടുന്നത് വരെ. നിങ്ങൾ നിങ്ങളെയും കള്ളം പറയലിനെയും സൂക്ഷിക്കണം. കാരണം, തീർച്ചയായും കള്ളം പറയൽ തിന്മയിലേക്ക് നയിക്കും. നിശ്ചയം തിന്മ നരകത്തിലേക്ക് വഴികാണിക്കും. അടിമ കളവ് പറഞ്ഞും അസത്യത്തിന് പ്രേരണ നൽകിയും കൊണ്ടിരിക്കും, അല്ലാഹുവിന്റെ അടുക്കൽ അവൻ കൂടുതലായി കളവ് പറയുന്നവൻ (കദ്ദാബ്) എന്ന് എഴുതപ്പെടുന്നതു വരെ." (ബു,മു,ദ,തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 784, 784, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا كَذَبَ الْعَبْدُ تَبَاعَدَ عَنْهُ الْمَلَكُ مِيلًا، مِنْ نَتْنِ مَا جَاءَ بِهِ". حَسَنٌ. (ت)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം നബി(സ) പറഞ്ഞു: "അടിമ അസത്യം പറഞ്ഞാൽ, അവൻ കൊണ്ട് വന്ന ദുർഗന്ധത്താൽ മലക്ക് അവനിൽ നിന്ന് ഒരു മൈൽ ദൂരത്താകും." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 785, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا كَانَ خُلُقٌ أَبْغَضَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ الْكَذِبِ، وَلَقَدْ كَانَ الرَّجُلُ يُحَدِّثُ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْكِذْبَةِ، فَمَا يَزَالُ فِي نَفْسِهِ حَتَّى يَعْلَمَ أَنَّهُ قَدْ أَحْدَثَ مِنْهَا تَوْبَةً. حَدِيثٌ حَسَنٌ. (ت)', 'ആഇശ(റ): നബി(സ)ക്ക് അസത്യം പറയുന്നതിനേക്കാൾ കഠിന ദേഷ്യമുള്ള മറ്റൊരു സ്വഭാവവുമില്ലായിരുന്നു. ഒരാൾ നബി(സ)യുടെ അടുക്കൽ വന്ന് കളവ് പറഞ്ഞാൽ, അവനിൽ നിന്ന് അതിന്റെ തൗബ ഉണ്ടാകുന്നത് വരെ അത് അവിടത്തെ മനസ്സിൽ (വിഷമമായി) നിലനിൽക്കുമായിരുന്നു. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 785, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ مُعَاوِيَةَ بْنِ جَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "وَيْلٌ لِلَّذِي يُحَدِّثُ فَيَكْذِبُ لِيُضْحِكَ بِهِ الْقَوْمَ، وَيْلٌ لَهُ، وَيْلٌ لَهُ". (د,ت)', 'മുആവിയതുബ്നു ജൈദ(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ആളുകളെ ചിരിപ്പിക്കാനായി കളവ് പറഞ്ഞ് സംസാരിക്കുന്നവനാണ് നാശം. അവന് തന്നെയാണ് നാശം. അവന് തന്നെയാണ് നാശം." (ദ,തു)', 'مُعَاوِيَةَ بْنِ جَيْدَةَ', 'മുആവിയതുബ്നു ജൈദ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 785, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ عَبْدِ اللهِ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: دَعَتْنِي أُمِّي يَوْمًا وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ فِي بَيْتِنَا، فَقَالَتْ: هَا، تَعَالَ أُعْطِيكَ؟ فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَمَا أَرَدْتِ أَنْ تُعْطِيهِ". قَالَتْ: أُعْطِيهِ تَمْرًا، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَا إِنَّكِ لَوْ لَمْ تُعْطِهِ شَيْئًا كُتِبَتْ عَلَيْكِ كِذْبَةٌ". (د)', 'അബ്ദുല്ലാഹിബ്നു ആമിർ(റ): ഒരു ദിവസം അല്ലാഹുവിന്റെ റസൂൽ(സ) ഞങ്ങളുടെ വീട്ടിൽ ഇരിക്കുമ്പോൾ എന്റെ ഉമ്മ എന്നെ വിളിച്ചുകൊണ്ട് പറഞ്ഞു: ഇതാ, നീ ഇവിടെ വാ, ഞാനിത് നിനക്ക് തരാം. അപ്പോൾ മഹതിയോട് അല്ലാഹുവിന്റെ റസൂൽ(സ) ചോദിച്ചു: "അവന് എന്തു കൊടുക്കാനാണ് നീ ഉദ്ദേശിച്ചത്?" മഹതി പറഞ്ഞു: ഞാനവന് കാരക്ക കൊടുക്കും. അപ്പോൾ മഹതിയോട് അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "നീയെങ്ങാനും അവന് ഒന്നും നൽകിയില്ലെങ്കിൽ നിന്റെ മേൽ ഒരു കളവ് എഴുതപ്പെടും." (ദ)', 'عَبْدِ اللهِ بْنِ عَامِرٍ', 'അബ്ദുല്ലാഹിബ്നു ആമിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 785, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كَفَى بِالْمَرْءِ إِثْمًا أَنْ يُحَدِّثَ بِكُلِّ مَا سَمِعَ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: " കേട്ടത് മുഴുവൻ പറയൽ തന്നെ ഒരുത്തൻ കുറ്റക്കാരനാവാൻ മതിയായതാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 785, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ أُمِّ كُلْثُومٍ رَضِيَ اللهُ عَنْهَا بِنْتِ عُقْبَةَ بْنِ أَبِي مُعَيْطٍ – وَكَانَتْ مِنَ الْمُهَاجِرَاتِ الْأُوَلِ اللَّاتِي بَايَعْنَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – أَخْبَرَتْهُ أَنَّهَا سَمِعَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقُولُ: "لَيْسَ الْكَذَّابُ الَّذِي يُصْلِحُ بَيْنَ النَّاسِ وَيَقُولُ خَيْرًا وَيَنْمِي خَيْرًا" قَالَ ابْنُ شِهَابٍ: وَلَمْ أَسْمَعْ يُرَخَّصُ فِي شَيْءٍ مِمَّا يَقُولُ النَّاسُ كَذِبٌ إِلَّا فِي ثَلَاثٍ: الْحَرْبُ، وَالْإِصْلَاحُ بَيْنَ النَّاسِ، وَحَدِيثُ الرَّجُلِ امْرَأَتَهُ وَحَدِيثُ الْمَرْأَةِ زَوْجَهَا. وفي رواية: قَالَتْ: وَلَمْ أَسْمَعْهُ يُرَخِّصُ فِي شَيْءٍ مِمَّا يَقُولُ النَّاسُ إِلَّا فِي ثَلَاثٍ. (م)', 'ഉമ്മുകുൽസും ബിൻതു ഉഖ്ബതുബ്നു മുഐത്(റ) - നബി(സ)യെ ബൈഅത്ത് ചെയ്ത ആദ്യകാല മുഹാജിർ സ്ത്രീകളിൽ പെട്ടവരായിരുന്നു മഹതി. - റസൂൽ(സ) പറയുന്നത് മഹതി കേട്ടു: "ജനങ്ങൾക്കിടയിൽ ഒത്തുതീർപ്പാക്കുകയും (അതിനായി കള്ളം പറയേണ്ടിവന്നാലും) അങ്ങനെ ഏറ്റവും നല്ലത് പറയുകയും വളർത്തുകയും ചെയ്യുന്നവനല്ല അസത്യവാൻ." ഇബ്നു ശിഹാബ്(റ) പറഞ്ഞു: ജനങ്ങൾ കളവാണെന്ന് പറയുന്ന ഒന്നിലും അവിടന്ന് വിട്ടുവീഴ്ച ചെയ്യുന്നതായി ഞാൻ കേട്ടിട്ടില്ല, മൂന്നെണ്ണത്തിലൊഴികെ, യുദ്ധം, ജനങ്ങൾക്കിടയിൽ ഒത്തുതീർപ്പാക്കൽ, ഭാര്യ ഭർത്താവിനോടോ ഭർത്താവ് ഭാര്യയോടോ സംസാരിക്കുന്ന സംസാരം. മറ്റൊരു നിവേദനം: ജനങ്ങൾ പറയുന്നവയിലൊന്നിലും അവിടന്ന് വിട്ടുവീഴ്ച ചെയ്തതായി ഞാൻ കേട്ടിട്ടില്ല, മൂന്നെണ്ണത്തിലൊഴികെ. (മു)', 'أُمِّ كُلْثُومٍ', 'ഉമ്മുകുൽസും ബിൻതു ഉഖ്ബതുബ്നു മുഐത്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 786, 786, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=168), 1, 'وَفِي رِوَايَةٍ: قَالَتْ: وَلَمْ أَسْمَعْهُ يُرَخِّصُ فِي شَيْءٍ مِمَّا يَقُولُ النَّاسُ إِلَّا فِي ثَلَاثٍ. (م)', 'മറ്റൊരു നിവേദനം: ജനങ്ങൾ പറയുന്നവയിലൊന്നിലും അവിടന്ന് വിട്ടുവീഴ്ച ചെയ്തതായി ഞാൻ കേട്ടിട്ടില്ല, മൂന്നെണ്ണത്തിലൊഴികെ. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: بَيْنَمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ وَمَعَهُ أَصْحَابُهُ وَقَعَ رَجُلٌ بِأَبِي بَكْرٍ، فَآذَاهُ، فَصَمَتَ عَنْهُ أَبُو بَكْرٍ، ثُمَّ آذَاهُ الثَّانِيَةَ فَصَمَتَ عَنْهُ أَبُو بَكْرٍ، ثُمَّ آذَاهُ الثَّالِثَةَ فَانْتَصَرَ مِنْهُ أَبُو بَكْرٍ، فَقَامَ رَسُولُ اللهِ حِينَ انْتَصَرَ أَبُو بَكْرٍ، فَقَالَ أَبُو بَكْرٍ: أَوَجَدْتَ عَلَيَّ يَا رَسُولَ اللهِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نَزَلَ مَلَكٌ مِنَ السَّمَاءِ يُكَذِّبُهُ بِمَا قَالَ لَكَ، فَلَمَّا انْتَصَرْتَ وَقَعَ الشَّيْطَانُ، فَلَمْ أَكُنْ لِأَجْلِسَ إِذْ وَقَعَ الشَّيْطَانُ". وَفِي رِوَايَةٍ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا كَانَ يَسُبُّ أَبَا بَكْرٍ....، وَسَاقَ نَحْوَهُ. (د)', 'സഈദുബ്നുൽ മുസയ്യിബ്(റ): തിരുദൂതർ(സ) ഒരിക്കൽ സ്വഹാബാക്കളുടെ കൂടെ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ അബൂബക്കർ(റ)വുമായി ശണ്ഠകൂടി. അങ്ങനെ അയാൾ അബൂബക്കർ(റ)വിനെ ഉപദ്രവിച്ചു. അപ്പോൾ അബൂബക്കർ(റ) മൗനം ദീക്ഷിച്ചു. അയാൾ രണ്ടാമതും ഉപദ്രവിച്ചു. അപ്പോഴും അബൂബക്കർ(റ) മൗനം ദീക്ഷിച്ചു. പിന്നീടയാൾ മൂന്നാമതും ഉപദ്രവിച്ചപ്പോൾ അബൂബക്കർ(റ) പ്രതികരിച്ചു. അബൂബക്കർ(റ) പ്രതികരിച്ചപ്പോൾ റസൂൽ(സ) എഴുന്നേറ്റു. അപ്പോൾ അബൂബക്കർ(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, അവിടത്തേക്ക് എന്നോട് കോപം വന്നോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അയാൾ താങ്കളോട് പറഞ്ഞത് കള്ളമാക്കിക്കൊണ്ട് ആകാശത്ത് നിന്ന് മലക്ക് ഇറങ്ങിവന്നു. താങ്കൾ പ്രതികാരം ചെയ്തപ്പോൾ പിശാച് ഇറങ്ങിവന്നു. പിശാച് ഇറങ്ങി വന്നതിനാൽ എനിക്കിരിക്കാൻ പറ്റാതെ വന്നു."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=169), 1, 'وَفِي رِوَايَةٍ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا كَانَ يَسُبُّ أَبَا بَكْرٍ....، وَسَاقَ نَحْوَهُ. (د)', 'മറ്റൊരു നിവേദനിൽ: അബൂഹുറൈറ(റ): ഒരാൾ അബൂബക്കർ(റ)വിനെ ചീത്ത വിളിക്കുമായിരുന്നു. ശേഷം മേൽ പറഞ്ഞ പോലെ തുടർന്നു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ عَبْدِ اللهِ بْنِ عَوْنٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَسْأَلُ عَنِ الِانْتِصَارِ: {وَلَمَنِ انْتَصَرَ بَعْدَ ظُلْمِهِ فَأُولَئِكَ مَا عَلَيْهِمْ مِنْ سَبِيلٍ} [الشورى: ٤١] فَحَدَّثَنِي عَلِيُّ بْنُ زَيْدِ بْنِ جُدْعَانَ، عَنْ أُمِّ مُحَمَّدٍ امْرَأَةِ أَبِيهِ – قَالَ ابْنُ عَوْنٍ: وَزَعَمُوا أَنَّهَا كَانَتْ تَدْخُلُ عَلَى أُمِّ الْمُؤْمِنِينَ – قَالَتْ: قَالَتْ أُمُّ الْمُؤْمِنِينَ: دَخَلَ عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَنَا زَيْنَبُ بِنْتُ جَحْشٍ، فَجَعَلَ يَصْنَعُ شَيْئًا بِيَدِهِ، فَقُلْتُ بِيَدِهِ حَتَّى فَطَّنْتُهُ لَهَا، فَأَمْسَكَ، وَأَقْبَلَتْ زَيْنَبُ تَقْحَمُ لِعَائِشَةَ رَضِيَ اللهُ عَنْهَا، فَنَهَاهَا، فَأَبَتْ أَنْ تَنْتَهِيَ، فَقَالَ لِعَائِشَةَ: "سُبِّيهَا" فَسَبَبْتُهَا فَغَلَبْتُهَا، فَانْطَلَقَتْ زَيْنَبُ إِلَى عَلِيٍّ رَضِيَ اللهُ عَنْهُ فَقَالَتْ: إِنَّ عَائِشَةَ رَضِيَ اللهُ عَنْهَا وَقَعَتْ بِكُمْ وَفَعَلَتْ، فَجَاءَتْ فَاطِمَةُ، فَقَالَ لَهَا: "إِنَّهَا حِبَّةُ أَبِيكِ وَرَبِّ الْكَعْبَةِ". فَانْصَرَفَتْ، فَقَالَتْ لَهُمْ: أَنِّي قُلْتُ لَهُ كَذَا وَكَذَا، فَقِيلَ لِي كَذَا وَكَذَا قَالَ: وَجَاءَ عَلِيٌّ رَضِيَ اللهُ عَنْهُمْ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَكَلَّمَهُ فِي ذَلِكَ. (د)', 'അബ്ദുല്ലാഹിബ്നു ഔൻ(റ): (താൻ അക്രമിക്കപ്പെട്ട ശേഷം പ്രതികരിച്ചാൽ അവനെതിരെ എന്തെങ്കിലും ചെയ്യാൻ ഒരു മാർഗ്ഗവും ഇല്ല തന്നെ) (ശൂറ: 41) എന്ന ഖുർആൻ സൂക്തത്തിലെ ''പ്രതികാരത്തെ''ക്കുറിച്ച് ഞാൻ ചോദിക്കുമായിരുന്നു. അപ്പോൾ അലിയ്യുബ്നു സൈദിബ്നി ജുദ്ആൻ(റ), തന്റെ പിതാവിന്റെ ഭാര്യയായ ഉമ്മുമുഹമ്മദ്(റ)വിൽ നിന്നുദ്ധരിച്ചുകൊണ്ട് പറഞ്ഞു: - ഇബ്നുഔൻ(റ) പറഞ്ഞു: ഉമ്മുമുഹമ്മദ്(റ) മുഅ്മിനീങ്ങളുടെ മാതാവിന്റെ (അഥവാ, ആഇശ(റ)വിന്റെ) അടുക്കൽ പോകാറുണ്ടായിരുന്നു - ഉമ്മുമുഹമ്മദ്(റ) പറഞ്ഞു: ഉമ്മുൽ മുഅ്മിനീൻ പറഞ്ഞു: ജഹ്ശിന്റെ പുത്രി സൈനബ്(റ) ഞങ്ങളുടെ കൂടെയുണ്ടായിരിക്കെ, റസൂൽ(സ) എന്റെയടുക്കൽ കയറിവന്നു. അവിടന്ന് തന്റെ കരംകൊണ്ട് ചിലത് ചെയ്യാൻ തുടങ്ങി. അവരെക്കുറിച്ച് (സൈനബിനെക്കുറിച്ച് അഥവാ, അവരിവിടെ ഉണ്ടെന്ന്) അവിടത്തെ മനസ്സിലാക്കിക്കൊടുക്കും വരെ ഞാൻ അവിടത്തോട് ആംഗ്യം കാണിച്ചുകൊണ്ടിരുന്നു. അപ്പോൾ തിരുമേനി(സ) അതു നിർത്തിവെച്ചു. സൈനബ്(റ) വന്ന് ആഇശ(റ)യുടെ നേരെ അന്ധമായി ചാടിവീഴാൻ തുടങ്ങി. മഹതി അവരെ തടുത്തു. പക്ഷേ, അവരൊതുങ്ങിയില്ല. അപ്പോൾ അവിടന്ന് ആഇശ(റ)യോട് പറഞ്ഞു: "അവളെ അകറ്റു." അപ്പോൾ മഹതി അവരെ ചീത്തപറയുകയും കീഴ്പ്പെടുത്തുകയും ചെയ്തു. അങ്ങനെ സൈനബ്(റ) അലി(റ)വിന്റെ അടുക്കൽ ചെന്നു പറഞ്ഞു: ആഇശ(റ) നിങ്ങളോട് ശണ്ഠ കൂടിയിട്ടുണ്ട്. (ഇന്നാലിന്നതൊക്കെ) ചെയ്തിട്ടുണ്ട്. അപ്പോൾ ഫാത്വിമ(റ) (നബി(സ)യുടെ അടുത്തേക്ക്) വന്നു. നബി(സ) മഹതിയോട് പറഞ്ഞു: "അവൾ, നിന്റെ പിതാവിന്റെ ഇഷ്ടഭാജനമാണ്, കഅ്ബയുടെ നാഥനാണ് സത്യം". അപ്പോൾ അവരവിടന്ന് മടങ്ങിപ്പോയി. അവിടെയുള്ളവരോട് പറഞ്ഞു: ഞാനവിടത്തോട് ഇന്നതെല്ലാം പറഞ്ഞു: അപ്പോൾ അവിടെന്നോട് ഇന്നതൊക്കെ പറഞ്ഞു. നിവേദകൻ പറയുന്നു: അപ്പോൾ അലി(റ) നബി(സ)യുടെ അടുക്കൽ വന്ന് അതേക്കുറിച്ച് സംസാരിച്ചു. (ദ)', 'عَبْدِ اللهِ بْنِ عَوْنٍ', 'അബ്ദുല്ലാഹിബ്നു ഔൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الشورى: ٤١', null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَاسًا مِنَ الْأَنْصَارِ سَأَلُوا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَعْطَاهُمْ، ثُمَّ سَأَلُوهُ فَأَعْطَاهُمْ، ثُمَّ قَالَ: "مَا يَكُونُ عِنْدِي مِنْ خَيْرٍ فَلَنْ أَدَّخِرَهُ عَنْكُمْ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللهُ، وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللهُ، وَمَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللهُ. وَمَا أُعْطِيَ أَحَدٌ شَيْئًا هُوَ خَيْرٌ وَأَوْسَعُ مِنَ الصَّبْرِ". حَسَنٌ صَحِيحٌ (ق,د,ت,ن)', 'അബുസഈദ്(റ): ഒരു കൂട്ടം അൻസാരികൾ നബി(സ)യോട് എന്തോ ചോദിച്ചു: അപ്പോൾ അവിടന്ന് അവർക്ക് നൽകി. വീണ്ടും അവർ അവിടത്തോട് ചോദിച്ചു. അപ്പോഴും അവിടന്ന് അവർക്ക് നൽകി. പിന്നീട് അവിടന്നരുളി: "എന്റെ പക്കൽ വല്ല നന്മയുമുണ്ടെങ്കിൽ നിങ്ങളെത്തൊട്ട് ഞാനത് സൂക്ഷിച്ച് വെക്കുകയില്ല തന്നെ. ആരെങ്കിൽ ഐശ്വര്യം തേടിയാൽ അവനെ അല്ലാഹു ഐശ്വര്യവാനാക്കും. സച്ചരിതത്വം തേടുന്നുവെങ്കിൽ അല്ലാഹു അവനെ സച്ചരിതനാക്കും. ക്ഷമിക്കാനാഗ്രഹിക്കുന്നുവെങ്കിൽ അല്ലാഹു അവന് ക്ഷമ നൽകും. ക്ഷമയേക്കാൾ ഏറ്റവും വിശാലമായതും ഏറ്റവും നല്ലതുമായ ഒന്നും ആർക്കും നൽകപ്പെട്ടിട്ടില്ല." (ബു,മു,ദ,തു,ന)', 'أَبِي سَعِيدٍ', 'അബുസഈദ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 787, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيْسَ أَحَدٌ، أَوْ لَيْسَ شَيْءٌ، أَصْبَرَ عَلَى أَذًى سَمِعَهُ مِنَ اللهِ إِنَّهُمْ لَيَدْعُونَ لَهُ وَلَدًا وَإِنَّهُ لَيُعَافِيهِمْ وَيَرْزُقُهُمْ". (خ)', 'അബുമൂസ(റ): നബി(സ) പറഞ്ഞു: "ആരോപണങ്ങളിൽ അല്ലാഹുവിനേക്കാൾ ക്ഷമ കൈകൊള്ളുന്ന ഒരാളും, ഒരു വസ്തുവുമില്ല. നിശ്ചയം അവർ അവന് മകനുണ്ടെന്ന് പറയുന്നു. (എന്നിട്ടും) അവൻ അവർക്ക് മാപ്പ് നൽകുകയും ഭക്ഷണം (സകലതും) നൽകുകയും ചെയ്യുന്നു." (ബു)', 'أَبِي مُوسَى', 'അബുമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 788, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ عِيَاضِ بْنِ حِمَارٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ أَوْحَى إِلَيَّ أَنْ تَوَاضَعُوا، حَتَّى لَا يَبْغِيَ أَحَدٌ عَلَى أَحَدٍ، وَلَا يَفْخَرَ أَحَدٌ عَلَى أَحَدٍ". (جه)', 'ഇയാളുബ്നു ഹിമാർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മറ്റൊരാളേക്കാൾ അഹന്ത കാണിക്കാതെയും, മറ്റൊരാളേക്കാൾ (കൂടുതൽ കിട്ടാൻ) കൊതിക്കാതെയും, നിങ്ങൾ താഴ്മ കാണിക്കുക എന്ന് എനിക്ക് അല്ലാഹു ദിവ്യ ബോധനം നൽകി." (ജ)', 'عِيَاضِ بْنِ حِمَارٍ', 'ഇയാളുബ്നു ഹിമാർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 788, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ خَبَّابِ بْنِ الْأَرَتِّ رَضِيَ اللهُ عَنْهُ قَالَ: شَكَوْنَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُتَوَسِّدٌ بُرْدَةً لَهُ فِي ظِلِّ الْكَعْبَةِ، قُلْنَا لَهُ: أَلَا تَسْتَنْصِرُ لَنَا، أَلَا تَدْعُو اللهَ لَنَا، قَالَ كَانَ الرَّجُلُ فِيمَنْ قَبْلَكُمْ يُحْفَرُ لَهُ فِي الْأَرْضِ فَيُجْعَلُ فِيهِ، فَيُجَاءُ بِالْمِنْشَارِ فَيُوضَعُ عَلَى رَأْسِهِ فَيُشَقُّ بِاثْنَتَيْنِ وَمَا يَصُدُّهُ ذَلِكَ عَنْ دِينِهِ، وَيُمْشَطُ بِأَمْشَاطِ الْحَدِيدِ مَا دُونَ لَحْمِهِ مِنْ عَظْمٍ أَوْ عَصَبٍ، وَمَا يَصُدُّهُ ذَلِكَ عَنْ دِينِهِ، وَاللهِ لَيُتِمَّنَّ هَذَا الْأَمْرَ حَتَّى يَسِيرَ الرَّاكِبُ مِنْ صَنْعَاءَ إِلَى حَضْرَمَوْتَ لَا يَخَافُ إِلَّا اللهَ أَوِ الذِّئْبَ عَلَى غَنَمِهِ، وَلَكِنَّكُمْ تَسْتَعْجِلُونَ. (خ)', 'ഖബ്ബാബുബ്നുൽ അരത്ത്(റ): റസൂൽ(സ) തന്റെ ഒരു വിരിപ്പ് തലയണയായി വെച്ച് കഅ്ബയുടെ തണലിൽ കിടക്കുമ്പോൾ ഞങ്ങൾ അവിടത്തോട് പരാതിപ്പെട്ടു. ഞങ്ങൾ ചോദിച്ചു: അങ്ങ് ഞങ്ങൾക്ക് വേണ്ടി സഹായം ചോദിക്കുന്നില്ലേ. അങ്ങ് ഞങ്ങൾക്കുവേണ്ടി അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുന്നില്ലേ? അവിടന്ന് പറഞ്ഞു: "നിങ്ങളുടെ മുൻകഴിഞ്ഞ സമൂഹത്തിൽ ഒരാളെ ഭൂമിയിൽ കുഴികുഴിച്ച് അതിൽ നിർത്തുകയും ശേഷം ഈർച്ചവാൾ കൊണ്ട് വന്ന് തലയിൽ വെച്ച് അവനെ രണ്ട് കഷ്ണമായി മുറിക്കുകയും ചെയ്യുമായിരുന്നു. ഇതൊന്നും തന്റെ മതത്തിൽ നിന്ന് അവനെ പിന്തിരിപ്പിക്കുമായിരുന്നില്ല. അവന്റെ മാംസത്തിനടിയിലുള്ള എല്ലും ഞരമ്പുമെല്ലാം ഇരുമ്പിന്റെ ചീർപ്പ് കൊണ്ട് വലിച്ചെടുക്കപ്പെടുമായിരുന്നു. അതും തന്റെ മതത്തിൽ നിന്ന് അവനെ പിന്തിരിപ്പിക്കുമായിരുന്നില്ല. അല്ലാഹുവിനെയോ തന്റെ ആടുകളെ പിടിക്കാൻ വരുന്ന ചെന്നായകളെയോ മാത്രം പേടിച്ച് കൊണ്ട് സൻആഅ് മുതൽ ഹളർമൗത് വരെ ഒരാൾക്ക് യാത്രചെയ്യാവുന്ന അവസ്ഥ വരും വിധം അല്ലാഹു ഈ ദീനിനെ പൂർത്തീകരിക്കും. പക്ഷെ, നിങ്ങൾ ധൃതിപിടിച്ചുകൊണ്ടിരിക്കുന്നു." (ബു)', 'خَبَّابِ بْنِ الْأَرَتِّ', 'ഖബ്ബാബുബ്നുൽ അരത്ത്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 788, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ، وَمَا زَادَ رَجُلًا بِعَفْوٍ إِلَّا عِزًّا، وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلَّا رَفَعَهُ اللهُ". حَسَنٌ صَحِيحٌ. (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്വദഖ സമ്പത്ത് കുറക്കുകയില്ല. വിട്ടുവീഴ്ച ചെയ്യൽ കൊണ്ട് ഏതൊരാൾക്കും പ്രതാപമേ ഉണ്ടായിട്ടുള്ളൂ. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിനായി ആരും താഴ്മകാട്ടിയിട്ടില്ല, അല്ലാഹു അവനെ ഉയർത്തിയിട്ടല്ലാതെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 788, 789, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ عَلَى رَجُلٍ مِنَ الْأَنْصَارِ وَهُوَ يَعِظُ أَخَاهُ فِي الْحَيَاءِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "دَعْهُ، فَإِنَّ الْحَيَاءَ مِنَ الْإِيمَانِ". (ق,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): അൻസാരികളിൽ പെട്ട ഒരാൾ തന്റെ സഹോദരനെ ലജ്ജയുടെ വിഷയത്തിൽ ഉപദേശിച്ച് കൊണ്ടിരിക്കെ, അയാളുടെ അടുക്കലൂടെ നബി(സ) നടന്നുപോയി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവനെ ഒഴിവാക്കൂ, തീർച്ചയായും ലജ്ജ ഈമാനിൽ പെട്ടതാണ്." (ബു,മു,ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 789, 789, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ عِمْرَانَ بْنِ حُصَيْنٍ وَثَمَّ بُشَيْرُ بْنُ كَعْبٍ، فَحَدَّثَ عِمْرَانُ بْنُ حُصَيْنٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْحَيَاءُ كُلُّهُ خَيْرٌ". فَقَالَ بُشَيْرُ بْنُ كَعْبٍ: إِنَّا نَجِدُ فِي بَعْضِ الْكُتُبِ: أَنَّ مِنْهُ سَكِينَةً وَوَقَارًا، وَمِنْهُ ضَعْفًا. فَأَعَادَ عِمْرَانُ الْحَدِيثَ، وَأَعَادَ بُشَيْرٌ الْكَلَامَ، قَالَ: فَغَضِبَ عِمْرَانُ حَتَّى احْمَرَّتْ عَيْنَاهُ وَقَالَ: أَلَا أَرَانِي أُحَدِّثُكَ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَتُحَدِّثُنِي عَنْ كُتُبِكَ؟ قَالَ: قُلْنَا: يَا أَبَا نُجَيْدٍ، إِيهِ إِيهِ. (م,د)', 'അബൂഖതാദ(റ): ഞങ്ങൾ ഇംറാനുബ്നു ഹുസൈൻ(റ)വിന്റെ കൂടെയായിരുന്നു. അവിടെ ബുശൈറുബ്നു കഅ്ബ്(റ)വും ഉണ്ടായിരുന്നു. അപ്പോൾ ഇംറാനുബ്നു ഹുസൈൻ(റ) പറഞ്ഞു: റസൂൽ പറഞ്ഞു: "ലജ്ജ, അത് മുഴുക്കെയും നന്മ തന്നെ." അപ്പോൾ ബുശൈറുബ്നു കഅ്ബ്(റ) പറഞ്ഞു: നാം ചില കിതാബുകളിൽ കണ്ടിട്ടുണ്ട്: അതിൽ പെട്ടതാണ് ഒതുക്കവും ഗാംഭീര്യവും, അതിൽ പെട്ടതാണ് ബലക്ഷയവും. അപ്പോൾ ഇംറാൻ(റ) ആ ഹദീസ് ആവർത്തിച്ചു. ബുശൈർ(റ) ആ വചനങ്ങളും ആവർത്തിച്ചു. നിവേദകൻ പറഞ്ഞു: തന്റെ രണ്ടു കണ്ണുകൾ ചുവക്കും വിധം ഇംറാൻ(റ)വിന് ദേഷ്യം പിടിച്ചു. അദ്ദേഹം പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യുടെ ഹദീസ് പറയുന്നത് നീ കാണുന്നില്ലേ, (അപ്പോൾ) നീ നിന്റെ കിതാബുകളിൽ നിന്ന് സംസാരിക്കുകയോ? നിവേദകൻ പറഞ്ഞു: ഞങ്ങൾ പറഞ്ഞു: അബു നുജൈദേ, അതെ! അതെ! (മു,ദ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 789, 789, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى: إِذَا لَمْ تَسْتَحْيِ فَافْعَلْ مَا شِئْتَ". (خ,د,جه)', 'അബുമസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "പ്രവാചകവചനങ്ങളിൽ നിന്ന് ജനങ്ങൾക്ക് ആദ്യമായി എത്തിയതിൽ പെട്ടതാണ്: നിനക്ക് ലജ്ജയില്ലെങ്കിൽ നീ ഉദ്ദേശിച്ചത് ചെയ്തുകൊള്ളുക." (ബു,ദ,ജ)', 'أَبِي مَسْعُودٍ', 'അബുമസ്ഊദ്(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 789, 789, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْحَيَاءُ مِنَ الْإِيمَانِ، وَالْإِيمَانُ فِي الْجَنَّةِ، وَالْبَذَاءُ مِنَ الْجَفَاءِ، وَالْجَفَاءُ فِي النَّارِ". حَسَنٌ صَحِيحٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: " ലജ്ജ ഈമാനിൽ പെട്ടതാണ്. ഈമാൻ സ്വർഗ്ഗത്തിലുമാണ്. അസഭ്യം പറയൽ ക്രൂരപെരുമാറ്റത്തിൽ പെട്ടതാണ്. ക്രൂരമായി പെരുമാറൽ നരകത്തിലുമാണ്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 789, 789, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْحَيَاءُ لَا يَأْتِي إِلَّا بِخَيْرٍ". (خ)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): നബി(സ) പറഞ്ഞു: "ലജ്ജ നന്മയെയല്ലാതെ കൊണ്ടുവരികയില്ല." (ബു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 790, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَمَّا صَوَّرَ اللهُ آدَمَ فِي الْجَنَّةِ تَرَكَهُ مَا شَاءَ اللهُ أَنْ يَتْرُكَهُ، فَجَعَلَ إِبْلِيسُ يُطِيفُ بِهِ، يَنْظُرُ مَا هُوَ، فَلَمَّا رَآهُ أَجْوَفَ عَرَفَ أَنَّهُ خُلِقَ خَلْقًا لَا يَتَمَالَكُ". (م)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ആദം(അ)ന്റെ രൂപം സ്വർഗ്ഗത്തിൽ സൃഷ്ടിച്ചപ്പോൾ അല്ലാഹു ഉദ്ദേശിച്ചത്ര (കാലം) അതുപോലെ ഉപേക്ഷിച്ചിട്ടു. അപ്പോൾ ഇബ്ലീസ് എന്താണതെന്ന് നോക്കിക്കൊണ്ട് അതിനെ വലയംചെയ്തു. അത് ഉള്ളിലൊന്നുമില്ലാത്തതാണെന്ന് കണ്ടപ്പോൾ അവന് മനസ്സിലായി; സ്വന്തത്തിൽ ഒരധികാരവും ഇല്ലാത്ത നിലയിലാണ് ആദം സൃഷ്ടിക്കപ്പെട്ടത്." (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 790, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ عَادَ مَرِيضًا أَوْ زَارَ أَخًا لَهُ فِي اللهِ، نَادَاهُ مُنَادٍ: أَنْ طِبْتَ وَطَابَ مَمْشَاكَ، وَتَبَوَّأْتَ مِنَ الْجَنَّةِ مَنْزِلًا". حَسَنٌ. (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും രോഗിയെ സന്ദർശിച്ചാൽ, അല്ലെങ്കിൽ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള തന്റെ സഹോദരനെ സന്ദർശിച്ചാൽ അവനോട് ഒരു വിളംബരക്കാരൻ വിളിച്ച് പറയും: നീ നല്ലവനായി, നിന്റെ സഞ്ചാരമാർഗ്ഗവും നല്ലതായി. നീ സ്വർഗ്ഗത്തിലൊരു വീട് തയ്യാറാക്കിയിരിക്കുന്നു." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 790, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا قَدِمَ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ الْمَدِينَةَ آخَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُ وَبَيْنَ سَعْدِ بْنِ الرَّبِيعِ رَضِيَ اللهُ عَنْهُ، فَقَالَ لَهُ: هَلُمَّ أُقَاسِمْكَ مَالِي نِصْفَيْنِ، وَلِي امْرَأَتَانِ فَأُطَلِّقُ إِحْدَاهُمَا، فَإِذَا انْقَضَتْ عِدَّتُهَا فَتَزَوَّجْهَا. فَقَالَ: بَارَكَ اللهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، دُلُّونِي عَلَى السُّوقِ. فَدَلُّوهُ عَلَى السُّوقِ، فَمَا رَجَعَ يَوْمَئِذٍ إِلَّا وَمَعَهُ شَيْءٌ مِنْ أَقِطٍ وَسَمْنٍ قَدِ اسْتَفْضَلَهُ، فَرَآهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ذَلِكَ وَعَلَيْهِ وَضَرٌ مِنْ صُفْرَةٍ، فَقَالَ: "مَهْيَمْ". قَالَ: تَزَوَّجْتُ امْرَأَةً مِنَ الْأَنْصَارِ، قَالَ: "فَمَا أَصْدَقْتَهَا". قَالَ: نَوَاةً – أَوْ: وَزْنَ نَوَاةٍ – مِنْ ذَهَبٍ. فَقَالَ: "أَوْلِمْ وَلَوْ بِشَاةٍ". حَسَنٌ صَحِيحٌ. (خ,ت)', 'അനസ്(റ): അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) മദീനയിലെത്തിയപ്പോൾ നബി(സ) അദ്ദേഹത്തിന്റെയും സഅ്ദുബ്നു റബീഅ്(റ)വിന്റെയും ഇടയിൽ സാഹോദര്യമുണ്ടാക്കി. അപ്പോൾ സഅദ്(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: വരൂ, താങ്കൾക്കായി ഞാനെന്റെ സമ്പത്ത് രണ്ട് പകുതിയായി ഭാഗിക്കാം. എനിക്ക് രണ്ട് ഭാര്യമാരുമുണ്ട്. ഞാനവരിലൊന്നിനെ ത്വലാഖ് ചൊല്ലാം. അവളുടെ ഇദ്ദ കഴിഞ്ഞാൽ താങ്കൾക്ക് അവളെ വിവാഹം കഴിക്കാം. അപ്പോൾ അബ്ദുറഹ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹു താങ്കളുടെ കുടുംബത്തിലും സമ്പത്തിലും അനുഗ്രഹം ചെയ്യട്ടെ. എനിക്ക് മാർക്കറ്റ് കാണിച്ച് തരൂ. അപ്പോൾ സഅ്ദ്(റ) അദ്ദേഹത്തിന് മാർക്കറ്റ് കാണിച്ചു കൊടുത്തു. ബാക്കിയായ നെയ്യും പാൽകട്ടിയുമായാണ് അന്ന് അദ്ദേഹം മടങ്ങിയത്. അതിന് ശേഷം റസൂൽ(സ) അദ്ദേഹത്തിന്റെ ശരീരത്തിൽ പുളിച്ച ഭക്ഷണത്തിന്റെ മഞ്ഞനിറം ഉണ്ടായിരുന്ന നിലയിലായിരുന്നു കണ്ടത്. അപ്പോൾ അവിടന്ന് ചോദിച്ചു: "എന്ത് പറ്റി?" അദ്ദേഹം പറഞ്ഞു: ഞാൻ ഒരു അൻസാരിപ്പെണ്ണിനെ വിവാഹം കഴിച്ചു. അവിടന്ന് പറഞ്ഞു: "എന്താണ് മഹർ നൽകിയത്?" അദ്ദേഹം പറഞ്ഞു: അഞ്ച് ദിർഹമിന്റെ തൂക്കം സ്വർണ്ണം. അപ്പോൾ അവിടന്നരുളി: "താങ്കൾ വിവാഹ സദ്യ ഒരുക്കുക, ഒരാട് കൊണ്ടായാലും ശരി." (ബു,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 790, 791, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: مَا خُيِّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي أَمْرَيْنِ إِلَّا اخْتَارَ أَيْسَرَهُمَا، مَا لَمْ يَكُنْ إِثْمًا، فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ، وَمَا انْتَقَمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِنَفْسِهِ، إِلَّا أَنْ تُنْتَهَكَ حُرْمَةُ اللهِ تَعَالَى فَيَنْتَقِمَ لِلَّهِ بِهَا. (ق,د)', 'ആഇശ(റ): രണ്ട് കാര്യങ്ങളിൽ ഒന്ന് തെരഞ്ഞെടുക്കാൻ അവസരമുണ്ടായാൽ റസൂൽ(സ) അവയിലേറ്റവും എളുപ്പമുള്ളത് മാത്രമാണ് തെരഞ്ഞെടുത്തിരുന്നത്, അതൊരു തെറ്റാകാത്തിടത്തോളം. അത്, തെറ്റാണെങ്കിൽ, നബി(സ)യായിരുന്നു അതിൽ നിന്ന് കൂടുതൽ വിട്ടുനിൽക്കുന്നയാൾ. അവിടന്ന് സ്വന്തത്തിനുവേണ്ടി ആരെയും ശിക്ഷിച്ചിട്ടില്ല. അല്ലാഹുവിന്റെ ലംഘിക്കപ്പെടാൻ പാടില്ലാത്ത കാര്യങ്ങൾ തകർക്കപ്പെട്ടാലൊഴികെ. അങ്ങനെ വന്നാൽ അവിടന്ന് അല്ലാഹുവിന് വേണ്ടി ശിക്ഷിക്കുമായിരുന്നു. (ബു,മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 791, 791, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا ضَرَبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَادِمًا وَلَا امْرَأَةً قَطْ. (م,د,جه)', 'ആഇശ(റ): റസൂൽ(സ) ഒരു സേവകനെയോ ഒരു അടിമസ്ത്രീയെയോ ഒരിക്കലും അടിച്ചിട്ടില്ല. (മു,ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 791, 791, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا: فِي قَوْلِهِ: {خُذِ الْعَفْوَ} [الأعراف: ١٩٩] قَالَ: أُمِرَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَأْخُذَ الْعَفْوَ مِنْ أَخْلَاقِ النَّاسِ. (خ,د)', 'അബ്ദുല്ലാഹിബ്നുസുബൈർ(റ): ''വിട്ടുവീഴ്ച പാലിക്കുക.'' (അഅ്റാഫ്: 199) എന്ന സൂക്തത്തെക്കുറിച്ച് അദ്ദേഹം പറഞ്ഞു: ജനങ്ങളുടെ സ്വഭാവങ്ങളിൽ വിട്ടുവീഴ്ച കൈകൊള്ളാൻ അല്ലാഹുവിന്റെ പ്രവാചകർ(സ) കൽപിക്കപ്പെട്ടു. (ബു,ദ)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നുസുബൈർ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], 'الأعراف: ١٩٩', null, 791, 791, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أُخْبِرُكُمْ بِأَفْضَلَ مِنْ دَرَجَةِ الصِّيَامِ وَالصَّلَاةِ وَالصَّدَقَةِ". قَالُوا: بَلَى يَا رَسُولَ اللهِ. قَالَ: "إِصْلَاحُ ذَاتِ الْبَيْنِ، وَفَسَادُ ذَاتِ الْبَيْنِ الْحَالِقَةُ". (د,ت)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നോമ്പിന്റെയും, നിസ്കാരത്തിന്റെയും സ്വദഖയുടെയും സ്ഥാനത്തേക്കാൾ ഏറ്റവും ശ്രേഷ്ഠമാക്കപ്പെട്ടത് ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞ് തരട്ടെയോ?" അവർ പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ ദൂതരേ. അവിടന്നരുളി: "രണ്ടാളുകൾക്കിടയിലെ ബന്ധം നന്നാക്കലാണത്. രണ്ടാളുകൾക്കിടയിൽ പ്രശ്നമുണ്ടാക്കൽ നാശമാണ്." (ദ,തു)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 791, 792, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ أُمِّ كُلْثُومٍ بِنْتِ عُقْبَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَمْ يَكْذِبْ مَنْ نَمَى بَيْنَ اثْنَيْنِ لِيُصْلِحَ". وفي رواية: "لَيْسَ بِالْكَاذِبِ مَنْ أَصْلَحَ بَيْنَ النَّاسِ، فَقَالَ: خَيْرًا أَوْ نَمَى خَيْرًا". (د,ت)', 'ഉമ്മുകുൽസൂം ബിൻത് ഉഖ്ബ(റ): പ്രവാചകർ(സ) പറഞ്ഞു: "രണ്ടാളുകൾക്കിടയിലെ ബന്ധം നന്നാക്കുവാൻ ഇല്ലാത്തത് പറഞ്ഞവൻ കളവ് പറഞ്ഞവനല്ല." മറ്റൊരു നിവേദനം: ജനങ്ങൾക്കിടയിലെ ബന്ധം നന്നാക്കാൻ കളവ് പറഞ്ഞവൻ അസത്യവാനല്ല. അവൻ നന്മയാണ് പറഞ്ഞത്, അല്ലെങ്കിൽ നന്മയാണ് അവൻ ഉണ്ടാക്കിപ്പറഞ്ഞത്. (ദ,തു)', 'أُمِّ كُلْثُومٍ بِنْتِ عُقْبَةَ', 'ഉമ്മുകുൽസൂം ബിൻത് ഉഖ്ബ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 792, 792, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=188), 1, 'وَفِي رِوَايَةٍ: "لَيْسَ بِالْكَاذِبِ مَنْ أَصْلَحَ بَيْنَ النَّاسِ، فَقَالَ: خَيْرًا أَوْ نَمَى خَيْرًا". (د,ت)', 'മറ്റൊരു നിവേദനം: ജനങ്ങൾക്കിടയിലെ ബന്ധം നന്നാക്കാൻ കളവ് പറഞ്ഞവൻ അസത്യവാനല്ല. അവൻ നന്മയാണ് പറഞ്ഞത്, അല്ലെങ്കിൽ നന്മയാണ് അവൻ ഉണ്ടാക്കിപ്പറഞ്ഞത്. (ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ أُمِّ كُلْثُومِ بِنْتِ عُقْبَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُرَخِّصُ فِي شَيْءٍ مِنَ الْكَذِبِ إِلَّا فِي ثَلَاثٍ، كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا أَعُدُّهُ كَاذِبًا: الرَّجُلُ يُصْلِحُ بَيْنَ النَّاسِ، يَقُولُ الْقَوْلَ وَلَا يُرِيدُ بِهِ إِلَّا الْإِصْلَاحَ، وَالرَّجُلُ يَقُولُ فِي الْحَرْبِ، وَالرَّجُلُ يُحَدِّثُ امْرَأَتَهُ وَالْمَرْأَةُ تُحَدِّثُ زَوْجَهَا". (ق,د,ت)', 'ഉമ്മുകുൽസൂം ബിൻത് ഉഖ്ബ(റ): കളവിന്റെ കാര്യത്തിൽ റസൂൽ(സ) ഒരു വിട്ടുവീഴ്ചയും ചെയ്യുന്നത് ഞാൻ കേട്ടിട്ടില്ല, മൂന്ന് കാര്യത്തിലൊഴികെ. റസൂൽ(സ) പറയാറുണ്ടായിരുന്നു: "ഞാൻ അവനെ കളവ് പറയുന്നവനായി ഗണിക്കുകയില്ല: ഒത്തുതീർപ്പിന് വേണ്ടി മാത്രം കളവ് പറയുന്ന, ജനങ്ങൾക്കിടയിൽ ഒത്തുതീർപ്പ് നടത്തുന്നവൻ, യുദ്ധത്തിൽ സംസാരിക്കുന്നവൻ, ഭാര്യയോട് സംസാരിക്കുന്ന ഭർത്താവും, ഭർത്താവിനോട് സംസാരിക്കുന്ന ഭാര്യയും." (ബു,മു,ദ,തു)', 'أُمِّ كُلْثُومِ بِنْتِ عُقْبَةَ', 'ഉമ്മുകുൽസൂം ബിൻത് ഉഖ്ബ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 792, 792, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَحِلُّ الْكَذِبُ إِلَّا فِي ثَلَاثٍ: يُحَدِّثُ الرَّجُلُ امْرَأَتَهُ لِيُرْضِيَهَا، وَالْكَذِبُ فِي الْحَرْبِ، وَالْكَذِبُ لِيُصْلِحَ بَيْنَ النَّاسِ". حَسَنٌ. (ق,د,ت,ن)', 'അസ്മാഅ് ബിൻത് യസീദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് കാര്യങ്ങളിലല്ലാതെ കളവ് പറയൽ അനുവദനീയമല്ല: ഭാര്യയെ തൃപ്തിപ്പെടുത്താൻ വേണ്ടി സംസാരിക്കുക, യുദ്ധ വേളയിൽ അസത്യം പറയൽ, ജനങ്ങൾക്കിടയിൽ ഒത്തുതീർപ്പിനായി കളവ് പറയൽ." (ബു,മു,ദ,തു,ന)', 'أَسْمَاءَ بِنْتِ يَزِيدَ', 'അസ്മാഅ് ബിൻത് യസീദ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 792, 792, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عَبْدِ اللهِ ابْنِ سَرْجِسَ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "السَّمْتُ الْحَسَنُ، وَالتُّؤَدَةُ، وَالِاقْتِصَادُ، جُزْءٌ مِنْ أَرْبَعَةٍ وَعِشْرِينَ جُزْءًا مِنَ النُّبُوَّةِ". حَسَنٌ (ت)', 'അബ്ദുല്ലാഹിബ്നു സർജിസിൽ മുസ്നി(റ): നബി(സ) പറഞ്ഞു: "നല്ല പെരുമാറ്റവും, സൗമ്യതയും, മിതത്വവും നുബുവ്വതിന്റെ ഇരുപത്തിനാല് ഭാഗങ്ങളിൽ ഒന്നാണ്." (തു)', 'عَبْدِ اللهِ ابْنِ سَرْجِسَ الْمُزَنِيِّ', 'അബ്ദുല്ലാഹിബ്നു സർജിസിൽ മുസ്നി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 792, 792, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِأَشَجِّ عَبْدِ الْقَيْسِ: "إِنَّ فِيكَ خَصْلَتَيْنِ يُحِبُّهُمَا اللهُ: الْحِلْمُ، وَالْأَنَاةُ". حَسَنٌ صَحِيحٌ (م,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അശജ്ജ് അബ്ദുൽ ഖൈസ്(റ)വിനോട് നബി(സ) പറഞ്ഞു: "നിശ്ചയം, നിന്നിൽ അല്ലാഹു ഇഷ്ടപ്പെടുന്ന രണ്ട് കാര്യങ്ങളുണ്ട്: സഹനശീലവും അവധാനതയും." (മു,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 792, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْأَنَاةُ مِنَ اللهِ، وَالْعَجَلَةُ مِنَ الشَّيْطَانِ". (ت)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ): റസൂൽ(സ) പറഞ്ഞു: "അവധാനത അല്ലാഹുവിൽ നിന്നുള്ളതാണ്. ധൃതി പിശാചിൽ നിന്നും." (തു)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 793, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْهَدْيَ الصَّالِحَ وَالسَّمْتَ الصَّالِحَ وَالِاقْتِصَادَ جُزْءٌ مِنْ خَمْسَةٍ وَعِشْرِينَ جُزْءًا مِنَ النُّبُوَّةِ". (د)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം നല്ല ചര്യയും നല്ല പെരുമാറ്റവും മിതത്വവും നുബുവ്വതിന്റെ ഇരുപത്തഞ്ച് ഭാഗങ്ങളിൽപ്പെട്ട ഒരു ഭാഗമാണ്." (ദ)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 793, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ – رَفَعَهُ – قَالَ: "أَحْبِبْ حَبِيبَكَ هَوْنًا مَا، عَسَى أَنْ يَكُونَ بَغِيضَكَ يَوْمًا مَا، وَأَبْغِضْ بَغِيضَكَ هَوْنًا مَا، عَسَى أَنْ يَكُونَ حَبِيبَكَ يَوْمًا مَا". (ت)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം മർഫൂആക്കി പറയുന്നു: "നീ നിന്റെ സ്നേഹിതനെ അതിർ വെച്ച് മാത്രം സ്നേഹിക്കുക. അവനൊരുപക്ഷേ, എന്നെങ്കിലുമൊരിക്കൽ നീ വെറുക്കുന്നവനായേക്കാം. നീ വെറുക്കുന്നവനെ ഒരതിർ വെച്ച് മാത്രം വെറുക്കുക. ഒരുപക്ഷേ, എന്നെങ്കിലുമൊരിക്കൽ അവൻ നിന്റെ സ്നേഹിതനായേക്കാം." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 793, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ، وَأَمْرُكَ بِالْمَعْرُوفِ وَنَهْيُكَ عَنِ الْمُنْكَرِ صَدَقَةٌ، وَإِرْشَادُكَ الرَّجُلَ فِي أَرْضِ الضَّلَالِ لَكَ صَدَقَةٌ، وَبَصَرُكَ لِلرَّجُلِ الرَّدِيءِ الْبَصَرِ لَكَ صَدَقَةٌ، وَإِمَاطَتُكَ الْحَجَرَ وَالشَّوْكَةَ وَالْعَظْمَ عَنِ الطَّرِيقِ لَكَ صَدَقَةٌ، وَإِفْرَاغُكَ مِنْ دَلْوِكَ فِي دَلْوِ أَخِيكَ لَكَ صَدَقَةٌ". حَسَنٌ (ت)', 'അബുദർറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നീ നിന്റെ സഹോദരന്റെ മുഖത്ത് നോക്കി പുഞ്ചിരിക്കുന്നത് നിനക്ക് ധർമ്മമാണ്. നന്മകൊണ്ടുള്ള നിന്റെ കൽപനയും തിന്മയെത്തൊട്ടുള്ള നിരോധനവും നിനക്ക് ധർമ്മമാണ്. (യാത്രക്കാർ) വഴിപിഴച്ച് പോയേക്കാവുന്ന സ്ഥലത്തുള്ള നിന്റെ മാർഗ്ഗ ദർശനവും നിനക്ക് ധർമ്മമാണ്. അവഗണനയോടെ നോക്കപ്പെടുന്ന ആളെ പരിഗണനയോടെ നീ നോക്കുന്നതും ധർമ്മമാണ്. വഴിയിൽ നിന്ന് കല്ല്, മുള്ള്, എല്ല് എന്നിവ നീക്കലും നിനക്ക് ധർമ്മമാണ്. നിന്റെ ബക്കറ്റിൽ നിന്ന് സഹോദരന്റെ ബക്കറ്റിലേക്ക് നീ ഒഴിച്ച് കൊടുക്കുന്നതും ധർമ്മമാണ്." (തു)', 'أَبِي ذَرٍّ', 'അബുദർറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 793, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُلُّ مَعْرُوفٍ صَدَقَةٌ". (خ,د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "എല്ലാ നന്മയും സ്വദഖയാണ്." (ബു,ദ)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 793, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ مُسْلِمٍ غَرَسَ غَرْسًا فَأَكَلَ مِنْهُ إِنْسَانٌ أَوْ دَابَّةٌ إِلَّا كَانَ لَهُ بِهِ صَدَقَةٌ". (خ)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറയുന്നു: "ഒരു മുസ്ലിം കൃഷി ചെയ്യുകയും അതിൽ നിന്ന് വല്ല മനുഷ്യനോ മൃഗമോ തിന്നുകയും ചെയ്താൽ അവന് സ്വദഖയുടെ പ്രതിഫലം ലഭിക്കുക തന്നെചെയ്യും." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ مَعْرُوفٍ صَدَقَةٌ، وَإِنَّ مِنَ الْمَعْرُوفِ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ، وَأَنْ تُفْرِغَ مِنْ دَلْوِكَ فِي إِنَاءِ أَخِيكَ". حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ നന്മയും ധർമ്മമാണ്. നിശ്ചയം, നീ നിന്റെ സഹോദരനെ പ്രസന്നമുഖത്തോടെ കണ്ടുമുട്ടലും നിന്റെ ബക്കറ്റിൽ നിന്ന് നിന്റെ സഹോദരന്റെ പാത്രത്തിലേക്ക് ഒഴിച്ച്കൊടുക്കലും ധർമ്മമാണ്." (ബു,മു,ദ,തു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ فِي الْجَنَّةِ غُرَفًا، تُرَى ظُهُورُهَا مِنْ بُطُونِهَا وَبُطُونُهَا مِنْ ظُهُورِهَا". فَقَامَ أَعْرَابِيٌّ فَقَالَ: لِمَنْ هِيَ يَا رَسُولَ اللهِ؟ قَالَ: "لِمَنْ أَطَابَ الْكَلَامَ، وَأَطْعَمَ الطَّعَامَ، وَأَدَامَ الصِّيَامَ، وَصَلَّى لِلَّهِ بِاللَّيْلِ وَالنَّاسُ نِيَامٌ". (ت)', 'അലി(റ): നബി(സ) പറഞ്ഞു: "അകത്ത് നിന്ന് പുറവും പുറത്ത് നിന്ന് അകവും കാണുന്ന ഒരുപാട് റൂമുകൾ സ്വർഗ്ഗത്തിലുണ്ട്." അപ്പോൾ ഒരു ഗ്രാമീണൻ എഴുന്നേറ്റു നിന്നു ചോദിച്ചു: അവ ആർക്കുള്ളതാണ്, അല്ലാഹുവിന്റെ റസൂലേ? അവിടന്ന് പറഞ്ഞു: "സംസാരം നന്നാക്കുകയും ഭക്ഷിപ്പിക്കുകയും വ്രതം പതിവാക്കുകയും ജനങ്ങൾ ഉറങ്ങിയിരിക്കെ രാത്രി അല്ലാഹുവിന് വേണ്ടി നിസ്കരിക്കുകയും ചെയ്തവർക്ക്." (തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، أَيُّ الصَّدَقَةِ أَفْضَلُ؟ قَالَ: "سَقْيُ الْمَاءِ". (د,ن,جه)', 'സഅ്ദുബ്നു ഉബാദ(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഏത് സ്വദഖയാണ് ഏറ്റവും ശ്രേഷ്ഠമായത്. അവിടന്ന് പറഞ്ഞു: "വെള്ളം കുടിപ്പിക്കൽ" (ദ,ന,ജ)', 'سَعْدِ بْنِ عُبَادَةَ', 'സഅ്ദുബ്നു ഉബാദ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ أَنَسِ ابْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَصُفُّ النَّاسُ – وَفِي رِوَايَةٍ: أَهْلُ الْجَنَّةِ – يَوْمَ الْقِيَامَةِ صُفُوفًا. فَيَمُرُّ الرَّجُلُ مِنْ أَهْلِ النَّارِ عَلَى الرَّجُلِ فَيَقُولُ: يَا فُلَانُ، أَمَا تَذْكُرُ يَوْمَ اسْتَسْقَيْتَ فَسَقَيْتُكَ شَرْبَةً؟ قَالَ: فَيَشْفَعُ لَهُ. وَيَمُرُّ الرَّجُلُ فَيَقُولُ: أَمَا تَذْكُرُ يَوْمَ نَاوَلْتُكَ طَهُورًا؟ فَيَشْفَعُ لَهُ". وَفِي رِوَايَةٍ: "وَيَقُولُ: يَا فُلَانُ، أَمَا تَذْكُرُ يَوْمَ بَعَثْتَنِي فِي حَاجَةِ كَذَا وَكَذَا، فَذَهَبْتُ لَكَ؟ فَيَشْفَعُ لَهُ". فِي سَنَدِهِ ضَعِيفٌ. (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ ജനങ്ങൾ – മറ്റൊരു നിവേദനത്തിൽ, സ്വർഗ്ഗവാസികൾ – വരിയായി നിൽക്കും. അപ്പോൾ അവരിൽപ്പെട്ട ഒരാളുടെ അടുത്തു കൂടെ നരകവാസി നടന്നുപോവുകയും ഇപ്രകാരം ചോദിക്കുകയും ചെയ്യും. മനുഷ്യാ, നീ വെള്ളം ചോദിക്കുകയും അപ്പോൾ ഞാൻ നിന്നെ കുടിപ്പിക്കുകയും ചെയ്ത ദിവസം നീ ഓർക്കുന്നില്ലെയോ? അവിടന്ന് പറഞ്ഞു: അപ്പോൾ അദ്ദേഹം ഇയാൾക്ക് വേണ്ടി ശിപാർശ ചെയ്യും. മറ്റൊരാൾ നടക്കുകയും ഇപ്രകാരം ചോദിക്കുകയും ചെയ്യും: ഞാൻ നിനക്ക് ശുദ്ധജലം നൽകിയ ദിനം ഓർക്കുന്നില്ലയോ? അപ്പോൾ അദ്ദേഹം അയാൾക്ക് വേണ്ടി ശിപാർശ ചെയ്യും." മറ്റൊരു നിവേദനത്തിൽ: "അയാൾ ചോദിക്കും: മനുഷ്യാ, ഇന്നാലിന്ന ആവശ്യത്തിനായി നീയെന്നെ അയക്കുകയും നിനക്ക് വേണ്ടി ഞാൻ പോവുകയും ചെയ്ത ദിനം നീ ഓർക്കുന്നില്ലെയോ? അപ്പോൾ അദ്ദേഹം അയാൾക്ക് വേണ്ടി ശിപാർശ ചെയ്യും." പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَنَسِ ابْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 794, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=202), 1, 'وَفِي رِوَايَةٍ: أَهْلُ الْجَنَّةِ – يَوْمَ الْقِيَامَةِ صُفُوفًا. فَيَمُرُّ الرَّجُلُ مِنْ أَهْلِ النَّارِ عَلَى الرَّجُلِ فَيَقُولُ: يَا فُلَانُ، أَمَا تَذْكُرُ يَوْمَ اسْتَسْقَيْتَ فَسَقَيْتُكَ شَرْبَةً؟ قَالَ: فَيَشْفَعُ لَهُ. وَيَمُرُّ الرَّجُلُ فَيَقُولُ: أَمَا تَذْكُرُ يَوْمَ نَاوَلْتُكَ طَهُورًا؟ فَيَشْفَعُ لَهُ".', 'മറ്റൊരു നിവേദനത്തിൽ, സ്വർഗ്ഗവാസികൾ – വരിയായി നിൽക്കും. അപ്പോൾ അവരിൽപ്പെട്ട ഒരാളുടെ അടുത്തു കൂടെ നരകവാസി നടന്നുപോവുകയും ഇപ്രകാരം ചോദിക്കുകയും ചെയ്യും. മനുഷ്യാ, നീ വെള്ളം ചോദിക്കുകയും അപ്പോൾ ഞാൻ നിന്നെ കുടിപ്പിക്കുകയും ചെയ്ത ദിവസം നീ ഓർക്കുന്നില്ലെയോ? അവിടന്ന് പറഞ്ഞു: അപ്പോൾ അദ്ദേഹം ഇയാൾക്ക് വേണ്ടി ശിപാർശ ചെയ്യും. മറ്റൊരാൾ നടക്കുകയും ഇപ്രകാരം ചോദിക്കുകയും ചെയ്യും: ഞാൻ നിനക്ക് ശുദ്ധജലം നൽകിയ ദിനം ഓർക്കുന്നില്ലയോ? അപ്പോൾ അദ്ദേഹം അയാൾക്ക് വേണ്ടി ശിപാർശ ചെയ്യും."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=202), 2, 'وَفِي رِوَايَةٍ: "وَيَقُولُ: يَا فُلَانُ، أَمَا تَذْكُرُ يَوْمَ بَعَثْتَنِي فِي حَاجَةِ كَذَا وَكَذَا، فَذَهَبْتُ لَكَ؟ فَيَشْفَعُ لَهُ". فِي سَنَدِهِ ضَعِيفٌ. (جه)', 'മറ്റൊരു നിവേദനത്തിൽ: "അയാൾ ചോദിക്കും: മനുഷ്യാ, ഇന്നാലിന്ന ആവശ്യത്തിനായി നീയെന്നെ അയക്കുകയും നിനക്ക് വേണ്ടി ഞാൻ പോവുകയും ചെയ്ത ദിനം നീ ഓർക്കുന്നില്ലെയോ? അപ്പോൾ അദ്ദേഹം അയാൾക്ക് വേണ്ടി ശിപാർശ ചെയ്യും." പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ سُرَاقَةَ بْنِ جُعْشُمٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ضَالَّةِ الْإِبِلِ، تَغْشَى حِيَاضِي قَدْ لُطْتُهَا لِإِبِلِي، فَهَلْ لِي مِنْ أَجْرٍ إِنْ سَقَيْتُهَا؟ قَالَ: "نَعَمْ، فِي كُلِّ ذَاتِ كَبِدٍ حَرَّى أَجْرٌ". فِي سَنَدِهِ مُدَلِّسٌ عَنْعَنَهُ. (جه)', 'സുറാഖതുബ്നു ജുഅ്ശും(റ): എന്റെ ഒട്ടകത്തിന് വേണ്ടി തയ്യാറാക്കിയ ജലസംഭരണികൾക്കടുത്തേക്ക് വെള്ളം കുടിക്കാനായി വരുന്ന വഴിതെറ്റിയ ഒട്ടകത്തെക്കുറിച്ച് ഞാൻ അല്ലാഹുവിന്റെ റസൂൽ(സ)യോട് ചോദിച്ചു: ഞാനതിന് വെള്ളം നൽകിയാൽ എനിക്ക് പ്രതിഫലമുണ്ടോ? അവിടന്ന് പറഞ്ഞു: "അതെ, ദാഹിക്കുന്ന എല്ലാ ജീവികളിലും പ്രതിഫലമുണ്ട്." (പരമ്പരയിൽ ഹദീസ് അൻഅനയാക്കിപ്പറഞ്ഞ മുദല്ലിസുണ്ട്.) (ജ)', 'سُرَاقَةَ بْنِ جُعْشُمٍ', 'സുറാഖതുബ്നു ജുഅ്ശും(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ الْمُهَاجِرِينَ قَالُوا: يَا رَسُولَ اللهِ، ذَهَبَتِ الْأَنْصَارُ بِالْأَجْرِ كُلِّهِ قَالَ: "لَا، مَا دَعَوْتُمُ اللهَ لَهُمْ وَأَثْنَيْتُمْ عَلَيْهِمْ". (د)', 'അനസ്(റ): മുഹാജിറുകൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അൻസാറുകൾ മുഴുവൻ പ്രതിഫലങ്ങളുമായി പോയി. അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ അവർക്ക് വേണ്ടി പ്രാർത്ഥിക്കുകയും അവരെ പുകഴ്ത്തിക്കൊണ്ടിരിക്കുകയും ചെയ്യുന്നിടത്തോളം അങ്ങനെയുണ്ടാവുകയില്ല." (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أُعْطِيَ عَطَاءً فَوَجَدَ فَلْيَجْزِ بِهِ، فَإِنْ لَمْ يَجِدْ فَلْيُثْنِ بِهِ، فَمَنْ أَثْنَى بِهِ فَقَدْ شَكَرَهُ، وَمَنْ كَتَمَهُ فَقَدْ كَفَرَهُ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും വല്ലതും നൽകപ്പെട്ടാൽ, സാധ്യമെങ്കിൽ നൽകിയവന് പ്രത്യുപകാരമായി വല്ലതും നൽകട്ടെ. തിരിച്ച് നൽകാൻ ഒന്നും ലഭിച്ചില്ലെങ്കിൽ അത് നൽകിയവനെ പുകഴ്ത്തിക്കൊള്ളട്ടെ. അങ്ങനെ ആരെങ്കിലും നൽകിയവനെ പുകഴ്ത്തിയാൽ തീർച്ചയായുമവൻ അയാൾക്ക് നന്ദി ചെയ്തിരിക്കുന്നു. ആരെങ്കിലും അത് മറച്ചുവെച്ചാൽ തീർച്ചയായും അവൻ അയാളോട് നന്ദികേട് കാണിച്ചിരിക്കുന്നു." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أُبْلِيَ بَلَاءً فَذَكَرَهُ فَقَدْ شَكَرَهُ، وَإِنْ كَتَمَهُ فَقَدْ كَفَرَهُ". (د)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾക്ക് വല്ല ബുദ്ധിമുട്ടുണ്ടായിട്ട് അല്ലാഹുവിനെ ഓർത്താൽ അവനതിനോട് നന്ദിയുള്ളവനായിരിക്കുന്നു. ഇനിയവനതിനെ മറച്ചുവെച്ചാൽ അവനതിന് നന്ദികേട് കാണിച്ചിരിക്കുന്നു." (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 796, 796, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَا يَشْكُرُ النَّاسَ لَا يَشْكُرُ اللهَ". حَسَنٌ صَحِيحٌ (د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങൾക്ക് നന്ദി ചെയ്യാത്തവൻ അല്ലാഹുവിന് നന്ദി ചെയ്യുകയില്ല." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 796, 796, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَمْ يَشْكُرِ النَّاسَ لَمْ يَشْكُرِ اللهَ". حَسَنٌ صَحِيحٌ (د,ت)', 'അബൂസഈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങൾക്ക് നന്ദി ചെയ്തിട്ടില്ലാത്തവൻ അല്ലാഹുവിന് നന്ദി ചെയ്തിട്ടില്ല." (ദ,തു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 796, 796, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: كَانَ يَقْبَلُ الْهَدِيَّةَ وَيُثِيبُ عَلَيْهَا. حَسَنٌ صَحِيحٌ (خ,د,ت)', 'ആഇശ(റ): നിശ്ചയം നബി(സ) ഹദ്യ സ്വീകരിക്കുകയും അതിന് പകരം നൽകുകയും ചെയ്യുമായിരുന്നു. (ബു,ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 796, 796, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا غِرْتُ عَلَى أَحَدٍ مِنْ أَزْوَاجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَا غِرْتُ عَلَى خَدِيجَةَ، وَمَا بِي أَنْ أَكُونَ أَدْرَكْتُهَا، وَمَا ذَاكَ إِلَّا لِكَثْرَةِ ذِكْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَهَا، وَإِنْ كَانَ لَيَذْبَحُ الشَّاةَ فَيَتَتَبَّعُ بِهَا صَدَائِقَ خَدِيجَةَ فَيُهْدِيهَا لَهُنَّ. حَسَنٌ صَحِيحٌ (ق,ت)', 'ആഇശ(റ): ഖദീജ(റ)യോട് ഞാൻ അസൂയപ്പെട്ടപോലെ നബി(സ)യുടെ ഭാര്യമാരിൽ ഒരാളോടും ഞാൻ അസൂയപ്പെട്ടിട്ടില്ല. ഞാനാണെങ്കിൽ മഹതിയെ കണ്ടിട്ടുമില്ല. അല്ലാഹുവിന്റെ റസൂൽ(സ) മഹതിയെ സ്മരിക്കുന്നതിന്റെ ആധിക്യമല്ലാതെ മറ്റൊന്നുമായിരുന്നില്ല ഈ അസൂയക്ക് കാരണം. അവിടന്ന് ആടിനെ അറുക്കുകയും അത് നൽകാനായി ഖദീജ(റ)യുടെ കൂട്ടുകാരികളെ അന്വേഷിക്കുകയും അങ്ങനെ അത് അവർക്ക് നൽകുകയും ചെയ്യുമായിരുന്നു. (ബു,മു,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 796, 796, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ مِنْ أَحَبِّكُمْ إِلَيَّ، وَأَقْرَبِكُمْ مِنِّي مَجْلِسًا يَوْمَ الْقِيَامَةِ، أَحَاسِنَكُمْ أَخْلَاقًا. وَإِنَّ أَبْغَضَكُمْ إِلَيَّ، وَأَبْعَدَكُمْ مِنِّي مَجْلِسًا يَوْمَ الْقِيَامَةِ: الثَّرْثَارُونَ وَالْمُتَشَدِّقُونَ وَالْمُتَفَيْهِقُونَ". قَالُوا: يَا رَسُولَ اللهِ، قَدْ عَلِمْنَا: "الثَّرْثَارُونَ وَالْمُتَشَدِّقُونَ". فَمَا الْمُتَفَيْهِقُونَ؟ قَالَ: "الْمُتَكَبِّرُونَ". حَسَنٌ. (ت)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം നിങ്ങളിൽ എനിക്ക് ഏറ്റവും സ്നേഹമുള്ളവനും, അന്ത്യനാളിൽ ഇരിപ്പിടം കൊണ്ട് എന്നിലേക്ക് ഏറ്റവും അടുത്തവനും നിങ്ങളിലെ ഏറ്റവും ഉത്തമ സ്വഭാവിയാണ്. നിശ്ചയം നിങ്ങളിൽ എനിക്ക് ഏറ്റവും ദേഷ്യമുള്ളവനും അന്ത്യനാളിൽ ഇരിപ്പിടം കൊണ്ട് എന്നിൽ നിന്ന് ഏറ്റവും വിദൂരത്തായവനും ''സർസാറൂൻ'' (ആവശ്യത്തിന് വേണ്ടിയല്ലാതെ കീർത്തനയോടു കൂടി ധാരാളം സംസാരിക്കുന്നവർ), ''മുതശദ്ദിഖൂൻ'' (സൂക്ഷ്മത കൂടാതെ സാഹിത്യം കൂട്ടി വിശാലമായി സംസാരിക്കുന്നവർ), ''മുതഫൈഹിഖൂൻ'' എന്നിവരാണ്." സ്വഹാബികൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ''സർസാറൂൻ'' എന്നതും ''മുതശദ്ദിഖൂൻ'' എന്നതും ഞങ്ങൾക്ക് മനസ്സിലായി. പക്ഷേ, ആരാണീ ''മുതഫൈഹിഖൂൻ''? അവിടന്ന് പറഞ്ഞു: "അഹങ്കാരികൾ". (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 796, 797, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: قُلْتُ يَا رَسُولَ اللهِ، إِنَّهُ لَيْسَ لِي مِنْ بَيْتِي إِلَّا مَا أَدْخَلَ عَلَيَّ الزُّبَيْرُ، أَفَأُعْطِي؟ قَالَ: "نَعَمْ، وَلَا تُوكِي فَيُوكَى عَلَيْكِ". يَقُولُ: لَا تُحْصِي فَيُحْصَى عَلَيْكِ. حَسَنٌ صَحِيحٌ (ق,د,ت,ن)', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, സുബൈർ(റ) എനിക്ക് കൊണ്ടുവന്ന് തന്നതല്ലാതെ എന്റെ വീട്ടിൽ എനിക്കായി ഒന്നുമില്ല. അതിനാൽ ഞാനതിൽ നിന്ന് ദാനം ചെയ്യട്ടെയോ? അവിടന്ന് പറഞ്ഞു: "അതെ, നീ കുറച്ചുമാത്രം കൊടുക്കരുത്. അപ്പോൾ നിനക്കും കുറച്ച് മാത്രമേ നൽകപ്പെടുകയുള്ളൂ." അവിടന്ന് ഉദ്ദേശിക്കുന്നത്: നീ ക്ലിപ്തപ്പെടുത്തിക്കൊടുക്കരുത്. അപ്പോൾ നിനക്കുള്ളതും ക്ലിപ്തപ്പെടുത്തപ്പെടും. (ബു,മു,ദ,തു,ന)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 797, 797, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "السَّخِيُّ: قَرِيبٌ مِنَ اللهِ، قَرِيبٌ مِنَ الْجَنَّةِ قَرِيبٌ مِنَ النَّاسِ بَعِيدٌ مِنَ النَّارِ وَالْبَخِيلُ بَعِيدٌ مِنَ اللهِ بَعِيدٌ مِنَ الْجَنَّةِ بَعِيدٌ مِنَ النَّاسِ قَرِيبٌ مِنَ النَّارِ. وَلَجَاهِلٌ سَخِيٌّ أَحَبُّ إِلَى اللهِ عَزَّ وَجَلَّ مِنْ عَالِمٍ بَخِيلٍ". (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഉദാരൻ: അവൻ അല്ലാഹുവിനോട് അടുത്തവനാണ്. സ്വർഗ്ഗത്തോട് അടുത്തവനാണ്. ജനങ്ങളോട് അടുത്തവനാണ്. നരകത്തിൽ നിന്ന് വിദൂരത്തായവനാണ്. പിശുക്കൻ, അവൻ അല്ലാഹുവിൽ നിന്ന് വിദൂരത്തായവനാണ്. സ്വർഗ്ഗത്തിൽ നിന്ന് വിദൂരത്തായവനാണ്. ജനങ്ങളിൽ നിന്ന് വിദൂരത്തായവനാണ്. നരകത്തോട് അടുത്തവനാണ്. നിശ്ചയം, ഉദാരനായ ഒരു പാമരൻ പിശുക്കനായ ഒരു പണ്ഡിതനേക്കാൾ അല്ലാഹുവിന് ഇഷ്ടപ്പെട്ടവനാണ്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 797, 797, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا بَلَغَهُ عَنِ الرَّجُلِ الشَّيْءُ لَمْ يَقُلْ: مَا بَالُ فُلَانٍ يَقُولُ؟ وَلَكِنْ يَقُولُ: مَا بَالُ أَقْوَامٍ يَقُولُونَ كَذَا وَكَذَا؟ (د)', 'ആഇശ(റ): ആരെങ്കിലും ഒരാൾ വല്ലതും പറഞ്ഞതായി നബി(സ)ക്ക് വിവരം കിട്ടിയാൽ, അപ്രകാരം പറയുന്ന ഇന്നാലിന്ന ആളുടെ അവസ്ഥയെന്താണ്? എന്ന് അവിടന്ന് ചോദിക്കുകയില്ല. മറിച്ച് ഇപ്രകാരമെല്ലാം പറയുന്ന സമൂഹത്തിന്റെ അവസ്ഥയെന്താണ്? എന്നാണ് അവിടന്ന് ചോദിക്കുക. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 797, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا دَخَلَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ أَثَرُ صُفْرَةٍ، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَلَّمَا يُوَاجِهُ رَجُلًا فِي وَجْهِهِ بِشَيْءٍ يَكْرَهُهُ، فَلَمَّا خَرَجَ قَالَ: "لَوْ أَمَرْتُمْ هَذَا أَنْ يَغْسِلَ ذَا عَنْهُ". (د)', 'അനസ്(റ): നിശ്ചയം, ദേഹത്ത് മഞ്ഞനിറത്തിന്റെ അടയാളമുള്ള ഒരാൾ അല്ലാഹുവിന്റെ റസൂൽ(സ)യുടെ സന്നിധിയിലേക്ക് വന്നു. വെറുക്കുന്ന വല്ലതും മുഖത്തുള്ളയാളോട് വളരെ കുറച്ച് മാത്രമേ അല്ലാഹുവിന്റെ റസൂൽ(സ) സംസാരിക്കാറുണ്ടായിരുന്നുള്ളൂ. അങ്ങനെ അയാൾ തിരിച്ച് പോയപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ അയാളോട് അയാളുടെ ദേഹത്തിൽ നിന്നത് കഴുകിക്കളയാൻ കൽപിച്ചിരുന്നുവെങ്കിൽ." (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمُؤْمِنُ غِرٌّ كَرِيمٌ وَالْفَاجِرُ خِبٌّ لَئِيمٌ". (د,ت)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "വിശ്വാസി ശുദ്ധഹൃദയനും ഔദാര്യവാനുമാണ്. തെമ്മാടി വഞ്ചകനും നീചനുമാണ്." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتِ: اسْتَأْذَنَ رَجُلٌ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "بِئْسَ ابْنُ الْعَشِيرَةِ أَوْ بِئْسَ رَجُلُ الْعَشِيرَةِ" ثُمَّ قَالَ: "ائْذَنُوا لَهُ". فَلَمَّا دَخَلَ أَلَانَ لَهُ الْقَوْلَ، فَقَالَتْ عَائِشَةُ: يَا رَسُولَ اللهِ، أَلَنْتَ لَهُ الْقَوْلَ، وَقَدْ قُلْتَ لَهُ مَا قُلْتَ؟ قَالَ: إِنَّ شَرَّ النَّاسِ عِنْدَ اللهِ مَنْزِلَةً يَوْمَ الْقِيَامَةِ مَنْ وَدَعَهُ – أَوْ تَرَكَهُ – النَّاسُ لِاتِّقَاءِ فُحْشِهِ". (ق,د)', 'ആഇശ(റ): ഒരാൾ നബി(സ)യോട് പ്രവേശിക്കാനനുമതി തേടി. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഗോത്രസന്താനം എത്ര മോശം" അല്ലെങ്കിൽ "ഗോത്രത്തിലെ അംഗം എത്ര മോശം." ശേഷം അവിടന്ന് പറഞ്ഞു: "അയാൾക്ക് അനുമതി നൽകുക." അയാൾ വന്നപ്പോൾ അവിടന്ന് അയാളോട് മൃദുലമായി സംസാരിച്ചു. അപ്പോൾ ആഇശ(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടന്ന് അയാളെക്കുറിച്ച് പറഞ്ഞതെല്ലാം പറഞ്ഞിരിക്കെ അയാളോടുള്ള സംസാരം മൃദുലമാക്കിയതെന്തേ? അവിടന്ന് പറഞ്ഞു: "അന്ത്യനാളിൽ അല്ലാഹുവിങ്കൽ സ്ഥാനത്താൽ ഏറ്റവും മോശമായവൻ, തന്റെ നീചവൃത്തി സൂക്ഷിക്കാനായി ജനങ്ങൾ ഉപേക്ഷിച്ചിട്ട ആളാണ്." (ബു,മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَجُلًا اسْتَأْذَنَ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بِئْسَ أَخُو الْعَشِيرَةِ". فَلَمَّا دَخَلَ انْبَسَطَ إِلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَكَلَّمَهُ، فَلَمَّا خَرَجَ قُلْتُ: يَا رَسُولَ اللهِ، لَمَّا اسْتَأْذَنَ قُلْتَ: "بِئْسَ أَخُو الْعَشِيرَةِ". فَلَمَّا دَخَلَ انْبَسَطْتَ إِلَيْهِ؟ فَقَالَ: "يَا عَائِشَةُ، إِنَّ اللهَ لَا يُحِبُّ الْفَاحِشَ الْمُتَفَحِّشَ". وفي رواية: "يَا عَائِشَةُ، إِنَّ مِنْ شِرَارِ النَّاسِ الَّذِينَ يُكْرِمُونَ اتِّقَاءَ أَلْسِنَتِهِمْ". (د)', 'ആഇശ(റ): നിശ്ചയം ഒരാൾ നബി(സ)യോട് അടുത്ത് വരാൻ സമ്മതം ചോദിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഗോത്രസഹോദരൻ എത്ര മോശമാണ്" അങ്ങനെ അയാൾ അകത്ത് വന്നപ്പോൾ അല്ലാഹുവിന്റെ റസൂൽ(സ) പ്രസന്നനാവുകയും അയാളോട് സംസാരിക്കുകയും ചെയ്തു. അങ്ങനെ അയാൾ പോയപ്പോൾ ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അയാൾ സമ്മതം ചോദിച്ചപ്പോൾ "ഗോത്ര സഹോദരൻ എത്ര മോശം" എന്ന് അങ്ങ് പറയുകയും അങ്ങനെ അയാൾ അകത്ത് വന്നപ്പോൾ അങ്ങ് അയാളോട് പ്രസന്നനാവുകയും ചെയ്തതെന്തേ? അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ആഇശാ, നിശ്ചയം അല്ലാഹു അസൻമാർഗിയായ ദുസ്വഭാവിയെ ഇഷ്ടപ്പെടുകയില്ല." മറ്റൊരു നിവേദനത്തിൽ: "ആഇശാ, സ്വന്തം നാവിനെ സൂക്ഷിക്കാൻ വേണ്ടി ബഹുമാനിക്കപ്പെടുന്നവർ ജനങ്ങളിൽ ഏറ്റവും മോശമായവരിൽപ്പെട്ടവരാണ്." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 798, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=218), 1, 'وَفِي رِوَايَةٍ: "يَا عَائِشَةُ، إِنَّ مِنْ شِرَارِ النَّاسِ الَّذِينَ يُكْرِمُونَ اتِّقَاءَ أَلْسِنَتِهِمْ". (د)', 'മറ്റൊരു നിവേദനത്തിൽ: "ആഇശാ, സ്വന്തം നാവിനെ സൂക്ഷിക്കാൻ വേണ്ടി ബഹുമാനിക്കപ്പെടുന്നവർ ജനങ്ങളിൽ ഏറ്റവും മോശമായവരിൽപ്പെട്ടവരാണ്." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَا رَأَيْتُ رَجُلًا الْتَقَمَ أُذُنَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَيُنَحِّي رَأْسَهُ، حَتَّى يَكُونَ الرَّجُلُ هُوَ الَّذِي يُنَحِّي رَأْسَهُ. وَمَا رَأَيْتُ رَجُلًا أَخَذَ بِيَدِهِ فَتَرَكَ يَدَهُ، حَتَّى يَكُونَ الرَّجُلُ هُوَ الَّذِي يَدَعُ يَدَهُ. (د)', 'അനസ്(റ): ഒരാൾ റസൂൽ(സ)യോട് സ്വകാര്യം പറഞ്ഞ് ആ വ്യക്തി സ്വന്തം തലമാറ്റിയിട്ടല്ലാതെ തിരുമേനി(സ) തല മാറ്റുന്നത് ഞാൻ കണ്ടിട്ടില്ല. ഒരാൾ തിരുമേനി(സ)യുടെ കരം പിടിച്ച്, അയാൾ തന്നെ തന്റെ കരം പിൻവലിക്കുന്നതുവരെ നബി(സ) കൈ വലിക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ وَجَدَ غُصْنَ شَوْكٍ، فَأَخَّرَهُ، فَشَكَرَ اللهُ لَهُ فَغَفَرَ لَهُ". حَسَنٌ صَحِيحٌ (ق،ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ ഒരു വഴിയിലൂടെ നടന്ന് കൊണ്ടിരിക്കെ, മുള്ളുള്ള ഒരു മരക്കൊമ്പ് കണ്ടെത്തി. അപ്പോൾ അയാളത് നീക്കി വെച്ചു. അതുകാരണം അല്ലാഹു അയാളോട് നന്ദി പ്രകടിപ്പിക്കുകയും അയാൾക്ക് പാപമോചനം നൽകുകയും ചെയ്തു." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَرَّ رَجُلٌ بِغُصْنِ شَجَرَةٍ عَلَى ظَهْرِ طَرِيقٍ، فَقَالَ: وَاللهِ لَأُنَحِّيَنَّ هَذَا عَنِ الْمُسْلِمِينَ لَا يُؤْذِيهِمْ، فَأُدْخِلَ الْجَنَّةَ". (م،جه)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ വഴിയുടെ മീതെയുള്ള ഒരു മരക്കൊമ്പിന്റെ അടുത്തുകൂടി നടന്നുപോയി. അപ്പോൾ അയാൾ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം. നിശ്ചയം ഞാനിതിനെ മുസ്ലിംകളെ ബുദ്ധിമുട്ടിക്കാത്ത വിധത്തിൽ മാറ്റിക്കളയും. അതുകാരണമയാൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കപ്പെട്ടു." (മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ أَبِي بَرْزَةَ الْأَسْلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، دُلَّنِي عَلَى عَمَلٍ أَنْتَفِعُ بِهِ. قَالَ: "اعْزِلِ الْأَذَى عَنْ طَرِيقِ الْمُسْلِمِينَ". (م،جه)', 'അബൂബർസതിൽ അസ്ലമീ(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഉപകാരപ്രദമായ ഒരു പ്രവർത്തനം അങ്ങ് എനിക്ക് അറിയിച്ച് തന്നാലും. അവിടന്ന് പറഞ്ഞു: "മുസ്ലിംകളുടെ വഴിയിൽ നിന്ന് നീ ബുദ്ധിമുട്ടുകളെ നീക്കുക." (മു,ജ)', 'أَبِي بَرْزَةَ الْأَسْلَمِيِّ', 'അബൂബർസതിൽ അസ്ലമീ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عُرِضَتْ عَلَيَّ أُمَّتِي بِأَعْمَالِهَا، حَسَنِهَا وَسَيِّئِهَا: فَرَأَيْتُ فِي مَحَاسِنِ أَعْمَالِهَا الْأَذَى يُنَحَّى عَنِ الطَّرِيقِ، وَرَأَيْتُ فِي سَيِّئِ أَعْمَالِهَا النُّخَاعَةَ فِي الْمَسْجِدِ لَا تُدْفَنُ". (جه)', 'അബൂദർറ്(റ): നബി(സ) പറഞ്ഞു: "എന്റെ സമുദായം, അവരുടെ നല്ലതും ചീത്തയുമായ പ്രവർത്തനങ്ങളോടു കൂടെ എനിക്ക് വെളിവാക്കപ്പെട്ടു. അപ്പോൾ അവരുടെ നല്ല പ്രവർത്തനങ്ങളിൽ വഴിയിൽ നിന്ന് മാറ്റപ്പെടുന്ന തടസ്സത്തെ ഞാൻ കണ്ടു. പള്ളിയിലുള്ള മണ്ണിൽ മൂടപ്പെടാത്ത കഫത്തെ, അവരുടെ മോശപ്പെട്ട പ്രവർത്തനങ്ങളിലും ഞാൻ കണ്ടു." (ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "فِي الْإِنْسَانِ ثَلَاثُ مِائَةٍ وَسِتُّونَ مَفْصِلًا، فَعَلَيْهِ أَنْ يَتَصَدَّقَ عَنْ كُلِّ مَفْصِلٍ مِنْهُ بِصَدَقَةٍ". قَالُوا: وَمَنْ يُطِيقُ ذَلِكَ يَا نَبِيَّ اللهِ؟ قَالَ: "النُّخَاعَةُ فِي الْمَسْجِدِ تَدْفِنُهَا، وَالشَّيْءُ تُنَحِّيهِ عَنِ الطَّرِيقِ، فَإِنْ لَمْ تَجِدْ فَرَكْعَتَا الضُّحَى تُجْزِئُكَ". (د)', 'ബുറൈദ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മനുഷ്യനിൽ മുന്നൂറ്ററുപത് കെണിപ്പുകളുണ്ട്. അവക്കോരോന്നിനും സ്വദഖ ചെയ്യൽ അവന്റെ ബാധ്യതയാണ്." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അതിനാർക്കാണ് സാധിക്കുക? അവിടന്ന് പറഞ്ഞു: "അത് പള്ളിയിലുള്ള കഫം നീ കുഴിച്ച് മൂടിയതാവാം. വഴിയിൽ നിന്ന് നീ മാറ്റിയിടുന്ന വസ്തുവാകും. ഇനി അവ നീ എത്തിച്ചില്ലെങ്കിൽ ളുഹായുടെ രണ്ട് റക്അത്ത് നിസ്കാരം നിനക്ക് മതിയാകും." (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُصْبِحُ عَلَى كُلِّ سُلَامَى مِنِ ابْنِ آدَمَ صَدَقَةٌ، تَسْلِيمُهُ عَلَى مَنْ لَقِيَ صَدَقَةٌ، وَأَمْرُهُ بِالْمَعْرُوفِ صَدَقَةٌ، وَنَهْيُهُ عَنِ الْمُنْكَرِ صَدَقَةٌ، وَإِمَاطَتُهُ الْأَذَى عَنِ الطَّرِيقِ صَدَقَةٌ، وَبُضْعَتُهُ أَهْلَهُ صَدَقَةٌ". قَالُوا يَا رَسُولَ اللهِ، يَأْتِي شَهْوَةً وَتَكُونُ لَهُ صَدَقَةٌ؟ قَالَ: "أَرَأَيْتَ لَوْ وَضَعَهَا فِي غَيْرِ حَقِّهَا أَكَانَ يَأْثَمُ". قَالَ: "وَيُجْزِئُ مِنْ ذَلِكَ كُلِّهِ رَكْعَتَانِ مِنَ الضُّحَى". (م،د،ن)', 'അബൂദർറ്(റ): നബി(സ) പറഞ്ഞു: "ആദം സന്തതിക്ക് തന്റെ അവയവ സന്ധികളുടെ കണക്കനുസരിച്ചുള്ള ധർമ്മം അനിവാര്യമാണ്. അവൻ കണ്ടുമുട്ടിയവരോട് സലാം പറയലും, നന്മ കൊണ്ടുള്ള അവന്റെ കൽപനയും തിൻമയെത്തൊട്ടുള്ള നിരോധനവും സ്വദഖയാണ്. വഴിയിലുള്ള തടസ്സങ്ങൾ നീക്കലും സ്വദഖയാണ്, തന്റെ ഭാര്യയുമായി അവൻ ബന്ധപ്പെടലും സ്വദഖയാണ്." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവൻ വികാരത്തോടെ ചെന്നാലും അതവന് സ്വദഖയാകുമോ? അവിടന്ന് പറഞ്ഞു: "നിങ്ങളുടെ അഭിപ്രായമെന്താണ്? അവനതിനെ അവന്റെ അവകാശമില്ലാത്തിടത്ത് വെച്ചാൽ അവൻ തെറ്റുകാരനാവില്ലേ." അവിടന്ന് പറഞ്ഞു: "ഇതിനെല്ലാം പകരമായി ളുഹാ സമയത്തുള്ള രണ്ട് റക്അത്ത് നിസ്കാരം മതിയാകും." (മു,ദ,ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "نَزَعَ رَجُلٌ – لَمْ يَعْمَلْ خَيْرًا قَطُّ – غُصْنَ شَوْكٍ عَنِ الطَّرِيقِ: إِمَّا كَانَ فِي شَجَرَةٍ فَقَطَعَهُ وَأَلْقَاهُ، وَإِمَّا كَانَ مَوْضُوعًا فَأَمَاطَهُ، فَشَكَرَ اللهُ لَهُ بِهَا فَأَدْخَلَهُ الْجَنَّةَ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു നന്മയും ചെയ്തിട്ടില്ലാത്ത ഒരാൾ, മുള്ളുള്ള ഒരു മരക്കൊമ്പ് വഴിയിൽ നിന്ന് മാറ്റിയിട്ടു. ഒന്നുകിൽ അത് മരത്തിൻമേലായിരുന്നു. അപ്പോൾ അയാൾ അത് മുറിച്ചൊഴിവാക്കി. അതല്ലെങ്കിൽ വീണുകിടക്കുകയായിരുന്നു, അത് നീക്കം ചെയ്തു. അത് കാരണമായി അല്ലാഹു അവനോട് നന്ദി കാണിക്കുകയും അവനെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയും ചെയ്തു." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: مَا عَابَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ طَعَامًا قَطُّ كَانَ إِذَا اشْتَهَاهُ أَكَلَهُ وَإِلَّا تَرَكَهُ. حَسَنٌ صَحِيحٌ. (ق،د،ت،جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഒരു ഭക്ഷണത്തെയും ഒരിക്കലും ആക്ഷേപിച്ചിട്ടില്ല. തിരുമേനി(സ)ക്ക് ആഗ്രഹമുണ്ടെങ്കിൽ അതു ഭക്ഷിക്കും, ആഗ്രഹമില്ലെങ്കിൽ വേണ്ടെന്ന് വെക്കും. (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعَثَ مُعَاذَ بْنَ جَبَلٍ إِلَى الْيَمَنِ، فَقَالَ: "اتَّقِ دَعْوَةَ الْمَظْلُومِ، فَإِنَّهَا لَيْسَ بَيْنَهَا وَبَيْنَ اللهِ حِجَابٌ". حَسَنٌ صَحِيحٌ. (ق،د،ت،ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) മുആദുബ്നു ജബൽ(റ)വിനെ യമനിലേക്കയച്ചു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അക്രമിക്കപ്പെട്ടവന്റെ പ്രാർത്ഥന നീ സൂക്ഷിക്കുക, കാരണം അതിന്റെയും അല്ലാഹുവിന്റെയുമിടയിൽ യാതൊരു മറയുമില്ല." (ബു,മു,ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سُرِقَ لَهَا شَيْءٌ، فَجَعَلَتْ تَدْعُو عَلَيْهِ، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُسَبِّخِي عَنْهُ". (د)', 'ആഇശ(റ): മഹതിയുടെ ഒരു സാധനം മോഷ്ടിക്കപ്പെട്ടു. അപ്പോൾ മഹതി അയാൾക്കെതിരെ പ്രാർത്ഥിക്കാൻ തുടങ്ങി. അപ്പോൾ മഹതിയോട് അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "നീ അയാൾക്കെതിരെ ദുആ ചെയ്ത് അയാളുടെ കുറ്റത്തെ ലഘുവാക്കേണ്ടതില്ല." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَدَّثَ: "أَنَّ رَجُلًا قَالَ: وَاللهِ لَا يَغْفِرُ اللهُ لِفُلَانٍ، وَإِنَّ اللهَ تَعَالَى قَالَ: مَنْ ذَا الَّذِي يَتَأَلَّى عَلَيَّ أَنْ لَا أَغْفِرَ لِفُلَانٍ، فَإِنِّي قَدْ غَفَرْتُ لِفُلَانٍ، وَأَحْبَطْتُ عَمَلَكَ" أَوْ كَمَا قَالَ. (م)', 'ജുൻദുബ്(റ): റസൂൽ(സ) ഉദ്ധരിക്കുന്നു: "ഒരാൾ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, അല്ലാഹു ഇന്നാലിന്നയാൾക്ക് പൊറുത്തു കൊടുക്കില്ല. അല്ലാഹു പറയും: ഇന്നാലിന്നവന് ഞാൻ പൊറുത്ത് കൊടുക്കുകില്ലെന്ന് എന്റെ മേൽ സത്യം ചെയ്യുന്നവനാരാണ്, നിശ്ചയം ഞാനയാൾക്ക് പൊറുത്ത് കൊടുക്കുകയും നിന്റെ പ്രവർത്തനങ്ങളെ മായ്ച്ച് കളയുകയും ചെയ്തിരിക്കുന്നു." അല്ലെങ്കിൽ അവിടന്ന് പറഞ്ഞത് പോലെ. (മു)', 'جُنْدَبٍ', 'ജുൻദുബ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يُشِيرُ أَحَدُكُمْ إِلَى أَخِيهِ بِالسِّلَاحِ، فَإِنَّهُ لَا يَدْرِي أَحَدُكُمْ لَعَلَّ الشَّيْطَانَ يَنْزِعُ فِي يَدِهِ، فَيَقَعُ فِي حُفْرَةٍ مِنَ النَّارِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഒരാളും തന്റെ സഹോദരന്റെ നേരെ ആയുധം ചൂണ്ടരുത്. കാരണം നിങ്ങൾ അറിയുകയില്ല, കയ്യിൽ ശൈത്വാൻ അവസരം ഉപയോഗപ്പെടുത്തിയേക്കാമെന്നത്. അങ്ങനെയവൻ നരകക്കുണ്ടിൽ വീഴുകയും ചെയ്യും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ وَأَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُمَا سَمِعَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا يُصِيبُ الْمُؤْمِنَ مِنْ وَصَبٍ، وَلَا نَصَبٍ، وَلَا سَقَمٍ، وَلَا حُزْنٍ، حَتَّى الْهَمِّ يُهَمُّهُ إِلَّا كُفِّرَ بِهِ مِنْ سَيِّئَاتِهِ". (م)', 'അബൂസഇൗദിൽ ഖുദ്രി(റ), അബൂഹുറൈറ(റ): അവർ രണ്ടു പേരും അല്ലാഹുവിന്റെ റസൂൽ(സ) പറയുന്നതായി കേട്ടു: "ദോശങ്ങൾ പൊറുക്കപ്പെട്ടിട്ടല്ലാതെ, ഒരു മുഅ്മിനിനും ബുദ്ധിമുട്ടോ ക്ഷീണമോ അസുഖമോ ദുഃഖമോ വല്ല അസ്വാസ്ഥ്യമോ പിടിപെടുകയില്ല." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 802, 802, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ: {مَنْ يَعْمَلْ سُوءًا يُجْزَ بِهِ} [النساء: ١٢٣]. بَلَغَتْ مِنَ الْمُسْلِمِينَ مَبْلَغًا شَدِيدًا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قَارِبُوا وَسَدِّدُوا، فَفِي كُلِّ مَا يُصَابُ بِهِ الْمُسْلِمُ كَفَّارَةٌ، حَتَّى النَّكْبَةِ يُنْكَبُهَا أَوِ الشَّوْكَةِ يُشَاكُهَا". (م)', 'അബൂഹുറൈറ(റ): ''ആരെങ്കിലും വല്ല ചീത്ത കാര്യവും ചെയ്താൽ അവനതിന് പ്രതിഫലം നൽകപ്പെടും'' (നിസാഅ്: 123) എന്ന സൂക്തം ഇറങ്ങിയപ്പോൾ മുസ്ലിംകൾക്കത് വല്ലാത്ത വിഷമമായി. അപ്പോൾ തിരുദൂതർ(സ) പറഞ്ഞു: "നിങ്ങൾ മിതത്വം പാലിക്കുക, സത്യത്തോടൊപ്പം ഉറച്ചുനിൽക്കുക. മുസ്ലിമിന് സംഭവിക്കുന്നതിലൊക്കെ പാപമോചനമുണ്ട്. അവനേൽക്കുന്ന മുള്ളിലും അവനെത്തുന്ന ബുദ്ധിമുട്ടുകളിൽ പോലും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'النساء: ١٢٣', null, 802, 802, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنِ الْأَسْوَدِ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ شَبَابٌ مِنْ قُرَيْشٍ عَلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا، وَهِيَ بِمِنًى، وَهُمْ يَضْحَكُونَ، فَقَالَتْ: مَا يُضْحِكُكُمْ؟ قَالُوا: فُلَانٌ خَرَّ عَلَى طُنُبِ فُسْطَاطٍ، فَكَادَتْ عُنُقُهُ – أَوْ عَيْنُهُ – أَنْ تَذْهَبَ. فَقَالَتْ: لَا تَضْحَكُوا، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ مُسْلِمٍ يُشَاكُ شَوْكَةً فَمَا فَوْقَهَا إِلَّا كُتِبَتْ لَهُ بِهَا دَرَجَةٌ، وَمُحِيَتْ عَنْهُ بِهَا خَطِيئَةٌ". (م)', 'അസ്വദ്(റ): ആഇശ(റ) മിനയിലായിരിക്കെ ഖുറൈശികളിൽപ്പെട്ട ചില യുവാക്കൾ ചിരിച്ചുകൊണ്ട് മഹതിയുടെ അടുക്കൽ വന്നു. അപ്പോൾ മഹതി ചോദിച്ചു: നിങ്ങൾ എന്തിനാണ് ചിരിക്കുന്നത്? അവർ പറഞ്ഞു: കൂടാരത്തിന്റെ വലിച്ചുകെട്ടിയ കയറിന്മേൽ ഒരാൾ വീണു. അങ്ങനെ അയാളുടെ പിരടി - അല്ലെങ്കിൽ അയാളുടെ കണ്ണ് - പോകാനടുക്കുകയും ചെയ്തു. മഹതി പറഞ്ഞു: നിങ്ങൾ ചിരിക്കരുത്. കാരണം, നിശ്ചയം അല്ലാഹുവിന്റെ റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "മുള്ള് കുത്തുകയോ അല്ലെങ്കിൽ അതിലേറെ വലിയ വല്ലതും സംഭവിക്കുകയോ ചെയ്ത ഏതു മുസ്ലിമിനും അത് കാരണമായി ഒരു സ്ഥാനം എഴുതപ്പെടുകയും അവന്റെ ദോഷങ്ങൾ മായ്ക്കപ്പെടുകയും ചെയ്യാതിരിക്കില്ല." (മു)', 'الْأَسْوَدِ', 'അസ്വദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 802, 802, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُؤْمِنُ مِرْآةُ الْمُؤْمِنِ، وَالْمُؤْمِنُ أَخُو الْمُؤْمِنِ: يَكُفُّ عَلَيْهِ ضَيْعَتَهُ، وَيَحُوطُهُ مِنْ وَرَائِهِ". (د)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "ഒരു മുഅ്മിൻ മറ്റൊരു മുഅ്മിനിന്റെ കണ്ണാടിയാണ്. ഒരു മുഅ്മിൻ മറ്റൊരു മുഅ്മിനിന്റെ സഹോദരനാണ്. അവന് നഷ്ടം വരൽ ഇവൻ തടഞ്ഞുനിർത്തും. അവന്റെ പിന്നിലൂടെ അവനെ സംരക്ഷിക്കുകയും ചെയ്യും." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 802, 803, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنْ تَمِيمٍ الدَّارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الدِّينَ النَّصِيحَةُ، إِنَّ الدِّينَ النَّصِيحَةُ". قَالُوا: لِمَنْ يَا رَسُولَ اللهِ؟ قَالَ: "لِلَّهِ وَكِتَابِهِ وَرَسُولِهِ وَأَئِمَّةِ الْمُؤْمِنِينَ وَعَامَّتِهِمْ". أَوْ: "أَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ". (م،د،ت،ن)', 'തമീമുദാരി(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "നിശ്ചയം മതമെന്നാൽ ഉപദേശമാണ്. നിശ്ചയം മതമെന്നാൽ ഉപദേശമാണ്." അവർ ചോദിച്ചു: ആരോടാണ് അല്ലാഹുവിന്റെ റസൂലേ? അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവിനോടും അവന്റെ ഗ്രന്ഥത്തോടും അവന്റെ റസൂലിനോടും മുഅ്മിനീങ്ങളുടെ ഇമാമുമാരോടും പൊതുജനങ്ങളോടും." അല്ലെങ്കിൽ "മുസ്ലിംകളുടെ ഇമാമുമാരോടും അവരിലെ സാധാരണക്കാരോടും." (മു,ദ,തു,ന)', 'تَمِيمٍ الدَّارِيِّ', 'തമീമുദാരി(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 803, 803, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنْ جَرِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَايَعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ، وَأَنْ أَنْصَحَ لِكُلِّ مُسْلِمٍ، قَالَ: وَكَانَ إِذَا بَاعَ الشَّيْءَ أَوِ اشْتَرَاهُ قَالَ: "أَمَا إِنَّ الَّذِي أَخَذْنَا مِنْكَ أَحَبُّ إِلَيْنَا مِمَّا أَعْطَيْنَاكَ، فَاخْتَرْ". (ق،د،ن)', 'ജരീർ(റ): കേൾക്കുകയും അനുസരിക്കുകയും ചെയ്യുമെന്നും എല്ലാ മുസ്ലിംകളെയും ഉപദേശിക്കുമെന്നും ഞാൻ അല്ലാഹുവിന്റെ റസൂലിനോട് ഉടമ്പടി ചെയ്തു. നിവേദകൻ പറയുന്നു: വല്ലതും വാങ്ങുകയോ വിൽക്കുകയോ ചെയ്താൽ അവിടന്ന് പറയുമായിരുന്നു: "നിശ്ചയം ഞാൻ നിന്നിൽ നിന്നും വാങ്ങിയതാണ് ഞാൻ നിനക്ക് നൽകിയതിനേക്കാൾ എനിക്കിഷ്ടം. അതുകൊണ്ട് നിനക്ക് ഇഷ്ടമുള്ളത് തെരഞ്ഞെടുക്കുക." (ബു,മു,ദ,ന)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 803, 803, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: بَايَعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى إِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالنُّصْحِ لِكُلِّ مُسْلِمٍ. صَحِيحٌ. (ق،د،ت،ن)', 'ജരീറുബ്നു അബ്ദില്ല(റ): നിസ്കാരം നിലനിർത്തുമെന്നും സകാത്ത് കൊടുക്കുമെന്നും എല്ലാ മുസ്ലിംകളെയും ഉപദേശിക്കുമെന്നും ഞാൻ അല്ലാഹുവിന്റെ റസൂലിനോട് ഉടമ്പടി ചെയ്തു. (ബു,മു,ദ,തു,ന)', 'جَرِيرِ بْنِ عَبْدِ اللهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 803, 803, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا حَدَّثَ الرَّجُلُ الْحَدِيثَ، ثُمَّ الْتَفَتَ، فَهِيَ أَمَانَةٌ". حَسَنٌ. (د،ت)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ വല്ലതും പറയുകയും പിന്നീട് (മറ്റുള്ളവർ അത് കേൾക്കുന്നത് ഭയന്ന്) അതിൽ നിന്ന് പിന്തിരിഞ്ഞുകളയുകയും ചെയ്താൽ അയാൾ പറഞ്ഞത് സൂക്ഷിപ്പുസ്വത്താണ്." (ദ,തു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 803, 803, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيُخَالِطُنَا حَتَّى يَقُولَ لِأَخٍ لِي صَغِيرٍ: "يَا أَبَا عُمَيْرٍ مَا فَعَلَ النُّغَيْرُ". (خ)', 'അനസ്(റ): തിരുദൂതർ(സ) ഞങ്ങളുമായി ഇടകലർന്നുകൊണ്ടാണ് ജീവിച്ചത്. അവിടന്ന് ചിലപ്പോൾ എന്റെ കൊച്ചുസഹോദരനോട് ചോദിക്കും: "അബൂഉമൈർ, നിന്റെ കുരുവിക്കെന്തുപറ്റി?" (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 803, 803, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ مَنَحَ مَنِيحَةَ لَبَنٍ أَوْ وَرِقٍ، أَوْ هَدَى زُقَاقًا كَانَ لَهُ مِثْلُ عِتْقِ رَقَبَةٍ". حَسَنٌ صَحِيحٌ (ت)', 'ബറാഉബ്നു ആസിബ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും പാൽ നിറഞ്ഞൊഴുകുന്ന ആടിനെ, അല്ലെങ്കിൽ ചാരവർണത്തിലുള്ള ഒട്ടകങ്ങളെ ദാനംചെയ്യുകയോ അല്ലെങ്കിൽ വഴിതെറ്റിയവന് വഴികാണിച്ചു കൊടുക്കുകയോ ചെയ്താൽ അടിമയെ മോചിപ്പിച്ചതിന് സമാനമായ പ്രതിഫലം അവനുണ്ട്." (തു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 804, 804, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْحَيَاءُ وَالْعِيُّ شُعْبَتَانِ مِنَ الْإِيمَانِ، وَالْبَذَاءُ وَالْبَيَانُ شُعْبَتَانِ مِنَ النِّفَاقِ". حَسَنٌ. (ت)', 'അബൂഉമാമ(റ): നബി(സ) പറഞ്ഞു: "ലജ്ജയും നന്മയില്ലാത്ത കാര്യങ്ങൾ സംസാരിക്കാതിരിക്കലും ഈമാനിന്റെ രണ്ട് ശാഖകളാണ്. മോശമായി സംസാരിക്കലും സംസാരത്തിൽ ആവശ്യത്തിലമിതമായി സാഹിത്യം ഉപയോഗിക്കലും കാപട്യത്തിന്റെ രണ്ട് ശാഖകളാണ്." (തു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 804, 804, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلَانِ، فَكَلَّمَاهُ بِشَيْءٍ لَا أَدْرِي مَا هُوَ؟ فَأَغْضَبَاهُ، فَلَعَنَهُمَا وَسَبَّهُمَا، فَلَمَّا خَرَجَا، قُلْتُ: يَا رَسُولَ اللهِ، مَنْ أَصَابَ مِنَ الْخَيْرِ شَيْئًا مَا أَصَابَهُ هَذَانِ. قَالَ: "وَمَا ذَاكِ". قَالَتْ: قُلْتُ: لَعَنْتَهُمَا وَسَبَبْتَهُمَا قَالَ: "أَوَ مَا عَلِمْتِ مَا شَارَطْتُ عَلَيْهِ رَبِّي؟ قُلْتُ: اللَّهُمَّ إِنَّمَا أَنَا بَشَرٌ، فَأَيُّ الْمُسْلِمِينَ لَعَنْتُهُ أَوْ سَبَبْتُهُ فَاجْعَلْهُ لَهُ زَكَاةً وَأَجْرًا". (م)', 'ആഇശ(റ): രണ്ടാളുകൾ അല്ലാഹുവിന്റെ റസൂൽ(സ)യുടെ അടുക്കൽ വന്നു. എനിക്ക് അറിഞ്ഞ് കൂടാത്ത എന്തൊക്കെയോ അവർ അവിടത്തോട് സംസാരിക്കുകയും അവർ അവിടുത്തെ ദേഷ്യം പിടിപ്പിക്കുകയും ചെയ്തു. അപ്പോൾ അവിടന്ന് രണ്ടുപേരെയും ആക്ഷേപിക്കുകയും ചീത്ത പറയുകയും ചെയ്തു. അങ്ങനെ അവർ രണ്ടുപേരും പോയപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നന്മയിൽ നിന്ന് വളരെ തുഛം മാത്രം ലഭിച്ച ഒരാൾക്ക് കിട്ടിയത് പോലും ഇവർക്ക് കിട്ടിയിട്ടില്ല. അവിടന്ന് ചോദിച്ചു: "അതെന്താണ്?" മഹതി പറയുന്നു: ഞാൻ പറഞ്ഞു: അങ്ങവരെ ചീത്ത പറയുകയും ആക്ഷേപിക്കുകയും ചെയ്തിരിക്കുന്നു. അപ്പോൾ അവിടന്ന് ചോദിച്ചു: "ഞാൻ എന്റെ രക്ഷിതാവുമായി കരാറിലേർപ്പെട്ടത് നിനക്കറിയില്ലേ? ഞാൻ പറഞ്ഞു: അല്ലാഹുവേ, തീർച്ചയായും ഞാൻ ഒരു മനുഷ്യനാണ്. അതുകൊണ്ട് ഞാൻ ആക്ഷേപിച്ചവന്നും ചീത്തവിളിച്ചവന്നും അത് ധർമ്മവും പ്രതിഫലവുമാക്കിക്കൊടുക്കണേ." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 804, 804, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتْ عِنْدَ أُمِّ سُلَيْمٍ يَتِيمَةٌ، وَهِيَ أُمُّ أَنَسٍ، فَرَأَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْيَتِيمَةَ، فَقَالَ: "آنْتِ هِيَهْ؟ لَقَدْ كَبِرْتِ لَا كَبِرَ سِنُّكِ". فَرَجَعَتِ الْيَتِيمَةُ إِلَى أُمِّ سُلَيْمٍ تَبْكِي، فَقَالَتْ أُمُّ سُلَيْمٍ: مَا لَكِ يَا بُنَيَّةُ؟ قَالَتِ الْجَارِيَةُ: دَعَا عَلَيَّ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا يَكْبَرَ سِنِّي، فَالْآنَ لَا يَكْبَرُ سِنِّي أَبَدًا، أَوْ قَالَتْ: قَرْنِي. فَخَرَجَتْ أُمُّ سُلَيْمٍ مُسْتَعْجِلَةً تَلُوثُ خِمَارَهَا حَتَّى لَقِيَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا لَكِ يَا أُمَّ سُلَيْمٍ". فَقَالَتْ: يَا نَبِيَّ اللهِ أَدَعَوْتَ عَلَى يَتِيمَتِي؟ قَالَ: "وَمَا ذَاكِ يَا أُمَّ سُلَيْمٍ" فَقَالَتْ: زَعَمَتْ أَنَّكَ دَعَوْتَ أَنْ لَا يَكْبَرَ سِنُّهَا، وَلَا يَكْبَرَ قَرْنُهَا. قَالَتْ: فَضَحِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: "يَا أُمَّ سُلَيْمٍ، أَمَا تَعْلَمِينَ أَنَّ شَرْطِي عَلَى رَبِّي؟ أَنِّي اشْتَرَطْتُ عَلَى رَبِّي فَقُلْتُ: إِنَّمَا أَنَا بَشَرٌ أَرْضَى كَمَا يَرْضَى الْبَشَرُ، وَأَغْضَبُ كَمَا يَغْضَبُ الْبَشَرُ، فَأَيُّمَا أَحَدٍ دَعَوْتُ عَلَيْهِ مِنْ أُمَّتِي بِدَعْوَةٍ – لَيْسَ لَهَا بِأَهْلٍ – أَنْ يَجْعَلَهَا لَهُ طَهُورًا وَزَكَاةً، وَقُرْبَةً يُقَرِّبُهُ بِهَا مِنْهُ يَوْمَ الْقِيَامَةِ". (م)', 'അനസുബ്നു മാലിക്(റ): ഉമ്മുസുലൈം(റ)യുടെ കൂടെ ഒരു അനാഥ ബാലികയുണ്ടായിരുന്നു. ഉമ്മു അനസ്(റ)യാണവൾ. അങ്ങനെ അല്ലാഹുവിന്റെ റസൂൽ(സ) ആ അനാഥയെ കണ്ടു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "നീയാണോ അത്? തീർച്ചയായും നീ വലുതായിരിക്കുന്നു, പക്ഷേ നിന്റെ പ്രായം കൂടാതിരിക്കട്ടെ." അപ്പോൾ അനാഥബാലിക കരഞ്ഞുകൊണ്ട് ഉമ്മുസുലൈം(റ)യുടെ അരികിൽ വന്നു. ഉമ്മുസുലൈം(റ) ചോദിച്ചു: പൊന്നുമോളേ, നിനക്ക് എന്തുപറ്റി? അവൾ പറഞ്ഞു: നബി(സ) എനിക്കെതിരെ എന്റെ പ്രായം കൂടാതിരിക്കട്ടെ, എന്ന് പ്രാർത്ഥിച്ചിരിക്കുന്നു. അതുകൊണ്ട് ഇനി ഒരിക്കലും എന്റെ പ്രായം വളരുകയില്ല. (അല്ലെങ്കിൽ: അവൾ പറഞ്ഞത് എന്റെ കാലം എന്നാണ്.) ഉടനെ ഉമ്മുസുലൈം(റ) തന്റെ മുഖമക്കനയും വലിച്ചുകൊണ്ട് പ്രവാചകസന്നിധിയിലേക്ക് ധൃതിയിൽ പുറപ്പെട്ടു. അവർ തിരുമേനി(സ)യെ കണ്ടുമുട്ടി. തിരുമേനി(സ) അവരോട് ചോദിച്ചു: "ഉമ്മുസുലൈം, നിനക്കെന്തുപറ്റി?" മഹതി പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് എന്റെ അനാഥബാലികക്കെതിരിൽ പ്രാർത്ഥിച്ചിരുന്നോ? അപ്പോൾ തിരുമേനി(സ) പ്രതിവചിച്ചു: "എന്ത് പ്രാർത്ഥനയാണ് ഉമ്മുസുലൈം?" അപ്പോൾ ഉമ്മുസുലൈം(റ) പറഞ്ഞു: അങ്ങ് അവളുടെ പ്രായം കൂടാതിരിക്കട്ടെ, അല്ലെങ്കിൽ കാലം കൂടാതിരിക്കട്ടെ എന്ന് പ്രാർത്ഥിച്ചു എന്ന് അവൾ പറയുന്നു. ഉമ്മു സുലൈം(റ) പറയുന്നു: അപ്പോൾ തിരുമേനി(സ) ചിരിച്ചു. എന്നിട്ട് പറഞ്ഞു: "ഉമ്മു സുലൈം, ഞാൻ എന്റെ നാഥനോട് കരാറിലേർപ്പെട്ടത് നിനക്കറിയില്ലേ? ഞാൻ പറഞ്ഞു: ഞാൻ ഒരു മനുഷ്യൻ മാത്രമാണ്. മനുഷ്യർ ഇഷ്ടപ്പെടുന്നത് പോലെ ഞാനും ഇഷ്ടപ്പെടുന്നു. മനുഷ്യൻ ദേഷ്യം പിടിക്കുന്നതു പോലെ ഞാനും ദേഷ്യം പിടിക്കുന്നു. അതുകൊണ്ട് ഞാൻ എന്റെ ഉമ്മതിൽ പെട്ട ആർക്കെങ്കിലും എതിരായി, അവർ ഉത്തരവാദികളാകാത്തതിൽ പ്രാർത്ഥിച്ചാൽ അതിനെ അവർക്ക് ആത്മസംസ്കരണവും ധർമ്മവും അന്ത്യനാളിൽ അല്ലാഹുവിനോട് അടുക്കുവാനുള്ള സാമീപ്യവുമാക്കാൻ വേണ്ടിയാണ്." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 805, 805, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنْتُ أَلْعَبُ مَعَ الصِّبْيَانِ، فَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَتَوَارَيْتُ خَلْفَ بَابٍ، قَالَ: فَجَاءَ فَحَطَأَنِي حَطْأَةً، وَقَالَ: "اذْهَبْ وَادْعُ لِي مُعَاوِيَةَ". قَالَ: فَجِئْتُ فَقُلْتُ: هُوَ يَأْكُلُ. قَالَ: ثُمَّ قَالَ لِي: "اذْهَبْ فَادْعُ لِي مُعَاوِيَةَ". قَالَ: فَجِئْتُ فَقُلْتُ: هُوَ يَأْكُلُ. فَقَالَ: "لَا أَشْبَعَ اللهُ بَطْنَهُ". قَالَ ابْنُ الْمُثَنَّى: قُلْتُ لِأُمَيَّةَ: مَا (حَطَأَنِي)؟ قَالَ: قَفَدَنِي قَفْدَةً. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാൻ കുട്ടികളോടൊത്ത് കളിച്ചു കൊണ്ടിരിക്കെ അല്ലാഹുവിന്റെ റസൂൽ(സ) കടന്നു വന്നു. അപ്പോൾ ഞാൻ വാതിലിനു പിന്നിൽ മറഞ്ഞ് നിന്നു. അദ്ദേഹം പറയുന്നു: അവിടന്ന് എന്റെയടുത്തേക്ക് വന്ന് കൈ പരത്തിപ്പിടിച്ച് എന്റെ പിരടിയിൽ അടിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "നീ പോയി എനിക്ക് വേണ്ടി മആവിയ(റ)യെ വിളിക്കുക." നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞാൻ തിരിച്ചുവന്ന് ഇപ്രകാരം പറഞ്ഞു: അദ്ദേഹം ഭക്ഷണം കഴിക്കുകയാണ്. നിവേദകൻ പറയുന്നു: പിന്നീട് അവിടന്ന് എന്നോട് പറഞ്ഞു: "നീ പോയി എനിക്ക് വേണ്ടി മുആവിയയെ വിളിക്കുക." നിവേദകൻ പറയുന്നു: അപ്പോൾ ഞാൻ വന്ന് ഇപ്രകാരം പറഞ്ഞു: അദ്ദേഹം ഭക്ഷണം കഴിക്കുകയാണ്. അവിടന്ന് പറഞ്ഞു: "അല്ലാഹു അദ്ദേഹത്തിന്റെ വയർ നിറക്കാതിരിക്കട്ടെ." ഇബ്നുൽ മുസന്ന(റ) പറയുന്നു: ഞാൻ ഉമയ്യ(റ)യോട് ചോദിച്ചു: ''ഹത്വഅനീ'' എന്ന് പറഞ്ഞാൽ എന്താണ്? അദ്ദേഹം പറഞ്ഞു: ''കൈ പരത്തി എന്റെ പിരടിക്കടിച്ചു'' എന്നാണ്. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 805, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَكُونُ الْمُؤْمِنُ لَعَّانًا". حَسَنٌ. (ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുഅ്മിൻ ആക്ഷേപിക്കുന്നവനാവുകയില്ല." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 806, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنْ سَمُرَةَ بْنِ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَلَاعَنُوا بِلَعْنَةِ اللهِ، وَلَا بِغَضَبِهِ، وَلَا بِالنَّارِ". حَسَنٌ صَحِيحٌ. (د،ت)', 'സമുറതുബ്നു ജുൻദുബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ ആക്ഷേപം, അവന്റെ ദേഷ്യം, അവന്റെ നരകം എന്നിവ കൊണ്ട് നിങ്ങൾ പരസ്പരം ആക്ഷേപിക്കരുത്." (ദ,തു)', 'سَمُرَةَ بْنِ جُنْدَبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 806, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ الْمُؤْمِنُ بِالطَّعَّانِ وَلَا اللَّعَّانِ وَلَا الْفَاحِشِ وَلَا الْبَذِيءِ". حَسَنٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "മുഅ്മിൻ പതിവായി കുറ്റം പറയുന്നവനോ ആക്ഷേപിക്കുന്നവനോ ചീത്ത പറയുന്നവനോ അസഭ്യം സംസാരിക്കുന്നവനോ അല്ല." (തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 806, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْعَبْدَ إِذَا لَعَنَ شَيْئًا صَعِدَتِ اللَّعْنَةُ إِلَى السَّمَاءِ، فَتُغْلَقُ أَبْوَابُ السَّمَاءِ دُونَهَا، ثُمَّ تَهْبِطُ إِلَى الْأَرْضِ فَتُغْلَقُ أَبْوَابُهَا دُونَهَا، ثُمَّ تَأْخُذُ يَمِينًا وَشِمَالًا، فَإِذَا لَمْ تَجِدْ مَسَاغًا رَجَعَتْ إِلَى الَّذِي لُعِنَ، فَإِنْ كَانَ لِذَلِكَ أَهْلًا، وَإِلَّا رَجَعَتْ إِلَى قَائِلِهَا". (د)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം അടിമ വല്ല വസ്തുവിനെയും ആക്ഷേപിച്ചാൽ ആ ആക്ഷേപം ആകാശത്തിലേക്കുയരും. അപ്പോൾ അതിനു മുന്നിൽ ആകാശത്തിന്റെ വാതായനങ്ങൾ അടക്കപ്പെടും. പിന്നീടത് ഭൂമിയിലേക്കിറങ്ങി വരും. അപ്പോൾ അതിന്റെ മുന്നിൽ ഭൂമിയുടെ കവാടങ്ങൾ അടക്കപ്പെടും. പിന്നെയത് ഇടത്തോട്ടും വലത്തേക്കും പോകും. അങ്ങനെ എവിടെയും ഒരു പ്രവേശന സ്ഥലവും കണ്ടെത്തിയില്ലെങ്കിലത് ആക്ഷേപിക്കപ്പെട്ടവനിലേക്ക് മടങ്ങും, അവൻ ആക്ഷേപത്തിന് അർഹനാണെങ്കിൽ (അവനിൽ പ്രവേശിക്കും). ഇനി അവനതിന് അർഹനല്ലെങ്കിൽ ആക്ഷേപിച്ചവനിലേക്ക് അത് മടങ്ങും." (ദ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 806, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا لَعَنَ الرِّيحَ، وَفِي رِوَايَةٍ: إِنَّ رَجُلًا نَازَعَتْهُ الرِّيحُ رِدَاءَهُ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَعَنَهَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَلْعَنْهَا فَإِنَّهَا مَأْمُورَةٌ، وَإِنَّهُ مَنْ لَعَنَ شَيْئًا لَيْسَ لَهُ بِأَهْلٍ رَجَعَتِ اللَّعْنَةُ عَلَيْهِ". (د،ت)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ കാറ്റിനെ ആക്ഷേപിച്ചു. മറ്റൊരു നിവേദത്തിൽ: നബി(സ)യുടെ കാലത്ത് ഒരാളുടെ വസ്ത്രം പിടിച്ചു വലിച്ച് കൊണ്ടു കാറ്റ് അയാളോട് കലഹിച്ചു. അയാളതിനെ ആക്ഷേപിച്ചു. അപ്പോൾ തിരുനബി(സ) പറഞ്ഞു: "നീയതിനെ ആക്ഷേപിക്കരുത്. കാരണം അത് കൽപിക്കപ്പെട്ടതാണ്. നിശ്ചയം ആക്ഷേപാർഹമില്ലാത്ത വല്ലതിനെയും ആരെങ്കിലും ആക്ഷേപിച്ചാൽ ആ ആക്ഷേപം അവന്റെ മേൽ തന്നെ മടങ്ങും." (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 806, 807, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=250), 1, 'وَفِي رِوَايَةٍ: إِنَّ رَجُلًا نَازَعَتْهُ الرِّيحُ رِدَاءَهُ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَعَنَهَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَلْعَنْهَا فَإِنَّهَا مَأْمُورَةٌ، وَإِنَّهُ مَنْ لَعَنَ شَيْئًا لَيْسَ لَهُ بِأَهْلٍ رَجَعَتِ اللَّعْنَةُ عَلَيْهِ". (د،ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ اللَّعَّانِينَ لَا يَكُونُونَ شُهَدَاءَ وَلَا شُفَعَاءَ يَوْمَ الْقِيَامَةِ". (م)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "നിശ്ചയം ആക്ഷേപകർ അന്ത്യനാളിൽ ശിപാർശകരോ സാക്ഷികളോ ആവുകയില്ല." (മു)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 807, 807, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قِيلَ: يَا رَسُولَ اللهِ، ادْعُ عَلَى الْمُشْرِكِينَ. قَالَ: "إِنِّي لَمْ أُبْعَثْ لَعَّانًا، وَإِنَّمَا بُعِثْتُ رَحْمَةً". (م)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് ബഹുദൈവാരാധകർക്കെതിരെ പ്രാർത്ഥിച്ചാലും എന്ന് പറയപ്പെട്ടു. അവിടന്ന് പറഞ്ഞു: "നിശ്ചയം ആക്ഷേപിക്കുന്നവനായി ഞാൻ അയക്കപ്പെട്ടിട്ടില്ല. തീർച്ചയായും ഞാൻ അയക്കപ്പെട്ടത് അനുഗ്രഹമായാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 807, 807, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ، أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَرْمِي رَجُلٌ رَجُلًا بِالْفُسُوقِ، وَلَا يَرْمِيهِ بِالْكُفْرِ إِلَّا ارْتَدَّتْ عَلَيْهِ إِنْ لَمْ يَكُنْ صَاحِبُهُ كَذَلِكَ. (خ)', 'അബൂദർറ്(റ): നബി(സ) പറയുന്നതായി അദ്ദേഹം കേട്ടു: "ആരോപിക്കപ്പെട്ടവൻ ആരോപിക്കപ്പെട്ടതു പോലെയല്ലെങ്കിൽ ആ ആരോപണം ആക്ഷേപിച്ചവനിലേക്ക് തന്നെ മടങ്ങിയിട്ടല്ലാതെ, ഒരാളും ഒരാളെയും തെമ്മാടിത്തം കൊണ്ടോ സത്യ നിഷേധം കൊണ്ടോ ആരോപിക്കുകയില്ല." (ബു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 807, 807, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنْ ثَابِتِ بْنِ الضَّحَّاكِ رَضِيَ اللهُ عَنْهُ وَكَانَ مِنْ أَصْحَابِ الشَّجَرَةِ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَلَفَ عَلَى مِلَّةٍ غَيْرِ الْإِسْلَامِ فَهُوَ كَمَا قَالَ، وَلَيْسَ عَلَى ابْنِ آدَمَ نَذْرٌ فِيمَا لَا يَمْلِكُ، وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ فِي الدُّنْيَا عُذِّبَ بِهِ يَوْمَ الْقِيَامَةِ وَمَنْ لَعَنَ مُؤْمِنًا فَهُوَ كَقَتْلِهِ وَمَنْ قَذَفَ مُؤْمِنًا بِكُفْرٍ فَهُوَ كَقَتْلِهِ". (خ)', 'സാബിതുബ്നു ളഹ്ഹാക്(റ), ''അസ്ഹാബുശ്ശജറ''യിൽപ്പെട്ട ആളാണ് അദ്ദേഹം: അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "ഇസ്ലാമല്ലാത്ത ഏതെങ്കിലുമൊരു മതത്തിന്റെ മേൽ ആരെങ്കിലും സത്യം ചെയ്താൽ അവൻ പറഞ്ഞത് പോലെത്തന്നെയാണവൻ. ഉടമാവകാശമില്ലാത്തതിൽ നേർച്ച ചെയ്യൽ ആദം സന്തതിക്ക് അനുവദനീയമല്ല. ദുൻയാവിൽ വെച്ച് വല്ല വസ്തുവും ഉപയോഗിച്ച് ആരെങ്കിലും ആത്മഹത്യ ചെയ്താൽ ആന്ത്യനാളിൽ അത്കൊണ്ട് തന്നെ അവൻ ശിക്ഷിക്കപ്പെടും. ആരെങ്കിലും ഒരു മുഅ്മിനിനെ ആക്ഷേപിച്ചാൽ അവൻ അദ്ദേഹത്തെ കൊല്ലുന്നത് പോലെയാണ്. ആരെങ്കിലും ഒരു മുഅ്മിനിനെ സത്യനിഷേധം കൊണ്ട് ആരോപിച്ചാൽ അവൻ അദ്ദേഹത്തെ കൊല്ലുന്നത് പോലെയാണ്." (ബു)', 'ثَابِتِ بْنِ الضَّحَّاكِ', 'സാബിതുബ്നു ളഹ്ഹാക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 807, 807, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ، وَامْرَأَةٌ مِنَ الْأَنْصَارِ عَلَى نَاقَةٍ، فَضَجِرَتْ، فَلَعَنَتْهَا، فَسَمِعَ ذَلِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "خُذُوا مَا عَلَيْهَا وَدَعُوهَا، فَإِنَّهَا مَلْعُونَةٌ". قَالَ عِمْرَانُ: فَكَأَنِّي أَرَاهَا الْآنَ تَمْشِي فِي النَّاسِ مَا يَعْرِضُ لَهَا أَحَدٌ. (م)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) ഒരു യാത്രയിലായിരിക്കെ, ഒരു അൻസാരിസ്ത്രീ ഒട്ടകപ്പുറത്ത് യാത്ര ചെയ്യുകയായിരുന്നു. അപ്പോൾ ആ ഒട്ടകം മുഷിപ്പുള്ളതായി, ആ സ്ത്രീ അതിനെ ആക്ഷേപിച്ചു. അല്ലാഹുവിന്റെ റസൂൽ(സ) അത് കേട്ടു. അവിടന്ന് പറഞ്ഞു: "ആ ഒട്ടകത്തിന്റെ പുറത്തുള്ളത് എടുത്ത് നിങ്ങളതിനെ വിട്ടയക്കുക, കാരണം തീർച്ചയായുമത് ആക്ഷേപിക്കപ്പെട്ടതാണ്." ഇംറാൻ(റ) പറയുന്നു: ആരാലും ശ്രദ്ധിക്കപ്പെടാതെ ജനങ്ങൾക്കിടയിലത് നടക്കുന്നത് ഞാനിപ്പോഴും കാണുന്നത് പോലെയുണ്ട്. (മു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 807, 808, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُسْتَبَّانِ: مَا قَالَ فَعَلَى الْبَادِي مِنْهُمَا، مَا لَمْ يَعْتَدِ الْمَظْلُومُ". حَسَنٌ صَحِيحٌ. (م،د،ت)', 'അബൂഹുറൈറ(റ): നിശ്ചയം അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "പരസ്പരം ചീത്ത പറയുന്ന രണ്ടാളുകൾ: ചീത്തപറയപ്പെട്ടവൻ അതിർ കടന്നിട്ടില്ലെങ്കിൽ അവർ രണ്ട് പേരും പറഞ്ഞത് (മുഴുവൻ) തുടങ്ങിയവന്റെ മേലിലാണ്." (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 808, 808, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "سِبَابُ الْمُسْلِمِ فُسُوقٌ، وَقِتَالُهُ كُفْرٌ". حَسَنٌ صَحِيحٌ. (ق،ت،ن،جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിമിനെ ചീത്ത പറയൽ തെമ്മാടിത്തമാണ്, അവനോട് യുദ്ധം ചെയ്യൽ സത്യ നിഷേധവുമാണ്." (ബു,മു,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 808, 808, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَسُبُّوا الرِّيحَ، فَإِنَّهَا مِنْ رَوْحِ اللهِ، تَأْتِي بِالرَّحْمَةِ وَالْعَذَابِ، وَلَكِنْ سَلُوا اللهَ مِنْ خَيْرِهَا، وَتَعَوَّذُوا بِاللهِ مِنْ شَرِّهَا". (د،جه)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ കാറ്റിനെ ചീത്ത പറയരുത്, കാരണമത് അല്ലാഹുവിന്റെ അനുഗ്രഹത്തിൽ പെട്ടതാണ്. അനുഗ്രഹത്തെയും ശിക്ഷയെയും അത് കൊണ്ടുവരും. പക്ഷേ, നിങ്ങൾ അല്ലാഹുവിനോട് അതിന്റെ നന്മയെ ചോദിക്കുക, അതിന്റെ തിന്മയിൽ നിന്ന് നിങ്ങൾ അല്ലാഹുവിനോട് കാവൽ തേടുകയും ചെയ്യുക." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 808, 808, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا مَاتَ صَاحِبُكُمْ فَدَعُوهُ وَلَا تَقَعُوا فِيهِ". (د)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ കൂട്ടുകാരൻ മരിച്ചാൽ നിങ്ങളവനെ വെറുതെ വിടുക, അവനെ നിങ്ങൾ ശകാരിക്കരുത്." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 808, 809, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اذْكُرُوا مَحَاسِنَ مَوْتَاكُمْ، وَكُفُّوا عَنْ مَسَاوِيهِمْ". (ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ നിന്ന് മരിച്ചവരുടെ നന്മകൾ നിങ്ങൾ സ്മരിക്കുക, അവരുടെ തിന്മകൾ (സ്മരിക്കുന്നവന്) നിങ്ങൾ നിർത്തിവെക്കുക." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 809, 809, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَسُبُّوا الْأَمْوَاتَ فَتُؤْذُوا الْأَحْيَاءَ". (ت)', 'മുഗീറതുബ്നു ശുഅ്ബ(റ): റസൂൽ(സ) പറഞ്ഞു: "മരിച്ചവരെ നിങ്ങൾ ചീത്ത പറയരുത്. കാരണം അപ്പോൾ നിങ്ങൾ ബുദ്ധിമുട്ടിക്കുന്നത് ജീവിച്ചിരിക്കുന്നവരെത്തന്നെയാണ്." (തു)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 809, 809, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَالَ اللهُ عَزَّ وَجَلَّ: يُؤْذِينِي ابْنُ آدَمَ يَقُولُ: يَا خَيْبَةَ الدَّهْرِ. فَلَا يَقُولَنَّ أَحَدُكُمْ يَا خَيْبَةَ الدَّهْرِ، فَإِنِّي أَنَا الدَّهْرُ، أُقَلِّبُ لَيْلَهُ وَنَهَارَهُ فَإِذَا شِئْتُ قَبَضْتُهُمَا". (ق،د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു പറയുന്നു: കാലത്തിന്റെ പരാജയമേ, എന്ന് പറഞ്ഞ് മനുഷ്യൻ എന്നെ ബുദ്ധിമുട്ടിക്കുന്നു. അത് കൊണ്ട് നിങ്ങളാരും തന്നെ ''കാലത്തിന്റെ പരാജയമേ'' എന്ന് പറയരുത്. കാരണം, നിശ്ചയം ഞാനാണ് കാലം. അതിന്റെ രാപ്പകലുകളെ മാറ്റിമറിക്കുന്നവൻ ഞാനാണ്. ഞാനുദ്ദേശിക്കുകയാണെങ്കിൽ അവയെ പിടിച്ച് വെക്കുകയും ചെയ്യും." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 809, 809, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَقُولُ اللهُ عَزَّ وَجَلَّ: يُؤْذِينِي ابْنُ آدَمَ: يَسُبُّ الدَّهْرَ، وَأَنَا الدَّهْرُ، بِيَدِي الْأَمْرُ، أُقَلِّبُ اللَّيْلَ وَالنَّهَارَ". (ق،د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു പറയുന്നു: കാലത്തെ കുറ്റം പറഞ്ഞ് മനുഷ്യൻ എന്നെ ബുദ്ധിമുട്ടിക്കുന്നു. ഞാനാണ് കാലം, കാര്യങ്ങൾ മുഴുവൻ എന്റെ കയ്യിലാണ്, രാപ്പകലുകളെ ഞാൻ മാറ്റി മറിക്കും." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 809, 809, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَسُبُّوا الدَّهْرَ، فَإِنَّ اللهَ هُوَ الدَّهْرُ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ കാലത്തെ കുറ്റം പറയരുത്. കാരണം തീർച്ചയായും അല്ലാഹുവാണ് കാലം." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 809, 809, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَلَكَ الْمُتَنَطِّعُونَ". قَالَهَا ثَلَاثًا. (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "സംസാരത്തിലും പ്രവർത്തനത്തിലും അതിർ കവിയുന്നവർ നശിച്ചിരിക്കുന്നു." അവിടന്ന് ഇത് മൂന്ന് പ്രാവശ്യം പറഞ്ഞു. (മു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 809, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا أُنَبِّئُكُمْ مَا الْعَضْهُ؟ هِيَ النَّمِيمَةُ الْقَالَةُ بَيْنَ النَّاسِ". وَإِنَّ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الرَّجُلَ يَصْدُقُ حَتَّى يُكْتَبَ صِدِّيقًا، وَيَكْذِبُ حَتَّى يُكْتَبَ كَذَّابًا". (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): മുഹമ്മദ്(സ) പറഞ്ഞു: "അളഹ് എന്താണെന്ന് ഞാൻ നിങ്ങൾക്ക് അറിയിച്ച് തരട്ടെയോ? ജനങ്ങൾക്കിടയിൽ കൂടുതലായി പറയപ്പെടുന്ന പരദൂഷണമാണത്." നിശ്ചയം മുഹമ്മദ്(സ) പറഞ്ഞു: "നിശ്ചയം ഒരാൾ സത്യം പറയും, അങ്ങനെയവൻ സത്യവാനായി എഴുതപ്പെടും. അവൻ കളവ് പറയും, അങ്ങനെയവൻ കളവ് പറയുന്നവനായി എഴുതപ്പെടും." (മു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 810, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ هَمَّامِ بْنِ الْحَارِثِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا جُلُوسًا مَعَ حُذَيْفَةَ فِي الْمَسْجِدِ، فَجَاءَ رَجُلٌ حَتَّى جَلَسَ إِلَيْنَا، فَقِيلَ لِحُذَيْفَةَ: إِنَّ هَذَا يَرْفَعُ إِلَى السُّلْطَانِ أَشْيَاءَ. فَقَالَ: حُذَيْفَةُ – إِرَادَةَ أَنْ يُسْمِعَهُ –: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَدْخُلُ الْجَنَّةَ قَتَّاتٌ". (م)', 'ഹമ്മാമുബ്നുൽ ഹാരിസ്(റ): ഞങ്ങൾ ഹുദൈഫ(റ)വിനോടൊപ്പം പള്ളിയിൽ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ വന്ന് ഞങ്ങളുടെ അടുത്ത് ഇരുന്നു. അപ്പോൾ ഹുദൈഫ(റ)വിനോട് പറയപ്പെട്ടു: നിശ്ചയം ഇയാൾ സുൽത്വാനിലേക്ക് കാര്യങ്ങൾ എത്തിക്കും. അപ്പോൾ ഹുദൈഫ(റ) അയാളെ കേൾപ്പിക്കാൻ ഉദ്ദേശിച്ച് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു. "ഏഷണിക്കാരൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കില്ല." (മു)', 'هَمَّامِ بْنِ الْحَارِثِ', 'ഹമ്മാമുബ്നുൽ ഹാരിസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 810, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنْ هَمَّامِ بْنِ الْحَارِثِ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ رَجُلٌ عَلَى حُذَيْفَةَ بْنِ الْيَمَانِ رَضِيَ اللهُ عَنْهُ، فَقِيلَ لَهُ: إِنَّ هَذَا يُبَلِّغُ الْأُمَرَاءَ الْحَدِيثَ عَنِ النَّاسِ. فَقَالَ حُذَيْفَةُ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَدْخُلُ الْجَنَّةَ قَتَّاتٌ". حَسَنٌ صَحِيحٌ. (ق،د،ت)', 'ഹമ്മാമുബ്നുൽ ഹാരിസ്(റ): ഹുദൈഫതുബ്നുൽ യമാൻ(റ)വിന്റെ അരികിലൂടെ ഒരാൾ നടന്നുപോയി. അപ്പോൾ അദ്ദേഹത്തോട് പറയപ്പെട്ടു: നിശ്ചയം ഇയാൾ ജനങ്ങളെക്കുറിച്ചുള്ള വാർത്തകൾ അമീറുമാരിലേക്ക് എത്തിക്കും. അപ്പോൾ ഹുദൈഫ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഏഷണിക്കാരൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കില്ല." (ബു,മു,ദ,തു)', 'هَمَّامِ بْنِ الْحَارِثِ', 'ഹമ്മാമുബ്നുൽ ഹാരിസ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 810, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الشَّيْطَانَ قَدْ يَئِسَ أَنْ يَعْبُدَهُ الْمُصَلُّونَ، وَلَكِنْ فِي التَّحْرِيشِ بَيْنَهُمْ". حَسَنٌ (م،ت)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം പിശാച്, നിസ്കരിക്കുന്നവർ അവനെ ആരാധിക്കുന്നതിൽ ആശയറ്റിരിക്കുന്നു. എങ്കിലും അവരെ പരസ്പരം കലഹിപ്പിക്കുന്നതിൽ (അവൻ വിജയിച്ചു)" (മു,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 810, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ شَرِّ النَّاسِ عِنْدَ اللهِ يَوْمَ الْقِيَامَةِ ذُو الْوَجْهَيْنِ". حَسَنٌ صَحِيحٌ. (ق،ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഇരട്ടമുഖമുള്ളവൻ അന്ത്യനാളിൽ അല്ലാഹുവിങ്കൽ ജനങ്ങളിൽ വെച്ച് ഏറ്റവും മോശപ്പെട്ടവരിൽ പെട്ടവനാണ്." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 811, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مِنْ شَرِّ النَّاسِ ذُو الْوَجْهَيْنِ: الَّذِي يَأْتِي هَؤُلَاءِ بِوَجْهٍ وَهَؤُلَاءِ بِوَجْهٍ". (م،د)', 'അബൂഹുറൈറ(റ): നിശ്ചയം നബി(സ) പറഞ്ഞു: "ഒരു കൂട്ടം ആളുകളുടെ അടുത്ത് ഒരു മുഖവുമായും മറ്റൊരു കൂട്ടത്തിന്റെയടുക്കൽ മറ്റൊരു മുഖവുമായി വരുന്ന, ഇരട്ടമുഖമുള്ളവർ ജനങ്ങളിൽ ഏറ്റവും മോശപ്പെട്ടവരിൽ പെട്ടവരാണ്." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 811, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ عَمَّارٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ لَهُ وَجْهَانِ فِي الدُّنْيَا كَانَ لَهُ يَوْمَ الْقِيَامَةِ لِسَانَانِ مِنْ نَارٍ". (د)', 'അമ്മാർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും ദുൻയാവിൽ ഇരട്ടമുഖങ്ങളുണ്ടെങ്കിൽ അന്ത്യനാളിൽ തീയിനാലുള്ള രണ്ട് നാവുകൾ അവനുണ്ടാകും." (ദ)', 'عَمَّارٍ', 'അമ്മാർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 811, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: عَلِّمْنِي شَيْئًا، وَلَا تُكْثِرْ عَلَيَّ، لَعَلِّي أَعِيهِ. قَالَ: "لَا تَغْضَبْ". فَرَدَّدَ ذَلِكَ مِرَارًا كُلُّ ذَلِكَ يَقُولُ: "لَا تَغْضَبْ". حَسَنٌ صَحِيحٌ. (خ،ت)', 'അബൂഹുറൈറ(റ): ഒരാൾ നബി(സ)യുടെ സന്നിധിയിൽ വന്ന് പറഞ്ഞു: കൂടുതലാവാതെ, അങ്ങെനിക്ക് വല്ലതും പഠിപ്പിച്ച് തന്നാലും, ഞാനത് ശ്രദ്ധിച്ചു കേൾക്കാം. അവിടന്ന് പറഞ്ഞു: "നീ ദേഷ്യം പിടിക്കരുത്." അപ്പോൾ അദ്ദേഹമത് ആവർത്തിച്ചാവർത്തിച്ച് ചോദിക്കുകയും അപ്പോഴെല്ലാം അവിടന്ന് "നീ ദേഷ്യം പിടിക്കരുത്" എന്ന് പറയുകയും ചെയ്തു. (ബു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 811, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَوْصِنِي. قَالَ: "لَا تَغْضَبْ"، فَرَدَّدَ مِرَارًا قَالَ: "لَا تَغْضَبْ". (خ)', 'അബൂഹുറൈറ(റ): നിശ്ചയം ഒരാൾ നബി(സ)യോട് എന്നെ ഉപദേശിച്ചാലും എന്ന്പറഞ്ഞു: അവിടന്ന് പറഞ്ഞു: "നീ ദേഷ്യം പിടിക്കരുത്." അപ്പോൾ അയാൾ (ചോദ്യം) പലപ്രാവശ്യം ആവർത്തിച്ചു. അവിടന്ന് പറഞ്ഞു: "നീ ദേഷ്യം പിടിക്കരുത്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 811, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنْ سُلَيْمَانَ بْنِ صُرَدٍ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتَبَّ رَجُلَانِ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلَ أَحَدُهُمَا يَغْضَبُ وَيَحْمَرُّ وَجْهُهُ، فَنَظَرَ إِلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنِّي لَأَعْلَمُ كَلِمَةً لَوْ قَالَهَا لَذَهَبَ ذَا عَنْهُ: أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ". فَقَامَ إِلَى الرَّجُلِ رَجُلٌ مِمَّنْ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَتَدْرِي مَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ آنِفًا؟ قَالَ: "إِنِّي لَأَعْلَمُ كَلِمَةً لَوْ قَالَهَا لَذَهَبَ ذَا عَنْهُ: أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ". فَقَالَ لَهُ الرَّجُلُ: أَمَجْنُونًا تَرَانِي؟ (م)', 'സൽമാനുബ്നു സുറദ്(റ): നബി(സ)യുടെ സന്നിധിയിൽ വെച്ച് രണ്ടാളുകൾ പരസ്പരം ചീത്ത പറഞ്ഞു: "അവരിലൊരാൾക്ക് ദേഷ്യം വരാനും അയാളുടെ മുഖം ചുവക്കാനും തുടങ്ങി. അപ്പോൾ നബി(സ) അയാളെ നോക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "നിശ്ചയം എനിക്കൊരു വാക്യമറിയാം അയാളെങ്ങാനും അത് ഉരുവിടുകയാണെങ്കിൽ അയാളിൽ നിന്നിത് (ദേഷ്യം) പോകും: "ശപിക്കപ്പെട്ട പിശാചിൽ നിന്ന് അല്ലാഹുവിനോട് ഞാൻ കാവൽ തേടുന്നു." അപ്പോൾ, നബി(സ) പറയുന്നത് കേട്ട ഒരാൾ ഇയാളുടെ അടുക്കലേക്ക് എണീറ്റ് ചെന്ന് അയാളോട് ചോദിച്ചു: തൊട്ടുമുമ്പ് നബി(സ) എന്താണ് പറഞ്ഞതെന്ന് നിനക്കറിയുമോ? അവിടന്ന് പറഞ്ഞു: "നിശ്ചയം എനിക്കൊരു വാക്യമറിയാം. അയാളെങ്ങാനും അത് ഉരുവിടുകയാണെങ്കിൽ അയാളിൽ നിന്നത് പോകും. ശപിക്കപ്പെട്ട പിശാചിൽ നിന്ന് ഞാൻ അല്ലാഹുവിനോട് കാവൽ തേടുന്നു എന്നതാണത്." അപ്പോൾ അദ്ദേഹം ഇദ്ദേഹത്തോട് ചോദിച്ചു: എന്നെയൊരു ഭ്രാന്തനായിട്ടാണോ നീ കാണുന്നത്. (മു)', 'سُلَيْمَانَ بْنِ صُرَدٍ', 'സൽമാനുബ്നു സുറദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 812, 812, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتَبَّ رَجُلَانِ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَغَضِبَ أَحَدُهُمَا غَضَبًا شَدِيدًا، حَتَّى خُيِّلَ إِلَيَّ أَنَّ أَنْفَهُ يَتَمَزَّعُ مِنْ شِدَّةِ غَضَبِهِ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَأَعْلَمُ كَلِمَةً، لَوْ قَالَهَا لَذَهَبَ عَنْهُ مَا يَجِدُهُ مِنَ الْغَضَبِ". فَقَالَ: مَا هِيَ يَا رَسُولَ اللهِ؟ قَالَ: "يَقُولُ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الشَّيْطَانِ الرَّجِيمِ". قَالَ: فَجَعَلَ مُعَاذٌ يَأْمُرُهُ، فَأَبَى وَمَحِكَ، وَجَعَلَ يَزْدَادُ غَضَبًا. (د،ت)', 'മുആദുബ്നു ജബൽ(റ): നബി(സ)യുടെ സന്നിധിയിൽ വെച്ച് രണ്ടാളുകൾ പരസ്പരം ചീത്ത പറഞ്ഞു. അപ്പോൾ അവരിലൊരാൾ അങ്ങേയറ്റം കോപിഷ്ഠനായി. എത്രത്തോളമെന്നാൽ കോപാധിക്യത്താൽ അയാളുടെ മൂക്ക് വിറക്കുന്നത് പോലെ എനിക്ക് തോന്നി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിശ്ചയം എനിക്കൊരു വാക്യമറിയാം. അയാളെങ്ങാനും അത് ഉരുവിടുകയാണെങ്കിൽ, തീർച്ചയായും അയാളെ പിടികൂടിയ ഈ ദേഷ്യം അയാളെ വിട്ട് പോകുക തന്നെ ചെയ്യും." അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: അതെന്താണ് അല്ലാഹുവിന്റെ റസൂലേ? അവിടന്ന് പറഞ്ഞു: "അയാൾ പറയണം: അല്ലാഹുവേ നിന്നെക്കൊണ്ട് ഞാൻ ശപിക്കപ്പെട്ട പിശാചിൽ നിന്ന് കാവൽ തേടുന്നു." നിവദേകൻ പറയുന്നു: അപ്പോൾ മുആദ്(റ) അദ്ദേഹത്തോടിത് പറയാൻ ആവശ്യപ്പെടാൻ തുടങ്ങി. അയാളത് നിരസിക്കുകയും തർക്കിക്കുകയും ചെയ്തു. അയാളുടെ ദേഷ്യം കൂടി വരാനും തുടങ്ങി. (ദ,തു)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 812, 812, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَنَا: "إِذَا غَضِبَ أَحَدُكُمْ وَهُوَ قَائِمٌ فَلْيَجْلِسْ، فَإِنْ ذَهَبَ عَنْهُ الْغَضَبُ، وَإِلَّا فَلْيَضْطَجِعْ". (د)', 'അബൂദർറ്(റ): റസൂൽ(സ) ഞങ്ങളോട് പറഞ്ഞു: "നിൽക്കുമ്പോൾ നിങ്ങളിലാർക്കെങ്കിലും ദേഷ്യം പിടിച്ചാൽ അവൻ ഇരുന്നുകൊള്ളട്ടെ, അപ്പോൾ ദേഷ്യം അവനെ വിട്ട് പോയാൽ (അത് മതി) ഇല്ലെങ്കിൽ അവൻ കിടന്ന് കൊള്ളട്ടെ." (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 812, 812, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنْ عَطِيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْغَضَبَ مِنَ الشَّيْطَانِ، وَإِنَّ الشَّيْطَانَ خُلِقَ مِنَ النَّارِ، وَإِنَّمَا تُطْفَأُ النَّارُ بِالْمَاءِ، فَإِذَا غَضِبَ أَحَدُكُمْ فَلْيَتَوَضَّأْ". (د)', 'അതിയ്യ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ദേഷ്യം പിശാചിൽ നിന്നുള്ളതാണ്. നിശ്ചയം പിശാച് തീയിൽ നിന്നാണ് സൃഷ്ടിക്കപ്പെട്ടത്. തീ അണക്കപ്പെടേണ്ടത് വെള്ളം കൊണ്ടാണ്. അതുകൊണ്ട് നിങ്ങളിലാർക്കെങ്കിലും ദേഷ്യം പിടിച്ചാൽ അവൻ വുളൂ ചെയ്ത് കൊള്ളട്ടെ." (ദ)', 'عَطِيَّةَ', 'അതിയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 813, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا تَعُدُّونَ الرَّقُوبَ فِيكُمْ". قَالَ: قُلْنَا: الَّذِي لَا يُولَدُ لَهُ. قَالَ: "لَيْسَ ذَاكَ بِالرَّقُوبِ، وَلَكِنَّهُ الرَّجُلُ الَّذِي لَمْ يُقَدِّمْ مِنْ وَلَدِهِ شَيْئًا". قَالَ: "فَمَا تَعُدُّونَ الصُّرَعَةَ فِيكُمْ". قَالَ: قُلْنَا: الَّذِي لَا يَصْرَعُهُ الرِّجَالُ. قَالَ: "لَيْسَ بِذَلِكَ، وَلَكِنَّهُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ". (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) ചോദിച്ചു: "ആരെയാണ് നിങ്ങൾ ''റഖൂബ്'' ആയി കണക്കാക്കുന്നത്." നിവേദകൻ പറയുന്നു: ഞങ്ങൾ പറഞ്ഞു: കുട്ടികളില്ലാത്തവനെ. തിരുമേനി(സ) പറഞ്ഞു: "അവനല്ല റഖൂബ്, മക്കളിൽ ആരും തനിക്കുമുമ്പേ (മരിച്ചു) പോകാത്തവനാണ് റഖൂബ്." പിന്നീട് തിരുമേനി(സ) ചോദിച്ചു: "ആരെയാണ് നിങ്ങൾ ശക്തനായി കണക്കാക്കുന്നത്." നിവേദകൻ പറയുന്നു: ഞങ്ങൾ പറഞ്ഞു: മറ്റുള്ളവർക്ക് ഇടിച്ച്വീഴ്ത്താൻ സാധിക്കാത്തവൻ. തിരുമേനി(സ) പറഞ്ഞു: "അവനല്ല ശക്തൻ, മറിച്ച് ദേഷ്യം വരുമ്പോൾ സ്വന്തത്തെ ഒതുക്കിനിർത്തുന്നവനാണ് ശക്തൻ." (മു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 813, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ദ്വന്ദയുദ്ധത്തിൽ ജയിക്കുന്നവനല്ല ശക്തൻ. നിശ്ചയം ദേഷ്യം വരുമ്പോൾ സ്വന്തത്തെ പിടിച്ച്നിർത്തുന്നവനാണ് ശക്തൻ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 813, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنْ مُعَاذٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَظَمَ غَيْظًا، وَهُوَ قَادِرٌ عَلَى أَنْ يُنْفِذَهُ، دَعَاهُ اللهُ عَزَّ وَجَلَّ عَلَى رُءُوسِ الْخَلَائِقِ يَوْمَ الْقِيَامَةِ، حَتَّى يُخَيِّرَهُ اللهُ مِنَ الْحُورِ الْعِينِ مَا يَشَاءُ". (د،ت،جه)', 'മുആദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ദേഷ്യത്തെ, അത് നടപ്പാക്കാൻ കഴിവുണ്ടായിരിക്കെത്തന്നെ കടിച്ചിറക്കിയാൽ, അന്ത്യനാളിൽ അല്ലാഹു അവനെ ജനസമക്ഷം വിളിക്കുകയും ഹൂറുൽ ഈനുകളിൽ നിന്ന് അവനുദ്ദേശിച്ചത് അവനെക്കൊണ്ട് തെരഞ്ഞെടുപ്പിക്കുകയും ചെയ്യും." (ദ,തു,ജ)', 'مُعَاذٍ', 'മുആദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 813, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنْ سُوَيْدِ بْنِ وَهْبٍ رَضِيَ اللهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: نَحْوَهُ، قَالَ: "مَلَأَهُ اللهُ أَمْنًا وَإِيمَانًا". لَمْ يَذْكُرْ قِصَّةَ "دَعَاهُ اللهُ". زَادَ: "وَمَنْ تَرَكَ لُبْسَ ثَوْبِ جَمَالٍ وَهُوَ يَقْدِرُ عَلَيْهِ – تَوَاضُعًا – كَسَاهُ اللهُ حُلَّةَ الْكَرَامَةِ، وَمَنْ زَوَّجَ لِلَّهِ تَعَالَى تَوَّجَهُ اللهُ تَاجَ الْمُلْكِ". (د)', 'സുവൈദുബ്നു വഹ്ബ്(റ): നബി(സ) മേൽ പറഞ്ഞപോലെത്തന്നെയുള്ള ഒരു ഹദീസ് പറഞ്ഞു. എന്നിട്ടവിടുന്ന് "അല്ലാഹു അദ്ദേഹത്തിന് നിർഭയത്വവും ഈമാനും നിറക്കും." എന്ന് പറഞ്ഞു. എന്നാൽ "അല്ലാഹു അദ്ദേഹത്തെ വിളിക്കും" എന്ന് പരാമർശിച്ചിട്ടില്ല. അദ്ദേഹം കൂടുതലായി പറഞ്ഞതിതാണ്: "ഭംഗിയുള്ള വസ്ത്രം ധരിക്കാൻ കഴിയുമായിരുന്നിട്ടും താഴ്മ കാരണം അത് ഉപേക്ഷിച്ചവന്ന് അല്ലാഹു മാന്യതയുടെ വസ്ത്രം ധരിപ്പിക്കും. ആരെങ്കിലും അല്ലാഹുവിന് വേണ്ടി വിവാഹം കഴിച്ചാൽ അധികാരത്തിന്റെ കിരീടം അല്ലാഹു അവന് ധരിപ്പിക്കും." (ദ)', 'سُوَيْدِ بْنِ وَهْبٍ', 'സുവൈദുബ്നു വഹ്ബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 813, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّكَ إِنِ اتَّبَعْتَ عَوْرَاتِ النَّاسِ أَفْسَدْتَهُمْ، أَوْ: كِدْتَ أَنْ تُفْسِدَهُمْ". فَقَالَ أَبُو الدَّرْدَاءِ: كَلِمَةٌ سَمِعَهَا مُعَاوِيَةُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَفَعَهُ اللهُ تَعَالَى بِهَا. (د)', 'മുആവിയ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം നീ ജനങ്ങളുടെ ന്യൂനതകൾ ചികഞ്ഞന്വേഷിക്കുകയാണെങ്കിൽ നീയവരെ നശിപ്പിക്കുകയാണ് ചെയ്യുന്നത്. അല്ലെങ്കിൽ നീയവരെ നശിപ്പിക്കാനടുത്തിരിക്കുന്നു." അപ്പോൾ അബുദ്ദർദാഅ്(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂൽ(സ)യിൽ നിന്ന് മുആവിയ(റ) കേട്ട വചനത്തെ അല്ലാഹു അദ്ദേഹത്തിന് ഉപകാരപ്രദമാക്കിയിരിക്കുന്നു. (ദ)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 814, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ جُبَيْرِ بْنِ نُفَيْرٍ وَكَثِيرِ بْنِ مُرَّةَ وَعَمْرِو بْنِ الْأَسْوَدِ وَالْمِقْدَامِ بْنِ مَعْدِي كَرِبَ وَأَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُمْ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْأَمِيرَ إِذَا ابْتَغَى الرِّيبَةَ فِي النَّاسِ أَفْسَدَهُمْ". (د)', 'ജുബൈറുബ്നു നുഫൈൽ, കസീറുബ്നു മുർറ, അംറുബ്നു അസ്വദ്, മിഖ്ദാമുബ്നു മഅ്ദീ കരിബ, അബൂ ഉമാമ(റ) എന്നിവർ നബി(സ)യിൽ നിന്ന് ഉദ്ധരിക്കുന്നു: നബി(സ) പറഞ്ഞു: "നിശ്ചയം, നേതാവ് ജനങ്ങളിലുള്ള സംശയങ്ങളെ (അറിയാനായി) ആവശ്യപ്പെട്ടാൽ അയാളവരെ നശിപ്പിച്ചിരിക്കുന്നു." (ദ)', 'جُبَيْرِ بْنِ نُفَيْرٍ وَكَثِيرِ بْنِ مُرَّةَ وَعَمْرِو بْنِ الْأَسْوَدِ وَالْمِقْدَامِ بْنِ مَعْدِي كَرِبَ وَأَبِي أُمَامَةَ', null, null, null, array['د']::text[], array['ദ']::text[], null, null, 814, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ زَيْدِ بْنِ وَهْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ ابْنُ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ فَقِيلَ: هَذَا فُلَانٌ تَقْطُرُ لِحْيَتُهُ خَمْرًا، فَقَالَ عَبْدُ اللهِ: إِنَّا قَدْ نُهِينَا عَنِ التَّجَسُّسِ، وَلَكِنْ إِنْ يَظْهَرْ لَنَا شَيْءٌ نَأْخُذْ بِهِ. (د)', 'സൈദുബ്നു വഹ്ബ്(റ): ഇബ്നു മസ്ഊദ്(റ)വിന്റെ അടുക്കൽ ഒരാളെ കൊണ്ട് വരികയും ഇപ്രകാരം പറയപ്പെടുകയും ചെയ്തു: താടിയിലൂടെ കള്ള് ഇറ്റുവീഴുന്നവനാണിവൻ. അപ്പോൾ അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) പറഞ്ഞു: ചാര വൃത്തിയെത്തൊട്ട് നാം വിലക്കപ്പെട്ടിരിക്കുന്നു. പക്ഷേ, നമുക്ക് വ്യക്തമായത് കൊണ്ട് നാം പിടിക്കും. (ദ)', 'زَيْدِ بْنِ وَهْبٍ', 'സൈദുബ്നു വഹ്ബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 814, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنْ أَبِي بَرْزَةَ الْأَسْلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا مَعْشَرَ مَنْ آمَنَ بِلِسَانِهِ وَلَمْ يَدْخُلِ الْإِيمَانُ قَلْبَهُ، لَا تَغْتَابُوا الْمُسْلِمِينَ، وَلَا تَتَّبِعُوا عَوْرَاتِهِمْ، فَإِنَّهُ مَنِ اتَّبَعَ عَوْرَاتِهِمْ يَتَّبِعِ اللهُ عَوْرَتَهُ، وَمَنْ يَتَّبِعِ اللهُ عَوْرَتَهُ يَفْضَحْهُ فِي بَيْتِهِ". (د)', 'അബൂബർസതുൽ അസ്ലമീ(റ): റസൂൽ(സ) പറഞ്ഞു: "വിശ്വാസം ഹൃദയത്തിലേക്കിറങ്ങാതെ, നാവ് കൊണ്ട് മാത്രം വിശ്വസിച്ച സമൂഹമേ, നിങ്ങൾ മുസ്ലിംകളെക്കുറിച്ച് പരദൂഷണം പറയുകയോ അവരുടെ ന്യൂനതകൾ ചികഞ്ഞന്വേഷിക്കുകയോ ചെയ്യരുത്. കാരണം, ആരെങ്കിലും അവരുടെ ന്യൂനതകൾ ചികഞ്ഞന്വേഷിക്കുകയാണെങ്കിൽ തീർച്ചയായും അല്ലാഹു അവന്റെ ന്യൂനതകളെയും ചികഞ്ഞന്വേഷിക്കും. ആരുടെ ന്യൂനതകളെ അല്ലാഹു ചികഞ്ഞന്വേഷിക്കുന്നോ അവനെ അല്ലാഹു അവന്റെ വീട്ടിൽ വെച്ച് വഷളാക്കും." (ദ)', 'أَبِي بَرْزَةَ الْأَسْلَمِيِّ', 'അബൂബർസതുൽ അസ്ലമീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 814, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِيَّاكُمْ وَالْحَسَدَ، فَإِنَّ الْحَسَدَ يَأْكُلُ الْحَسَنَاتِ كَمَا تَأْكُلُ النَّارُ الْحَطَبَ". أَوْ قَالَ: "الْعُشْبَ". (د)', 'അബൂഹുറൈറ(റ): നിശ്ചയം നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അസൂയയെ സുക്ഷിച്ചുകൊള്ളുക. കാരണം, നിശ്ചയം അസൂയ, തീ വിറക് തിന്നും പോലെ, നന്മകളെ തിന്നും." അല്ലെങ്കിൽ അവിടന്ന് പറഞ്ഞത്: "പുല്ല്" എന്നാണ്. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 815, 815, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنْ سَهْلِ بْنِ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ دَخَلَ هُوَ وَأَبُوهُ عَلَى أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا بِالْمَدِينَةِ، فِي زَمَانِ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ وَهُوَ أَمِيرُ الْمَدِينَةِ، فَإِذَا هُوَ يُصَلِّي صَلَاةً خَفِيفَةً دَقِيقَةً، كَأَنَّهَا صَلَاةُ مُسَافِرٍ أَوْ قَرِيبًا مِنْهَا، فَلَمَّا سَلَّمَ قَالَ أَبِي: يَرْحَمُكَ اللهُ، أَرَأَيْتَ هَذِهِ الصَّلَاةَ: الْمَكْتُوبَةَ أَوْ شَيْءٌ تَنَفَّلْتَهُ؟ قَالَ: إِنَّهَا الْمَكْتُوبَةُ، وَإِنَّهَا لَصَلَاةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، مَا أَخْطَأْتُ إِلَّا شَيْئًا سَهَوْتُ عَنْهُ. فَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "لَا تُشَدِّدُوا عَلَى أَنْفُسِكُمْ فَيُشَدَّدَ عَلَيْكُمْ، فَإِنَّ قَوْمًا شَدَّدُوا عَلَى أَنْفُسِهِمْ فَشَدَّدَ اللهُ عَلَيْهِمْ، فَتِلْكَ بَقَايَاهُمْ فِي الصَّوَامِعِ وَالدِّيَارِ: {وَرَهْبَانِيَّةً ابْتَدَعُوهَا مَا كَتَبْنَاهَا عَلَيْهِمْ} [الحديد:٢٧]. ثُمَّ غَدَا مِنَ الْغَدِ فَقَالَ: أَلَا تَرْكَبُ لِتَنْظُرَ وَلِتَعْتَبِرَ؟ قَالَ: نَعَمْ، فَرَكِبُوا جَمِيعًا فَإِذَا هُمْ بِدِيَارٍ بَادَ أَهْلُهَا وَانْقَضَوْا وَفَنُوا خَاوِيَةً عَلَى عُرُوشِهَا، فَقَالَ: أَتَعْرِفُ هَذِهِ الدِّيَارَ؟ فَقُلْتُ: مَا أَعْرِفُنِي بِهَا وَبِأَهْلِهَا، هَذِهِ دِيَارُ قَوْمٍ أَهْلَكَهُمُ الْبَغْيُ وَالْحَسَدُ، إِنَّ الْحَسَدَ يُطْفِئُ نُورَ الْحَسَنَاتِ، وَالْبَغْيُ يُصَدِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ، وَالْعَيْنُ تَزْنِي وَالْكَفُّ وَالْقَدَمُ وَالْجَسَدُ وَاللِّسَانُ، وَالْفَرْجُ يُصَدِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ. (د)', 'സഹ്ലുബ്നു അബീഉമാമ(റ): അദ്ദേഹവും അദ്ദേഹത്തിന്റെ പിതാവും ഉമറുബ്നു അബ്ദിൽ അസീസ്(റ)വിന്റെ ഭരണ കാലത്ത്, മദീനയിലെ അമീറായ അനസുബ്നു മാലിക്(റ)വിനെ മദീനയിൽ ചെന്ന് കണ്ടു. അന്നേരമദ്ദേഹം നേരിയ ഒരു നിസ്കാരം നിസ്കരിക്കുന്നത് കണ്ടു. അത് യാത്രക്കാരന്റെ നിസ്കാരമോ അല്ലെങ്കിൽ അതിനോടടുത്ത നിസ്കാരമോ പോലെയുണ്ട്. അങ്ങനെ സലാം വീട്ടിയപ്പോൾ എന്റെ പിതാവ് പറഞ്ഞു: അല്ലാഹു അങ്ങേക്ക് അനുഗ്രഹം നൽകട്ടെ, ഈ നിസ്കാരത്തെക്കുറിച്ച് താങ്കൾ പറഞ്ഞ് തന്നാലും. അത് നിർബന്ധമാക്കപ്പെട്ട നിസ്കാരമാണോ അതോ അങ്ങ് സുന്നത്തായി ചെയ്ത വല്ലതുമാണോ? അദ്ദേഹം പറഞ്ഞു: "നിശ്ചയം അത് നിർബന്ധമാക്കപ്പെട്ട നിസ്കാരമാണ്. അത് അല്ലാഹുവിന്റെ റസൂൽ(സ)യുടെ നിസ്കാരമാണ്. അതിൽ മറന്നുപോയ കാര്യത്തിലല്ലാതെ ഒന്നിലും ഞാൻ പിഴവും വരുത്തിയിട്ടില്ല. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: നിശ്ചയം അല്ലാഹുവിന്റെ റസൂൽ(സ) പറയാറുണ്ടായിരുന്നു: "നിങ്ങൾ നിങ്ങളുടെ ശരീരത്തോട് തീവ്രമായി പെരുമാറരുത്. അപ്പോൾ നിങ്ങളോടും തീവ്രമായി പെരുമാറപ്പെടും. നിശ്ചയം ഒരു സമൂഹം അവരുടെ ശരീരത്തോട് തീവ്രമായി പെരുമാറി. അപ്പോൾ അല്ലാഹു അവരോട് തീവ്രമായി പെരുമാറി. ആശ്രമങ്ങളിലും സന്യാസിമങ്ങളിലുമുള്ളതെല്ലാം അവരുടെ ബാക്കി പത്രങ്ങളാണ്. (പൗരോഹിത്യമെന്നത് അവർ പുതുതായി തുടങ്ങിയതാണ്. നാമതിനെയവർക്ക് നിർബന്ധമാക്കിയിട്ടില്ല.)" (അൽ ഹദീദ്: 27) പിന്നെ അടുത്ത പ്രഭാതമായപ്പോൾ അദ്ദേഹം ചോദിച്ചു: വിഷയങ്ങൾ നേരിട്ട് കാണാനും ചിന്തിച്ച് മനസ്സിലാക്കാനുമായി താങ്കൾ വരുന്നില്ലേയോ? അദ്ദേഹം പറഞ്ഞു: അതെ. അങ്ങനെ അവരെല്ലാവരും വാഹനം കയറുകയും ചില മാങ്ങളുടെ അടുത്തെത്തുകയും ചെയ്തു. അതിന്റെ ആളുകൾ നശിക്കുകയും വേരോടെ പിഴുതെറിയപ്പെടുകയും തകർക്കപ്പെടുകയും ചെയ്തിരിക്കുന്നു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: ഈ മാങ്ങളെ താങ്കൾക്കറിയാമോ? അപ്പോൾ ഞാൻ പറഞ്ഞു: ഇതേക്കുറിച്ചും ഇതിന്റെ ആളുകളെക്കുറിച്ചും എനിക്ക് നന്നായി അറിയാം. അസൂയയും അന്യായവും നശിപ്പിച്ച ഒരു സമൂഹത്തിന്റെ മാങ്ങളാണിത്. നിശ്ചയം അസൂയ നന്മകളുടെ പ്രകാശത്തെ കെടുത്തിക്കളയും. അതിക്രമമതിനെ സത്യമാക്കുകയോ അസത്യമാക്കുകയോ ചെയ്യും. കണ്ണ്, മുൻകൈ, പാദം, ശരീരം, നാവ് എന്നിവ വ്യഭിചരിക്കുന്നു. ലിംഗം അതിനെ സത്യമാക്കുകയോ അസത്യമാക്കുകയോ ചെയ്യുന്നു. (ദ)', 'سَهْلِ بْنِ أَبِي أُمَامَةَ', 'സഹ്ലുബ്നു അബീഉമാമ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الحديد:٢٧', null, 815, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقَاطَعُوا، وَلَا تَدَابَرُوا، وَلَا تَبَاغَضُوا، وَلَا تَحَاسَدُوا، وَكُونُوا عِبَادَ اللهِ إِخْوَانًا، وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثٍ". حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ പരസ്പര സ്നേഹമില്ലാത്തവരാവരുത്. നിങ്ങൾ പരസ്പരം ഭിന്നിക്കരുത്, നിങ്ങൾ പരസ്പരം ദേഷ്യം വെക്കരുത്, നിങ്ങൾ പരസ്പരം അസൂയയുള്ളവരാവരുത്, നിങ്ങൾ പരസ്പര സഹോദരങ്ങളായ അല്ലാഹുവിന്റെ അടിമകളാവുക, ഒരു മുസ്ലിമിനും തന്റെ സഹോദരനോട് മൂന്ന് ദിവസത്തിലേറെ പിണങ്ങി നിൽക്കൽ അനുദനീയമല്ല." (ബു,മു,ദ,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا حَسَدَ إِلَّا فِي اثْنَتَيْنِ: رَجُلٌ آتَاهُ اللهُ مَالًا، فَهُوَ يُنْفِقُ مِنْهُ آنَاءَ اللَّيْلِ وَآنَاءَ النَّهَارِ. وَرَجُلٌ آتَاهُ اللهُ الْقُرْآنَ، فَهُوَ يَقُومُ بِهِ آنَاءَ اللَّيْلِ وَآنَاءَ النَّهَارِ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് ആളുകളോടല്ലാതെ അസൂയയില്ല: അല്ലാഹു സമ്പത്ത് നൽകിയ ഒരാൾ, അയാൾ അതിൽ നിന്ന് രാപ്പകൽ ഭേദമന്യേ ചെലവഴിക്കുന്നു. മറ്റൊരാൾ, അയാൾക്കല്ലാഹു ഖുർആൻ നൽകിയിരിക്കുന്നു. അയാൾ രാപ്പകൽ സമയങ്ങളിൽ അതുമായി പ്രവർത്തനങ്ങൾ നടത്തുന്നു." (ബു,മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَصْلَتَانِ لَا تَجْتَمِعَانِ فِي مُؤْمِنٍ: الْبُخْلُ وَسُوءُ الْخُلُقِ". (ت)', 'അബൂസഇൗദിൽ ഖുദ്രിയ്യ്(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് കാര്യങ്ങൾ ഒരു മുഅ്മിനിൽ ഒരിക്കലും ഒരുമിച്ച് കൂടുകയില്ല: പിശുക്കും ചീത്ത സ്വഭാവവും." (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്രിയ്യ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنْ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَدْخُلُ الْجَنَّةَ خِبٌّ وَلَا مَنَّانٌ وَلَا بَخِيلٌ". حَسَنٌ. (ت)', 'അബൂബക്ർ സിദ്ദീഖ്(റ): നബി(സ) പറഞ്ഞു: "ജനങ്ങൾക്കിടയിൽ കുഴപ്പമുണ്ടാക്കുന്ന ചതിയനും, ചെയ്ത നന്മ എടുത്ത് പറയുന്നവനും പിശുക്കനും സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കില്ല." ഹദീസ് ഹസനാണ്. (തു)', 'أَبِي بَكْرٍ الصِّدِّيقِ', 'അബൂബക്ർ സിദ്ദീഖ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمُؤْمِنُ غِرٌّ كَرِيمٌ، وَالْفَاجِرُ خِبٌّ لَئِيمٌ". (د)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "വിശ്വാസി ശുദ്ധഹൃദയനും ഉദാരനുമാണ്. തെമ്മാടി നീചനും ലുബ്ധനുമാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا كَانَ الْفُحْشُ فِي شَيْءٍ إِلَّا شَانَهُ، وَمَا كَانَ الْحَيَاءُ فِي شَيْءٍ إِلَّا زَانَهُ". حَسَنٌ. (ت,جه)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "തെമ്മാടിത്തം, അത് ഒരു വസ്തുവിലും അതിനെ മോശമാക്കിയിട്ടല്ലാതെ ഉണ്ടാവുകയില്ല. ലജ്ജ, അത് ഒരു വസ്തുവിലും അതിനെ ഭംഗിയുള്ളതാക്കിയിട്ടല്ലാതെ ഉണ്ടാവുകയില്ല." (തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 817, 817, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنْ أَبِي صِرْمَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ ضَارَّ ضَارَّ اللهُ بِهِ، وَمَنْ شَاقَّ شَاقَّ اللهُ عَلَيْهِ". حَسَنٌ. (د,جه)', 'അബൂസിർമ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ബുദ്ധിമുട്ടുണ്ടാക്കിയാൽ അല്ലാഹു അവന് ബുദ്ധിമുട്ടുണ്ടാക്കും. ആരെങ്കിലും എതിരാളിയായാൽ അല്ലാഹു അവനോട് എതിരാളിയാവും." (ദ,ജ)', 'أَبِي صِرْمَةَ', 'അബൂസിർമ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 817, 817, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَلْعُونٌ مَنْ ضَارَّ مُؤْمِنًا أَوْ مَكَرَ بِهِ". (ت)', 'അബൂബക്ർ സിദ്ദീഖ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുഅ്മിനിനെ ബുദ്ധിമുട്ടിച്ചവൻ അല്ലെങ്കിൽ മുഅ്മിനിനെ ചതിയിൽ കുടുക്കിയവൻ ശപിക്കപ്പെട്ടവനാണ്." (തു)', 'أَبِي بَكْرٍ الصِّدِّيقِ', 'അബൂബക്ർ സിദ്ദീഖ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 817, 817, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْغَادِرَ يُرْفَعُ لَهُ لِوَاءٌ يَوْمَ الْقِيَامَةِ، يُقَالُ هَذِهِ غَدْرَةُ فُلَانِ بْنِ فُلَانٍ". (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം അന്ത്യനാളിൽ വഞ്ചകന് വേണ്ടി ഒരു കൊടി നാട്ടപ്പെടും, അപ്പോൾ പറയപ്പെടും: ഇന്നാലിന്ന ആളുടെ മകൻ ഇന്നാലിന്നവന്റെ ചതിയാണിത്." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 817, 817, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَتَدْرُونَ مَا الْغِيبَةُ". قَالُوا: اللهُ وَرَسُولُهُ أَعْلَمُ قَالَ: "ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ". قِيلَ: أَفَرَأَيْتَ إِنْ كَانَ فِي أَخِي مَا أَقُولُ؟ قَالَ: "إِنْ كَانَ فِيهِ مَا تَقُولُ فَقَدِ اغْتَبْتَهُ، وَإِنْ لَمْ يَكُنْ فِيهِ فَقَدْ بَهَتَّهُ". (م,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്താണ് പരദൂഷണം എന്ന് നിങ്ങൾക്കറിയുമോ?" അവർ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ റസൂലുമാണ് ഏറ്റവും അറിവുള്ളവർ. അവിടന്ന് പറഞ്ഞു: "നീ നിന്റെ സഹോദരനെക്കുറിച്ച് അവന് ഇഷ്ടമില്ലാത്തത് പറയലാണ്." അപ്പോൾ ഒരാൾ ചോദിച്ചു: ഞാൻ പറയുന്നത് എന്റെ സഹോദരനിലുണ്ടെങ്കിൽ അതേക്കുറിച്ച് അവിടന്ന് എന്താണ് പറയുന്നത്? അവിടന്ന് പറഞ്ഞു: "നീ പറയുന്നത് അവനിലുണ്ടെങ്കിൽ തീർച്ചയായും നീ അവനെക്കുറിച്ച് പരദൂഷണം പറഞ്ഞിരിക്കുന്നു. ഇനി അത് അവനിലില്ലെങ്കിൽ തീർച്ചയായും നീ അവനെക്കുറിച്ച് കള്ളം പറഞ്ഞുണ്ടാക്കിയിരിക്കുന്നു." (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 817, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قُلْتُ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: حَسْبُكَ مِنْ صَفِيَّةَ كَذَا وَكَذَا، تَعْنِي قَصِيرَةً. فَقَالَ: "لَقَدْ قُلْتِ كَلِمَةً لَوْ مُزِجَتْ بِمَاءِ الْبَحْرِ لَمَزَجَتْهُ". قَالَتْ: وَحَكَيْتُ لَهُ إِنْسَانًا، فَقَالَ: "مَا أُحِبُّ أَنِّي حَكَيْتُ إِنْسَانًا وَأَنَّ لِي كَذَا وَكَذَا". (ت)', 'ആഇശ(റ): ഞാൻ പ്രവാചകർ(സ)യോട് പറഞ്ഞു: സ്വഫിയ്യയിൽ നിന്ന് താങ്കൾക്ക് (മഹതിയുടെ ന്യൂനതയായി) ഇന്നലിന്നതൊക്കെ മതിയാകും. മഹതി ഉദ്ദേശിക്കുന്നത് സ്വഫിയ്യയുടെ വലിപ്പക്കുറവിനെയാണ്. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "തീർച്ചയായും കടൽവെള്ളത്തിൽ കലക്കിയാൽ അതിനെ പകർച്ചയാക്കുന്ന ഒരു വാക്കാണ് നീ പറഞ്ഞത്." മഹതി പറയുന്നു: ഞാൻ ഒരാളെ പരിഹസിച്ചുകൊണ്ട് അവിടത്തേക്ക് അയാളെപ്പോലെ പ്രവർത്തിച്ച് കാട്ടിക്കൊടുത്തു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "എനിക്ക് ഇന്ന വസ്തുക്കളെല്ലാം പകരമായി കിട്ടുമെങ്കിലും, ഒരാളെ പരിഹസിച്ച് കൊണ്ട് അയാളെപ്പോലെ പ്രവർത്തിക്കാൻ ഞാൻ ഇഷ്ടപ്പെടുന്നില്ല." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 818, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنْ سَعِيدِ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ مِنْ أَرْبَى الرِّبَا الِاسْتِطَالَةَ فِي عِرْضِ الْمُسْلِمِ بِغَيْرِ حَقٍّ". (د)', 'സഇൗദുബ്നു സൈദ്(റ): നബി(സ) പറഞ്ഞു: "അവകാശം കൂടാതെ ഒരു മുസ്ലിമിന്റെ അഭിമാനത്തിൽ വാചാലനാവൽ ഏറ്റവും ശക്തവും നിഷിദ്ധവുമായ പലിശയിൽപ്പെട്ടതാണ്." (ദ)', 'سَعِيدِ بْنِ زَيْدٍ', 'സഇൗദുബ്നു സൈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 818, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ أَكْبَرِ الْكَبَائِرِ اسْتِطَالَةَ الْمَرْءِ فِي عِرْضِ رَجُلٍ مُسْلِمٍ بِغَيْرِ حَقٍّ، وَمِنَ الْكَبَائِرِ السَّبَّتَانِ بِالسَّبَّةِ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഒരാൾ അവകാശം കൂടാതെ മുസ്ലിമായ ഒരാളുടെ അഭിമാനത്തിൽ കളങ്കം വരുത്തി വാചാലനാവൽ വൻദോഷങ്ങളിൽ ഏറ്റവും പ്രധാനപ്പെട്ടതിലൊന്നാണ്. ഒരു ചീത്തവാക്കിന് പകരമായി രണ്ട് ചീത്തവാക്ക് പറയലും വൻദോഷങ്ങളിൽപ്പെട്ടതാകുന്നു." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 818, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَمَّا عُرِجَ بِي مَرَرْتُ بِقَوْمٍ لَهُمْ أَظْفَارٌ مِنْ نُحَاسٍ، يَخْمُشُونَ وُجُوهَهُمْ وَصُدُورَهُمْ، فَقُلْتُ: مَنْ هَؤُلَاءِ يَا جِبْرِيلُ؟ قَالَ: هَؤُلَاءِ الَّذِينَ يَأْكُلُونَ لُحُومَ النَّاسِ وَيَقَعُونَ فِي أَعْرَاضِهِمْ". (د)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ആകാശാരോഹണത്തിനായി ഉയർത്തപ്പെട്ടപ്പോൾ, ചെമ്പിന്റെ നഖങ്ങളുള്ള ഒരു സമൂഹത്തിന്റെ അടുത്തുകൂടെ ഞാൻ നടന്നുപോയി. അവർ അവരുടെ മുഖവും നെഞ്ചും മാന്തിപ്പൊളിക്കുന്നുണ്ട്. അപ്പോൾ ഞാൻ ചോദിച്ചു: ജിബ്രീലേ, ഇവർ ആരാണ്? ജിബ്രീൽ(അ) പറഞ്ഞു: ജനങ്ങളുടെ മാംസം ഭക്ഷിക്കുകയും അവരുടെ അഭിമാനത്തിൽ കളങ്കം വരുത്തുകയും ചെയ്യുന്നവരാണവർ." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 818, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنِ الْمُسْتَوْرِدِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَكَلَ بِرَجُلٍ مُسْلِمٍ أَكْلَةً فَإِنَّ اللهَ يُطْعِمُهُ مِثْلَهَا مِنْ جَهَنَّمَ، وَمَنْ كُسِيَ ثَوْبًا بِرَجُلٍ مُسْلِمٍ فَإِنَّ اللهَ يَكْسُوهُ مِثْلَهُ مِنْ جَهَنَّمَ، وَمَنْ قَامَ بِرَجُلٍ مَقَامَ سُمْعَةٍ وَرِيَاءٍ فَإِنَّ اللهَ يَقُومُ بِهِ مَقَامَ سُمْعَةٍ وَرِيَاءٍ يَوْمَ الْقِيَامَةِ". (د)', 'മുസ്തൗരിദ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു മുസ്ലിമിനെ അപകീർത്തിപ്പെടുത്തിയതിന് പ്രതിഫലമായി കിട്ടിയതിൽ നിന്ന് ഒരു പിടി ആരെങ്കിലും തിന്നാൽ നരകത്തിൽ നിന്ന് അതു പോലെയുള്ള ഒന്നിനെ അല്ലാഹു അവന് ഭക്ഷിപ്പിക്കും. ഒരു മുസ്ലിമിനെ അപകീർത്തിപ്പെടുത്തിയതിന് പ്രതിഫലമായി കിട്ടിയതിൽ നിന്ന് ആരെങ്കിലും വസ്ത്രമണിഞ്ഞാൽ നരകത്തിൽ നിന്നു അതിനോട് സമാനമായതിനെ അല്ലാഹു അവനെ ധരിപ്പിക്കും. ഒരാൾ പ്രശസ്തിയും ലോകമാന്യവും ഉദ്ദേശിച്ച് മറ്റൊരാളുടെ കാര്യം ഏറ്റെടുത്താൽ അന്ത്യനാളിൽ അല്ലാഹു പ്രശസ്തിയും ലോകമാന്യവും മാത്രം ഉദ്ദേശിച്ച് അവന്റെ കാര്യങ്ങൾ ഏറ്റെടുക്കും." (ദ)', 'الْمُسْتَوْرِدِ', 'മുസ്തൗരിദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 818, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ: مَالُهُ، وَعِرْضُهُ، وَدَمُهُ، حَسْبُ امْرِئٍ مِنَ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ". (م,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു മുസ്ലിമിന്റെ എല്ലാം മറ്റൊരു മുസ്ലിമിന് ഹറാമാണ്; അവന്റെ സമ്പത്തും അവന്റെ അഭിമാനനും അവന്റെ രക്തവും. തന്റെ മുസ്ലിമായ സഹോദരനെ നിന്ദിക്കൽ തന്നെ ഒരാൾക്ക് തിന്മയാകാൻ മതി." (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عَنْ مُعَاذِ بْنِ أَسَدٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَمَى مُؤْمِنًا مِنْ مُنَافِقٍ بَعَثَ اللهُ مَلَكًا يَحْمِي لَحْمَهُ يَوْمَ الْقِيَامَةِ مِنْ نَارِ جَهَنَّمَ، وَمَنْ رَمَى مُسْلِمًا بِشَيْءٍ يُرِيدُ شَيْنَهُ بِهِ حَبَسَهُ اللهُ عَلَى جِسْرِ جَهَنَّمَ حَتَّى يَخْرُجَ مِمَّا قَالَ". (د)', 'മുആദുബ്നു അസദിൽ ജുഹനീ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു മുഅ്മിനിനെ ഒരു മുനാഫിഖിൽ നിന്ന് സംരക്ഷിച്ചാൽ, അന്ത്യനാളിൽ നരകാഗ്നിയിൽ നിന്ന് അയാളുടെ മാംസത്തെ സംരക്ഷിക്കുന്ന ഒരു മലക്കിനെ അല്ലാഹു അയക്കും. ആരെങ്കിലും ഒരു മുസ്ലിമിനെതിരെ അദ്ദേഹത്തെ മോശമാക്കണമെന്ന ഉദ്ദേശ്യത്തിൽ വല്ല ആരോപണവും ഉന്നയിച്ചാൽ അയാളെ അല്ലാഹു അയാൾ പറഞ്ഞതിൽ നിന്ന് പിന്തിരിയുന്നതുവരെ നരകത്തിന്റെ പാലത്തിന്മേൽ പിടിച്ച് വെക്കും." (ദ)', 'مُعَاذِ بْنِ أَسَدٍ الْجُهَنِيِّ', 'മുആദുബ്നു അസദിൽ ജുഹനീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ وَأَبِي طَلْحَةَ بْنِ سَهْلٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُمْ قَالَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنِ امْرِئٍ يَخْذُلُ امْرَأً مُسْلِمًا، فِي مَوْضِعٍ تُنْتَهَكُ فِيهِ حُرْمَتُهُ وَيُنْتَقَصُ فِيهِ مِنْ عِرْضِهِ، إِلَّا خَذَلَهُ اللهُ فِي مَوْطِنٍ يُحِبُّ فِيهِ نُصْرَتَهُ. وَمَا مِنِ امْرِئٍ يَنْصُرُ مُسْلِمًا، فِي مَوْضِعٍ يُنْتَقَصُ فِيهِ مِنْ عِرْضِهِ وَيُنْتَهَكُ فِيهِ مِنْ حُرْمَتِهِ، إِلَّا نَصَرَهُ اللهُ فِي مَوْطِنٍ يُحِبُّ نُصْرَتَهُ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ), അബൂത്വൽഹതുബ്നു സഹ്ലിൽ അൻസാരി(റ): നബി(സ) പറഞ്ഞു: "ഒരു മുസ്ലിമായ മനുഷ്യനെ അയാളുടെ മാന്യത തകർക്കപ്പെടുകയും അഭിമാനം കുറച്ച് കാട്ടപ്പെടുകയും ചെയ്യുന്ന ഒരു സ്ഥലത്ത് വെച്ച് നിന്ദിക്കുന്ന ഒരാളെയും, അയാൾ അല്ലാഹുവിന്റെ സഹായം ആഗ്രഹിക്കുന്ന ഒരു സ്ഥലത്ത് വെച്ച്, അല്ലാഹു നിന്ദിക്കാതിരിക്കില്ല. ഒരു മുസ്ലിമിനെ അയാളുടെ മാന്യത തകർക്കപ്പെടുകയും അഭിമാനം കുറച്ചുകാട്ടപ്പെടുകയും ചെയ്യുന്ന ഒരു സ്ഥലത്ത് വെച്ച് സഹായിക്കുന്ന ഒരാളെയും അയാൾ അല്ലാഹുവിന്റെ സഹായം ആഗ്രഹിക്കുന്ന ഒരു സ്ഥലത്ത് വെച്ച് അല്ലാഹു സഹായിക്കാതിരിക്കില്ല."(ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ وَأَبِي طَلْحَةَ بْنِ سَهْلٍ الْأَنْصَارِيِّ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عَنْ جُنْدُبِ بْنِ عَبْدِ اللهِ الْبَجَلِيِّ رَضِيَ اللهُ عَنْهُ: قَالَ: جَاءَ أَعْرَابِيٌّ فَأَنَاخَ رَاحِلَتَهُ ثُمَّ عَقَلَهَا، ثُمَّ دَخَلَ الْمَسْجِدَ فَصَلَّى خَلْفَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا سَلَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَتَى رَاحِلَتَهُ فَأَطْلَقَهَا، ثُمَّ رَكِبَ، ثُمَّ نَادَى: اللَّهُمَّ ارْحَمْنِي وَمُحَمَّدًا، وَلَا تُشْرِكْ فِي رَحْمَتِنَا أَحَدًا. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَتَقُولُونَ هُوَ أَضَلُّ أَمْ بَعِيرُهُ، أَلَمْ تَسْمَعُوا إِلَى مَا قَالَ". قَالُوا: بَلَى. (د)', 'ജുൻദുബുബ്നു അബ്ദില്ലാഹിൽ ബജലീ(റ): ഒരു ഗ്രാമീണൻ വരികയും വാഹനത്തെ മുട്ട് കുത്തിക്കുകയും അതിനെ കെട്ടിയിടുകയും ചെയ്തു. പിന്നെ പള്ളിയിൽ പ്രവേശിച്ച് തിരുമേനി(സ)യുടെ പിന്നിൽ നിസ്കരിച്ചു. അല്ലാഹുവിന്റെ റസൂൽ(സ) സലാം വീട്ടിയപ്പോൾ അയാൾ വാഹനത്തിന്റെ അടുക്കൽ ചെന്ന് അതിന്റെ കെട്ടഴിച്ച് വാഹനപ്പുറത്ത് കയറി വിളിച്ചുപറഞ്ഞു: അല്ലാഹുവേ നീ എനിക്കും മുഹമ്മദിനും അനുഗ്രഹം ചെയ്യേണമേ, ഞങ്ങളുടെ അനുഗ്രഹത്തിൽ നീ മറ്റൊരാളെയും പങ്കാളിയാക്കരുത്. അപ്പോൾ തിരുദൂതർ(സ) പറഞ്ഞു: "അയാളാണോ അതോ അയാളുടെ ഒട്ടകമാണോ ഏറ്റവും വലിയ വിഢ്ഢിയെന്നതിൽ നിങ്ങൾക്കെന്തൊണ് പറയാനുള്ളത്. അയാൾ പറഞ്ഞത് നിങ്ങൾ കേട്ടില്ലെയോ." അവർ പറഞ്ഞു: അതെ. (ദ)', 'جُنْدُبِ بْنِ عَبْدِ اللهِ الْبَجَلِيِّ', 'ജുൻദുബുബ്നു അബ്ദില്ലാഹിൽ ബജലീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 819, 820, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عَنْ قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكُونَ مِثْلَ أَبِي ضَيْغَمٍ، أَوْ ضَمْضَمٍ؟ كَانَ إِذَا أَصْبَحَ قَالَ: اللَّهُمَّ إِنِّي قَدْ تَصَدَّقْتُ بِعِرْضِي عَلَى عِبَادِكَ. (د)', 'ഖതാദ(റ): അബൂളൈഅമിനെപ്പോലെ, അല്ലെങ്കിൽ ളംളമിനെപ്പോലെയാവാൻ നിങ്ങൾ അശക്തരാണോ? പ്രഭാതമായാൽ അയാൾ പറയും: അല്ലാഹുവേ, ഞാൻ എന്റെ അഭിമാനത്തെ നിന്റെ ദാസർക്ക് ധർമ്മം ചെയ്തിരിക്കുന്നു. (ദ)', 'قَتَادَةَ', 'ഖതാദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 820, 820, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَجْلَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكُونَ مِثْلَ أَبِي ضَمْضَمٍ". قَالُوا: وَمَنْ أَبُو ضَمْضَمٍ؟ قَالَ: "رَجُلٌ فِيمَنْ كَانَ مِنْ قَبْلِكُمْ – بِمَعْنَاهُ – قَالَ: عِرْضِي لِمَنْ شَتَمَنِي". (د)', 'അബ്ദുർറഹ്മാനുബ്നു അജ്ലാൻ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "അബു ളംളമിനെപ്പോലെ ആവാൻ നിങ്ങളിലാരെങ്കിലും അശക്തനാകുമോ?" അവർ ചോദിച്ചു: ആരാണ് അബൂളംളം? തിരുദൂതർ(സ) പറഞ്ഞു: "നിങ്ങളുടെ മുമ്പുണ്ടായിരുന്ന ഒരു മനുഷ്യൻ - ഇൗ അർത്ഥത്തിൽ ഒന്നു പറഞ്ഞു- അയാൾ പറഞ്ഞു: എന്റെ അഭിമാനം എന്നെ ആക്ഷേപിച്ചവനാണ്." (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ عَجْلَانَ', 'അബ്ദുർറഹ്മാനുബ്നു അജ്ലാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 820, 820, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَرَكَ الْكَذِبَ وَهُوَ بَاطِلٌ بُنِيَ لَهُ فِي رَبَضِ الْجَنَّةِ، وَمَنْ تَرَكَ الْمِرَاءَ وَهُوَ مُحِقٌّ بُنِيَ لَهُ فِي وَسَطِهَا، وَمَنْ حَسَّنَ خُلُقَهُ بُنِيَ لَهُ فِي أَعْلَاهَا". حَسَنٌ (ت,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും പൊള്ളയായ കളവ് പറയുന്നത് ഒഴിവാക്കിയാൽ സ്വർഗാതിർത്തിയിൽ അവന് വേണ്ടി കെട്ടിടം നിർമ്മിക്കപ്പെടും. സത്യം തന്റെ ഭാഗത്തായിരിക്കെത്തന്നെ ആരെങ്കിലും തർക്കത്തെ ഒഴിവാക്കിയാൽ അവന് വേണ്ടി സ്വർഗത്തിന്റെ മധ്യത്തിൽ കെട്ടിടം നിർമ്മിക്കപ്പെടും. ആരെങ്കിലും തന്റെ സ്വഭാവം നന്നാക്കിയാൽ അവന് വേണ്ടി സ്വർഗത്തിന്റെ ഏറ്റവും മുകളിൽ കെട്ടിടം നിർമ്മിക്കപ്പെടും." (തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 820, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كَفَى بِكَ إِثْمًا أَنْ لَا تَزَالَ مُخَاصِمًا". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "നീയൊരു തർക്കിക്കുന്നവനാവൽ തന്നെ കുറ്റത്താൽ നിനക്ക് മതി." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 821, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُمَارِ أَخَاكَ، وَلَا تُمَازِحْهُ، وَلَا تَعِدْهُ مَوْعِدَةً فَتُخْلِفَهُ". حَسَنٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നീ നിന്റെ സഹോദരനോട് തർക്കിക്കരുത്. അവനുമായി അന്യോന്യം തമാശ പറയരുത്. അവനോടൊരു വാഗ്ദത്തം ചെയ്ത് നീയത് ലംഘിക്കരുത്." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 821, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ مِنْ كِبْرٍ، وَلَا يَدْخُلُ النَّارَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ إِيمَانٍ". حَسَنٌ صَحِيحٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "ഹൃദയത്തിൽ ഒരു കടുക് മണിയുടെ തൂക്കം അഹങ്കാരമുള്ളവൻ സ്വർഗത്തിൽ കടക്കില്ല. ഹൃദയത്തിൽ ഒരു ധാന്യത്തിന്റെ തൂക്കം ഇൗമാനുള്ളവൻ നരകത്തിലും കടക്കില്ല." (തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 821, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ، وَلَا يَدْخُلُ النَّارَ يَعْنِي مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ إِيمَانٍ". فَقَالَ لَهُ رَجُلٌ: إِنَّهُ يُعْجِبُنِي أَنْ يَكُونَ ثَوْبِي حَسَنًا وَنَعْلِي حَسَنَةً؟ قَالَ: "إِنَّ اللهَ يُحِبُّ الْجَمَالَ، وَلَكِنَّ الْكِبْرَ مَنْ بَطِرَ الْحَقَّ وَغَمَصَ النَّاسَ". حَسَنٌ صَحِيحٌ. (م,د,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "ഹൃദയത്തിൽ അണുമണിത്തൂക്കം അഹങ്കാരമുള്ളവൻ സ്വർഗ്ഗത്തിൽ കടക്കുകയില്ല. ഹൃദയത്തിൽ അണുമണിത്തൂക്കം ഇൗമാനുള്ളവൻ നരകത്തിൽ കടക്കുകയില്ല." അപ്പോൾ അവിടുത്തോടൊരാൾ ചോദിച്ചു: എന്റെ വസ്ത്രവും ചെരിപ്പും നല്ലതാകൽ എന്നെ സന്തോഷിപ്പിക്കുന്നു. അവിടുന്ന് പറഞ്ഞു: "നിശ്ചയം അല്ലാഹു ഭംഗിയെ ഇഷ്ടപ്പെടുന്നു. പക്ഷേ, സത്യത്തെ അവഗണിക്കലും ജനങ്ങളെ നിന്ദിക്കലുമാണ് അഹങ്കാരം." (മു,ദ,തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 821, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزَالُ الرَّجُلُ يَذْهَبُ بِنَفْسِهِ حَتَّى يُكْتَبَ فِي الْجَبَّارِينَ، فَيُصِيبُهُ مَا أَصَابَهُمْ". حَسَنٌ. (ت)', 'സലമതുബ്നുൽ അക്വഅ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ താൻ സ്വന്തമെന്ന ബോധത്തോടെ പോയിക്കൊണ്ടിരിക്കും. അങ്ങനെ അയാൾ അഹങ്കാരികളിൽ എഴുതപ്പെടും. അങ്ങനെ അവർക്ക കിട്ടിയത് ഇയാൾക്കും കിട്ടും." (തു)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നുൽ അക്വഅ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 821, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: تَقُولُونَ فِي التِّيهِ، وَقَدْ رَكِبْتُ الْحِمَارَ، وَلَبِسْتُ الشَّمْلَةَ، وَقَدْ حَلَبْتُ الشَّاةَ، وَقَدْ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ فَعَلَ هَذَا فَلَيْسَ فِيهِ مِنَ الْكِبْرِ شَيْءٌ". حَسَنٌ صَحِيحٌ. (ت)', 'ജുബൈറുബ്നു മുത്ഇം(റ): നിങ്ങൾ എന്നിൽ അഹങ്കാരം ആരോപിക്കുന്നു. ഞനാണെങ്കിൽ കഴുതയെ വാഹനമാക്കിയിട്ടുണ്ട്. ചെറിയ തലപ്പാവ് ഞാൻ ധരിച്ചിട്ടുണ്ട്. ഞാൻ ആടിനെ കറന്നിട്ടുമുണ്ട്. അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞിരിക്കുന്നു: "ഇതെല്ലാം ആരെങ്കിലും ചെയ്താൽ അവനിൽ അഹങ്കാരം തീരെ ഇല്ല." (തു)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 822, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ وَأَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُمَا قَالَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْعِزُّ إِزَارُهُ، وَالْكِبْرِيَاءُ رِدَاؤُهُ، فَمَنْ يُنَازِعُنِي عَذَّبْتُهُ". (م)', 'അബൂസഇൗദിൽ ഖുദ്രീ(റ), അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അഭിമാനം അവന്റെ(അല്ലാഹുവിന്റെ) അരയുടുപ്പാണ്. അഹങ്കാരം അവന്റെ മേൽതട്ടമാണ്. അതിനാൽ എന്നോടാരെങ്കിലും തർക്കിച്ചാൽ ഞാനവനെ ശിക്ഷിക്കും." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ وَأَبِي هُرَيْرَةَ', 'അബൂസഇൗദിൽ ഖുദ്രീ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 822, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثَةٌ لَا يُكَلِّمُهُمُ اللهُ يَوْمَ الْقِيَامَةِ وَلَا يُزَكِّيهِمْ – قَالَ أَبُو مُعَاوِيَةَ: وَلَا يَنْظُرُ إِلَيْهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ: شَيْخٌ زَانٍ، وَمَلِكٌ كَذَّابٌ، وَعَائِلٌ مُسْتَكْبِرٌ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മൂന്ന് വിധം ആളുകൾ, അന്ത്യനാളിൽ അല്ലാഹു അവരോട് സംസാരിക്കുകയില്ല, അവരെ അവൻ സംസ്കരിക്കുകയുമില്ല. അബൂമുആവിയ(റ) പറയുന്നു: അവരിലേക്കവൻ നോക്കുകയുമില്ല. അവർക്ക് വേദനാജനകമായ ശിക്ഷയുമുണ്ട്: വ്യഭിചാരിയായ വൃദ്ധൻ, കളവ് പറയുന്ന രാജാവ്, അഹങ്കാരിയായ ദരിദ്രൻ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 822, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "كَانَ رَجُلَانِ فِي بَنِي إِسْرَائِيلَ مُتَوَاخِيَيْنِ، فَكَانَ أَحَدُهُمَا يُذْنِبُ وَالْآخَرُ مُجْتَهِدٌ فِي الْعِبَادَةِ، فَكَانَ لَا يَزَالُ الْمُجْتَهِدُ يَرَى الْآخَرَ عَلَى الذَّنْبِ، فَيَقُولُ: أَقْصِرْ، فَوَجَدَهُ يَوْمًا عَلَى ذَنْبٍ، فَقَالَ لَهُ: أَقْصِرْ، فَقَالَ: خَلِّنِي وَرَبِّي، أَبُعِثْتَ عَلَيَّ رَقِيبًا؟ فَقَالَ: وَاللهِ لَا يَغْفِرُ اللهُ لَكَ، أَوْ: لَا يُدْخِلُكَ اللهُ الْجَنَّةَ. فَقَبَضَ أَرْوَاحَهُمَا، فَاجْتَمَعَا عِنْدَ رَبِّ الْعَالَمِينَ، فَقَالَ لِهَذَا الْمُجْتَهِدِ: أَكُنْتَ بِي عَالِمًا؟ أَوْ كُنْتَ عَلَى مَا فِي يَدِي قَادِرًا؟ وَقَالَ لِلْمُذْنِبِ: اذْهَبْ فَادْخُلِ الْجَنَّةَ بِرَحْمَتِي، وَقَالَ لِلْآخَرِ: اذْهَبُوا بِهِ إِلَى النَّارِ". قَالَ: أَبُو هُرَيْرَةَ وَالَّذِي نَفْسِي بِيَدِهِ، لَتَكَلَّمَ بِكَلِمَةٍ أَوْبَقَتْ دُنْيَاهُ وَآخِرَتَهُ. (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ബനൂ ഇസ്രാഇൗലിൽ രണ്ട് സഹോദരങ്ങളുണ്ടായിരുന്നു. അവരിലൊരാൾ ദോഷിയും, മറ്റെയാൾ ആരാധനയിൽ പ്രയത്നിക്കുന്നവനുമായിരുന്നു. (ആരാധനയിൽ) പ്രയത്നിക്കുന്നയാൾ മറ്റെയാൾ ദോഷങ്ങൾ ചെയ്യുന്നതു കാണുമായിരുന്നു. അപ്പോൾ പറയും: നീ കുറക്കുക. അങ്ങനെ ഒരു ദിവസം ഇദ്ദേഹം അയാൾ ഒരു ദോഷം ചെയ്യുന്നതായി കണ്ടു. അപ്പോൾ അയാളോട് പറഞ്ഞു: നീ കുറക്കുക. അപ്പോൾ അയാൾ പറഞ്ഞു: നീ എന്നെയും എന്റെ റബ്ബിനെയും (ഞങ്ങളുടെ വഴിക്ക്) വിടുക, എന്നെ നിരീക്ഷിക്കുന്നവനായി നീ അയക്കപ്പെട്ടുവോ? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, അല്ലാഹു നിനക്ക് പൊറുത്ത് തരില്ല. അല്ലെങ്കിൽ അല്ലാഹു നിന്നെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കില്ല. ശേഷം അല്ലാഹു അവർ ഇരുവരെയും മരിപ്പിച്ചു. അങ്ങനെ രണ്ട് പേരും ലോക രക്ഷിതാവിന്റെ സന്നിധാനത്തിൽ ഒരുമിക്കുകയും ചെയ്തു. അപ്പോൾ അല്ലാഹു ഈ (ആരാധനയിൽ) പ്രയത്നിക്കുന്ന ആളോട് ചോദിച്ചു: നീ എന്നെക്കുറിച്ച് അറിയുന്നവനായിരുന്നോ? അല്ലെങ്കിൽ എന്റെ അധീനതയിലുള്ള ഒന്നിൽ (വല്ലതും ചെയ്യാൻ) കഴിവുള്ളവനായിരുന്നോ? ശേഷം അല്ലാഹു ആ ദോഷിയോട് പറഞ്ഞു: എന്റെ അനുഗ്രഹം കൊണ്ട് നീ സ്വർഗ്ഗത്തിൽ കടക്കുക. അല്ലാഹു മറ്റേയാളെക്കുറിച്ച് പറഞ്ഞു: നിങ്ങൾ ഇയാളെ നരകത്തിലേക്ക് കൊണ്ടുപോകുക." അബൂഹുറൈറ(റ) പറയുന്നു: എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം! തീർച്ചയായും അയാൾ പറഞ്ഞത് അയാളുടെ ദുൻയാവിനെയും ആഖിറത്തെയും നശിപ്പിച്ച ഒരു വാക്കാണ്. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 822, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ ذَنْبٍ أَجْدَرُ أَنْ يُعَجِّلَ اللهُ تَعَالَى لِصَاحِبِهِ الْعُقُوبَةَ فِي الدُّنْيَا، مَعَ مَا يَدَّخِرُ لَهُ فِي الْآخِرَةِ، مِثْلُ الْبَغْيِ وَقَطِيعَةِ الرَّحِمِ". (د,ت,جه)', 'അബൂബക്റത്(റ): റസൂൽ(സ) പറഞ്ഞു: "പരലോകത്ത് വെച്ചുള്ള ശിക്ഷ ഒരുക്കിവെക്കപ്പെട്ടിരിക്കെ തന്നെ ദുൻയാവിൽ വെച്ച് അല്ലാഹു ശിക്ഷയെ ഉളരിപ്പിക്കാൻ വ്യഭിചാരത്തേക്കാളും കുടുംബ ബന്ധം മുറിച്ച് കളയുന്നതിനേക്കാളും ഏറ്റവും ബന്ധപ്പെട്ട മറ്റൊരു ദോശവുമില്ല." (ദ,തു,ജ)', 'أَبِي بَكْرَةَ', 'അബൂബക്റത്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 823, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الظُّلْمُ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "അക്രമം അന്ത്യദിനത്തിലെ ഇരുളുകളാണ്." (ബു,മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 823, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قَاتَلَ أَحَدُكُمْ أَخَاهُ فَلَا يَلْطِمَنَّ الْوَجْهَ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആരെങ്കിലും തന്റെ സഹോദരനുമായി യുദ്ധം ചെയ്യുകയാണെങ്കിൽ അയാളുടെ മുഖത്തടിക്കരുത്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 823, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 323, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قَاتَلَ أَحَدُكُمْ أَخَاهُ فَلْيَجْتَنِبِ الْوَجْهَ، فَإِنَّ اللهَ خَلَقَ آدَمَ عَلَى صُورَتِهِ". (م)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ആരെങ്കിലും തന്റെ സഹോദരനോട് യുദ്ധം ചെയ്യുകയാണെങ്കിൽ അവന്റെ മുഖം ഒഴിവാക്കിക്കൊള്ളട്ടെ. കാരണം അല്ലാഹു ആദമിനെ സൃഷ്ടിച്ചത് തന്റെ രൂപത്തിലാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 823, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 324, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الشَّيْطَانَ قَدْ أَيِسَ أَنْ يَعْبُدَهُ الْمُصَلُّونَ فِي جَزِيرَةِ الْعَرَبِ، وَلَكِنْ فِي التَّحْرِيشِ بَيْنَهُمْ". (م)', 'ജാബിർ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അറേബ്യൻ ഉപഭൂഖണ്ധത്തിലുള്ള നിസ്കാരക്കാർ പിശാചിനെ ആരാധിക്കലിൽ നിന്നും അവൻ ആശയറ്റിരിക്കുന്നു. പക്ഷേ, അവർക്കിടയിൽ വിദ്വേഷം ഇളക്കി വിടുന്നതിൽ (അവൻ വിജയിച്ചിരിക്കുന്നു.)" (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 824, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 325, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أُعْطِيَ عَطَاءً فَوَجَدَ فَلْيَجْزِ بِهِ، وَمَنْ لَمْ يَجِدْ فَلْيُثْنِ، فَإِنَّ مَنْ أَثْنَى فَقَدْ شَكَرَ وَمَنْ كَتَمَ فَقَدْ كَفَرَ. وَمَنْ تَحَلَّى بِمَا لَمْ يُعْطَهُ كَانَ كَلَابِسِ ثَوْبَيْ زُورٍ". حَسَنٌ. (د,ت)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും വല്ല ദാനവും നൽകപ്പെട്ടാൽ സാധ്യമായ വിധത്തിൽ അവനതിന് പ്രത്യുപകാരം ചെയ്യട്ടെ. ഇനി അതിന് സാധ്യമായില്ലെങ്കിൽ അവൻ സ്തുതിച്ച് കൊള്ളട്ടെ. തീർച്ചയായും സ്തുതിച്ചവൻ നന്ദിചെയ്തിരിക്കുന്നു. അതിനെ മറച്ചുവെച്ചവൻ നന്ദികേട് കാണിച്ചിരിക്കുന്നു. നൽകപ്പെടാത്തത് കൊണ്ട് സ്വയം അലങ്കരിച്ചവൻ, വ്യാജമായി നിർമ്മിച്ച രണ്ട് വസ്ത്രങ്ങൾ ധരിച്ചവനെപ്പോലെയാണ്." (ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 824, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 326, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صُنِعَ إِلَيْهِ مَعْرُوفٌ، فَقَالَ لِفَاعِلِهِ: جَزَاكَ اللهُ خَيْرًا، فَقَدْ أَبْلَغَ فِي الثَّنَاءِ". حَسَنٌ جَيِّدٌ. (ت)', 'ഉസാമതുബ്നു സൈദ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ നന്മ ചെയ്യപ്പെടുകയും, അത് ചെയ്ത ആളോട് നിനക്കല്ലാഹു പ്രതിഫലം നൽകട്ടെ എന്ന് പറയുകയും ചെയ്താൽ അയാൾ സ്തുതിക്കുന്നതിൽ അങ്ങേയറ്റമെത്തിയിരിക്കുന്നു." (തു)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 824, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 327, 'عَنْ فَاطِمَةَ بِنْتِ الْمُنْذِرِ رَضِيَ اللهُ عَنْهَا عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً قَالَتْ: يَا رَسُولَ اللهِ، إِنَّ لِي جَارَةً – تَعْنِي ضَرَّةً – هَلْ عَلَيَّ جُنَاحٌ إِنْ تَشَبَّعْتُ لَهَا بِمَا لَمْ يُعْطِ زَوْجِي؟ قَالَ: "الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَ كَلَابِسِ ثَوْبَيْ زُورٍ". (ق,د)', 'അസ്മാഉ ബിൻതു അബീബക്കർ(റ)വിൽ നിന്ന് ഫാതിമതുബിൻതുൽ മുൻദിർ(റ): ഒരു സ്ത്രീ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, നിശ്ചയം എനിക്കൊരു അയൽവാസിനിയുണ്ട്. -മഹതി തന്റെ സഹകളത്രത്തെയാണ് ഉദ്ദേശിക്കുന്നത്- എന്റെ ഭർത്താവ് എനിക്ക് നൽകാത്ത ഒന്ന് കൊണ്ട് ഞാൻ അവരോട് സമ്പത്തുള്ളതായി നടക്കുന്നതിൽ വല്ല കുഴപ്പവുമുണ്ടോ? അവിടന്ന് പറഞ്ഞു: "നൽകപ്പെടാത്തത് കൊണ്ട് സമ്പന്നത നടിക്കുന്നവൻ, വ്യാജമായി നിർമ്മിച്ച രണ്ട് വസ്ത്രങ്ങൾ ധരിക്കുന്നവനെ പോലെയാണ്." (ബു,മു,ദ)', 'فَاطِمَةَ بِنْتِ الْمُنْذِرِ', 'അസ്മാഉ ബിൻതു അബീബക്കർ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 824, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 328, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ، فَكَسَعَ رَجُلٌ مِنَ الْمُهَاجِرِينَ رَجُلًا مِنَ الْأَنْصَارِ، فَقَالَ الْأَنْصَارِيُّ: يَا لَلْأَنْصَارِ. وَقَالَ الْمُهَاجِرِيُّ: يَا لَلْمُهَاجِرِينَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا بَالُ دَعْوَى الْجَاهِلِيَّةِ". قَالُوا يَا رَسُولَ اللهِ، كَسَعَ رَجُلٌ مِنَ الْمُهَاجِرِينَ رَجُلًا مِنَ الْأَنْصَارِ. فَقَالَ: "دَعُوهَا فَإِنَّهَا مُنْتِنَةٌ". فَسَمِعَهَا عَبْدُ اللهِ بْنُ أُبَيٍّ، فَقَالَ: قَدْ فَعَلُوهَا؟ وَاللهِ: لَئِنْ رَجَعْنَا إِلَى الْمَدِينَةِ لَيُخْرِجَنَّ الْأَعَزُّ مِنْهَا الْأَذَلَّ. قَالَ عُمَرُ: دَعْنِي أَضْرِبُ عُنُقَ هَذَا الْمُنَافِقِ. فَقَالَ: "دَعْهُ، لَا يَتَحَدَّثُ النَّاسُ أَنَّ مُحَمَّدًا يَقْتُلُ أَصْحَابَهُ". (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞങ്ങൾ ഒരു യുദ്ധത്തിൽ നബി(സ)യോടൊപ്പമായിരുന്നു. അപ്പോൾ മുഹാജിറുകളിൽ പെട്ട ഒരു വ്യക്തി അൻസാറുകളിൽ പെട്ട ഒരു വ്യക്തിയെ അടിച്ചു. അപ്പോൾ ആ അൻസാരി പറഞ്ഞു: ഓ അൻസാരികളേ, വരൂ. ആ മുഹാജിറും പറഞ്ഞു: ഓ മുഹാജിറുകളേ, വരൂ. അപ്പോൾ അല്ലാഹുവന്റെ റസൂൽ(സ) പറഞ്ഞു: "ജാഹിലിയ്യാ വാദത്തിന്റെ അവസ്ഥയെന്താണ്." അവർ പറഞ്ഞു: മുഹാജിറുകളിൽ പെട്ട ഒരു വ്യക്തി അൻസാരികളിൽപ്പെട്ട ഒരു വ്യക്തിയെ അടിച്ചിരിക്കുന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങളത് ഒഴിവാക്കുക, കാരണമത് ദുർഗന്ധം വമിക്കുന്നതാണ്." അപ്പോൾ അബ്ദുല്ലാഹിബ്നു ഉബയ്യ് ഇത് കേട്ടു. അയാൾ പറഞ്ഞു: തീർച്ചയായും അവരത് ചെയ്തിട്ടില്ലെയോ? അല്ലാഹുവാണ് സത്യം! ഞങ്ങൾ മദീനയിലേക്ക് മടങ്ങിവരികയാണെങ്കിൽ അവിടത്തെ മാന്യന്മാർ നിന്ദ്യൻമാരെ പുറത്താക്കുക തന്നെ ചെയ്യും. ഉമർ(റ) പറഞ്ഞു: നിങ്ങളെന്നെ വിടുക, ഞാനീ കപട വിശ്വാസിയുടെ കഴുത്തറുക്കട്ടെ. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങളവനെ വിട്ടേക്കുക, നിശ്ചയം മുഹമ്മദ് തന്റെ അനുയായികളെ കൊല്ലുമെന്ന് ജനങ്ങൾ പറയാതിരിക്കട്ടെ." (മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 825, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 329, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنْ عِنْدِهَا لَيْلًا، قَالَتْ: فَغِرْتُ عَلَيْهِ، فَجَاءَ فَرَأَى مَا أَصْنَعُ، فَقَالَ: "مَا لَكِ يَا عَائِشَةُ أَغِرْتِ". فَقُلْتُ: وَمَا لِي لَا يَغَارُ مِثْلِي عَلَى مِثْلِكَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَقَدْ جَاءَكِ شَيْطَانُكِ". قَالَتْ: يَا رَسُولَ اللهِ، أَوَ مَعِي شَيْطَانٌ؟ قَالَ: "نَعَمْ". قُلْتُ: وَمَعَ كُلِّ إِنْسَانٍ؟ قَالَ: "نَعَمْ". قُلْتُ: وَمَعَكَ يَا رَسُولَ اللهِ؟ قَالَ: "نَعَمْ، وَلَكِنْ رَبِّي أَعَانَنِي عَلَيْهِ حَتَّى أَسْلَمَ". (م)', 'പ്രവാചക പത്നിയായ ആഇശ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) ഒരു രാത്രി മഹതിയുടെ അടുക്കൽ നിന്നും പുറത്ത് പോയി. മഹതി പറയുന്നു: അപ്പോൾ (അവിടന്ന് മറ്റേതെങ്കിലും ഭാര്യമാരുടെ അടുത്ത് പോകുന്നത് വെറുത്ത്) എനിക്ക് അവിടത്തോട് ദേഷ്യം തോന്നി. അപ്പോൾ അവിടന്ന് വരികയും ഞാൻ ചെയ്യുന്നത് കാണുകയും ചെയ്തു. അവിടന്ന് ചോദിച്ചു: "ആഇശാ, നിനക്കെന്തു പറ്റി. നിനക്ക് ദേഷ്യം പിടിച്ചോ?" അപ്പോൾ ഞാൻ ചോദിച്ചു: എനിക്കെന്തോ, അങ്ങയെപ്പോലുള്ള ഒരാളോട് എന്നെപ്പോലുള്ള ഒരാൾ എങ്ങനെ ദേഷ്യപ്പെടാതിരിക്കും. അപ്പോൾ അല്ലാഹുവിന്റെ റസൂൽ(സ) ചോദിച്ചു: "നിന്റെ അടുത്തേക്ക് നിന്റെ പിശാച് വന്നോ?" മഹതി ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ കൂടെ പിശാചുണ്ടോ. അവിടന്ന് പറഞ്ഞു: "അതെ." ഞാൻ ചോദിച്ചു: എല്ലാ മനുഷ്യരുടെ കൂടെയുമുണ്ടോ? അവിടന്ന് പറഞ്ഞു: "അതെ." ഞാൻ ചോദിച്ചു: അങ്ങയുടെ കൂടെയുമുണ്ടോ, അല്ലാഹുവിന്റെ റസൂലേ. അവിടന്ന് പറഞ്ഞു: "അതെ, പക്ഷേ അവനെതിരെ എന്റെ രക്ഷിതാവ് എന്നെ സഹായിക്കുകയും അങ്ങനെ അവൻ മുസ്ലിമാകുകയും ചെയ്തിരിക്കുന്നു." (മു)', 'عَائِشَةَ', 'പ്രവാചക പത്നിയായ ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 825, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 330, 'عَنِ الْمِقْدَادِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نَحْثُوَ فِي وُجُوهِ الْمَدَّاحِينَ التُّرَابَ. (م,ت,جه)', 'മിഖ്ദാദുബ്നു അംറ്(റ): പുകഴ്ത്തുന്നവരുടെ മുഖത്തേക്ക് മണ്ണ് വാരിയിടാൻ അല്ലാഹുവിന്റെ റസൂൽ(സ) ഞങ്ങളോട് കൽപിച്ചു. (മു,തു,ജ)', 'الْمِقْدَادِ بْنِ عَمْرٍو', 'മിഖ്ദാദുബ്നു അംറ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 331, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِيَّاكُمْ وَالتَّمَادُحَ، فَإِنَّهُ الذَّبْحُ". (جه)', 'മുആവിയ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങൾ നിങ്ങളെയും പരസ്പരം പുകഴ്ത്തലിനെയും സുക്ഷിക്കുക, കാരണമത് അറുക്കലാണ്." (ജ)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 332, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَجُلًا ذُكِرَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَثْنَى عَلَيْهِ رَجُلٌ خَيْرًا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَيْحَكَ قَطَعْتَ عُنُقَ صَاحِبِكَ، يَقُولُهُ مِرَارًا، إِنْ كَانَ أَحَدُكُمْ مَادِحًا لَا مَحَالَةَ فَلْيَقُلْ أَحْسِبُ كَذَا وَكَذَا، إِنْ كَانَ يَرَى أَنَّهُ كَذَلِكَ، وَحَسِيبُهُ اللهُ، وَلَا يُزَكِّي عَلَى اللهِ أَحَدًا". (خ,د,جه)', 'അബൂബക്റ(റ): ഒരാളെക്കുറിച്ച് നബി(സ)യുടെ സന്നിധിയിൽ പറയപ്പെട്ടു: അപ്പോൾ മറ്റൊരാൾ അയാളെ പുകഴ്ത്തി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിനക്ക് നാശം, നീ നിന്റെ സുഹൃത്തിന്റെ പിരടിയറുത്തിരിക്കുന്നു." അവിടന്നത് പല പ്രാവശ്യം പറയാൻ തുടങ്ങി: "നിങ്ങളിൽ നിന്നാരെങ്കിലും പുകഴ്ത്തുകയാണെങ്കിൽ ഞാൻ ഇങ്ങനെയെല്ലാം വിചാരിക്കുന്നുവെന്ന് മാത്രം പറഞ്ഞുകൊള്ളട്ടെ. ഇനി അവൻ അങ്ങനെയെല്ലാമാണെന്ന് കാണപ്പെടുകയാണെങ്കിൽ അതിന് യോഗ്യനായവൻ അല്ലാഹുവാണ്. അല്ലാഹുവിനേക്കാൾ ഒരാളെയും പരിശുദ്ധനാക്കരുത്." (ബു,ദ,ജ)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 333, 'عَنْ هَمَّامٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ فَأَثْنَى عَلَى عُثْمَانَ فِي وَجْهِهِ، فَأَخَذَ الْمِقْدَادُ بْنُ الْأَسْوَدِ تُرَابًا فَحَثَا فِي وَجْهِهِ، وَقَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا لَقِيتُمُ الْمَدَّاحِينَ فَاحْثُوا فِي وُجُوهِهِمُ التُّرَابَ". (م,د,جه)', 'ഹമ്മാം(റ): ഒരാൾ വന്ന് ഉസ്മാൻ(റ)വിനെ മുഖത്തുനോക്കി പുകഴ്ത്തി. അപ്പോൾ മിഖ്ദാദുബ്നുൽ അസ്വദ്(റ) കുറച്ച് മണ്ണെടുത്ത് അത് അദ്ദേഹത്തിന്റെ മുഖത്തെറിയുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: റസൂൽ(സ) പറഞ്ഞിരിക്കുന്നു: "പുകഴ്ത്തുന്നവരെ നിങ്ങൾ കണ്ടുമുട്ടുകയാണെങ്കിൽ അവരുടെ മുഖത്തേക്ക് മണ്ണെറിയുക." (മു,ദ,ജ)', 'هَمَّامٍ', 'ഹമ്മാം(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 334, 'عَنْ عَبْدِ اللهِ بْنِ الشِّخِّيرِ رَضِيَ اللهُ عَنْهُ قَالَ: انْطَلَقْتُ فِي وَفْدِ بَنِي عَامِرٍ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْنَا: أَنْتَ سَيِّدُنَا، فَقَالَ: "السَّيِّدُ اللهُ تَبَارَكَ وَتَعَالَى". قُلْنَا: وَأَفْضَلُنَا فَضْلًا وَأَعْظَمُنَا طَوْلًا، فَقَالَ: "قُولُوا بِقَوْلِكُمْ، أَوْ: بَعْضِ قَوْلِكُمْ، وَلَا يَسْتَجْرِيَنَّكُمُ الشَّيْطَانُ". (د)', 'അബ്ദുല്ലാഹിബ്നു ശിഖ്ഖീർ(റ): ബനൂആമിരിൽ നിന്നുള്ള സംഘത്തോടൊപ്പം ഞാൻ അല്ലാഹുവിന്റെ റസൂൽ(സ)യുടെ അടുക്കൽ പോയി. ഞങ്ങൾ പറഞ്ഞു: അങ്ങ് ഞങ്ങളുടെ നേതാവാണ്, അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നേതാവ്, പരിശുദ്ധനും മഹോന്നതനുമായ അല്ലാഹുവാണ്." ഞങ്ങൾ പറഞ്ഞു: ശ്രേഷ്ഠതയാൽ ഞങ്ങളിൽ ഏറ്റവും ശ്രേഷ്ഠരായവരും മേന്മയാൽ ഞങ്ങളിൽവെച്ച് ഏറ്റവും ഉന്നതരായവരും അങ്ങാണ്. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങളത് നിങ്ങളുടെ വാക്കുകൾ കൊണ്ട്, അല്ലെങ്കിൽ നിങ്ങളുടെ ചില വാക്കുകൾ കൊണ്ട് പറയുക, പിശാച് നിങ്ങളെ അവന്റെ പ്രതിനിധിയായി നിയമിക്കാതിരിക്കട്ടെ." (ദ)', 'عَبْدِ اللهِ بْنِ الشِّخِّيرِ', 'അബ്ദുല്ലാഹിബ്നു ശിഖ്ഖീർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 335, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالُوا: يَا رَسُولَ اللهِ، إِنَّكَ تُدَاعِبُنَا؟ قَالَ: "إِنِّي لَا أَقُولُ إِلَّا حَقًّا". حَسَنٌ صَحِيحٌ. (ت)', 'അബൂഹുറൈറ(റ): അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് ഞങ്ങളുടെ കൂടെ കളിക്കുന്നുണ്ടല്ലേ? അവിടന്ന് പറഞ്ഞു: "നിശ്ചയം ഞാൻ സത്യമല്ലാതെ പറയുകയില്ല." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 336, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا اسْتَحْمَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنِّي حَامِلُكَ عَلَى وَلَدِ النَّاقَةِ". فَقَالَ: يَا رَسُولَ اللهِ، مَا أَصْنَعُ بِوَلَدِ النَّاقَةِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَهَلْ تَلِدُ الْإِبِلَ إِلَّا النُّوقُ". حَسَنٌ صَحِيحٌ. (د,ت)', 'അനസുബ്നു മാലിക്(റ): ഒരാൾ അല്ലാഹുവിന്റെ റസൂൽ(സ)യോട് വാഹനത്തിൽ കയറ്റാനാവശ്യപ്പെട്ടു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: നിശ്ചയം നിന്നെ ഞാനൊരു ഒട്ടകക്കുട്ടിയുടെ മേൽ കയറ്റും." അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഒട്ടകക്കുട്ടിയുമായി ഞാനെന്ത് ചെയ്യും? അപ്പോൾ അല്ലാഹുവിന്റെ റസൂൽ(സ) ചോദിച്ചു: "ഒട്ടകം ഒട്ടകക്കുട്ടിയെയല്ലാതെ പ്രസവിക്കുമോ?" (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 337, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا ذَا الْأُذُنَيْنِ". حَدِيثٌ صَحِيحٌ. (د,ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "ഏ, രണ്ട് ചെവിയുള്ളവനേ." ഹദീസ് സ്വഹീഹാണ്. (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 338, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتَأْذَنَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَمِعَ صَوْتَ عَائِشَةَ عَالِيًا، فَلَمَّا دَخَلَ تَنَاوَلَهَا لِيَلْطِمَهَا، وَقَالَ: أَلَا أَرَاكِ تَرْفَعِينَ صَوْتَكِ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَجَعَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَحْجِزُهُ، وَخَرَجَ أَبُو بَكْرٍ مُغْضَبًا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ خَرَجَ أَبُو بَكْرٍ: "كَيْفَ رَأَيْتِنِي أَنْقَذْتُكِ مِنَ الرَّجُلِ". قَالَ: فَمَكَثَ أَبُو بَكْرٍ أَيَّامًا، ثُمَّ اسْتَأْذَنَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوَجَدَهُمَا قَدِ اصْطَلَحَا، فَقَالَ لَهُمَا: أَدْخِلَانِي فِي سِلْمِكُمَا كَمَا أَدْخَلْتُمَانِي فِي حَرْبِكُمَا. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قَدْ فَعَلْنَا، قَدْ فَعَلْنَا". (د)', 'നുഅ്മാനുബ്നു ബഷീർ(റ): അബൂബക്കർ(റ) നബി(സ)യുടെ അടുത്ത് വരാൻ സമ്മതം ചോദിച്ചു, അപ്പോഴദ്ദേഹം ആഇശ(റ) ഉറക്കെ ശബ്ദിക്കുന്നത് കേട്ടു. അകത്തുവന്നപ്പോൾ അദ്ദേഹം മഹതിയെ മുഖത്തടിക്കാനായി പിടിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു. അല്ലാഹുവിന്റെ റസൂൽ(സ)യേക്കാൾ നീ ശബ്ദമുയർത്തുന്നത് ഞാനൊന്ന് കാണട്ടേ? അപ്പോൾ നബി(സ) അദ്ദേഹത്തെ പിടിച്ചുമാറ്റാൻ തുടങ്ങി. അപ്പോഴദ്ദേഹം ദേഷ്യപ്പെട്ട് പുറത്ത് പോയി. അബൂബക്കർ(റ) പുറത്ത് പോയപ്പോൾ നബി(സ) ചോദിച്ചു: "ഒരു പുരുഷനിൽ നിന്ന് നിന്നെ ഞാൻ രക്ഷപ്പെടുത്തുന്നത് നീ കണ്ടതെങ്ങനെയുണ്ട്." നിവേദകൻ പറയുന്നു: അങ്ങനെ അബൂബക്കർ(റ) ദിവസങ്ങളോളം അങ്ങോട്ട് വരാതിരിക്കുകയും പിന്നീട് അല്ലാഹുവിന്റെ റസൂൽ(സ)യോട് വരാൻ സമ്മതം ചോദിക്കുകയും ചെയ്തു. അപ്പോൾ അവർ രണ്ടുപേരും പരസ്പരം നന്നായതായി അദ്ദേഹം കണ്ടെത്തി. അപ്പോഴദ്ദേഹം അവരിരുവരോടുമായി പറഞ്ഞു: നിങ്ങളുടെ യുദ്ധകാലത്ത് നിങ്ങളെന്നെ അകത്ത് പ്രവേശിപ്പിച്ചത് പോലെ നിങ്ങളുടെ സന്ധികാലത്തും നിങ്ങളെന്നെ അകത്ത് പ്രവേശിപ്പിക്കുക. അപ്പോൾ നബി(സ) പറഞ്ഞു: "തീർച്ചയായും ഞങ്ങൾ അപ്രകാരം ചെയ്തിരിക്കുന്നു. തീർച്ചായയും ഞങ്ങൾ ചെയ്തിരിക്കുന്നു." (ദ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബഷീർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 827, 828, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 339, 'عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ رضي الله عنه قَالَ: أَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ وَهُوَ فِي قُبَّةٍ مِنْ أَدَمٍ، فَسَلَّمْتُ فَرَدَّ، وَقَالَ: "ادْخُلْ". فَقُلْتُ: أَكُلِّي يَا رَسُولَ اللهِ؟ قَالَ: "كُلُّكَ". فَدَخَلْتُ. عَنْ عُثْمَانَ بْنِ أَبِي الْعَاتِكَةِ قَالَ: إِنَّمَا قَالَ: (أَدْخُلُ كُلِّي) مِنْ صِغَرِ الْقُبَّةِ. (خ,د,جه)', 'ഔഫുബ്നു മാലികിൽ അശ്ജഇൗ(റ): തബൂക് യുദ്ധത്തിൽ വെച്ച് ഞാൻ, തോലിന്റെ കൂടാരത്തിലിരിക്കുന്ന റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്നിട്ട് അവിടത്തോട് സലാം പറഞ്ഞു. അപ്പോൾ അവിടന്ന് സലാം മടക്കുകയും "കടന്നു വരൂ" എന്ന് പറയുകയും ചെയ്തു. അപ്പോൾ ഞാൻ ചോദിച്ചു: ഞാൻ മുഴുവനായും (പ്രവേശിക്കട്ടെയോ), നബിയേ? അവിടന്ന് പറഞ്ഞു: "മുഴുവനായും (നീ പ്രവേശിക്കുക)." അപ്പോൾ ഞാൻ പ്രവേശിച്ചു. (ബു,ദ,ജ)
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 340, 'عَنْ يَزِيدَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَأْخُذَنَّ أَحَدُكُمْ مَتَاعَ أَخِيهِ لَاعِبًا وَلَا جَادًّا – وفي رواية: لَعِبًا وَلَا جِدًّا – وَمَنْ أَخَذَ عَصَا أَخِيهِ فَلْيَرُدَّهَا". (د,ت)', 'യസീദ്(റ): റസൂൽ(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "നിശ്ചയം നിങ്ങളിലൊരാളും തന്നെ തന്റെ സഹോദരന്റെ ചരക്കുകൾ തമാശയായിട്ടോ തന്റെ അവകാശമാണെന്ന് വാദിച്ചോ എടുക്കരുത്. ആരെങ്കിലും തന്റെ സഹോദരന്റെ വടിയെടുക്കുകയാണെങ്കിൽ അവനത് തിരിച്ച് കൊടുക്കട്ടെ." (ദ,തു)', 'يَزِيدَ', 'യസീദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 828, 828, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=9 and h.hadith_no=340), 1, 'وَفِي رِوَايَةٍ: لَعِبًا وَلَا جِدًّا – وَمَنْ أَخَذَ عَصَا أَخِيهِ فَلْيَرُدَّهَا". (د,ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 341, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنَا أَصْحَابُ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُمْ كَانُوا يَسِيرُونَ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَنَامَ رَجُلٌ مِنْهُمْ، فَانْطَلَقَ بَعْضُهُمْ إِلَى حَبْلٍ مَعَهُ فَأَخَذَهُ، فَفَزِعَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَحِلُّ لِمُسْلِمٍ أَنْ يُرَوِّعَ مُسْلِمًا". (د)', 'അബ്ദുർറഹ്മാനുബ്നു അബീലൈല(റ): മുഹമ്മദ്(സ)യുടെ അനുചരർ ഞങ്ങളെ അറിയിച്ചു: അവരൊരിക്കൽ നബി(സ)യോടൊപ്പം യാത്ര ചെയ്യുകയായിരുന്നു. അപ്പോൾ അവരിലൊരാൾ ഉറങ്ങിപ്പോയി. അപ്പോൾ അവരിൽ ചിലർ പോയി അയാളുടെ കൂടെയുണ്ടായിരുന്ന ഒരു കയറെടുത്തു. അങ്ങനെ അയാളാകെ പേടിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഒരു മുസ്ലിം മറ്റൊരു മുസ്ലിമിനെ പേടിപ്പിക്കുന്നത് അനുവദനീയമല്ല." (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى', 'അബ്ദുർറഹ്മാനുബ്നു അബീലൈല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 828, 829, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 342, 'عَنْ أُمِّ سَلَمَةَ رضي الله عنها قَالَتْ: خَرَجَ أَبُو بَكْرٍ فِي تِجَارَةٍ إِلَى بُصْرَى قَبْلَ مَوْتِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِعَامٍ، وَمَعَهُ نُعَيْمَانُ وَسُوَيْطُ بْنُ حَرْمَلَةَ، وَكَانَا شَهِدَا بَدْرًا، وَكَانَ نُعَيْمَانُ عَلَى الزَّادِ، وَكَانَ سُوَيْطٌ رَجُلًا مَزَّاحًا، فَقَالَ: لِنُعَيْمَانَ: أَطْعِمْنِي. قَالَ: حَتَّى يَجِيءَ أَبُو بَكْرٍ. قَالَ: فَلَأُغِيظَنَّكَ. قَالَ: فَمَرُّوا بِقَوْمٍ، فَقَالَ لَهُمْ سُوَيْطٌ: تَشْتَرُونَ مِنِّي عَبْدًا لِي؟ قَالُوا: نَعَمْ. قَالَ: إِنَّهُ عَبْدٌ لَهُ كَلَامٌ، وَهُوَ قَائِلٌ لَكُمْ: إِنِّي حُرٌّ، فَإِنْ كُنْتُمْ إِذَا قَالَ لَكُمْ هَذِهِ الْمَقَالَةَ، تَرَكْتُمُوهُ، فَلَا تُفْسِدُوا عَلَيَّ عَبْدِي. قَالُوا: لَا، بَلْ نَشْتَرِيهِ مِنْكَ. فَاشْتَرَوْهُ مِنْهُ بِعَشْرِ قَلَائِصَ، ثُمَّ أَتَوْهُ فَوَضَعُوا فِي عُنُقِهِ عِمَامَةً، أَوْ حَبْلًا. فَقَالَ نُعَيْمَانُ: إِنَّ هَذَا يَسْتَهْزِئُ بِكُمْ، وَإِنِّي حُرٌّ، لَسْتُ بِعَبْدٍ. فَقَالُوا: قَدْ أَخْبَرَنَا خَبَرَكَ. فَانْطَلَقُوا بِهِ، فَجَاءَ أَبُو بَكْرٍ فَأَخْبَرُوهُ بِذَلِكَ، قَالَ: فَاتَّبَعَ الْقَوْمَ وَرَدَّ عَلَيْهِمُ الْقَلَائِصَ وَأَخَذَ نُعَيْمَانَ. قَالَ: فَلَمَّا قَدِمُوا عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَخْبَرُوهُ، قَالَ: فَضَحِكَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ مِنْهُ حَوْلًا. [ز: فِي سنده ضعيف] (جه)', 'ഉമ്മുസലമ(റ): നബി(സ)യുടെ വഫാത്തിന്റെ ഒരു വർഷം മുമ്പ്, അബൂബക്കർ(റ) ഒരു കച്ചവട സംഘലത്തിലായി ബസ്വറയിലേക്ക് പോയി. അദ്ദേഹത്തോടൊപ്പം നുഐമാൻ(റ)വും സുവൈബിതുബ്നു ഹർമല(റ)വുമുണ്ടായിരുന്നു. അവർ രണ്ടുപേരും ബദ്റിൽ പങ്കെടുത്തവരാണ്. നുഐമാൻ(റ) ഭക്ഷണത്തിന്റെ കാര്യം നോക്കുന്നവരായിരുന്നു. സുവൈബിത്(റ) ഒരു തമാശക്കാരനായിരുന്നു. നുഐമാൻ(റ)വിനോടദ്ദേഹം പറഞ്ഞു: എനിക്ക് ഭക്ഷണം തരൂ. നുഐമാൻ(റ) പറഞ്ഞു: അബൂബക്കർ(റ) വരട്ടെ. സുവൈബിത്(റ) പറഞ്ഞു: എങ്കിൽ ഞാൻ നിന്നെ ദേഷ്യം പിടിപ്പിക്കുക തന്നെ ചെയ്യും. നിവേദകൻ പറയുന്നു: അങ്ങനെ അവരൊരു സമുദായത്തിന്റെ അടുത്തുകൂടെ നടന്നു പോയി. അപ്പോൾ സുവൈബിത്(റ) അവരോട് ചോദിച്ചു: എന്റെയൊരു അടിമയെ നിങ്ങൾ വാങ്ങുമോ? അവർ പറഞ്ഞു: അതെ, അദ്ദേഹം പറഞ്ഞു: നന്നായി സംസാരിക്കുന്നവനാണ് ആ അടിമ. താൻ സ്വതന്ത്രനാണെന്ന് അവൻ നിങ്ങളോട് പറഞ്ഞേക്കും. കാരണം അവൻ നിങ്ങളോടിങ്ങനെയെല്ലാം പറഞ്ഞാൽ നിങ്ങളവനെ ഒഴിവാക്കിയേക്കാമല്ലോ. അതിനാൽ നിങ്ങളെന്റെ നേരെ എന്റെ അടിമയെ ഇളക്കി വിടരുത്. അവർ പറഞ്ഞു: ഇല്ല, മറിച്ച് ഞങ്ങളവനെ വാങ്ങാം. അങ്ങനെ പത്ത് ഒട്ടകങ്ങൾ കൊടുത്ത് അവരവനെ വാങ്ങി. പിന്നെയവർ നുഐമാൻ(റ)വിന്റെ അടുക്കൽ ചെന്ന് അദ്ദേഹത്തിന്റെ പിരടിയിലൊരു തലപ്പാവ്, അല്ലെങ്കിൽ ഒരു കയറിട്ടു. അപ്പോൾ നുഐമാൻ(റ) പറഞ്ഞു: ഇദ്ദേഹം നിങ്ങളെ പരിഹസിക്കുകയാണ്. ഞാനൊരു സ്വതന്ത്രനാണ്. ഞാൻ അടിമയല്ല. അപ്പോൾ അവർ പറഞ്ഞു: നിന്നെക്കുറിച്ചുള്ള എല്ലാ വിഷയങ്ങളും അദ്ദേഹം ഞങ്ങളോട് പറഞ്ഞിട്ടുണ്ട്. അങ്ങനെയവർ അദ്ദേഹത്തെ കൊണ്ടുപോയി. അബൂബക്കർ(റ) വന്നപ്പോൾ സുവൈബിത്(റ) വിഷയങ്ങളെല്ലാം പറഞ്ഞു. നിവേദകൻ പറയുന്നു: അപ്പോൾ അദ്ദേഹം ആ ആളുകളെ പിന്തുടരുകയും ഒട്ടകങ്ങളെ അവർക്ക് തിരിച്ച് നൽകുകയും നുഐമാൻ(റ)വിനെ പിടിക്കുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: അങ്ങനെയവർ നബി(സ)യുടെ അടുക്കൽ വന്നപ്പോൾ അവിടത്തോട് വിഷയം പറഞ്ഞു: അപ്പോൾ നബി(സ)യും അവിടത്തെ ചുറ്റുമുണ്ടായിരുന്ന സ്വഹാബാക്കളും ചിരിച്ചു. (പരമ്പരയിൽ ഭംഗമുള്ളവരുണ്ട്) (ജ).', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي سنده ضعيف', null, 829, 829, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 343, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا حَلِيمَ إِلَّا ذُو عَثْرَةٍ، وَلَا حَكِيمَ إِلَّا ذُو تَجْرِبَةٍ". حَسَنٌ. (ت)', 'അബൂസഇൗദ്(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "വീഴ്ചപറ്റാത്ത സഹനശീലനില്ല. അനുഭവ സമ്പന്നനല്ലാത്ത ജ്ഞാനിയുമില്ല. (തു)', 'أَبِي سَعِيدٍ', 'അബൂസഇൗദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 830, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 344, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "حُبُّكَ الشَّيْءَ يُعْمِي وَيُصِمُّ". (د)', 'അബുദ്ദർദാഅ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു വസ്തുവിനോടുള്ള നിന്റെ സ്നേഹം നിന്നെ അന്ധനും ബധിരനുമാക്കും." (ദ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 830, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=2 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
